#[test]
fn released_predecessor_fixture_rejects_changed_bytes() {
    let source = TempDir::new().unwrap();
    let scenario = TempDir::new().unwrap();
    let prepared = released_predecessor::copy_to(source.path()).unwrap();
    let mut bytes = fs::read(&prepared).unwrap();
    bytes.push(0);
    fs::write(&prepared, bytes).unwrap();

    let error = released_predecessor::copy_from(&prepared, scenario.path()).unwrap_err();
    assert!(error.to_string().contains("SHA-256"), "{error:#}");
    assert_eq!(fs::read_dir(scenario.path()).unwrap().count(), 0);
}

#[test]
fn released_predecessor_fixture_rejects_unreadable_input() {
    use std::os::unix::fs::PermissionsExt;

    let source = TempDir::new().unwrap();
    let scenario = TempDir::new().unwrap();
    let missing = source.path().join("missing");
    let unreadable = source.path().join("unreadable");
    fs::write(&unreadable, "unreadable").unwrap();
    fs::set_permissions(&unreadable, fs::Permissions::from_mode(0)).unwrap();
    for path in [&missing, &unreadable] {
        let error = released_predecessor::copy_from(path, scenario.path()).unwrap_err();
        assert!(
            error.to_string().contains("FLUENT_RELEASED_050_BIN"),
            "{error:#}"
        );
        assert_eq!(fs::read_dir(scenario.path()).unwrap().count(), 0);
    }
}

fn released_050_binary(tmp: &TempDir) -> PathBuf {
    released_predecessor::copy_to(tmp.path()).unwrap()
}

fn released_fixture_cargo_home(tmp: &TempDir) -> PathBuf {
    let home = tmp.path().join("released-cargo-home");
    fs::create_dir_all(&home).unwrap();
    home
}

fn released_command(binary: &Path, project: &Path, args: &[&str]) -> std::process::Output {
    Command::new(binary)
        .current_dir(project)
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .args(args)
        .output()
        .unwrap()
}

fn record_release_refusal(
    scenario: &str,
    release: &Path,
    before: &[SnapshotEntry],
    after: &[SnapshotEntry],
    refusal: &std::process::Output,
) {
    let root = release_trace::output_directory(
        std::env::var_os("FLUENT_RELEASE_TRACE_DIR").map(PathBuf::from),
    );
    fs::create_dir_all(&root).unwrap();
    let mut artifacts = Vec::new();
    let mut facts = |stage: &str, snapshot: &[SnapshotEntry]| -> Vec<_> {
        snapshot
            .iter()
            .enumerate()
            .map(|(index, entry)| {
                let name = format!("{scenario}/{stage}/{index:05}.bin");
                let target = root.join(&name);
                fs::create_dir_all(target.parent().unwrap()).unwrap();
                fs::write(target, &entry.bytes).unwrap();
                let digest = format!("{:x}", Sha256::digest(&entry.bytes));
                artifacts.push(serde_json::json!({"path":name,"sha256":digest}));
                serde_json::json!({
                    "path":entry.path.to_string_lossy(), "kind":entry.kind,
                    "sha256":digest,"artifact":name
                })
            })
            .collect()
    };
    let before_facts = facts("before", before);
    let after_facts = facts("after", after);
    let release_bytes = fs::read(release).unwrap();
    let candidate_bytes = fs::read(assert_cmd::cargo::cargo_bin("fluent")).unwrap();
    let trace = serde_json::json!({
        "schema-version":1,"scenario":scenario,
        "fluent-commit":git_head(Path::new(env!("CARGO_MANIFEST_DIR"))),
        "fluent-binary-sha256":format!("{:x}", Sha256::digest(candidate_bytes)),
        "model-profile":"release-transition","collection-complete":true,
        "artifacts":artifacts,"events":[
            {"sequence":1,"actor":"current-reader","operation-id":"snapshot",
             "generation":null,"boundary":"before-refusal","causal-predecessors":[],
             "raw-facts":{"protected":before_facts,"predecessor-sha256":
                 format!("{:x}", Sha256::digest(&release_bytes))}},
            {"sequence":2,"actor":"released-reader","operation-id":"work-item-abandon",
             "generation":null,"boundary":"refused","causal-predecessors":[1],
             "raw-facts":{"exit-code":refusal.status.code(),
                 "stdout":String::from_utf8_lossy(&refusal.stdout),
                 "stderr":String::from_utf8_lossy(&refusal.stderr),
                 "protected":after_facts}}
        ]
    });
    fs::write(
        root.join(format!("{scenario}.json")),
        serde_json::to_vec_pretty(&trace).unwrap(),
    )
    .unwrap();
}

fn released_work_fixture(tmp: &TempDir, binary: &Path, id: &str) -> PathBuf {
    let project = setup_git_project(tmp);
    for args in [
        vec!["work-item", "create", id, "--title", "Released Work"],
        vec!["attempt", "create", id, "attempt-1"],
    ] {
        let result = released_command(binary, &project, &args);
        assert!(
            result.status.success(),
            "{}",
            String::from_utf8_lossy(&result.stderr)
        );
    }
    project
}

#[test]
fn released_upgrade_preserves_workflow_state() {
    let tmp = TempDir::new().unwrap();
    let release = released_050_binary(&tmp);
    let project = released_work_fixture(&tmp, &release, "released-planned");
    let before = WorkModelStore::new(&project)
        .read_work_item_snapshot("released-planned")
        .unwrap();
    let work_root = project.join(".fluent/work");
    let before_read = snapshot_tree(&work_root);
    fluent_cmd()
        .current_dir(&project)
        .args(["work-item", "show", "released-planned"])
        .assert()
        .success();
    let after_read = WorkModelStore::new(&project)
        .read_work_item_snapshot("released-planned")
        .unwrap();
    assert_eq!(after_read.id, before.id);
    assert_eq!(snapshot_tree(&work_root), before_read);
    fluent_cmd()
        .current_dir(&project)
        .args(["work-item", "upgrade", "released-planned"])
        .assert()
        .success();
    let after = WorkModelStore::new(&project)
        .read_work_item_snapshot("released-planned")
        .unwrap();
    assert_eq!(after.id, before.id);
    assert_eq!(after.attempts[0].id, before.attempts[0].id);
    assert_eq!(
        after.attempts[0].tasks[0].id,
        before.attempts[0].tasks[0].id
    );
    fluent_cmd()
        .current_dir(&project)
        .args(["attempt", "cancel", "released-planned", "attempt-1"])
        .assert()
        .success();
    assert_eq!(
        WorkModelStore::new(&project)
            .read_work_item_snapshot("released-planned")
            .unwrap()
            .attempts[0]
            .tasks[0]
            .id,
        before.attempts[0].tasks[0].id
    );

    let queued_tmp = TempDir::new().unwrap();
    let queued = released_work_fixture(&queued_tmp, &release, "released-queued");
    let queue = released_command(&release, &queued, &["queue", "add", "released-queued"]);
    assert!(
        queue.status.success(),
        "{}",
        String::from_utf8_lossy(&queue.stderr)
    );
    let queued_before = released_command(&release, &queued, &["queue", "show", "released-queued"]);
    assert!(queued_before.status.success());
    assert!(String::from_utf8_lossy(&queued_before.stdout).contains("queued"));
    let queued_before: serde_json::Value = serde_json::from_slice(&queued_before.stdout).unwrap();
    let queued_work_before =
        released_command(&release, &queued, &["work-item", "show", "released-queued"]);
    assert!(queued_work_before.status.success());
    let queued_work_before: serde_json::Value =
        serde_json::from_slice(&queued_work_before.stdout).unwrap();
    fluent_cmd()
        .current_dir(&queued)
        .args(["work-item", "upgrade", "released-queued"])
        .assert()
        .success();
    let queued_after = fluent_cmd()
        .current_dir(&queued)
        .args(["queue", "show", "released-queued"])
        .output()
        .unwrap();
    assert!(queued_after.status.success());
    assert!(String::from_utf8_lossy(&queued_after.stdout).contains("queued"));
    let queued_after: serde_json::Value = serde_json::from_slice(&queued_after.stdout).unwrap();
    assert_eq!(queued_after["dispatch_id"], queued_before["dispatch_id"]);
    assert_eq!(
        queued_after["bound_attempt_id"],
        queued_before["bound_attempt_id"]
    );
    let queued_work_after = fluent_cmd()
        .current_dir(&queued)
        .args(["work-item", "show", "released-queued"])
        .output()
        .unwrap();
    assert!(queued_work_after.status.success());
    let queued_work_after: serde_json::Value =
        serde_json::from_slice(&queued_work_after.stdout).unwrap();
    assert_eq!(
        queued_work_after["attempts"][0]["id"],
        queued_work_before["attempts"][0]["id"]
    );
    assert_eq!(
        queued_work_after["attempts"][0]["tasks"],
        queued_work_before["attempts"][0]["tasks"]
    );
    fluent_cmd()
        .current_dir(&queued)
        .args(["queue", "remove", "released-queued"])
        .assert()
        .success();
    let removed = fluent_cmd()
        .current_dir(&queued)
        .args(["queue", "show", "released-queued"])
        .output()
        .unwrap();
    assert!(removed.status.success());
    let removed: serde_json::Value = serde_json::from_slice(&removed.stdout).unwrap();
    assert_eq!(removed["dispatch_id"], queued_before["dispatch_id"]);
    assert_ne!(removed["status"], "queued");

    let paused_tmp = TempDir::new().unwrap();
    let paused = released_work_fixture(&paused_tmp, &release, "released-paused");
    let paused_before = released_command(
        &release,
        &paused,
        &["attempt", "cancel", "released-paused", "attempt-1"],
    );
    assert!(paused_before.status.success());
    let saved = released_command(&release, &paused, &["work-item", "show", "released-paused"]);
    assert!(saved.status.success());
    let paused_work: serde_json::Value = serde_json::from_slice(&saved.stdout).unwrap();
    fluent_cmd()
        .current_dir(&paused)
        .args(["work-item", "upgrade", "released-paused"])
        .assert()
        .success();
    let upgraded = fluent_cmd()
        .current_dir(&paused)
        .args(["work-item", "show", "released-paused"])
        .output()
        .unwrap();
    assert!(upgraded.status.success());
    let upgraded_work: serde_json::Value = serde_json::from_slice(&upgraded.stdout).unwrap();
    assert_eq!(
        upgraded_work["attempts"][0]["id"],
        paused_work["attempts"][0]["id"]
    );
    assert_eq!(
        upgraded_work["attempts"][0]["status"],
        paused_work["attempts"][0]["status"]
    );
    let paused_attempt = &paused_work["attempts"][0];
    let upgraded_attempt = &upgraded_work["attempts"][0];
    assert_eq!(upgraded_attempt["status"], "needs-user");
    assert_eq!(upgraded_attempt["pause_kind"], "interrupted");
    assert_eq!(upgraded_attempt["pause_kind"], paused_attempt["pause_kind"]);
    assert_eq!(
        upgraded_attempt["pause_recovery"],
        paused_attempt["pause_recovery"]
    );
    assert!(upgraded_attempt["pause_recovery"].is_null());
    assert_eq!(
        upgraded_attempt["cancellation"],
        paused_attempt["cancellation"]
    );
    let stop = &upgraded_attempt["cancellation"];
    assert!(stop["requested_at"].as_str().is_some());
    assert!(stop["settled_at"].as_str().is_some());
    assert!(stop["resumed_at"].is_null());
    assert_eq!(upgraded_attempt["tasks"], paused_attempt["tasks"]);
    assert_eq!(upgraded_attempt["tasks"][0]["id"], "attempt-1-write-1");
    assert_eq!(upgraded_attempt["tasks"][0]["kind"], "write");
    assert!(upgraded_attempt["tasks"][0]["output"].is_null());
    let upgraded_snapshot = WorkModelStore::new(&paused)
        .read_work_item_snapshot("released-paused")
        .unwrap();
    assert_eq!(
        upgraded_snapshot.attempts[0].tasks[0].status,
        TaskStatus::Planned
    );
    assert_eq!(
        upgraded_work["next-action"],
        "fluent queue resume released-paused --attempt attempt-1"
    );
    fluent_cmd()
        .current_dir(&paused)
        .args([
            "queue",
            "resume",
            "released-paused",
            "--attempt",
            "attempt-1",
        ])
        .assert()
        .success();
    let queued = fluent_cmd()
        .current_dir(&paused)
        .args(["queue", "show", "released-paused"])
        .output()
        .unwrap();
    assert!(queued.status.success());
    let dispatch: serde_json::Value = serde_json::from_slice(&queued.stdout).unwrap();
    assert_eq!(dispatch["status"], "queued");
    assert_eq!(dispatch["bound_attempt_id"], "attempt-1");
    assert_eq!(
        dispatch["resume_cancellation_requested_at"],
        stop["requested_at"]
    );
    let after_resume = WorkModelStore::new(&paused)
        .read_work_item_snapshot("released-paused")
        .unwrap();
    assert_eq!(
        serde_json::to_value(&after_resume.attempts[0]).unwrap()["tasks"],
        upgraded_attempt["tasks"]
    );
}

#[test]
fn released_upgrade_recovers_interrupted_publication() {
    let tmp = TempDir::new().unwrap();
    let release = released_050_binary(&tmp);
    let project = released_work_fixture(&tmp, &release, "released-pending");
    let result = fluent_cmd()
        .current_dir(&project)
        .env(
            "FLUENT_TEST_WORK_MODEL_INTERRUPT",
            "before-child-publication",
        )
        .args(["attempt", "cancel", "released-pending", "attempt-1"])
        .output()
        .unwrap();
    assert!(!result.status.success());
    assert!(
        project
            .join(".fluent/work/transactions/released-pending.json")
            .exists()
    );
    fluent_cmd()
        .current_dir(&project)
        .args(["attempt", "cancel", "released-pending", "attempt-1"])
        .assert()
        .success();
    assert!(
        !project
            .join(".fluent/work/transactions/released-pending.json")
            .exists()
    );
}

#[test]
fn released_upgrade_recovers_predecessor_interrupted_work() {
    let tmp = TempDir::new().unwrap();
    let release = released_050_binary(&tmp);
    let project = released_work_fixture(&tmp, &release, "released-interrupted");
    let bin = tmp.path().join("blocking-provider");
    write_mock_claude(
        &bin,
        "#!/bin/sh\nset -eu\nprintf 'started\\n' > \"$RELEASE_STARTED\"\nwhile :; do sleep 0.05; done\n",
    );
    let started = tmp.path().join("writer-started");
    let cargo_home = released_fixture_cargo_home(&tmp);
    let mut running = OwnedFixtureProcess::spawn(
        Command::new(&release)
            .current_dir(&project)
            .env("HOME", tmp.path())
            .env("CARGO_HOME", &cargo_home)
            .env("PATH", mock_path(&bin))
            .env("RELEASE_STARTED", &started)
            .env("FLUENT_NO_UPDATE_CHECK", "1")
            .args([
                "attempt",
                "run",
                "released-interrupted",
                "attempt-1",
                "--no-sandbox",
            ]),
    );
    wait_for_released_writer(&mut running, &started);
    let before = released_command(
        &release,
        &project,
        &["work-item", "show", "released-interrupted"],
    );
    assert!(before.status.success());
    let before: serde_json::Value = serde_json::from_slice(&before.stdout).unwrap();
    assert_eq!(before["attempts"][0]["status"], "executing");
    running.terminate_and_wait();
    let interrupted = released_command(
        &release,
        &project,
        &["work-item", "show", "released-interrupted"],
    );
    assert!(interrupted.status.success());
    let interrupted: serde_json::Value = serde_json::from_slice(&interrupted.stdout).unwrap();
    assert_eq!(
        interrupted["attempts"][0]["id"],
        before["attempts"][0]["id"]
    );
    assert_eq!(interrupted["attempts"][0]["status"], "executing");
    fluent_cmd()
        .current_dir(&project)
        .args(["attempt", "cancel", "released-interrupted", "attempt-1"])
        .assert()
        .success();
    let after = fluent_cmd()
        .current_dir(&project)
        .args(["work-item", "show", "released-interrupted"])
        .output()
        .unwrap();
    assert!(after.status.success());
    let after: serde_json::Value = serde_json::from_slice(&after.stdout).unwrap();
    assert_eq!(after["id"], interrupted["id"]);
    assert_eq!(after["attempts"][0]["id"], interrupted["attempts"][0]["id"]);
    assert_eq!(
        after["attempts"][0]["tasks"][0]["id"],
        interrupted["attempts"][0]["tasks"][0]["id"]
    );
    assert_eq!(after["attempts"][0]["status"], "needs-user");
}

#[test]
fn released_upgrade_preserves_landed_work() {
    let tmp = TempDir::new().unwrap();
    let release = released_050_binary(&tmp);
    let project = released_work_fixture(&tmp, &release, "work-1");
    let bin = tmp.path().join("release-provider");
    let cargo_home = released_fixture_cargo_home(&tmp);
    write_mock_claude(
        &bin,
        &learner_land_mock_script(r#"{"learning_summary":"none","follow_ups":[]}"#),
    );
    let run = Command::new(&release)
        .current_dir(&project)
        .env("HOME", tmp.path())
        .env("CARGO_HOME", &cargo_home)
        .env("PATH", mock_path(&bin))
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .output()
        .unwrap();
    assert!(
        run.status.success(),
        "released Attempt run: {}\n{}",
        String::from_utf8_lossy(&run.stdout),
        String::from_utf8_lossy(&run.stderr)
    );
    let before = released_command(&release, &project, &["work-item", "show", "work-1"]);
    assert!(before.status.success());
    let before: serde_json::Value = serde_json::from_slice(&before.stdout).unwrap();
    assert_eq!(before["attempts"][0]["status"], "complete");
    let landed = Command::new(&release)
        .current_dir(&project)
        .env("HOME", tmp.path())
        .env("CARGO_HOME", &cargo_home)
        .env("PATH", mock_path(&bin))
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .args(["merge-candidate", "land", "work-1", "--no-sandbox"])
        .output()
        .unwrap();
    assert!(
        landed.status.success(),
        "released landing: {}\n{}",
        String::from_utf8_lossy(&landed.stdout),
        String::from_utf8_lossy(&landed.stderr)
    );
    let released_landed = released_command(&release, &project, &["work-item", "show", "work-1"]);
    assert!(released_landed.status.success());
    let released_landed: serde_json::Value =
        serde_json::from_slice(&released_landed.stdout).unwrap();
    assert_eq!(
        released_landed["merge_candidates"][0]["merge_state"]["status"],
        "merged"
    );
    fluent_cmd()
        .current_dir(&project)
        .args(["work-item", "upgrade", "work-1"])
        .assert()
        .success();
    let after = fluent_cmd()
        .current_dir(&project)
        .args(["work-item", "show", "work-1"])
        .output()
        .unwrap();
    assert!(after.status.success());
    let after: serde_json::Value = serde_json::from_slice(&after.stdout).unwrap();
    assert_eq!(after["attempts"][0]["id"], before["attempts"][0]["id"]);
    assert_eq!(after["attempts"][0]["status"], "complete");
    assert_eq!(
        after["merge_candidates"][0]["merge_state"]["status"],
        "merged"
    );
    assert_eq!(
        after["merge_candidates"][0]["id"],
        released_landed["merge_candidates"][0]["id"]
    );
    let historical_tasks = |work: &serde_json::Value| -> Vec<_> {
        work["attempts"][0]["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .map(|task| {
                (
                    task["id"].clone(),
                    task["status"].clone(),
                    task["output"].clone(),
                    task["artifact_area"].clone(),
                )
            })
            .collect()
    };
    assert_eq!(historical_tasks(&after), historical_tasks(&released_landed));
    assert!(
        released_landed["attempts"][0]["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .any(|task| !task["output"].is_null() && !task["artifact_area"].is_null())
    );
    assert_eq!(
        after["merge_candidates"][0]["merge_state"],
        released_landed["merge_candidates"][0]["merge_state"]
    );
}

#[test]
fn released_upgrade_preserves_running_before_stop() {
    let tmp = TempDir::new().unwrap();
    let release = released_050_binary(&tmp);
    let project = released_work_fixture(&tmp, &release, "released-running");
    let bin = tmp.path().join("blocking-provider");
    write_mock_claude(
        &bin,
        "#!/bin/sh\nset -eu\nprintf 'started\\n' > \"$RELEASE_STARTED\"\nwhile [ ! -e \"$RELEASE_FINISH\" ]; do sleep 0.05; done\n",
    );
    let started = tmp.path().join("writer-started");
    let cargo_home = released_fixture_cargo_home(&tmp);
    let finish = tmp.path().join("writer-finish");
    let mut running = OwnedFixtureProcess::spawn(
        Command::new(&release)
            .current_dir(&project)
            .env("HOME", tmp.path())
            .env("CARGO_HOME", &cargo_home)
            .env("PATH", mock_path(&bin))
            .env("RELEASE_STARTED", &started)
            .env("RELEASE_FINISH", &finish)
            .env("FLUENT_NO_UPDATE_CHECK", "1")
            .args([
                "attempt",
                "run",
                "released-running",
                "attempt-1",
                "--no-sandbox",
            ]),
    );
    wait_for_released_writer(&mut running, &started);
    let before = released_command(
        &release,
        &project,
        &["work-item", "show", "released-running"],
    );
    assert!(before.status.success());
    let before: serde_json::Value = serde_json::from_slice(&before.stdout).unwrap();
    assert_eq!(before["attempts"][0]["status"], "executing");
    let stopped = released_command(
        &release,
        &project,
        &["attempt", "cancel", "released-running", "attempt-1"],
    );
    assert!(
        stopped.status.success(),
        "released cancel: {}\n{}",
        String::from_utf8_lossy(&stopped.stdout),
        String::from_utf8_lossy(&stopped.stderr)
    );
    let settled = released_command(
        &release,
        &project,
        &["work-item", "show", "released-running"],
    );
    assert!(settled.status.success());
    let settled: serde_json::Value = serde_json::from_slice(&settled.stdout).unwrap();
    fs::write(&finish, "finish").unwrap();
    let _ = running.wait();
    fluent_cmd()
        .current_dir(&project)
        .args(["work-item", "upgrade", "released-running"])
        .assert()
        .success();
    let after = fluent_cmd()
        .current_dir(&project)
        .args(["work-item", "show", "released-running"])
        .output()
        .unwrap();
    assert!(after.status.success());
    let after: serde_json::Value = serde_json::from_slice(&after.stdout).unwrap();
    assert_eq!(after["attempts"][0]["id"], before["attempts"][0]["id"]);
    assert_eq!(
        after["attempts"][0]["tasks"][0]["id"],
        before["attempts"][0]["tasks"][0]["id"]
    );
    assert_eq!(after["attempts"][0]["status"], "needs-user");
    assert_eq!(
        after["attempts"][0]["cancellation"],
        settled["attempts"][0]["cancellation"]
    );
    assert_eq!(
        after["attempts"][0]["tasks"],
        settled["attempts"][0]["tasks"]
    );
    assert_eq!(
        after["next-action"],
        "fluent queue resume released-running --attempt attempt-1"
    );
    fluent_cmd()
        .current_dir(&project)
        .args([
            "queue",
            "resume",
            "released-running",
            "--attempt",
            "attempt-1",
        ])
        .assert()
        .success();
    let resumed = fluent_cmd()
        .current_dir(&project)
        .args(["queue", "show", "released-running"])
        .output()
        .unwrap();
    assert!(resumed.status.success());
    let resumed: serde_json::Value = serde_json::from_slice(&resumed.stdout).unwrap();
    assert_eq!(resumed["bound_attempt_id"], after["attempts"][0]["id"]);
    assert_eq!(
        resumed["resume_cancellation_requested_at"],
        after["attempts"][0]["cancellation"]["requested_at"]
    );
}

#[test]
fn released_predecessor_refuses_current_authority() {
    let tmp = TempDir::new().unwrap();
    let release = released_050_binary(&tmp);
    let project = released_work_fixture(&tmp, &release, "released-refusal");
    let legacy_read = released_command(
        &release,
        &project,
        &["work-item", "show", "released-refusal"],
    );
    assert!(legacy_read.status.success());
    fluent_cmd()
        .current_dir(&project)
        .args(["work-item", "upgrade", "released-refusal"])
        .assert()
        .success();
    let root = project.join(".fluent/work");
    let before = snapshot_tree(&root);
    let result = released_command(
        &release,
        &project,
        &[
            "work-item",
            "abandon",
            "released-refusal",
            "--reason",
            "old reader",
        ],
    );
    assert!(
        !result.status.success(),
        "old release changed current authority"
    );
    let diagnostic = String::from_utf8_lossy(&result.stderr);
    assert!(
        diagnostic.contains("unsupported Work Item writer envelope format/schema")
            && diagnostic.contains("items/released-refusal.json"),
        "refusal must identify the incompatible Work Item: {diagnostic}"
    );
    let after = snapshot_tree(&root);
    assert_eq!(after, before);
    record_release_refusal("current-authority", &release, &before, &after, &result);
}

#[test]
fn released_predecessor_refuses_pending_current_publication() {
    let tmp = TempDir::new().unwrap();
    let release = released_050_binary(&tmp);
    let project = released_work_fixture(&tmp, &release, "released-pending-refusal");
    let result = fluent_cmd()
        .current_dir(&project)
        .env(
            "FLUENT_TEST_WORK_MODEL_INTERRUPT",
            "before-child-publication",
        )
        .args(["attempt", "cancel", "released-pending-refusal", "attempt-1"])
        .output()
        .unwrap();
    assert!(!result.status.success());
    let root = project.join(".fluent/work");
    assert!(
        root.join("transactions/released-pending-refusal.json")
            .exists()
    );
    let before = snapshot_tree(&root);
    let result = released_command(
        &release,
        &project,
        &[
            "work-item",
            "abandon",
            "released-pending-refusal",
            "--reason",
            "old reader",
        ],
    );
    assert!(
        !result.status.success(),
        "old release replayed current publication"
    );
    let diagnostic = String::from_utf8_lossy(&result.stderr);
    assert!(diagnostic.contains("invalid work model")
            && diagnostic.contains("transactions/released-pending-refusal.json")
            && diagnostic.contains("work item transaction id \"released-pending-refusal\" cannot be used as a file name"),
            "refusal must identify the incompatible transaction: {diagnostic}");
    let after = snapshot_tree(&root);
    assert_eq!(after, before);
    record_release_refusal("pending-publication", &release, &before, &after, &result);
    fluent_cmd()
        .current_dir(&project)
        .args(["attempt", "cancel", "released-pending-refusal", "attempt-1"])
        .assert()
        .success();
    assert!(
        !root
            .join("transactions/released-pending-refusal.json")
            .exists()
    );
}

fn fluent_cmd() -> LoggedCommand {
    let mut cmd = LoggedCommand::cargo_bin("fluent");
    cmd.env_remove("FLUENT_TASK_KIND");
    cmd.env("FLUENT_NO_UPDATE_CHECK", "1");
    cmd.env("FLUENT_TEST_HERMETIC_PROVIDERS", "1");
    // Integration fixtures exercise command routing rather than the caller's
    // real enclosing Seatbelt state. Tests for the boundary override this.
    cmd.env("FLUENT_TEST_HOST_SANDBOX_PREFLIGHT", "pass");
    cmd.env_remove("ANTHROPIC_API_KEY");
    cmd.env_remove("ANTHROPIC_AUTH_TOKEN");
    cmd.env_remove("CLAUDE_CODE_OAUTH_TOKEN");
    cmd.env_remove("OPENAI_API_KEY");
    cmd.env_remove("PI_API_KEY");
    cmd
}

#[cfg(unix)]
fn assert_launch_receipt(area: &Path) {
    let record: fluent::execution::ExecutionRecord =
        serde_json::from_slice(&fs::read(area.join("execution.json")).unwrap()).unwrap();
    assert_eq!(record.schema_version, 2);
    let generation = record.launch_generation.unwrap();
    let receipt = fs::read_to_string(area.join("execution-receipt")).unwrap();
    assert!(receipt.starts_with(&format!("2 {generation} ")));
}

struct CarriedFindingFixture {
    project: PathBuf,
    workspace: PathBuf,
    work: String,
    candidate: String,
    source_candidate: String,
    finding: String,
    evidence: PathBuf,
    protected: Vec<(PathBuf, Vec<u8>)>,
}

fn carried_finding_fixture(tmp: &TempDir) -> CarriedFindingFixture {
    carried_finding_fixture_with_request(
        tmp,
        "Evidence-Command: cargo test exact_host_check\nEvidence-Working-Directory: .\n",
    )
}

fn carried_finding_fixture_with_request(tmp: &TempDir, request: &str) -> CarriedFindingFixture {
    carried_finding_fixture_with_tester(tmp, request, None)
}

fn carried_finding_fixture_with_tester(
    tmp: &TempDir,
    request: &str,
    tester: Option<&str>,
) -> CarriedFindingFixture {
    use fluent::work_model::*;
    let project = setup_git_project(tmp).canonicalize().unwrap();
    if let Some(tester) = tester {
        commit_file(
            &project,
            ".fluent/tester.yaml",
            tester,
            "Declare canonical host check",
        );
    }
    let token: String = tmp
        .path()
        .file_name()
        .unwrap()
        .to_string_lossy()
        .chars()
        .filter(char::is_ascii_alphanumeric)
        .collect();
    let work = format!("carried-{token}");
    let mut item = WorkItem::planned(&work, "Hand off carried host evidence");
    item.planning_context = Some(PlanningContext {
        plan: Some("| # | State reached | Behaviors | Verification | Responsibility | Req? |\n| 1 | Correct source. | | `cargo test correction` | writer | Yes |\n| 2 | Review candidate. | | Review | review | Yes |\n| 3 | Verify candidate. | | Tester | tester | Yes |\n| 4 | Learn. | | Learner | learner | Yes |\n".into()),
        ..Default::default()
    });
    item.add_initial_attempt("attempt-1").unwrap();
    let contract = item.attempts[0].writer_completion_contract.clone().unwrap();
    let workspace_ref = item.attempts[0].tasks[0].workspace_access.writes[0].clone();
    git::run(
        &project,
        &["worktree", "add", "-b", "candidate", &workspace_ref.path],
        "create carried candidate",
    )
    .unwrap();
    let workspace = project.join(&workspace_ref.path).canonicalize().unwrap();
    let source_candidate = git_head(&workspace);
    let source = &mut item.attempts[0].tasks[0];
    source.status = TaskStatus::Complete;
    source.completed_at = Some(now_iso8601());
    source.output = Some(TaskOutput {
        workspace_id: workspace_ref.id,
        workspace_path: workspace_ref.path,
        source_branch: "candidate".into(),
        base_commit: Some(source_candidate.clone()),
        commit: source_candidate.clone(),
        no_change: None,
        learner_canonicalization: None,
    });
    let source_id = source.id.clone();
    let source_output = source.output.clone().unwrap();
    item.add_next_review_tasks("attempt-1", &["tests"]).unwrap();
    let review = item.attempts[0].tasks.last_mut().unwrap();
    review.status = TaskStatus::Complete;
    review.completed_at = Some(now_iso8601());
    let review_ref = ArtifactRef {
        producer_id: review.id.clone(),
        path: format!("{}/review.md", review.artifact_area.as_ref().unwrap().path),
    };
    let title = "Observe the real host check";
    let review_bytes =
        format!("Verdict: fail\n\n## Findings\n\n- [ ] {title}\n\n{request}").into_bytes();
    let review_path = project.join(&review_ref.path);
    fs::create_dir_all(review_path.parent().unwrap()).unwrap();
    fs::write(&review_path, &review_bytes).unwrap();
    let finding = WriterCompletionFinding {
        id: format!("finding:tests:{}", review::finding_identity("tests", title)),
        role: "tests".into(),
        source: review_ref.path.clone(),
        requirement: title.into(),
    };
    let mut protected = vec![(review_path, review_bytes.clone())];
    // Each continuation inherits the original assignment, including source A.
    for round in 2..=4 {
        let inputs = if round == 2 {
            vec![review_ref.clone()]
        } else {
            vec![]
        };
        let id = item.add_next_write_round("attempt-1", inputs).unwrap();
        commit_file(
            &workspace,
            "corrected.txt",
            &format!("correction {round}\n"),
            "Correct candidate source",
        );
        let task = item.attempts[0].tasks.last_mut().unwrap();
        task.status = TaskStatus::Complete;
        task.completed_at = Some(now_iso8601());
        task.output = Some(TaskOutput {
            commit: git_head(&workspace),
            ..source_output.clone()
        });
        task.writer_correction_assignment = Some(WriterCorrectionAssignment {
            schema_version: WRITER_CORRECTION_ASSIGNMENT_SCHEMA_VERSION,
            work_item_id: work.clone(),
            attempt_id: "attempt-1".into(),
            writer_task_id: id.clone(),
            source_task_id: source_id.clone(),
            source_candidate_commit: source_candidate.clone(),
            source_task_inputs: vec![],
            evidence: vec![WriterCorrectionAssignmentInput {
                artifact: review_ref.clone(),
                digest: format!("sha256:{:x}", Sha256::digest(&review_bytes)),
            }],
            findings: vec![finding.clone()],
            origin: WriterCorrectionAssignmentOrigin::Captured,
        });
    }
    for task in item.attempts[0]
        .tasks
        .iter()
        .filter(|task| task.kind == TaskKind::Write)
    {
        let findings = task
            .writer_correction_assignment
            .as_ref()
            .map(|a| a.findings.clone())
            .unwrap_or_default();
        let mut matrix =
            WriterCompletionMatrix::skeleton(&contract, &task.id, &findings, None).unwrap();
        matrix.rows[0].state = WriterCompletionState::Complete;
        matrix.rows[0].implementation_evidence = vec!["corrected.txt: correct source".into()];
        matrix.rows[0].verification = vec![WriterVerificationClaim {
            command: "cargo test correction".into(),
            result: WriterVerificationResult::Pass,
        }];
        matrix
            .status_against(&contract, &task.id, &findings)
            .unwrap();
        let area = project.join(&task.artifact_area.as_ref().unwrap().path);
        fs::create_dir_all(&area).unwrap();
        for (name, bytes) in [
            (
                "writer-completion.json",
                serde_json::to_vec_pretty(&matrix).unwrap(),
            ),
            (
                "transcript.jsonl",
                b"{\"fixture\":\"completed Writer\"}\n".to_vec(),
            ),
        ] {
            let path = area.join(name);
            fs::write(&path, &bytes).unwrap();
            protected.push((path, bytes));
        }
    }
    item.attempts[0].status = AttemptStatus::NeedsUser;
    item.attempts[0].pause_kind = Some(PauseKind::WriterCompletion);
    item.attempts[0].review_state = Some(AttemptReviewState::NotReviewed);
    WorkModelStore::new(&project)
        .create_work_item(&item)
        .unwrap();
    let evidence = tmp.path().join("host-proof.json");
    fs::write(&evidence, serde_json::to_vec_pretty(&serde_json::json!({
        "schema_version": 1, "producer": "fixture host", "check": "cargo test exact_host_check",
        "working_directory": ".", "result": "pass", "run_at": now_iso8601(), "output": "host check passed"
    })).unwrap()).unwrap();
    CarriedFindingFixture {
        candidate: git_head(&workspace),
        project,
        workspace,
        work,
        source_candidate,
        finding: finding.id,
        evidence,
        protected,
    }
}

fn carried_finding_attach(fixture: &CarriedFindingFixture) -> LoggedCommand {
    let mut command = fluent_cmd();
    command.current_dir(&fixture.project).args([
        "attempt",
        "evidence",
        "attach",
        &fixture.work,
        "attempt-1",
        "--candidate",
        &fixture.candidate,
        "--finding",
        &fixture.finding,
        "--evidence-file",
        fixture.evidence.to_str().unwrap(),
    ]);
    command
}

struct CombinedRecoveryFixture {
    carried: CarriedFindingFixture,
    original: PathBuf,
    input: String,
    assignment_digest: String,
}

// Import a historical mutable binding into synthetic records, then use public
// recovery and attachment routes to create the combined state.
fn combined_recovery_fixture(tmp: &TempDir, frozen: bool) -> CombinedRecoveryFixture {
    let carried = carried_finding_fixture(tmp);
    let input = format!(
        ".fluent/work/progress/{}/attempt-1/progress.md",
        carried.work
    );
    let bytes = b"Original assigned progress\n";
    fs::create_dir_all(carried.project.join(&input).parent().unwrap()).unwrap();
    fs::write(carried.project.join(&input), bytes).unwrap();
    let original = tmp
        .path()
        .canonicalize()
        .unwrap()
        .join("original-context.md");
    fs::write(&original, bytes).unwrap();
    let artifact = serde_json::json!({"producer_id": "required-progress", "path": input});
    for round in 1..=4 {
        let record = carried.project.join(format!(
            ".fluent/work/tasks/{}/attempt-1/attempt-1-write-{round}.json",
            carried.work
        ));
        let mut task = read_json_path(&record);
        if round == 1 {
            task["input_artifacts"] = serde_json::json!([artifact]);
        } else {
            task["writer_correction_assignment"]["schema_version"] = 1.into();
            task["writer_correction_assignment"]["source_task_inputs"] = serde_json::json!([{
                "artifact": artifact,
                "digest": format!("sha256:{:x}", Sha256::digest(bytes))
            }]);
        }
        write_json_path(&record, &task);
    }
    let store = WorkModelStore::new(&carried.project);
    let item = store.read_work_item_snapshot(&carried.work).unwrap();
    let assignment = item.attempts[0]
        .tasks
        .last()
        .unwrap()
        .writer_correction_assignment
        .as_ref()
        .unwrap();
    let fixture = CombinedRecoveryFixture {
        assignment_digest: format!(
            "sha256:{:x}",
            Sha256::digest(serde_json::to_vec(assignment).unwrap())
        ),
        carried,
        original,
        input,
    };
    if frozen {
        combined_recovery_command(&fixture).assert().success();
        fs::write(
            fixture.carried.project.join(&fixture.input),
            "Later progress\n",
        )
        .unwrap();
    }
    carried_finding_attach(&fixture.carried).assert().success();
    fixture
}

fn combined_recovery_command(fixture: &CombinedRecoveryFixture) -> LoggedCommand {
    let mut command = fluent_cmd();
    command.current_dir(&fixture.carried.project).args([
        "attempt",
        "recover-assignment-context",
        &fixture.carried.work,
        "attempt-1",
        "--task",
        "attempt-1-write-4",
        "--candidate",
        &fixture.carried.candidate,
        "--assignment-digest",
        &fixture.assignment_digest,
        "--input",
        &fixture.input,
        "--original-file",
        fixture.original.to_str().unwrap(),
        "--resolution",
        "Preserve the proven original context and carried evidence",
    ]);
    command
}

// Import the incident's historical setup state, never live Work identifiers.
// The completed candidate and accepted carried proof come from public routes.
fn output_free_context_fixture(tmp: &TempDir) -> CombinedRecoveryFixture {
    output_free_context_fixture_with_coder(tmp, fluent::coder::CoderKind::Claude)
}

fn output_free_context_fixture_with_coder(
    tmp: &TempDir,
    coder: fluent::coder::CoderKind,
) -> CombinedRecoveryFixture {
    use fluent::work_model::*;
    let mut fixture = combined_recovery_fixture(tmp, false);
    combined_recovery_accept_finding(&fixture, &tmp.path().join("provider"));
    let carried = &fixture.carried;
    let store = WorkModelStore::new(&carried.project);
    let mut item = store.read_work_item_snapshot(&carried.work).unwrap();
    item.attempts[0].coder_mapping.write.coder = coder;
    item.attempts[0]
        .tasks
        .iter_mut()
        .find(|t| t.id == "attempt-1-write-4")
        .unwrap()
        .input_artifacts = vec![ArtifactRef {
        producer_id: "required-progress".into(),
        path: fixture.input.clone(),
    }];
    item.add_final_tester_task("attempt-1").unwrap();
    let tester = item.attempts[0].tasks.last_mut().unwrap();
    tester.id = "attempt-1-tester-3".into();
    tester.status = TaskStatus::Complete;
    tester.artifact_area.as_mut().unwrap().path =
        work_artifact_path(&carried.work, "attempt-1", &tester.id);
    let tester_area = carried
        .project
        .join(&tester.artifact_area.as_ref().unwrap().path);
    fs::create_dir_all(tester_area.join("commands")).unwrap();
    fs::write(
        tester_area.join("commands/0-stdout.log"),
        "Two structured cancellation failures\n",
    )
    .unwrap();
    fs::write(tester_area.join("commands/0-stderr.log"), "").unwrap();
    let task_id = item.add_next_write_round("attempt-1", vec![]).unwrap();
    assert_eq!(task_id, "attempt-1-write-5");
    let source = item.attempts[0]
        .tasks
        .iter()
        .find(|t| t.id == "attempt-1-write-4")
        .unwrap()
        .clone();
    let task = item.attempts[0].tasks.last_mut().unwrap();
    task.status = TaskStatus::NeedsUser;
    let area = carried
        .project
        .join(&task.artifact_area.as_ref().unwrap().path);
    fs::create_dir_all(&area).unwrap();
    let evidence = ArtifactRef {
        producer_id: "attempt-1-tester-3".into(),
        path: work_artifact_path(
            &carried.work,
            "attempt-1",
            "attempt-1-tester-3/tester-results.json",
        ),
    };
    let results = serde_json::json!({
        "candidate_commit":carried.candidate,
        "commands":[{"command":"true","test_harness":"shell-harness","exit_code":1,"duration_ms":1,
            "stdout_log":"commands/0-stdout.log","stderr_log":"commands/0-stderr.log"}],
        "tests":[{"id":"cancel_during_startup","test_harness":"shell-harness","status":"fail"},
            {"id":"cancel_stops_each_stage","test_harness":"shell-harness","status":"fail"}],
        "summary":{"total":2,"pass":0,"fail":2,"skipped":0},"error":null
    });
    fs::create_dir_all(carried.project.join(&evidence.path).parent().unwrap()).unwrap();
    write_json_path(&carried.project.join(&evidence.path), &results);
    let findings = ["cancel_during_startup", "cancel_stops_each_stage"]
        .map(|name| WriterCompletionFinding {
            id: format!("finding:verification:{name}"),
            role: "verification".into(),
            source: evidence.path.clone(),
            requirement: format!("Resolve failed Tester case {name}"),
        })
        .to_vec();
    let assignment = WriterCorrectionAssignment {
        schema_version: 1,
        work_item_id: carried.work.clone(),
        attempt_id: "attempt-1".into(),
        writer_task_id: task_id.clone(),
        source_task_id: source.id,
        source_candidate_commit: carried.candidate.clone(),
        source_task_inputs: source
            .writer_correction_assignment
            .unwrap()
            .source_task_inputs,
        evidence: vec![WriterCorrectionAssignmentInput {
            digest: format!(
                "sha256:{:x}",
                Sha256::digest(fs::read(carried.project.join(&evidence.path)).unwrap())
            ),
            artifact: evidence.clone(),
        }],
        findings: findings.clone(),
        origin: WriterCorrectionAssignmentOrigin::Captured,
    };
    task.writer_correction_assignment = Some(assignment);
    task.input_artifacts = vec![evidence];
    let matrix = WriterCompletionMatrix::skeleton(
        item.attempts[0]
            .writer_completion_contract
            .as_ref()
            .unwrap(),
        &task_id,
        &findings,
        None,
    )
    .unwrap();
    fs::write(
        area.join("writer-completion.json"),
        serde_json::to_vec_pretty(&matrix).unwrap(),
    )
    .unwrap();
    item.attempts[0].status = AttemptStatus::NeedsUser;
    item.attempts[0].pause_kind = Some(PauseKind::WriterCompletion);
    store.write_work_item(&item).unwrap();
    fluent_cmd()
        .current_dir(&carried.project)
        .args([
            "attempt",
            "repair-writer-completion",
            &carried.work,
            "attempt-1",
            "--resolution",
            "Retry the original assigned Writer",
        ])
        .assert()
        .success();
    let mut item = store.read_work_item_snapshot(&carried.work).unwrap();
    let task = item.attempts[0].tasks.last_mut().unwrap();
    task.status = TaskStatus::Failed;
    task.started_at = Some("2026-09-16T22:18:32.168777+00:00".into());
    task.completed_at = Some("2026-09-16T22:18:34.067948+00:00".into());
    // A previous transcript may survive; it is not proof of this setup's launch.
    fs::write(
        area.join("transcript.jsonl"),
        "{\"historical\":\"earlier Writer session\"}\n",
    )
    .unwrap();
    write_json_path(
        &area.join("execution.json"),
        &serde_json::json!({
            "schema_version":1, "state":"launching", "owner_pid":2147483647u32,
            "leader_pid":0, "process_group_id":0,
            "started_at":"2026-09-16T22:18:32.168405+00:00",
            "heartbeat_at":"2026-09-16T22:18:32.168405+00:00",
            "attempt_owner":{"project_root":carried.project,"work_item_id":carried.work,"attempt_id":"attempt-1"}
        }),
    );
    fixture.assignment_digest = format!(
        "sha256:{:x}",
        Sha256::digest(
            serde_json::to_vec(task.writer_correction_assignment.as_ref().unwrap()).unwrap()
        )
    );
    item.add_next_write_round("attempt-1", vec![]).unwrap();
    let duplicate = item.attempts[0].tasks.last_mut().unwrap();
    let mut historical = source_assignment_for_duplicate(&store, &carried.work);
    historical.writer_task_id = duplicate.id.clone();
    duplicate.writer_correction_assignment = Some(historical);
    item.attempts[0].status = AttemptStatus::NeedsUser;
    item.attempts[0].pause_kind = Some(PauseKind::RoundCap);
    store.write_work_item(&item).unwrap();
    fs::write(
        carried.project.join(&fixture.input),
        b"Original assigned progress\n\nLater diagnosis\n",
    )
    .unwrap();
    fixture
}

fn source_assignment_for_duplicate(
    store: &WorkModelStore,
    work: &str,
) -> WriterCorrectionAssignment {
    store.read_work_item_snapshot(work).unwrap().attempts[0]
        .tasks
        .iter()
        .find(|t| t.id == "attempt-1-write-4")
        .unwrap()
        .writer_correction_assignment
        .clone()
        .unwrap()
}

fn output_free_context_command(fixture: &CombinedRecoveryFixture) -> LoggedCommand {
    let mut command = fluent_cmd();
    command.current_dir(&fixture.carried.project).args([
        "attempt",
        "recover-assignment-context",
        &fixture.carried.work,
        "attempt-1",
        "--task",
        "attempt-1-write-5",
        "--candidate",
        &fixture.carried.candidate,
        "--assignment-digest",
        &fixture.assignment_digest,
        "--input",
        &fixture.input,
        "--original-file",
        fixture.original.to_str().unwrap(),
        "--resolution",
        "Preserve the proven original context and carried evidence",
    ]);
    command
}

