#[test]
fn assignment_context_recovery_output_free_reports_next_action() {
    let tmp = TempDir::new().unwrap();
    let fixture = output_free_context_fixture(&tmp);
    let project = &fixture.carried.project;
    let work = &fixture.carried.work;
    let observe = |blocker: Option<&str>| {
        let before = snapshot_tree(&project.join(".fluent/work"));
        let show = fluent_cmd()
            .current_dir(project)
            .env_remove("FLUENT_QUIET")
            .args(["work-item", "show", work])
            .assert()
            .success();
        let shown: serde_json::Value = serde_json::from_slice(&show.get_output().stdout).unwrap();
        let status = fluent_cmd()
            .current_dir(project)
            .env_remove("FLUENT_QUIET")
            .args(["status"])
            .assert()
            .success();
        assert_eq!(snapshot_tree(&project.join(".fluent/work")), before);
        let action = shown["next-action"].as_str().map(str::to_owned);
        let status_stdout = String::from_utf8_lossy(&status.get_output().stdout);
        let status_stderr = String::from_utf8_lossy(&status.get_output().stderr);
        let show_stderr = String::from_utf8_lossy(&show.get_output().stderr);
        if let Some(blocker) = blocker {
            assert!(
                action.is_none(),
                "blocked recovery must withhold its action"
            );
            assert!(status_stdout.contains(blocker), "{status_stdout}");
            assert!(
                shown["recovery-blocker"]
                    .as_str()
                    .is_some_and(|reason| reason.contains(blocker)),
                "{shown}"
            );
            for output in [&status_stdout, &status_stderr, &show_stderr] {
                for ineligible in [
                    "fluent attempt run",
                    "fluent queue resume",
                    "→ Next:",
                    "next-action:",
                ] {
                    assert!(!output.contains(ineligible), "{output}");
                }
            }
        } else if let Some(action) = &action {
            for output in [&status_stdout, &status_stderr, &show_stderr] {
                assert!(output.contains(action), "{output} lacks {action}");
            }
            assert!(shown["recovery-blocker"].is_null(), "{shown}");
        }
        action
    };
    let action = observe(None).expect("exact context recovery guidance");
    for expected in [
        "recover-assignment-context",
        "attempt-1-write-5",
        &fixture.carried.candidate,
        &fixture.assignment_digest,
        &fixture.input,
        "--original-file",
    ] {
        assert!(action.contains(expected), "{action} lacks {expected}");
    }
    let recovered = output_free_context_command(&fixture).assert().success();
    let action = observe(None).expect("separate authorization guidance");
    assert!(
        action.starts_with("fluent attempt repair-writer-completion "),
        "{action}"
    );
    assert!(String::from_utf8_lossy(&recovered.get_output().stdout).contains(&action));
    output_free_retry_command(&fixture).assert().success();
    assert_eq!(
        observe(None).unwrap(),
        format!("fluent attempt run {work} attempt-1")
    );
    let dirty = fixture
        .carried
        .workspace
        .join("changed-after-authorization.txt");
    fs::write(&dirty, "candidate drift").unwrap();
    observe(Some("completion retry candidate changed or is dirty"));
    fs::remove_file(dirty).unwrap();
    assert_eq!(
        observe(None).unwrap(),
        format!("fluent attempt run {work} attempt-1")
    );
    fluent_cmd()
        .current_dir(project)
        .args(["attempt", "cancel", work, "attempt-1"])
        .assert()
        .success();
    assert!(
        observe(Some(
            "a later cancellation invalidates context retry authority"
        ))
        .is_none(),
        "cancellation must withhold retry guidance"
    );
}

#[test]
fn assignment_context_recovery_output_free_preserves_state() {
    let tmp = TempDir::new().unwrap();
    let fixture = output_free_context_fixture(&tmp);
    let carried = &fixture.carried;
    let store = WorkModelStore::new(&carried.project);
    let before = store.read_work_item_snapshot(&carried.work).unwrap();
    let artifacts = snapshot_tree(&carried.project.join(".fluent/work/artifacts"));
    let progress = fs::read(carried.project.join(&fixture.input)).unwrap();
    output_free_context_command(&fixture).assert().success();
    let after = store.read_work_item_snapshot(&carried.work).unwrap();
    let mut expected = before.attempts[0].clone();
    let changed = after.attempts[0]
        .tasks
        .iter()
        .find(|t| t.id == "attempt-1-write-5")
        .unwrap();
    expected
        .tasks
        .iter_mut()
        .find(|t| t.id == changed.id)
        .unwrap()
        .writer_correction_assignment = changed.writer_correction_assignment.clone();
    expected.artifacts = after.attempts[0].artifacts.clone();
    expected.recovery_operations = after.attempts[0].recovery_operations.clone();
    expected.pause_record = after.attempts[0].pause_record.clone();
    assert_eq!(after.attempts[0], expected);
    let binding = &changed
        .writer_correction_assignment
        .as_ref()
        .unwrap()
        .source_task_inputs[0];
    assert_eq!(
        fs::read(carried.project.join(&binding.artifact.path)).unwrap(),
        fs::read(&fixture.original).unwrap()
    );
    assert_eq!(
        fs::read(carried.project.join(&fixture.input)).unwrap(),
        progress
    );
    let after_artifacts = snapshot_tree(&carried.project.join(".fluent/work/artifacts"));
    for entry in artifacts {
        assert!(
            after_artifacts.contains(&entry),
            "changed historical artifact: {entry:?}"
        );
    }
    assert_eq!(git_head(&carried.workspace), carried.candidate);
}

#[test]
fn assignment_context_recovery_output_free_rejects_drift() {
    for defect in [
        "unchanged-context",
        "original",
        "assignment",
        "evidence",
        "authority",
        "owner",
        "execution-lease",
        "task-lease",
        "malformed-lock",
        "malformed-learner-lock",
        "later-directory",
        "later-file",
        "later-start",
        "candidate",
        "running",
        "identity",
    ] {
        let tmp = TempDir::new().unwrap();
        let mut fixture = output_free_context_fixture(&tmp);
        let carried = &fixture.carried;
        let task_path = carried.project.join(format!(
            ".fluent/work/tasks/{}/attempt-1/attempt-1-write-5.json",
            carried.work
        ));
        let task = read_json_path(&task_path);
        let area = carried
            .project
            .join(task["artifact_area"]["path"].as_str().unwrap());
        let mut lease = None;
        match defect {
            "unchanged-context" => fs::write(
                carried.project.join(&fixture.input),
                fs::read(&fixture.original).unwrap(),
            )
            .unwrap(),
            "original" => fs::write(&fixture.original, "wrong original").unwrap(),
            "assignment" => fixture.assignment_digest = "sha256:wrong".into(),
            "evidence" => fs::write(
                carried.project.join(
                    task["writer_correction_assignment"]["evidence"][0]["artifact"]["path"]
                        .as_str()
                        .unwrap(),
                ),
                "changed evidence",
            )
            .unwrap(),
            "authority" => fs::write(
                carried
                    .project
                    .join(task["input_artifacts"][1]["path"].as_str().unwrap()),
                "{}",
            )
            .unwrap(),
            "owner" | "running" | "identity" => {
                let path = area.join("execution.json");
                let mut record = read_json_path(&path);
                match defect {
                    "owner" => record["owner_pid"] = std::process::id().into(),
                    "running" => record["state"] = "running".into(),
                    _ => record["attempt_owner"]["attempt_id"] = "attempt-other".into(),
                }
                write_json_path(&path, &record);
            }
            "execution-lease" | "task-lease" | "malformed-lock" => {
                let path = if defect == "task-lease" {
                    fluent::lease::task_lock_path(
                        &carried.project,
                        &carried.work,
                        "attempt-1-write-5",
                    )
                } else {
                    area.join("execution-owner.lock")
                };
                if defect == "malformed-lock" {
                    fs::create_dir_all(path).unwrap();
                } else {
                    lease = Some(fluent::lease::acquire_blocking(&path).unwrap());
                }
            }
            "malformed-learner-lock" => {
                fs::create_dir_all(fluent::lease::learner_lock_path(
                    &carried.project,
                    &carried.work,
                    "attempt-1",
                ))
                .unwrap();
            }
            "later-directory" | "later-file" => {
                let path = carried.project.join(format!(
                    ".fluent/work/artifacts/{}/attempt-1/attempt-1-write-6",
                    carried.work
                ));
                if defect == "later-directory" {
                    fs::create_dir_all(path).unwrap();
                } else {
                    fs::write(path, "malformed").unwrap();
                }
            }
            "later-start" => {
                let path = carried.project.join(format!(
                    ".fluent/work/tasks/{}/attempt-1/attempt-1-write-6.json",
                    carried.work
                ));
                let mut value = read_json_path(&path);
                value["started_at"] = "2026-09-16T23:00:00Z".into();
                write_json_path(&path, &value);
            }
            "candidate" => commit_file(
                &carried.workspace,
                "drift.txt",
                "changed",
                "Change candidate",
            ),
            _ => unreachable!(),
        }
        let before = snapshot_tree(&carried.project.join(".fluent/work"));
        let head = git_head(&carried.workspace);
        output_free_context_command(&fixture).assert().failure();
        assert_eq!(
            snapshot_tree(&carried.project.join(".fluent/work")),
            before,
            "{defect}"
        );
        assert_eq!(git_head(&carried.workspace), head);
        drop(lease);
    }
}

#[test]
fn assignment_context_recovery_output_free_replays_safely() {
    for phase in ["audit", "journal", "children", "attempt", "task", "none"] {
        let tmp = TempDir::new().unwrap();
        let fixture = output_free_context_fixture(&tmp);
        let carried = &fixture.carried;
        if phase != "none" {
            output_free_context_command(&fixture)
                .env("FLUENT_TEST_ASSIGNMENT_CONTEXT_INTERRUPT", phase)
                .assert()
                .code(86);
        }
        output_free_context_command(&fixture).assert().success();
        let published = snapshot_tree(&carried.project.join(".fluent/work"));
        output_free_context_command(&fixture).assert().success();
        assert_eq!(
            snapshot_tree(&carried.project.join(".fluent/work")),
            published
        );
        fluent_cmd()
            .current_dir(&carried.project)
            .args(["attempt", "cancel", &carried.work, "attempt-1"])
            .assert()
            .success();
        let stopped = snapshot_tree(&carried.project.join(".fluent/work"));
        output_free_context_command(&fixture).assert().success();
        assert_eq!(
            snapshot_tree(&carried.project.join(".fluent/work")),
            stopped
        );
    }
    // The publication pins the native failure bytes, not just its current shape.
    let tmp = TempDir::new().unwrap();
    let fixture = output_free_context_fixture(&tmp);
    output_free_context_command(&fixture)
        .env("FLUENT_TEST_ASSIGNMENT_CONTEXT_INTERRUPT", "audit")
        .assert()
        .code(86);
    let path = fixture.carried.project.join(format!(
        ".fluent/work/artifacts/{}/attempt-1/attempt-1-write-5/transcript.jsonl",
        fixture.carried.work
    ));
    fs::write(path, "changed historical transcript\n").unwrap();
    let before = snapshot_tree(&fixture.carried.project.join(".fluent/work"));
    output_free_context_command(&fixture).assert().failure();
    assert_eq!(
        snapshot_tree(&fixture.carried.project.join(".fluent/work")),
        before
    );
}

