#[test]
fn combined_recovery_rejects_changed_context_authority() {
    for defect in [
        "original-bytes",
        "candidate",
        "assignment-digest",
        "pending-review",
        "unfinished-writer",
    ] {
        let tmp = TempDir::new().unwrap();
        let mut fixture = combined_recovery_fixture(&tmp, false);
        if defect != "pending-review" {
            combined_recovery_accept_finding(&fixture, &tmp.path().join("provider"));
        }
        fs::write(
            fixture.carried.project.join(&fixture.input),
            "Later progress\n",
        )
        .unwrap();
        let diagnostic = match defect {
            "original-bytes" => {
                fs::write(&fixture.original, "Replacement context\n").unwrap();
                "original bytes do not match"
            }
            "candidate" => {
                fixture.carried.candidate = fixture.carried.source_candidate.clone();
                "candidate is stale"
            }
            "assignment-digest" => {
                fixture.assignment_digest = format!("sha256:{}", "0".repeat(64));
                "saved assignment digest does not match"
            }
            "pending-review" => "Attempt has unresolved Tasks",
            "unfinished-writer" => {
                let path = fixture.carried.project.join(format!(
                    ".fluent/work/tasks/{}/attempt-1/attempt-1-write-4.json",
                    fixture.carried.work
                ));
                let mut record = read_json_path(&path);
                record["status"] = "planned".into();
                record.as_object_mut().unwrap().remove("output");
                record.as_object_mut().unwrap().remove("completed_at");
                write_json_path(&path, &record);
                "recovery requires the latest completed Writer"
            }
            _ => unreachable!(),
        };
        let before = snapshot_tree(&fixture.carried.project.join(".fluent/work"));
        let head = git_head(&fixture.carried.workspace);
        combined_recovery_command(&fixture)
            .assert()
            .failure()
            .stderr(predicate::str::contains(diagnostic));
        assert_eq!(
            snapshot_tree(&fixture.carried.project.join(".fluent/work")),
            before,
            "{defect}"
        );
        assert_eq!(git_head(&fixture.carried.workspace), head);
    }

    // Accepted evidence must not outlive changed audit, snapshot, or proof
    // bytes. Queue admission exercises the common validation before mutation.
    for defect in [
        "audit",
        "operation",
        "snapshot",
        "provenance",
        "proof",
        "binding",
        "source-review",
    ] {
        let tmp = TempDir::new().unwrap();
        let fixture = combined_recovery_fixture(&tmp, false);
        combined_recovery_accept_finding(&fixture, &tmp.path().join("provider"));
        let carried = &fixture.carried;
        fs::write(carried.project.join(&fixture.input), "Later progress\n").unwrap();
        combined_recovery_command(&fixture).assert().success();
        let item = WorkModelStore::new(&carried.project)
            .read_work_item_snapshot(&carried.work)
            .unwrap();
        let attempt = &item.attempts[0];
        let writer = attempt
            .tasks
            .iter()
            .find(|t| t.id == "attempt-1-write-4")
            .unwrap();
        let assignment = writer.writer_correction_assignment.as_ref().unwrap();
        let recovery = &attempt.evidence_recoveries[0];
        let path = match defect {
            "audit" => attempt
                .artifacts
                .iter()
                .find(|a| a.producer_id == "assignment-context-recovery")
                .unwrap()
                .path
                .clone(),
            "operation" => format!(".fluent/work/attempts/{}/attempt-1.json", carried.work),
            "snapshot" => assignment.source_task_inputs[0].artifact.path.clone(),
            "provenance" => assignment.evidence.last().unwrap().artifact.path.clone(),
            "proof" => recovery.attachment.snapshot_path.clone(),
            "binding" => serde_json::to_value(&recovery.carried_finding.as_ref().unwrap().artifact)
                .unwrap()["path"]
                .as_str()
                .unwrap()
                .to_owned(),
            "source-review" => recovery
                .carried_finding
                .as_ref()
                .unwrap()
                .binding
                .source_review
                .artifact
                .path
                .clone(),
            _ => unreachable!(),
        };
        let path = carried.project.join(path);
        if defect == "audit" || defect == "operation" {
            let mut value = read_json_path(&path);
            if defect == "audit" {
                value["attempt_digest"] = format!("sha256:{}", "0".repeat(64)).into();
            } else {
                value["recovery_operations"]
                    .as_array_mut()
                    .unwrap()
                    .retain(|r| r["operation-kind"] != "assignment-context-recovery");
            }
            write_json_path(&path, &value);
        } else {
            let mut bytes = fs::read(&path).unwrap();
            bytes.push(b'\n');
            fs::write(&path, bytes).unwrap();
        }
        drop(fluent::queue::lock_queue(&carried.project).unwrap());
        let before = snapshot_tree(&carried.project.join(".fluent/work"));
        fluent_cmd()
            .current_dir(&carried.project)
            .args(["queue", "resume", &carried.work, "--attempt", "attempt-1"])
            .assert()
            .failure();
        assert!(
            snapshot_tree(&carried.project.join(".fluent/work")) == before,
            "{defect}: rejection changed protected Work history"
        );
        assert_eq!(git_head(&carried.workspace), carried.candidate);
    }
}

fn combined_recovery_old_readers() -> [(&'static str, PathBuf); 3] {
    [
        (
            "assignment",
            "FLUENT_COMBINED_ASSIGNMENT_OLD_BIN",
            "c918cfe24ae190e4fd1b5bd29d49dd8ca91ed73e",
        ),
        (
            "base",
            "FLUENT_COMBINED_BASE_OLD_BIN",
            "fe6b6f607609fbf424daf6ce2224cd51fdf30f74",
        ),
        (
            "evidence",
            "FLUENT_COMBINED_EVIDENCE_OLD_BIN",
            "25cb3c7d741cb0d226e09dba7b1a32f9af66f046",
        ),
    ]
    .map(|(name, variable, source)| {
        let binary = writer_assignment_old_reader(variable, source);
        let identity = binary
            .parent()
            .unwrap()
            .parent()
            .unwrap()
            .parent()
            .unwrap()
            .join("identity.json");
        let archive =
            git::run_raw(Path::new(env!("CARGO_MANIFEST_DIR")), &["archive", source]).unwrap();
        assert!(archive.status.success());
        assert_eq!(
            read_json_path(&identity)["source_archive_sha256"],
            format!("{:x}", Sha256::digest(archive.stdout))
        );
        (name, binary)
    })
}

// Start a feature-specific fixture at a supported predecessor envelope. That
// exact executable then authors the feature mutation and any pending journal.
fn combined_recovery_import_predecessor(project: &Path, work: &str, name: &str) {
    let store = WorkModelStore::new(project);
    let path = store.work_item_path(work).unwrap();
    let mut record = read_json_path(&path);
    record["schema_version"] = 7.into();
    record["model_writer_version"]["schema_version"] = if name == "assignment" {
        6.into()
    } else {
        5.into()
    };
    // These pinned predecessors were built from 0.4.0. Their imported records
    // must carry that writer version before the predecessor can mutate them.
    record["model_writer_version"]["version"] = "0.4.0".into();
    write_json_path(&path, &record);
    let path = project.join(format!(".fluent/work/attempts/{work}/attempt-1.json"));
    let mut record = read_json_path(&path);
    record["schema_version"] = 7.into();
    write_json_path(&path, &record);
    for entry in fs::read_dir(project.join(format!(".fluent/work/tasks/{work}/attempt-1"))).unwrap()
    {
        let path = entry.unwrap().path();
        if path.extension().is_none_or(|extension| extension != "json") {
            continue;
        }
        let mut record = read_json_path(&path);
        if record["writer_correction_assignment"].is_object() && name != "assignment" {
            assert!(
                record["writer_correction_assignment"]["source_task_inputs"]
                    .as_array()
                    .is_none_or(|inputs| inputs.is_empty())
            );
            record["writer_correction_assignment"]["schema_version"] = 1.into();
            write_json_path(&path, &record);
        }
    }
}

fn combined_recovery_publish_predecessor(
    binary: &Path,
    project: &Path,
    work: &str,
    args: &[&str],
    pending: bool,
) -> fluent::work_model::WorkItem {
    use std::os::unix::fs::PermissionsExt;
    let tasks = project.join(format!(".fluent/work/tasks/{work}/attempt-1"));
    let permissions = fs::metadata(&tasks).unwrap().permissions();
    if pending {
        fs::set_permissions(&tasks, fs::Permissions::from_mode(0o555)).unwrap();
    }
    let result = Command::new(binary)
        .current_dir(project)
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .args(args)
        .output();
    fs::set_permissions(&tasks, permissions).unwrap();
    let result = result.unwrap();
    assert_eq!(
        result.status.success(),
        !pending,
        "{}",
        String::from_utf8_lossy(&result.stderr)
    );
    if pending {
        let journal =
            read_json_path(&project.join(format!(".fluent/work/transactions/{work}.json")));
        assert!(matches!(journal["schema_version"].as_u64(), Some(6 | 7)));
        serde_json::from_value(journal["work_item"].clone()).unwrap()
    } else {
        assert_eq!(
            read_json_path(&project.join(format!(".fluent/work/items/{work}.json")))["schema_version"],
            7
        );
        WorkModelStore::new(project)
            .read_work_item_snapshot(work)
            .unwrap()
    }
}

fn combined_recovery_assert_predecessor_preserved(
    project: &Path,
    expected: &fluent::work_model::WorkItem,
) {
    let artifacts = snapshot_tree(&project.join(".fluent/work/artifacts"));
    fluent_cmd()
        .current_dir(project)
        .args(["work-item", "upgrade", &expected.id])
        .assert()
        .success();
    let actual = WorkModelStore::new(project)
        .read_work_item_snapshot(&expected.id)
        .unwrap();
    let mut expected_attempts = expected.attempts.clone();
    for (after, before) in actual.attempts.iter().zip(&mut expected_attempts) {
        // Upgrade refreshes derived next-action guidance after publication.
        // Task, candidate, lifecycle, and original pause identity stay bound.
        if let (Some(after), Some(before)) = (&after.pause_record, &mut before.pause_record) {
            before.next_operation = after.next_operation.clone();
            before.no_safe_operation_reason = after.no_safe_operation_reason.clone();
            before.updated_at = after.updated_at.clone();
        }
    }
    assert_eq!(actual.attempts, expected_attempts);
    assert_eq!(actual.transitions, expected.transitions);
    assert_eq!(actual.merge_candidates, expected.merge_candidates);
    let current_artifacts = snapshot_tree(&project.join(".fluent/work/artifacts"));
    for entry in artifacts {
        assert!(
            current_artifacts.contains(&entry),
            "changed predecessor artifact: {:?}",
            entry.path
        );
    }
    assert!(
        !project
            .join(format!(".fluent/work/transactions/{}.json", expected.id))
            .exists()
    );
}

#[test]
fn combined_recovery_preserves_source_version_records() {
    for (name, binary) in combined_recovery_old_readers() {
        for pending in [false, true] {
            match name {
                "base" => {
                    let fixture = usage_limit_fixture();
                    combined_recovery_import_predecessor(&fixture.project, &fixture.work, name);
                    let expected = combined_recovery_publish_predecessor(
                        &binary,
                        &fixture.project,
                        &fixture.work,
                        &[
                            "attempt",
                            "recover-usage-limit",
                            &fixture.work,
                            "attempt-1",
                            "--resolution",
                            "Continue the saved correction",
                        ],
                        pending,
                    );
                    assert!(
                        expected.attempts[0]
                            .recovery_operations
                            .iter()
                            .any(|r| r.operation_kind == "usage-limit-writer-approval")
                    );
                    combined_recovery_assert_predecessor_preserved(&fixture.project, &expected);
                    let saved = WorkModelStore::new(&fixture.project)
                        .read_work_item_snapshot(&fixture.work)
                        .unwrap();
                    fixture.approve();
                    assert_eq!(
                        WorkModelStore::new(&fixture.project)
                            .read_work_item_snapshot(&fixture.work)
                            .unwrap(),
                        saved
                    );
                }
                "assignment" => {
                    let (fixture, digest, original) = legacy_assignment_context_fixture();
                    combined_recovery_import_predecessor(&fixture.project_root, "work-1", name);
                    let expected = combined_recovery_publish_predecessor(
                        &binary,
                        &fixture.project_root,
                        "work-1",
                        &[
                            "attempt",
                            "recover-assignment-context",
                            "work-1",
                            "attempt-1",
                            "--task",
                            "attempt-1-write-2",
                            "--candidate",
                            &git_head(&fixture.workspace),
                            "--assignment-digest",
                            &digest,
                            "--input",
                            ".fluent/work/progress/work-1/attempt-1/progress.md",
                            "--original-file",
                            original.to_str().unwrap(),
                            "--resolution",
                            "Retain the proven original progress bytes",
                        ],
                        pending,
                    );
                    assert!(
                        expected.attempts[0]
                            .recovery_operations
                            .iter()
                            .any(|r| r.operation_kind == "assignment-context-recovery")
                    );
                    combined_recovery_assert_predecessor_preserved(
                        &fixture.project_root,
                        &expected,
                    );
                    let saved = WorkModelStore::new(&fixture.project_root)
                        .read_work_item_snapshot("work-1")
                        .unwrap();
                    assignment_context_recovery_command(&fixture, &digest, &original)
                        .assert()
                        .success();
                    assert_eq!(
                        WorkModelStore::new(&fixture.project_root)
                            .read_work_item_snapshot("work-1")
                            .unwrap(),
                        saved
                    );
                }
                "evidence" => {
                    let tmp = TempDir::new().unwrap();
                    let fixture = carried_finding_fixture(&tmp);
                    combined_recovery_import_predecessor(&fixture.project, &fixture.work, name);
                    let expected = combined_recovery_publish_predecessor(
                        &binary,
                        &fixture.project,
                        &fixture.work,
                        &[
                            "attempt",
                            "evidence",
                            "attach",
                            &fixture.work,
                            "attempt-1",
                            "--candidate",
                            &fixture.candidate,
                            "--finding",
                            &fixture.finding,
                            "--evidence-file",
                            fixture.evidence.to_str().unwrap(),
                        ],
                        pending,
                    );
                    assert!(
                        expected.attempts[0].evidence_recoveries[0]
                            .carried_finding
                            .is_some()
                    );
                    combined_recovery_assert_predecessor_preserved(&fixture.project, &expected);
                    let saved = WorkModelStore::new(&fixture.project)
                        .read_work_item_snapshot(&fixture.work)
                        .unwrap();
                    carried_finding_attach(&fixture).assert().success();
                    assert_eq!(
                        WorkModelStore::new(&fixture.project)
                            .read_work_item_snapshot(&fixture.work)
                            .unwrap(),
                        saved
                    );
                }
                _ => unreachable!(),
            }
        }
    }
}

#[test]
fn combined_recovery_older_readers_refuse_mutation() {
    for (name, binary) in combined_recovery_old_readers() {
        for state in [
            "published",
            "attempt-record",
            "context-journal",
            "ordinary-journal",
        ] {
            for inner in [false, true] {
                let tmp = TempDir::new().unwrap();
                let fixture = combined_recovery_fixture(&tmp, state != "context-journal");
                let carried = &fixture.carried;
                if state == "context-journal" {
                    combined_recovery_accept_finding(&fixture, &tmp.path().join("provider"));
                    fs::write(carried.project.join(&fixture.input), "Later progress\n").unwrap();
                    combined_recovery_command(&fixture)
                        .env("FLUENT_TEST_ASSIGNMENT_CONTEXT_INTERRUPT", "journal")
                        .assert()
                        .code(86);
                } else if state == "ordinary-journal" {
                    fluent_cmd()
                        .current_dir(&carried.project)
                        .env(
                            "FLUENT_TEST_INTERRUPT_CARRIED_FINDING_PUBLICATION",
                            &carried.work,
                        )
                        .args(["attempt", "cancel", &carried.work, "attempt-1"])
                        .assert()
                        .failure()
                        .stderr(predicate::str::contains(
                            "interrupted carried finding publication",
                        ));
                }
                let root = carried.project.join(".fluent/work");
                let path = root.join(format!("items/{}.json", carried.work));
                let original = fs::read(&path).unwrap();
                if inner {
                    let mut value = read_json_path(&path);
                    value["model_writer_version"]["schema_version"] = if name == "assignment" {
                        6.into()
                    } else {
                        5.into()
                    };
                    if state != "published" {
                        value["schema_version"] = 7.into();
                    }
                    write_json_path(&path, &value);
                }
                let before = snapshot_tree(&root);
                for args in [
                    vec!["attempt", "cancel", carried.work.as_str(), "attempt-1"],
                    vec!["work-item", "upgrade", carried.work.as_str()],
                ] {
                    let result = Command::new(&binary)
                        .current_dir(&carried.project)
                        .env("FLUENT_NO_UPDATE_CHECK", "1")
                        .args(&args)
                        .output()
                        .unwrap();
                    assert!(
                        !result.status.success(),
                        "{name} accepted {args:?} for {state}, inner={inner}: {}",
                        String::from_utf8_lossy(&result.stderr)
                    );
                    if inner && state.ends_with("journal") {
                        assert!(
                            String::from_utf8_lossy(&result.stderr)
                                .contains("work item transaction"),
                            "{name}: {}",
                            String::from_utf8_lossy(&result.stderr)
                        );
                    }
                    assert!(
                        snapshot_tree(&root) == before,
                        "{name} changed protected {state} bytes, inner={inner}"
                    );
                }
                fs::write(path, original).unwrap();
                if state == "context-journal" {
                    combined_recovery_command(&fixture).assert().success();
                } else {
                    fluent_cmd()
                        .current_dir(&carried.project)
                        .args(["work-item", "upgrade", &carried.work])
                        .assert()
                        .success();
                }
                assert!(
                    !root
                        .join(format!("transactions/{}.json", carried.work))
                        .exists()
                );
                let item = WorkModelStore::new(&carried.project)
                    .read_work_item_snapshot(&carried.work)
                    .unwrap();
                assert!(
                    item.attempts[0].evidence_recoveries[0]
                        .carried_finding
                        .is_some()
                );
                assert_eq!(
                    item.attempts[0]
                        .tasks
                        .iter()
                        .find(|t| t.id == "attempt-1-write-4")
                        .unwrap()
                        .writer_correction_assignment
                        .as_ref()
                        .unwrap()
                        .schema_version,
                    2
                );
            }
        }
    }
}

fn carried_finding_review(fixture: &CarriedFindingFixture, bin: &Path, report: &str) {
    write_mock_claude(
        bin,
        &format!("#!/bin/sh\ncat > review.md <<'REPORT'\n{report}\nREPORT\n"),
    );
    fluent_cmd()
        .current_dir(&fixture.project)
        .env("PATH", mock_path(bin))
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .assert()
        .success();
}

#[test]
fn carried_finding_evidence_retry_preserves_identity_and_stop() {
    let tmp = TempDir::new().unwrap();
    let fixture = carried_finding_fixture(&tmp);
    let store = WorkModelStore::new(&fixture.project);
    carried_finding_attach(&fixture).assert().success();
    let first = snapshot_tree(&fixture.project.join(".fluent/work"));
    carried_finding_attach(&fixture).assert().success();
    assert_eq!(snapshot_tree(&fixture.project.join(".fluent/work")), first);
    for _ in 0..2 {
        fluent_cmd()
            .current_dir(&fixture.project)
            .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
            .assert()
            .success();
    }
    let ledger = fluent::queue::read_ledger(&fixture.project, &fixture.work)
        .unwrap()
        .unwrap();
    assert_eq!(ledger.dispatches.len(), 1);
    let dispatch = ledger.active().unwrap().dispatch_id.clone();
    let mut proof = read_json_path(&fixture.evidence);
    proof["output"] = serde_json::json!("changed active proof");
    let original = fs::read(&fixture.evidence).unwrap();
    fs::write(&fixture.evidence, serde_json::to_vec(&proof).unwrap()).unwrap();
    let active = snapshot_tree(&fixture.project.join(".fluent/work"));
    carried_finding_attach(&fixture).assert().failure();
    assert_eq!(snapshot_tree(&fixture.project.join(".fluent/work")), active);
    fs::write(&fixture.evidence, original).unwrap();
    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["attempt", "cancel", &fixture.work, "attempt-1"])
        .assert()
        .success();
    let stopped = store.read_work_item(&fixture.work).unwrap();
    assert!(stopped.attempts[0].cancellation_requested());
    carried_finding_attach(&fixture).assert().success();
    assert_eq!(store.read_work_item(&fixture.work).unwrap(), stopped);
    fluent_cmd()
        .current_dir(&fixture.project)
        .args([
            "attempt",
            "run",
            &fixture.work,
            "attempt-1",
            "--dispatch-id",
            &dispatch,
            "--no-sandbox",
        ])
        .assert()
        .failure();
    assert!(store.read_work_item(&fixture.work).unwrap().attempts[0].cancellation_requested());
    let bin = tmp.path().join("bin");
    write_mock_claude(
        &bin,
        &learner_mock_script(r#"{"schema_version":1,"observations":[],"work_items":[]}"#),
    );
    fluent_cmd()
        .current_dir(&fixture.project)
        .env("PATH", mock_path(&bin))
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .assert()
        .success();
    let resumed = store.read_work_item(&fixture.work).unwrap();
    assert!(!resumed.attempts[0].cancellation_requested());
    assert_eq!(resumed.attempts[0].evidence_recoveries.len(), 1);
    assert!(resumed.merge_candidates[0].ready_at.is_some());
    for task in &resumed.attempts[0].tasks {
        assert!(!fluent::lease::is_leased(&fluent::lease::task_lock_path(
            &fixture.project,
            &fixture.work,
            &task.id
        )));
        if let Some(area) = &task.artifact_area {
            assert!(
                !fluent::execution::execution_is_live(
                    &fluent::execution::record_path_for_artifact(&fixture.project, &area.path)
                )
                .unwrap()
            );
        }
    }
    for (path, bytes) in &fixture.protected {
        assert_eq!(fs::read(path).unwrap(), *bytes);
    }
}

#[test]
fn carried_finding_evidence_retry_replaces_failed_or_expired_proof() {
    use fluent::work_model::*;
    for expired in [false, true] {
        let tmp = TempDir::new().unwrap();
        let fixture = carried_finding_fixture_with_request(
            &tmp,
            if expired {
                "Evidence-Command: cargo test exact_host_check\nEvidence-Working-Directory: .\nEvidence-Applicability: {\"freshness\":{\"kind\":\"live-state\",\"max_age_seconds\":600}}\n"
            } else {
                "Evidence-Command: cargo test exact_host_check\nEvidence-Working-Directory: .\n"
            },
        );
        let store = WorkModelStore::new(&fixture.project);
        carried_finding_attach(&fixture).assert().success();
        let first =
            store.read_work_item(&fixture.work).unwrap().attempts[0].evidence_recoveries[0].clone();
        let mut proof = read_json_path(&fixture.evidence);
        let now = chrono::DateTime::parse_from_rfc3339(proof["run_at"].as_str().unwrap()).unwrap()
            + chrono::TimeDelta::seconds(600);
        let now = now.to_rfc3339();
        if !expired {
            carried_finding_review(
                &fixture,
                &tmp.path().join("bin"),
                "Verdict: fail\nDisposition: evidence-needed\nExternal-Condition: host changed\nAdditional-Proof: rerun the check\n\n- [ ] Observe the real host check\n",
            );
        }
        let old = store.read_work_item(&fixture.work).unwrap();
        let target = old.attempts[0].tasks.last().unwrap();
        let report_path = fixture
            .project
            .join(&target.artifact_area.as_ref().unwrap().path)
            .join("review.md");
        let report = fs::read(&report_path).ok();
        let status = fluent_cmd()
            .current_dir(&fixture.project)
            .env("FLUENT_TEST_EVIDENCE_NOW", &now)
            .args(["work-item", "show", &fixture.work])
            .output()
            .unwrap();
        assert!(
            String::from_utf8_lossy(&status.stdout).contains("--finding"),
            "{}",
            String::from_utf8_lossy(&status.stdout)
        );
        if expired {
            carried_finding_attach(&fixture)
                .env("FLUENT_TEST_EVIDENCE_NOW", &now)
                .assert()
                .failure();
        }
        proof["run_at"] = serde_json::json!(now);
        proof["output"] = serde_json::json!("fresh check passed");
        fs::write(&fixture.evidence, serde_json::to_vec(&proof).unwrap()).unwrap();
        let owner = fluent::lease::acquire(&fluent::lease::task_lock_path(
            &fixture.project,
            &fixture.work,
            &target.id,
        ))
        .unwrap();
        carried_finding_attach(&fixture)
            .env("FLUENT_TEST_EVIDENCE_NOW", &now)
            .assert()
            .failure();
        drop(owner);
        carried_finding_attach(&fixture)
            .env("FLUENT_TEST_EVIDENCE_NOW", &now)
            .assert()
            .success();
        let fresh = store.read_work_item(&fixture.work).unwrap();
        assert_eq!(fresh.attempts[0].evidence_recoveries.len(), 2);
        assert_eq!(
            fresh.attempts[0].evidence_recoveries[0].state,
            EvidenceRecoveryState::NeedsEvidence
        );
        assert_ne!(fresh.attempts[0].evidence_recoveries[1].id, first.id);
        assert_eq!(fs::read(&report_path).ok(), report);
        assert_eq!(
            fresh.attempts[0]
                .tasks
                .iter()
                .find(|t| t.id == target.id)
                .unwrap()
                .status,
            if expired {
                TaskStatus::Superseded
            } else {
                TaskStatus::Complete
            }
        );
        carried_finding_attach(&fixture)
            .env("FLUENT_TEST_EVIDENCE_NOW", &now)
            .assert()
            .success();
        assert_eq!(store.read_work_item(&fixture.work).unwrap(), fresh);
        let old_binding = serde_json::to_value(&fresh.attempts[0].evidence_recoveries[0]).unwrap()
            ["carried_finding"]["artifact"]["path"]
            .as_str()
            .unwrap()
            .to_string();
        let history = [&first.attachment.snapshot_path, &old_binding].map(|path| {
            (
                fixture.project.join(path),
                fs::read(fixture.project.join(path)).unwrap(),
            )
        });
        let fresh_target = fresh.attempts[0].evidence_recoveries[1].targets[0]
            .review_task_id
            .as_ref()
            .unwrap();
        let bin = tmp.path().join("bin");
        write_mock_claude(
            &bin,
            &learner_mock_script(r#"{"schema_version":1,"observations":[],"work_items":[]}"#),
        );
        fluent_cmd()
            .current_dir(&fixture.project)
            .env("PATH", mock_path(&bin))
            .env("FLUENT_TEST_EVIDENCE_NOW", &now)
            .args([
                "task",
                "run",
                &fixture.work,
                "attempt-1",
                fresh_target,
                "--no-sandbox",
            ])
            .assert()
            .success();
        let reviewed = store.read_work_item(&fixture.work).unwrap();
        assert!(reviewed.merge_candidates.is_empty());
        assert_eq!(
            reviewed.attempts[0].evidence_recoveries[1].state,
            EvidenceRecoveryState::Reviewing
        );
        fluent_cmd()
            .current_dir(&fixture.project)
            .env("PATH", mock_path(&bin))
            .env("FLUENT_TEST_EVIDENCE_NOW", &now)
            .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
            .assert()
            .success();
        let ready = store.read_work_item(&fixture.work).unwrap();
        let attempt = &ready.attempts[0];
        assert!(
            ready
                .merge_candidates
                .first()
                .is_some_and(|candidate| candidate.ready_at.is_some()),
            "accepted replacement must reach readiness: expired={expired}, status={:?}, pause={:?}",
            attempt.status,
            attempt.pause_kind
        );
        assert_eq!(attempt.evidence_recoveries.len(), 2);
        assert_eq!(
            attempt.evidence_recoveries[0],
            fresh.attempts[0].evidence_recoveries[0]
        );
        assert_eq!(
            attempt.evidence_recoveries[1].state,
            EvidenceRecoveryState::Complete
        );
        assert!(
            attempt.evidence_recoveries[1].targets[0]
                .review_digest
                .is_some()
        );
        assert_eq!(
            attempt
                .tasks
                .iter()
                .filter(|t| t.kind == TaskKind::Write)
                .count(),
            4
        );
        for role in review::REVIEWERS {
            assert!(
                attempt.tasks.iter().any(|t| t.kind == TaskKind::Review
                    && t.role == *role
                    && t.status == TaskStatus::Complete
                    && t.evidence_review_context.is_none()
                    && t.review_context
                        .as_ref()
                        .is_some_and(|c| c.candidate_commit == fixture.candidate)),
                "ordinary {role} Review must run after accepting replacement proof"
            );
        }
        assert!(attempt.tasks.iter().any(|t| {
            t.kind == TaskKind::Tester
                && t.status == TaskStatus::Complete
                && t.review_context
                    .as_ref()
                    .is_some_and(|c| c.candidate_commit == fixture.candidate)
        }));
        assert_eq!(
            attempt.learning.as_ref().unwrap().status,
            LearningStatus::Succeeded
        );
        assert_eq!(
            attempt.tasks.iter().find(|t| t.id == target.id),
            fresh.attempts[0].tasks.iter().find(|t| t.id == target.id)
        );
        assert_eq!(fs::read(&report_path).ok(), report);
        for (path, bytes) in history {
            assert_eq!(fs::read(path).unwrap(), bytes);
        }
        for (path, bytes) in &fixture.protected {
            assert_eq!(fs::read(path).unwrap(), *bytes);
        }
    }
}

#[test]
fn carried_finding_evidence_retry_code_change_keeps_source_authority() {
    use fluent::work_model::*;
    let tmp = TempDir::new().unwrap();
    let fixture = carried_finding_fixture(&tmp);
    let store = WorkModelStore::new(&fixture.project);
    let original = store.read_work_item(&fixture.work).unwrap();
    carried_finding_attach(&fixture).assert().success();
    let bin = tmp.path().join("bin");
    write_mock_claude(
        &bin,
        r#"#!/bin/sh
if [ "$FLUENT_TASK_KIND" = write ]; then exit 42; fi
cat > review.md <<'REPORT'
Verdict: fail
Disposition: code-change

- [ ] Correct the current candidate before checking the host
REPORT
"#,
    );
    fluent_cmd()
        .current_dir(&fixture.project)
        .env("PATH", mock_path(&bin))
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .assert()
        .failure();
    let item = store.read_work_item(&fixture.work).unwrap();
    let recovery = &item.attempts[0].evidence_recoveries[0];
    assert_eq!(recovery.state, EvidenceRecoveryState::CodeChange);
    let writer = item.attempts[0]
        .tasks
        .iter()
        .rev()
        .find(|t| t.kind == TaskKind::Write)
        .unwrap();
    let assignment = writer.writer_correction_assignment.as_ref().unwrap();
    assert_eq!(assignment.source_candidate_commit, fixture.candidate);
    assert_eq!(
        assignment.source_task_id,
        original.attempts[0].tasks.last().unwrap().id
    );
    assert_eq!(assignment.findings.len(), 1);
    assert_ne!(assignment.findings[0].id, fixture.finding);
    assert!(
        assignment
            .evidence
            .iter()
            .any(|a| Some(a.artifact.producer_id.as_str())
                == recovery.targets[0].review_task_id.as_deref())
    );
    assert!(item.merge_candidates.is_empty());
    for old in &original.attempts[0].tasks {
        assert_eq!(
            item.attempts[0]
                .tasks
                .iter()
                .find(|t| t.id == old.id)
                .unwrap(),
            old
        );
    }
    for (path, bytes) in &fixture.protected {
        assert_eq!(fs::read(path).unwrap(), *bytes);
    }
    for task in &item.attempts[0].tasks {
        assert!(!fluent::lease::is_leased(&fluent::lease::task_lock_path(
            &fixture.project,
            &fixture.work,
            &task.id
        )));
        let area = fixture
            .project
            .join(&task.artifact_area.as_ref().unwrap().path);
        let path = area.join("execution.json");
        if path.exists() {
            let execution: fluent::execution::ExecutionRecord =
                serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();
            assert!(
                execution.settled_at.is_some(),
                "execution must settle before cleanup: {execution:?}"
            );
            assert!(
                poll_until(std::time::Duration::from_secs(3), || {
                    !fluent::execution::execution_is_live(&path).unwrap()
                        && unsafe { libc::kill(execution.leader_pid as i32, 0) } != 0
                        && unsafe { libc::kill(execution.owner_pid as i32, 0) } != 0
                }),
                "execution processes must exit before cleanup: {execution:?}"
            );
        }
    }
    carried_finding_attach(&fixture).assert().failure();
}

fn interrupt_carried_finding_attachment(fixture: &CarriedFindingFixture) -> PathBuf {
    carried_finding_attach(fixture)
        .env(
            "FLUENT_TEST_INTERRUPT_CARRIED_FINDING_PUBLICATION",
            &fixture.work,
        )
        .assert()
        .failure()
        .stderr(predicate::str::contains(
            "interrupted carried finding publication",
        ));
    let journal = fixture
        .project
        .join(format!(".fluent/work/transactions/{}.json", fixture.work));
    let transaction = read_json_path(&journal);
    assert!(
        transaction["work_item"]["attempts"][0]["evidence_recoveries"][0]["carried_finding"]
            .is_object()
    );
    journal
}

#[test]
fn carried_finding_evidence_retry_recovers_interrupted_publication() {
    let tmp = TempDir::new().unwrap();
    let fixture = carried_finding_fixture(&tmp);
    let journal = interrupt_carried_finding_attachment(&fixture);
    let transaction = read_json_path(&journal);
    let artifacts = snapshot_tree(
        &fixture
            .project
            .join(format!(".fluent/work/artifacts/{}/attempt-1", fixture.work)),
    );
    let original = fs::read(&fixture.evidence).unwrap();
    let mut changed = read_json_path(&fixture.evidence);
    changed["output"] = serde_json::json!("different proof");
    fs::write(&fixture.evidence, serde_json::to_vec(&changed).unwrap()).unwrap();
    let interrupted = snapshot_tree(&fixture.project.join(".fluent/work"));
    carried_finding_attach(&fixture).assert().failure();
    assert_eq!(
        snapshot_tree(&fixture.project.join(".fluent/work")),
        interrupted
    );
    fs::write(&fixture.evidence, original).unwrap();
    carried_finding_attach(&fixture).assert().success();
    assert!(!journal.exists());
    let item = WorkModelStore::new(&fixture.project)
        .read_work_item(&fixture.work)
        .unwrap();
    assert_eq!(
        serde_json::to_value(&item.attempts[0].evidence_recoveries).unwrap(),
        transaction["work_item"]["attempts"][0]["evidence_recoveries"]
    );
    assert_eq!(
        serde_json::to_value(&item.attempts[0].tasks).unwrap(),
        transaction["work_item"]["attempts"][0]["tasks"]
    );
    assert_eq!(
        snapshot_tree(
            &fixture
                .project
                .join(format!(".fluent/work/artifacts/{}/attempt-1", fixture.work))
        ),
        artifacts
    );
    carried_finding_attach(&fixture).assert().success();
    assert_eq!(
        WorkModelStore::new(&fixture.project)
            .read_work_item(&fixture.work)
            .unwrap(),
        item
    );
}

#[test]
fn carried_finding_evidence_compatibility_refuses_published_records() {
    let binary = writer_assignment_old_reader(
        "FLUENT_CARRIED_FINDING_OLD_BIN",
        "b5d8bf02b016a3977a08fc713e47f525b895aed0",
    );
    for fence in ["envelope", "record", "attempt"] {
        let tmp = TempDir::new().unwrap();
        let fixture = carried_finding_fixture(&tmp);
        carried_finding_attach(&fixture).assert().success();
        let root = fixture.project.join(".fluent/work");
        let path = root.join(format!("items/{}.json", fixture.work));
        let original = read_json_path(&path);
        let mut record = original.clone();
        if fence != "record" {
            record["schema_version"] = serde_json::json!(6);
        }
        if fence != "envelope" {
            record["model_writer_version"]["schema_version"] = serde_json::json!(4);
        }
        write_json_path(&path, &record);
        let before = snapshot_tree(&root);
        let output = Command::new(&binary)
            .current_dir(&fixture.project)
            .env("FLUENT_NO_UPDATE_CHECK", "1")
            .args(["work-item", "upgrade", &fixture.work])
            .output()
            .unwrap();
        assert!(
            !output.status.success(),
            "pinned reader accepted {fence}: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        assert_eq!(
            snapshot_tree(&root),
            before,
            "refusal changed {fence} records"
        );
        write_json_path(&path, &original);
        carried_finding_attach(&fixture).assert().success();
        for (path, bytes) in &fixture.protected {
            assert_eq!(fs::read(path).unwrap(), *bytes);
        }
    }
}

#[test]
fn carried_finding_evidence_compatibility_refuses_public_transaction() {
    let binary = writer_assignment_old_reader(
        "FLUENT_CARRIED_FINDING_OLD_BIN",
        "b5d8bf02b016a3977a08fc713e47f525b895aed0",
    );
    for inner in [false, true] {
        let tmp = TempDir::new().unwrap();
        let fixture = carried_finding_fixture(&tmp);
        let journal = interrupt_carried_finding_attachment(&fixture);
        let transaction = read_json_path(&journal);
        assert_eq!(transaction["schema_version"], 14);
        let root = fixture.project.join(".fluent/work");
        let path = root.join(format!("items/{}.json", fixture.work));
        let original = read_json_path(&path);
        if inner {
            let mut record = original.clone();
            record["schema_version"] = serde_json::json!(6);
            record["model_writer_version"]["schema_version"] = serde_json::json!(4);
            write_json_path(&path, &record);
        }
        let before = snapshot_tree(&root);
        let output = Command::new(&binary)
            .current_dir(&fixture.project)
            .env("FLUENT_NO_UPDATE_CHECK", "1")
            .args(["work-item", "upgrade", &fixture.work])
            .output()
            .unwrap();
        assert!(
            !output.status.success(),
            "pinned reader accepted interrupted attachment: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        if inner {
            assert!(
                String::from_utf8_lossy(&output.stderr).contains("work item transaction"),
                "{}",
                String::from_utf8_lossy(&output.stderr)
            );
        }
        assert_eq!(snapshot_tree(&root), before);
        write_json_path(&path, &original);
        carried_finding_attach(&fixture).assert().success();
        assert!(!journal.exists());
        let item = WorkModelStore::new(&fixture.project)
            .read_work_item(&fixture.work)
            .unwrap();
        assert_eq!(
            serde_json::to_value(&item.attempts[0].evidence_recoveries).unwrap(),
            transaction["work_item"]["attempts"][0]["evidence_recoveries"]
        );
        assert_eq!(
            serde_json::to_value(&item.attempts[0].tasks).unwrap(),
            transaction["work_item"]["attempts"][0]["tasks"]
        );
        for (path, bytes) in &fixture.protected {
            assert_eq!(fs::read(path).unwrap(), *bytes);
        }
    }
}

#[test]
fn carried_finding_evidence_compatibility_preserves_legacy_meaning() {
    let tmp = TempDir::new().unwrap();
    let fixture = carried_finding_fixture(&tmp);
    let root = fixture.project.join(".fluent/work");
    let path = root.join(format!("items/{}.json", fixture.work));
    let mut record = read_json_path(&path);
    record["schema_version"] = serde_json::json!(6);
    record["model_writer_version"]["schema_version"] = serde_json::json!(4);
    write_json_path(&path, &record);
    let path = root.join(format!("attempts/{}/attempt-1.json", fixture.work));
    let mut record = read_json_path(&path);
    record["schema_version"] = serde_json::json!(6);
    write_json_path(&path, &record);
    let store = WorkModelStore::new(&fixture.project);
    let old = store.read_work_item_snapshot(&fixture.work).unwrap();
    let before = snapshot_tree(&root);
    assert!(old.attempts[0].evidence_recoveries.is_empty());
    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["work-item", "show", &fixture.work])
        .assert()
        .success();
    assert_eq!(snapshot_tree(&root), before);
    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["work-item", "upgrade", &fixture.work])
        .assert()
        .success();
    let current = store.read_work_item_snapshot(&fixture.work).unwrap();
    assert_eq!(current.attempts[0].tasks, old.attempts[0].tasks);
    assert!(current.attempts[0].evidence_recoveries.is_empty());
    for (path, bytes) in &fixture.protected {
        assert_eq!(fs::read(path).unwrap(), *bytes);
    }
    carried_finding_attach(&fixture).assert().success();
}

#[test]
fn carried_finding_evidence_attachment_plans_current_tests_review() {
    let tmp = TempDir::new().unwrap();
    let fixture = carried_finding_fixture(&tmp);
    let store = WorkModelStore::new(&fixture.project);
    let before = store.read_work_item(&fixture.work).unwrap();
    let review_path = before.attempts[0]
        .tasks
        .last()
        .unwrap()
        .writer_correction_assignment
        .as_ref()
        .unwrap()
        .findings[0]
        .source
        .clone();
    // The ordinary route must continue to reject a Review of candidate A.
    fluent_cmd()
        .current_dir(&fixture.project)
        .args([
            "attempt",
            "evidence",
            "attach",
            &fixture.work,
            "attempt-1",
            "--candidate",
            &fixture.candidate,
            "--review-artifact",
            &review_path,
            "--evidence-file",
            fixture.evidence.to_str().unwrap(),
        ])
        .assert()
        .failure();
    carried_finding_attach(&fixture).assert().success();
    let after = store.read_work_item(&fixture.work).unwrap();
    let attempt = &after.attempts[0];
    assert_eq!(attempt.tasks.len(), before.attempts[0].tasks.len() + 1);
    assert_eq!(
        &attempt.tasks[..before.attempts[0].tasks.len()],
        &before.attempts[0].tasks
    );
    assert_eq!(after.planning_context, before.planning_context);
    assert_eq!(attempt.writer_runs, before.attempts[0].writer_runs);
    assert_eq!(attempt.evidence_recoveries.len(), 1);
    let recovery = &attempt.evidence_recoveries[0];
    assert_eq!(recovery.candidate_commit, fixture.candidate);
    assert!(recovery.required_check.is_none());
    let target = attempt.tasks.last().unwrap();
    assert_eq!(target.kind, fluent::work_model::TaskKind::Review);
    assert_eq!(target.role, "tests");
    assert_eq!(target.status, TaskStatus::Planned);
    assert_eq!(
        target.review_context.as_ref().unwrap().candidate_commit,
        fixture.candidate
    );
    let saved = serde_json::to_value(recovery).unwrap();
    let binding = &saved["carried_finding"]["binding"];
    assert_eq!(binding["finding"]["id"], fixture.finding);
    assert_eq!(
        binding["assignment"]["source_candidate_commit"],
        fixture.source_candidate
    );
    assert_eq!(binding["candidate_commit"], fixture.candidate);
    assert_ne!(fixture.source_candidate, fixture.candidate);
    assert!(after.merge_candidates.is_empty());
    for (path, bytes) in &fixture.protected {
        assert_eq!(fs::read(path).unwrap(), *bytes);
    }
    assert_eq!(git_head(&fixture.workspace), fixture.candidate);
    assert!(
        git::run_stdout(
            &fixture.workspace,
            &["status", "--porcelain"],
            "inspect candidate"
        )
        .unwrap()
        .is_empty()
    );
    assert!(
        !fixture
            .project
            .join(&target.artifact_area.as_ref().unwrap().path)
            .join("transcript.jsonl")
            .exists()
    );
}

#[test]
fn carried_finding_evidence_acceptance_satisfies_only_selected_finding() {
    use fluent::work_model::*;
    for (proof, verdict) in [
        ("pass", "pass"),
        ("fail", "pass"),
        ("pass", "fail"),
        ("pass", "uncertain"),
    ] {
        let tmp = TempDir::new().unwrap();
        let fixture = carried_finding_fixture(&tmp);
        let mut document = read_json_path(&fixture.evidence);
        document["result"] = serde_json::json!(proof);
        fs::write(
            &fixture.evidence,
            serde_json::to_vec_pretty(&document).unwrap(),
        )
        .unwrap();
        let store = WorkModelStore::new(&fixture.project);
        let before = store.read_work_item(&fixture.work).unwrap();
        carried_finding_attach(&fixture).assert().success();
        let attached = store.read_work_item(&fixture.work).unwrap();
        assert_eq!(
            attached.attempts[0].evidence_recoveries[0].state,
            EvidenceRecoveryState::Reviewing
        );
        assert!(attached.merge_candidates.is_empty());
        let bin = tmp.path().join("bin");
        if verdict == "pass" {
            write_mock_claude(
                &bin,
                &learner_mock_script(r#"{"schema_version":1,"observations":[],"work_items":[]}"#),
            );
        } else {
            let report = if verdict == "fail" {
                "Verdict: fail\nDisposition: evidence-needed\nExternal-Condition: unavailable host\nAdditional-Proof: rerun the exact check\n\n- [ ] Observe the real host check\n"
            } else {
                "Verdict: uncertain\n"
            };
            write_mock_claude(
                &bin,
                &format!("#!/bin/sh\ncat > review.md <<'REPORT'\n{report}REPORT\n"),
            );
        }
        let output = fluent_cmd()
            .current_dir(&fixture.project)
            .env("PATH", mock_path(&bin))
            .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
            .output()
            .unwrap();
        let after = store.read_work_item(&fixture.work).unwrap();
        let attempt = &after.attempts[0];
        let recovery = &attempt.evidence_recoveries[0];
        if proof == "pass" && verdict == "pass" {
            assert!(
                output.status.success(),
                "{}",
                String::from_utf8_lossy(&output.stderr)
            );
            assert_eq!(recovery.state, EvidenceRecoveryState::Complete);
            assert!(recovery.targets[0].review_digest.is_some());
            assert_eq!(
                attempt
                    .tasks
                    .iter()
                    .filter(|t| t.kind == TaskKind::Write)
                    .count(),
                4
            );
            for role in review::REVIEWERS {
                assert!(
                    attempt.tasks.iter().any(|t| t.kind == TaskKind::Review
                        && t.role == *role
                        && t.status == TaskStatus::Complete
                        && t.evidence_review_context.is_none()
                        && t.review_context
                            .as_ref()
                            .is_some_and(|c| c.candidate_commit == fixture.candidate)),
                    "ordinary {role} Review must still run: {attempt:#?}"
                );
            }
            assert!(
                attempt
                    .tasks
                    .iter()
                    .any(|t| t.kind == TaskKind::Tester && t.status == TaskStatus::Complete)
            );
            assert_eq!(
                attempt.learning.as_ref().unwrap().status,
                LearningStatus::Succeeded
            );
            assert!(after.merge_candidates[0].ready_at.is_some());
            assert!(
                attempt
                    .artifacts
                    .iter()
                    .any(|a| a.path.ends_with("/candidate-gate.json")),
                "deterministic gate must run after finding acceptance"
            );
        } else {
            assert_ne!(
                recovery.state,
                EvidenceRecoveryState::Complete,
                "{proof} proof / {verdict} Review cannot accept a finding"
            );
            assert!(after.merge_candidates.is_empty());
            assert!(!attempt.tasks.iter().any(|t| t.kind == TaskKind::Tester));
            assert!(attempt.learning.is_none());
        }
        for old in &before.attempts[0].tasks {
            assert_eq!(attempt.tasks.iter().find(|t| t.id == old.id).unwrap(), old);
        }
        for (path, bytes) in &fixture.protected {
            assert_eq!(fs::read(path).unwrap(), *bytes);
        }
        assert_eq!(git_head(&fixture.workspace), fixture.candidate);
    }
}

#[test]
fn carried_finding_evidence_attachment_rejects_invalid_bindings() {
    use fluent::work_model::*;
    for case in [
        "unassigned",
        "no-assignment",
        "source-review",
        "review-candidate",
        "unfinished",
        "wrong-command",
        "wrong-directory",
        "dirty",
        "changed-candidate",
        "pending-writer",
        "live-task",
        "symlink-proof",
        "malformed-proof",
        "binding-schema",
        "duplicate-command",
        "live-learner",
        "live-landing",
        "live-execution",
    ] {
        let tmp = TempDir::new().unwrap();
        let mut fixture = if case == "duplicate-command" {
            carried_finding_fixture_with_request(
                &tmp,
                "Evidence-Command: cargo test exact_host_check\nEvidence-Command: cargo test other\nEvidence-Working-Directory: .\n",
            )
        } else {
            carried_finding_fixture(&tmp)
        };
        let store = WorkModelStore::new(&fixture.project);
        let mut item = store.read_work_item(&fixture.work).unwrap();
        let writer = item.attempts[0].tasks.last().unwrap().clone();
        let matrix_path = fixture
            .project
            .join(&writer.artifact_area.as_ref().unwrap().path)
            .join("writer-completion.json");
        let mut lease = None;
        let mut land = None;
        match case {
            "unassigned" => fixture.finding = "finding:tests:unassigned".into(),
            "no-assignment" => {
                let path = fixture.project.join(format!(
                    ".fluent/work/tasks/{}/attempt-1/{}.json",
                    fixture.work, writer.id
                ));
                let mut value = read_json_path(&path);
                value
                    .as_object_mut()
                    .unwrap()
                    .remove("writer_correction_assignment");
                fs::write(path, serde_json::to_vec_pretty(&value).unwrap()).unwrap();
            }
            "source-review" => {
                let path = &fixture.protected[0].0;
                fs::write(
                    path,
                    [fs::read(path).unwrap(), b"\nchanged".to_vec()].concat(),
                )
                .unwrap();
            }
            "review-candidate" => {
                item.attempts[0].tasks[1]
                    .review_context
                    .as_mut()
                    .unwrap()
                    .candidate_commit = fixture.candidate.clone();
                store.write_work_item(&item).unwrap();
            }
            "unfinished" => {
                let mut matrix = read_json_path(&matrix_path);
                matrix["rows"][0]["state"] = serde_json::json!("pending");
                fs::write(&matrix_path, serde_json::to_vec_pretty(&matrix).unwrap()).unwrap();
            }
            "wrong-command" | "wrong-directory" => {
                let mut document = read_json_path(&fixture.evidence);
                document[if case == "wrong-command" {
                    "check"
                } else {
                    "working_directory"
                }] = serde_json::json!("other");
                fs::write(
                    &fixture.evidence,
                    serde_json::to_vec_pretty(&document).unwrap(),
                )
                .unwrap();
            }
            "dirty" => fs::write(fixture.workspace.join("dirt"), "dirt").unwrap(),
            "changed-candidate" => {
                commit_file(&fixture.workspace, "later", "later", "Change candidate")
            }
            "pending-writer" => {
                item.add_next_write_round("attempt-1", vec![]).unwrap();
                store.write_work_item(&item).unwrap();
            }
            "duplicate-command" => {}
            "live-learner" => {
                lease = Some(
                    fluent::lease::acquire(&fluent::lease::learner_lock_path(
                        &fixture.project,
                        &fixture.work,
                        "attempt-1",
                    ))
                    .unwrap(),
                );
            }
            "live-landing" => {
                land = Some(
                    fluent::land_lock::acquire(&fluent::land_lock::lock_path(&fixture.project))
                        .unwrap(),
                );
            }
            "live-execution" => {
                let area = fixture
                    .project
                    .join(&writer.artifact_area.as_ref().unwrap().path);
                lease = Some(fluent::lease::acquire(&area.join("execution-owner.lock")).unwrap());
                let record = fluent::execution::ExecutionRecord {
                    schema_version: 1,
                    state: fluent::execution::ExecutionState::Running,
                    owner_pid: std::process::id(),
                    leader_pid: std::process::id(),
                    process_group_id: std::process::id(),
                    started_at: now_iso8601(),
                    heartbeat_at: now_iso8601(),
                    settled_at: None,
                    attempt_owner: None,
                    launch_generation: None,
                };
                fs::write(
                    area.join("execution.json"),
                    serde_json::to_vec_pretty(&record).unwrap(),
                )
                .unwrap();
            }
            "live-task" => {
                lease = Some(
                    fluent::lease::acquire(&fluent::lease::task_lock_path(
                        &fixture.project,
                        &fixture.work,
                        &writer.id,
                    ))
                    .unwrap(),
                );
            }
            "symlink-proof" => {
                let target = tmp.path().join("proof-link");
                std::os::unix::fs::symlink(&fixture.evidence, &target).unwrap();
                fixture.evidence = target;
            }
            "malformed-proof" => fs::write(&fixture.evidence, "not JSON").unwrap(),
            "binding-schema" => {
                carried_finding_attach(&fixture).assert().success();
                let attempt_path = fixture.project.join(format!(
                    ".fluent/work/attempts/{}/attempt-1.json",
                    fixture.work
                ));
                let mut attempt = read_json_path(&attempt_path);
                attempt["evidence_recoveries"][0]["carried_finding"]["binding"]["schema_version"] =
                    serde_json::json!(99);
                fs::write(&attempt_path, serde_json::to_vec_pretty(&attempt).unwrap()).unwrap();
            }
            _ => unreachable!(),
        }
        let work_before = snapshot_tree(&fixture.project.join(".fluent/work"));
        let candidate_before = snapshot_tree(&fixture.workspace);
        let git_before = snapshot_tree(&fixture.project.join(".git"));
        let result = carried_finding_attach(&fixture).assert().failure();
        if case == "binding-schema" {
            fluent_cmd()
                .current_dir(&fixture.project)
                .args(["work-item", "upgrade", &fixture.work])
                .assert()
                .failure();
        }
        assert!(
            String::from_utf8_lossy(&result.get_output().stderr).contains("Error:"),
            "{case}"
        );
        assert_eq!(
            snapshot_tree(&fixture.project.join(".fluent/work")),
            work_before,
            "Work changed for {case}"
        );
        assert_eq!(
            snapshot_tree(&fixture.workspace),
            candidate_before,
            "candidate changed for {case}"
        );
        assert_eq!(
            snapshot_tree(&fixture.project.join(".git")),
            git_before,
            "Git changed for {case}"
        );
        drop(lease);
        drop(land);
    }
}

#[test]
fn carried_finding_evidence_entrypoint_guidance_and_queue() {
    use fluent::work_model::*;
    let tmp = TempDir::new().unwrap();
    let fixture = carried_finding_fixture(&tmp);
    let before = snapshot_tree(&fixture.project.join(".fluent/work"));
    let shown = work_item_value(&fixture.project, &fixture.work);
    assert!(
        shown["next-action"]
            .as_str()
            .unwrap()
            .contains(&format!("--finding {}", fixture.finding))
    );
    assert!(
        shown["evidence-recovery"]["reason"]
            .as_str()
            .unwrap()
            .contains("cargo test exact_host_check")
    );
    assert_eq!(snapshot_tree(&fixture.project.join(".fluent/work")), before);
    carried_finding_attach(&fixture).assert().success();
    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
        .assert()
        .success();
    let dispatch = fluent::scheduler::pick_next_queued(&fixture.project)
        .unwrap()
        .unwrap();
    let bin = tmp.path().join("bin");
    write_mock_claude(
        &bin,
        &learner_mock_script(r#"{"schema_version":1,"observations":[],"work_items":[]}"#),
    );
    fluent::scheduler::dispatch_one(&fixture.project, &dispatch, &EvidenceCliRunner { bin })
        .unwrap();
    let item = WorkModelStore::new(&fixture.project)
        .read_work_item(&fixture.work)
        .unwrap();
    assert_eq!(
        item.attempts[0].evidence_recoveries[0].state,
        EvidenceRecoveryState::Complete
    );
    assert!(item.merge_candidates[0].ready_at.is_some());
    for (path, bytes) in &fixture.protected {
        assert_eq!(fs::read(path).unwrap(), *bytes);
    }
}

#[test]
fn carried_finding_evidence_entrypoint_rejects_stale_inputs() {
    for case in [
        "proof",
        "binding",
        "source-review",
        "matrix",
        "candidate",
        "owner",
    ] {
        let tmp = TempDir::new().unwrap();
        let fixture = carried_finding_fixture(&tmp);
        carried_finding_attach(&fixture).assert().success();
        fluent_cmd()
            .current_dir(&fixture.project)
            .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
            .assert()
            .success();
        let item = WorkModelStore::new(&fixture.project)
            .read_work_item(&fixture.work)
            .unwrap();
        let recovery = &item.attempts[0].evidence_recoveries[0];
        let binding = &recovery.carried_finding.as_ref().unwrap().binding;
        let _lease = (case == "owner").then(|| {
            fluent::lease::acquire(&fluent::lease::task_lock_path(
                &fixture.project,
                &fixture.work,
                &binding.writer_task_id,
            ))
            .unwrap()
        });
        let path = match case {
            "proof" => fixture.project.join(&recovery.attachment.snapshot_path),
            "binding" => fixture.project.join(
                serde_json::to_value(recovery).unwrap()["carried_finding"]["artifact"]["path"]
                    .as_str()
                    .unwrap(),
            ),
            "source-review" => fixture.project.join(&binding.source_review.artifact.path),
            "matrix" => fixture.project.join(
                serde_json::to_value(binding).unwrap()["source_matrix"]["path"]
                    .as_str()
                    .unwrap(),
            ),
            "candidate" | "owner" => fixture.workspace.join("changed.txt"),
            _ => unreachable!(),
        };
        let mut bytes = fs::read(&path).unwrap_or_default();
        bytes.push(b'\n');
        if case != "owner" {
            fs::write(path, bytes).unwrap();
        }
        let before = snapshot_tree(&fixture.project.join(".fluent/work"));
        let shown = work_item_value(&fixture.project, &fixture.work);
        assert!(
            shown["next-action"].is_null(),
            "stale {case} must withhold guidance: {shown}"
        );
        assert_eq!(shown["evidence-recovery"]["can-resume"], false);
        let target = recovery.targets[0].review_task_id.as_ref().unwrap();
        for args in [
            vec!["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"],
            vec!["queue", "resume", &fixture.work, "--attempt", "attempt-1"],
            vec![
                "task",
                "run",
                &fixture.work,
                "attempt-1",
                target,
                "--no-sandbox",
            ],
        ] {
            fluent_cmd()
                .current_dir(&fixture.project)
                .args(args)
                .assert()
                .failure();
        }
        assert!(
            fluent::queue::claim(&fixture.project, &fixture.work, "attempt-1").is_err(),
            "stale {case} claim"
        );
        assert_eq!(
            snapshot_tree(&fixture.project.join(".fluent/work")),
            before,
            "stale {case} mutated Work"
        );
    }
}

#[test]
fn carried_finding_evidence_entrypoint_preserves_later_required_check() {
    use fluent::work_model::*;
    let tmp = TempDir::new().unwrap();
    let required_os = if std::env::consts::OS == "linux" {
        "macos"
    } else {
        "linux"
    };
    let tester = format!(
        "commands:\n  - command: true\n    test_harness: shell-harness\n    applicability:\n      environment: {{os: {required_os}}}\n      freshness: {{kind: live-state, max_age_seconds: 600}}\n"
    );
    let fixture = carried_finding_fixture_with_tester(
        &tmp,
        "Evidence-Command: cargo test exact_host_check\nEvidence-Working-Directory: .\n",
        Some(&tester),
    );
    let store = WorkModelStore::new(&fixture.project);
    let original = store.read_work_item(&fixture.work).unwrap();
    let bin = tmp.path().join("bin");
    write_mock_claude(
        &bin,
        &learner_mock_script(r#"{"schema_version":1,"observations":[],"work_items":[]}"#),
    );
    carried_finding_attach(&fixture).assert().success();
    fluent_cmd()
        .current_dir(&fixture.project)
        .env("PATH", mock_path(&bin))
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .assert()
        .success();
    let blocked = store.read_work_item(&fixture.work).unwrap();
    let attempt = &blocked.attempts[0];
    let accepted = attempt.evidence_recoveries[0].clone();
    assert_eq!(accepted.state, EvidenceRecoveryState::Complete);
    assert_eq!(attempt.pause_kind, Some(PauseKind::HostEvidence));
    assert!(
        attempt
            .tasks
            .iter()
            .any(|t| t.kind == TaskKind::Tester && t.status == TaskStatus::Complete)
    );
    assert!(blocked.merge_candidates.is_empty());
    assert!(attempt.learning.is_none());
    let check = format!("tester:{:x}:0", Sha256::digest(tester.as_bytes()));
    let before = persisted_work_snapshot(&fixture.project, &fixture.work);
    let shown = work_item_value(&fixture.project, &fixture.work);
    assert_eq!(shown["evidence-recovery"]["can-resume"], false, "{shown}");
    assert!(
        shown["next-action"]
            .as_str()
            .unwrap()
            .contains(&format!("--required-check {check}")),
        "{shown}"
    );
    for args in [
        vec!["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"],
        vec!["queue", "resume", &fixture.work, "--attempt", "attempt-1"],
    ] {
        fluent_cmd()
            .current_dir(&fixture.project)
            .env("PATH", mock_path(&bin))
            .args(args)
            .assert()
            .failure()
            .stderr(predicate::str::contains(&check));
    }
    assert_eq!(
        persisted_work_snapshot(&fixture.project, &fixture.work),
        before
    );

    let proof = tmp.path().join("canonical-host-proof.json");
    let issued = chrono::Utc::now();
    fs::write(&proof, serde_json::to_vec(&serde_json::json!({
        "schema_version":1, "producer":"fixture host", "check":"true", "working_directory":".",
        "result":"pass", "run_at":issued.to_rfc3339(), "output":"host check passed", "environment":{"os":required_os}
    })).unwrap()).unwrap();
    fluent_cmd()
        .current_dir(&fixture.project)
        .args([
            "attempt",
            "evidence",
            "attach",
            &fixture.work,
            "attempt-1",
            "--candidate",
            &fixture.candidate,
            "--required-check",
            &check,
            "--evidence-file",
            proof.to_str().unwrap(),
        ])
        .assert()
        .success();
    let attached = store.read_work_item(&fixture.work).unwrap();
    assert_eq!(attached.attempts[0].evidence_recoveries[0], accepted);
    assert_eq!(attached.attempts[0].evidence_recoveries.len(), 2);
    let shown = work_item_value(&fixture.project, &fixture.work);
    assert_eq!(shown["evidence-recovery"]["can-resume"], true, "{shown}");
    assert!(
        shown["evidence-recovery"]["reason"]
            .as_str()
            .unwrap()
            .contains(&check),
        "{shown}"
    );
    assert!(
        shown["next-action"]
            .as_str()
            .unwrap()
            .contains("queue resume"),
        "{shown}"
    );

    // Accepted finding proof must also leave the new check's expiry visible.
    let expired = (issued + chrono::TimeDelta::seconds(600)).to_rfc3339();
    let before = persisted_work_snapshot(&fixture.project, &fixture.work);
    let shown = fluent_cmd()
        .current_dir(&fixture.project)
        .env("FLUENT_TEST_EVIDENCE_NOW", &expired)
        .args(["work-item", "show", &fixture.work])
        .output()
        .unwrap();
    assert!(shown.status.success());
    let shown: serde_json::Value = serde_json::from_slice(&shown.stdout).unwrap();
    assert_eq!(shown["evidence-recovery"]["can-resume"], false, "{shown}");
    assert!(
        shown["next-action"]
            .as_str()
            .unwrap()
            .contains(&format!("--required-check {check}")),
        "{shown}"
    );
    fluent_cmd()
        .current_dir(&fixture.project)
        .env("FLUENT_TEST_EVIDENCE_NOW", &expired)
        .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
        .assert()
        .failure()
        .stderr(predicate::str::contains("expired"));
    assert_eq!(
        persisted_work_snapshot(&fixture.project, &fixture.work),
        before
    );

    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&fixture.project)
        .env("PATH", mock_path(&bin))
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .assert()
        .success();
    let ready = store.read_work_item(&fixture.work).unwrap();
    assert_eq!(ready.attempts[0].evidence_recoveries[0], accepted);
    assert_eq!(
        ready.attempts[0].evidence_recoveries[1].state,
        EvidenceRecoveryState::Complete
    );
    assert!(ready.merge_candidates[0].ready_at.is_some());
    assert_eq!(
        ready.attempts[0].learning.as_ref().unwrap().status,
        LearningStatus::Succeeded
    );
    assert_eq!(
        ready.attempts[0]
            .tasks
            .iter()
            .filter(|t| t.kind == TaskKind::Write)
            .count(),
        4
    );
    for old in &original.attempts[0].tasks {
        assert_eq!(
            ready.attempts[0]
                .tasks
                .iter()
                .find(|t| t.id == old.id)
                .unwrap(),
            old
        );
    }
    for (path, bytes) in &fixture.protected {
        assert_eq!(fs::read(path).unwrap(), *bytes);
    }
}

#[test]
fn carried_finding_evidence_entrypoint_revalidates_accepted_review() {
    let tmp = TempDir::new().unwrap();
    let fixture = carried_finding_fixture(&tmp);
    carried_finding_attach(&fixture).assert().success();
    let bin = tmp.path().join("bin");
    write_mock_claude(
        &bin,
        &learner_mock_script(r#"{"schema_version":1,"observations":[],"work_items":[]}"#),
    );
    let store = WorkModelStore::new(&fixture.project);
    let item = store.read_work_item(&fixture.work).unwrap();
    let target = item.attempts[0].evidence_recoveries[0].targets[0]
        .review_task_id
        .as_ref()
        .unwrap();
    fluent_cmd()
        .current_dir(&fixture.project)
        .env("PATH", mock_path(&bin))
        .args([
            "task",
            "run",
            &fixture.work,
            "attempt-1",
            target,
            "--no-sandbox",
        ])
        .assert()
        .success();
    assert!(
        store
            .read_work_item(&fixture.work)
            .unwrap()
            .merge_candidates
            .is_empty()
    );
    fluent_cmd()
        .current_dir(&fixture.project)
        .env("PATH", mock_path(&bin))
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .assert()
        .success();
    let item = store.read_work_item(&fixture.work).unwrap();
    let review = item.attempts[0]
        .tasks
        .iter()
        .find(|t| &t.id == target)
        .unwrap();
    let path = fixture
        .project
        .join(&review.artifact_area.as_ref().unwrap().path)
        .join("review.md");
    let mut bytes = fs::read(&path).unwrap();
    bytes.push(b'\n');
    fs::write(path, bytes).unwrap();
    let before = snapshot_tree(&fixture.project.join(".fluent/work"));
    let shown = work_item_value(&fixture.project, &fixture.work);
    assert_eq!(shown["evidence-recovery"]["can-resume"], false);
    assert!(shown["next-action"].is_null());
    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .assert()
        .failure();
    assert_eq!(snapshot_tree(&fixture.project.join(".fluent/work")), before);
}

#[test]
fn carried_finding_evidence_entrypoint_review_inputs() {
    let tmp = TempDir::new().unwrap();
    let fixture = carried_finding_fixture(&tmp);
    carried_finding_attach(&fixture).assert().success();
    let item = WorkModelStore::new(&fixture.project)
        .read_work_item(&fixture.work)
        .unwrap();
    let recovery = &item.attempts[0].evidence_recoveries[0];
    let saved = serde_json::to_value(recovery).unwrap();
    let target = recovery.targets[0].review_task_id.as_ref().unwrap();
    let bin = tmp.path().join("bin");
    let prompt_path = tmp.path().join("prompt.txt");
    write_mock_claude(
        &bin,
        &format!(
            "#!/bin/sh\nprintf '%s\\n' \"$@\" > '{}'\nprintf 'Verdict: pass\\n' > review.md\n",
            prompt_path.display()
        ),
    );
    fluent_cmd()
        .current_dir(&fixture.project)
        .env("PATH", mock_path(&bin))
        .args([
            "task",
            "run",
            &fixture.work,
            "attempt-1",
            target,
            "--no-sandbox",
        ])
        .assert()
        .success();
    let prompt = fs::read_to_string(prompt_path).unwrap();
    assert!(prompt.contains("## Selected carried finding"));
    assert!(prompt.contains(&fixture.source_candidate));
    assert!(prompt.contains(&fixture.candidate));
    assert!(prompt.contains(&fixture.finding));
    for path in [
        saved["carried_finding"]["artifact"]["path"]
            .as_str()
            .unwrap(),
        saved["carried_finding"]["binding"]["source_matrix"]["path"]
            .as_str()
            .unwrap(),
        saved["carried_finding"]["binding"]["source_review"]["artifact"]["path"]
            .as_str()
            .unwrap(),
        &recovery.attachment.snapshot_path,
    ] {
        assert!(
            prompt.contains(fixture.project.join(path).to_str().unwrap()),
            "missing exact input {path}"
        );
        assert!(
            item.attempts[0]
                .tasks
                .last()
                .unwrap()
                .input_artifacts
                .iter()
                .any(|a| a.path == path)
        );
    }
}

struct WriterRecoveryFixture {
    project: PathBuf,
    workspace: PathBuf,
    work: String,
    task_id: String,
    candidate: String,
    resolution: String,
    audit: PathBuf,
    area: PathBuf,
}

struct InterruptedWriterFixture {
    writer: WriterRecoveryFixture,
    rejected: String,
    protected_files: Vec<PathBuf>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum InterruptedAssignmentContext {
    Empty,
    Legacy,
    Recovered,
}

fn interrupted_writer_fixture(tmp: &TempDir) -> InterruptedWriterFixture {
    interrupted_writer_fixture_with_assignment(tmp, true)
}

fn interrupted_writer_fixture_with_assignment(
    tmp: &TempDir,
    with_assignment: bool,
) -> InterruptedWriterFixture {
    interrupted_writer_fixture_with_lineage(tmp, with_assignment, false)
}

fn interrupted_writer_fixture_with_lineage(
    tmp: &TempDir,
    with_assignment: bool,
    inherited: bool,
) -> InterruptedWriterFixture {
    interrupted_writer_fixture_with_context(
        tmp,
        with_assignment,
        inherited,
        InterruptedAssignmentContext::Empty,
    )
}

fn interrupted_writer_fixture_with_context(
    tmp: &TempDir,
    with_assignment: bool,
    inherited: bool,
    context: InterruptedAssignmentContext,
) -> InterruptedWriterFixture {
    use fluent::work_model::{AttemptStatus, TaskKind, now_iso8601};
    let mut writer = writer_recovery_fixture_with_authority(tmp, !inherited);
    let store = WorkModelStore::new(&writer.project);
    let mut item = store.read_work_item(&writer.work).unwrap();
    let mut interrupted = item.attempts[0].tasks.pop().unwrap();
    item.add_next_review_tasks("attempt-1", &["tests"]).unwrap();
    let review = item.attempts[0].tasks.last_mut().unwrap();
    assert_eq!(review.kind, TaskKind::Review);
    review.status = TaskStatus::Complete;
    review.completed_at = Some(now_iso8601());
    let review_path = format!("{}/review.md", review.artifact_area.as_ref().unwrap().path);
    let review_ref = ArtifactRef {
        producer_id: review.id.clone(),
        path: review_path.clone(),
    };
    let finding = WriterCompletionFinding {
        id: format!("finding:tests:restore-{}", writer.work),
        role: "tests".into(),
        source: review_path.clone(),
        requirement: "Preserve the reviewed history".into(),
    };
    let review_file = writer.project.join(&review_path);
    fs::create_dir_all(review_file.parent().unwrap()).unwrap();
    fs::write(
        &review_file,
        "Verdict: fail\n\n- [ ] Preserve the reviewed history\n",
    )
    .unwrap();
    interrupted.writer_correction_assignment = Some(WriterCorrectionAssignment {
        schema_version: WRITER_CORRECTION_ASSIGNMENT_SCHEMA_VERSION,
        work_item_id: writer.work.clone(),
        attempt_id: "attempt-1".into(),
        writer_task_id: interrupted.id.clone(),
        source_task_id: item.attempts[0].tasks[0].id.clone(),
        source_candidate_commit: writer.candidate.clone(),
        source_task_inputs: vec![],
        evidence: vec![WriterCorrectionAssignmentInput {
            artifact: review_ref,
            digest: format!(
                "sha256:{:x}",
                Sha256::digest(fs::read(&review_file).unwrap())
            ),
        }],
        findings: vec![finding.clone()],
        origin: WriterCorrectionAssignmentOrigin::Captured,
    });
    if context != InterruptedAssignmentContext::Empty {
        assert!(inherited);
        let artifact = ArtifactRef {
            producer_id: "required-progress".into(),
            path: format!(
                ".fluent/work/progress/{}/attempt-1/progress.md",
                writer.work
            ),
        };
        let bytes = fs::read(writer.project.join(&artifact.path)).unwrap();
        item.attempts[0].tasks[0]
            .input_artifacts
            .push(artifact.clone());
        let assignment = interrupted.writer_correction_assignment.as_mut().unwrap();
        assignment.schema_version = 1;
        assignment
            .source_task_inputs
            .push(WriterCorrectionAssignmentInput {
                artifact,
                digest: format!("sha256:{:x}", Sha256::digest(bytes)),
            });
    }
    fs::write(
        writer.area.join("writer-completion.json"),
        serde_json::to_vec_pretty(
            &WriterCompletionMatrix::skeleton(
                item.attempts[0]
                    .writer_completion_contract
                    .as_ref()
                    .unwrap(),
                &interrupted.id,
                &[finding],
                None,
            )
            .unwrap(),
        )
        .unwrap(),
    )
    .unwrap();
    if inherited {
        // W2 corrects findings owned by W1 and produces a new candidate while
        // those obligations remain pending. W3 must inherit that assignment
        // through normal launch preparation, not a rewritten fixture record.
        let mut assignment = interrupted.writer_correction_assignment.clone().unwrap();
        let mut output = item.attempts[0].tasks[0].output.clone().unwrap();
        output.base_commit = Some(writer.candidate.clone());
        commit_file(
            &writer.workspace,
            "correction.txt",
            "partial correction",
            "Add partial correction",
        );
        writer.candidate = git_head(&writer.workspace);
        output.commit = writer.candidate.clone();
        interrupted.status = TaskStatus::Complete;
        interrupted.completed_at = Some(now_iso8601());
        interrupted.output = Some(output);
        fs::write(
            writer.area.join("transcript.jsonl"),
            "{\"fixture\":\"completed corrective Writer\"}\n",
        )
        .unwrap();
        let mut run = item.attempts[0].writer_runs.last().unwrap().clone();
        run.task_id = interrupted.id.clone();
        run.candidate_commit = writer.candidate.clone();
        run.kind = fluent::work_model::WriterRunKind::Corrective;
        item.attempts[0].writer_runs.push(run);
        item.attempts[0].tasks.push(interrupted);
        if context == InterruptedAssignmentContext::Recovered {
            item.attempts[0].status = AttemptStatus::NeedsUser;
            item.attempts[0].pause_kind = Some(fluent::work_model::PauseKind::WriterCompletion);
            store.write_work_item(&item).unwrap();
            let original = &assignment.source_task_inputs[0];
            let proof = writer.area.join("original-progress.md");
            fs::copy(writer.project.join(&original.artifact.path), &proof).unwrap();
            fs::write(
                writer.project.join(&original.artifact.path),
                "Updated progress before recovery.\n",
            )
            .unwrap();
            fluent_cmd()
                .current_dir(&writer.project)
                .args([
                    "attempt",
                    "recover-assignment-context",
                    &writer.work,
                    "attempt-1",
                    "--task",
                    &assignment.writer_task_id,
                    "--candidate",
                    &writer.candidate,
                    "--assignment-digest",
                    &format!(
                        "sha256:{:x}",
                        Sha256::digest(serde_json::to_vec(&assignment).unwrap())
                    ),
                    "--input",
                    &original.artifact.path,
                    "--original-file",
                    proof.to_str().unwrap(),
                    "--resolution",
                    "Preserve proven original context before continuation.",
                ])
                .assert()
                .success();
            item = store.read_work_item(&writer.work).unwrap();
            assignment = item.attempts[0]
                .tasks
                .last()
                .unwrap()
                .writer_correction_assignment
                .clone()
                .unwrap();
        }
        writer.task_id = item.add_next_write_round("attempt-1", vec![]).unwrap();
        writer.area = writer.project.join(
            &item.attempts[0]
                .tasks
                .last()
                .unwrap()
                .artifact_area
                .as_ref()
                .unwrap()
                .path,
        );
        store.write_work_item(&item).unwrap();
        capture_recovered_writer(&writer, tmp);
        let execution: fluent::execution::ExecutionRecord =
            serde_json::from_slice(&fs::read(writer.area.join("execution.json")).unwrap()).unwrap();
        assert!(!fluent::lease::is_leased(
            &writer.area.join("execution-owner.lock")
        ));
        assert!(
            fixture_group_is_gone(
                execution.process_group_id.try_into().unwrap(),
                std::time::Duration::from_secs(3)
            ),
            "native assignment-capture provider must settle before replacing the synthetic execution record"
        );
        item = store.read_work_item(&writer.work).unwrap();
        let carried = item.attempts[0]
            .tasks
            .last()
            .unwrap()
            .writer_correction_assignment
            .clone()
            .unwrap();
        let mut expected = assignment;
        expected.writer_task_id = writer.task_id.clone();
        if context == InterruptedAssignmentContext::Legacy {
            assert_eq!(carried.schema_version, 2);
            assert_ne!(carried.source_task_inputs, expected.source_task_inputs);
            assert_eq!(
                carried.source_task_inputs[0].digest,
                expected.source_task_inputs[0].digest
            );
            assert_eq!(carried.evidence.len(), expected.evidence.len() + 1);
            assert_eq!(
                &carried.evidence[..expected.evidence.len()],
                &expected.evidence
            );
            let mut authority = carried.clone();
            authority.schema_version = expected.schema_version;
            authority.source_task_inputs = expected.source_task_inputs.clone();
            authority.evidence = expected.evidence.clone();
            assert_eq!(
                authority, expected,
                "native freezing must preserve finding authority"
            );
            assert_eq!(
                item.attempts[0].tasks[2]
                    .writer_correction_assignment
                    .as_ref()
                    .unwrap()
                    .schema_version,
                1
            );
        } else {
            assert_eq!(
                carried, expected,
                "native launch must carry the original assignment"
            );
        }
        assert_ne!(carried.source_candidate_commit, writer.candidate);
        item.attempts[0].tasks.last_mut().unwrap().status = TaskStatus::NeedsUser;
        item.attempts[0].status = AttemptStatus::NeedsUser;
        item.attempts[0].pause_kind = Some(fluent::work_model::PauseKind::WriterCompletion);
        store.write_work_item(&item).unwrap();
        fluent_cmd()
            .current_dir(&writer.project)
            .args([
                "attempt",
                "repair-writer-completion",
                &writer.work,
                "attempt-1",
                "--resolution",
                &writer.resolution,
            ])
            .assert()
            .success();
        item = store.read_work_item(&writer.work).unwrap();
        interrupted = item.attempts[0].tasks.pop().unwrap();
        writer.audit = writer.project.join(
            &interrupted
                .input_artifacts
                .iter()
                .find(|input| input.producer_id == "writer-completion-recovery")
                .unwrap()
                .path,
        );
    }
    interrupted.status = TaskStatus::Executing;
    if !with_assignment {
        interrupted.writer_correction_assignment = None;
    }
    interrupted.started_at = Some(now_iso8601());
    item.attempts[0].tasks.push(interrupted);
    item.attempts[0].status = AttemptStatus::Executing;
    item.attempts[0].pause_kind = None;
    item.attempts[0].review_state = Some(AttemptReviewState::Failed);
    let mut exited = Command::new("/usr/bin/true").spawn().unwrap();
    let pid = exited.id();
    assert!(exited.wait().unwrap().success());
    let execution = fluent::execution::ExecutionRecord {
        schema_version: 1,
        state: fluent::execution::ExecutionState::Canceled,
        owner_pid: pid,
        leader_pid: pid,
        process_group_id: pid,
        started_at: now_iso8601(),
        heartbeat_at: now_iso8601(),
        settled_at: Some(now_iso8601()),
        attempt_owner: Some(fluent::execution::AttemptExecutionOwner {
            project_root: writer.project.clone(),
            work_item_id: writer.work.clone(),
            attempt_id: "attempt-1".into(),
        }),
        launch_generation: None,
    };
    fs::write(
        writer.area.join("execution.json"),
        serde_json::to_vec_pretty(&execution).unwrap(),
    )
    .unwrap();
    store.write_work_item(&item).unwrap();
    let tree = git::run_stdout(
        &writer.workspace,
        &["rev-parse", "HEAD^{tree}"],
        "read recorded tree",
    )
    .unwrap();
    let rejected = git::run_stdout(
        &writer.workspace,
        &["commit-tree", &tree, "-m", "Rewrite interrupted history"],
        "create synthetic rejected history",
    )
    .unwrap();
    git::run(
        &writer.workspace,
        &[
            "update-ref",
            "refs/heads/candidate",
            &rejected,
            &writer.candidate,
        ],
        "model interrupted rewrite",
    )
    .unwrap();
    fluent_cmd()
        .current_dir(&writer.project)
        .args(["attempt", "cancel", &writer.work, "attempt-1"])
        .assert()
        .success();
    let stopped = store.read_work_item(&writer.work).unwrap();
    assert!(stopped.attempts[0].cancellation_requested());
    assert!(
        stopped.attempts[0]
            .cancellation
            .as_ref()
            .unwrap()
            .settled_at
            .is_some()
    );
    assert_eq!(
        stopped.attempts[0].tasks.last().unwrap().status,
        TaskStatus::NeedsUser
    );
    assert!(!fluent::lease::is_leased(&fluent::lease::task_lock_path(
        &writer.project,
        &writer.work,
        &writer.task_id
    )));
    assert!(!fluent::execution::execution_is_live(&writer.area.join("execution.json")).unwrap());
    let mut protected_files = vec![
        writer.audit.clone(),
        review_file,
        writer.area.join("execution.json"),
        writer.project.join(format!(
            ".fluent/work/progress/{}/attempt-1/progress.md",
            writer.work
        )),
    ];
    for task in &stopped.attempts[0].tasks {
        if task.kind == TaskKind::Write {
            protected_files.push(
                writer
                    .project
                    .join(&task.artifact_area.as_ref().unwrap().path)
                    .join("writer-completion.json"),
            );
        }
    }
    InterruptedWriterFixture {
        writer,
        rejected,
        protected_files,
    }
}

fn restore_interrupted_command(fixture: &InterruptedWriterFixture) -> LoggedCommand {
    let mut command = fluent_cmd();
    command.current_dir(&fixture.writer.project).args([
        "attempt",
        "repair-candidate-ancestry",
        &fixture.writer.work,
        "attempt-1",
        "--restore-interrupted",
        "--rejected-candidate",
        &fixture.rejected,
        "--resolution",
        "Restore the exact saved candidate and retain the active stop.",
    ]);
    command
}

#[test]
fn interrupted_writer_candidate_restore_preserves_history() {
    let tmp = TempDir::new().unwrap();
    let fixture = interrupted_writer_fixture(&tmp);
    let writer = &fixture.writer;
    let store = WorkModelStore::new(&writer.project);
    let before = store.read_work_item(&writer.work).unwrap();
    let protected = fixture
        .protected_files
        .iter()
        .map(|path| (path.clone(), fs::read(path).unwrap()))
        .collect::<Vec<_>>();
    assert_ne!(writer.candidate, fixture.rejected);
    assert_eq!(
        git::run_stdout(
            &writer.workspace,
            &["rev-parse", &format!("{}^{{tree}}", writer.candidate)],
            "recorded tree"
        )
        .unwrap(),
        git::run_stdout(
            &writer.workspace,
            &["rev-parse", "HEAD^{tree}"],
            "rejected tree"
        )
        .unwrap()
    );
    assert!(
        !git::run_raw(
            &writer.workspace,
            &[
                "merge-base",
                "--is-ancestor",
                &writer.candidate,
                &fixture.rejected
            ]
        )
        .unwrap()
        .status
        .success()
    );
    restore_interrupted_command(&fixture).assert().success();
    assert_eq!(git_head(&writer.workspace), writer.candidate);
    let after = store.read_work_item(&writer.work).unwrap();
    assert_eq!(after.attempts[0].tasks, before.attempts[0].tasks);
    assert_eq!(
        after.attempts[0].cancellation,
        before.attempts[0].cancellation
    );
    assert_eq!(
        after.attempts[0].review_state,
        Some(AttemptReviewState::Failed)
    );
    let operation = after.attempts[0].recovery_operations.last().unwrap();
    assert_eq!(
        operation.operation_kind,
        "interrupted-writer-candidate-restoration"
    );
    assert_eq!(operation.task_id.as_deref(), Some(writer.task_id.as_str()));
    let audit_ref = after.attempts[0].artifacts.last().unwrap();
    assert_eq!(
        audit_ref.producer_id,
        "interrupted-writer-candidate-restoration"
    );
    let audit: serde_json::Value =
        serde_json::from_slice(&fs::read(writer.project.join(&audit_ref.path)).unwrap()).unwrap();
    assert_eq!(audit["recorded-candidate"], writer.candidate);
    assert_eq!(audit["rejected-candidate"], fixture.rejected);
    assert_eq!(
        git::run_stdout(
            &writer.workspace,
            &["rev-parse", audit["retained-ref"].as_str().unwrap()],
            "retained rejected history"
        )
        .unwrap(),
        fixture.rejected
    );
    let mut normalized = after.clone();
    normalized.attempts[0].artifacts.pop();
    normalized.attempts[0].recovery_operations.pop();
    assert_eq!(
        serde_json::to_value(normalized).unwrap(),
        serde_json::to_value(before).unwrap(),
        "restoration changes only its audit and operation records"
    );
    for (path, bytes) in protected {
        assert_eq!(fs::read(path).unwrap(), bytes);
    }
    assert!(
        !writer.area.join("transcript.jsonl").exists(),
        "restoration must not launch a provider"
    );
}

#[test]
fn interrupted_writer_candidate_restore_rejects_drift() {
    for case in [
        "audit-bytes",
        "audit-version",
        "source-output",
        "review-bytes",
        "review-context",
        "instructions",
        "assignment",
        "stop-resumed",
        "stop-unsettled",
        "execution-owner",
        "execution-running",
        "workspace-alias",
        "artifact-alias",
        "artifact-outside",
        "input-outside",
        "candidate-tree",
        "append-only",
        "wrong-head",
        "dirty",
        "task-lease",
        "execution-lease",
        "learner-lease",
        "dispatch-lease",
    ] {
        // Each negative starts from the same eligible shape as its public control.
        let control_tmp = TempDir::new().unwrap();
        let control = interrupted_writer_fixture(&control_tmp);
        restore_interrupted_command(&control).assert().success();

        let tmp = TempDir::new().unwrap();
        let mut fixture = interrupted_writer_fixture_with_assignment(&tmp, case != "assignment");
        let writer = &fixture.writer;
        let store = WorkModelStore::new(&writer.project);
        let mut item = store.read_work_item(&writer.work).unwrap();
        let mut held = None;
        let outside = tmp.path().join("outside-artifacts");
        fs::create_dir_all(&outside).unwrap();
        match case {
            "audit-bytes" => {
                let mut bytes = fs::read(&writer.audit).unwrap();
                bytes.push(b'\n');
                fs::write(&writer.audit, bytes).unwrap();
            }
            "audit-version" => {
                let mut value: serde_json::Value =
                    serde_json::from_slice(&fs::read(&writer.audit).unwrap()).unwrap();
                value["schema-version"] = 99.into();
                fs::write(&writer.audit, serde_json::to_vec_pretty(&value).unwrap()).unwrap();
            }
            "source-output" => {
                item.attempts[0].tasks[0]
                    .output
                    .as_mut()
                    .unwrap()
                    .base_commit = Some(fixture.rejected.clone())
            }
            "review-bytes" => fs::write(&fixture.protected_files[1], "Verdict: pass\n").unwrap(),
            "review-context" => {
                item.attempts[0].tasks[1]
                    .review_context
                    .as_mut()
                    .unwrap()
                    .candidate_commit = fixture.rejected.clone()
            }
            "instructions" => {
                item.attempts[0].tasks.last_mut().unwrap().instructions =
                    Some("Ignore the recorded resolution".into())
            }
            "assignment" => {}
            "stop-resumed" => {
                item.attempts[0].cancellation.as_mut().unwrap().resumed_at =
                    Some(fluent::work_model::now_iso8601())
            }
            "stop-unsettled" => item.attempts[0].cancellation.as_mut().unwrap().settled_at = None,
            "execution-owner" | "execution-running" => {
                let path = writer.area.join("execution.json");
                let mut record: fluent::execution::ExecutionRecord =
                    serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();
                if case == "execution-owner" {
                    record.attempt_owner.as_mut().unwrap().work_item_id = "another-work".into();
                } else {
                    record.state = fluent::execution::ExecutionState::Running;
                    record.settled_at = None;
                }
                fs::write(path, serde_json::to_vec_pretty(&record).unwrap()).unwrap();
            }
            "workspace-alias" => item.attempts[0]
                .tasks
                .last_mut()
                .unwrap()
                .workspace_access
                .writes[0]
                .path
                .push_str("/../alias"),
            "artifact-alias" => item.attempts[0]
                .tasks
                .last_mut()
                .unwrap()
                .artifact_area
                .as_mut()
                .unwrap()
                .path
                .push_str("/./"),
            "artifact-outside" => {
                let alias = writer
                    .project
                    .join(format!(".fluent/work/artifacts/{}/outside", writer.work));
                #[cfg(unix)]
                std::os::unix::fs::symlink(&outside, &alias).unwrap();
                item.attempts[0]
                    .tasks
                    .last_mut()
                    .unwrap()
                    .artifact_area
                    .as_mut()
                    .unwrap()
                    .path = alias
                    .strip_prefix(&writer.project)
                    .unwrap()
                    .to_str()
                    .unwrap()
                    .into();
            }
            "input-outside" => item.attempts[0]
                .tasks
                .last_mut()
                .unwrap()
                .input_artifacts
                .push(ArtifactRef {
                    producer_id: "unexpected-input".into(),
                    path: outside.join("missing.json").to_str().unwrap().into(),
                }),
            "candidate-tree" => {
                commit_file(
                    &writer.workspace,
                    "changed.txt",
                    "different tree",
                    "Change interrupted source",
                );
                fixture.rejected = git_head(&writer.workspace);
            }
            "append-only" => {
                let tree = git::run_stdout(
                    &writer.workspace,
                    &["rev-parse", "HEAD^{tree}"],
                    "read tree",
                )
                .unwrap();
                fixture.rejected = git::run_stdout(
                    &writer.workspace,
                    &[
                        "commit-tree",
                        &tree,
                        "-p",
                        &writer.candidate,
                        "-m",
                        "Append ordinary history",
                    ],
                    "create append-only candidate",
                )
                .unwrap();
                git::run(
                    &writer.workspace,
                    &["update-ref", "refs/heads/candidate", &fixture.rejected],
                    "install append-only candidate",
                )
                .unwrap();
            }
            "wrong-head" => fixture.rejected = writer.candidate.clone(),
            "dirty" => fs::write(writer.workspace.join("dirty.txt"), "uncommitted").unwrap(),
            "task-lease" | "execution-lease" | "learner-lease" | "dispatch-lease" => {
                let path = match case {
                    "task-lease" => fluent::lease::task_lock_path(
                        &writer.project,
                        &writer.work,
                        &writer.task_id,
                    ),
                    "execution-lease" => writer.area.join("execution-owner.lock"),
                    "learner-lease" => {
                        fluent::lease::learner_lock_path(&writer.project, &writer.work, "attempt-1")
                    }
                    _ => fluent::queue::dispatch_lease_path(&writer.project, &writer.work),
                };
                held = Some(fluent::lease::acquire(&path).unwrap());
            }
            _ => unreachable!(),
        }
        store.write_work_item(&item).unwrap();
        let before = persisted_work_snapshot(&writer.project, &writer.work)
            .into_iter()
            .filter(|entry| entry.path.extension().is_none_or(|ext| ext != "lock"))
            .collect::<Vec<_>>();
        let head = git_head(&writer.workspace);
        let refs =
            git::run_stdout(&writer.workspace, &["show-ref"], "snapshot references").unwrap();
        let result = restore_interrupted_command(&fixture).assert().failure();
        assert!(
            !result.get_output().stderr.is_empty(),
            "missing rejection diagnostic: {case}"
        );
        assert_eq!(git_head(&writer.workspace), head, "history changed: {case}");
        assert_eq!(
            git::run_stdout(&writer.workspace, &["show-ref"], "check references").unwrap(),
            refs,
            "references changed: {case}"
        );
        assert_eq!(
            persisted_work_snapshot(&writer.project, &writer.work)
                .into_iter()
                .filter(|entry| entry.path.extension().is_none_or(|ext| ext != "lock"))
                .collect::<Vec<_>>(),
            before,
            "Work evidence changed: {case}"
        );
        assert!(
            !outside.join("execution-owner.lock").exists(),
            "created an owner lock outside managed evidence: {case}"
        );
        drop(held);
        assert!(!fluent::lease::is_leased(&fluent::lease::task_lock_path(
            &writer.project,
            &writer.work,
            &writer.task_id
        )));
    }
}

#[test]
fn interrupted_writer_candidate_restore_replays_exactly() {
    for point in [
        "before-intent",
        "after-intent",
        "after-retain",
        "after-candidate",
        "after-operation",
    ] {
        let tmp = TempDir::new().unwrap();
        let fixture = interrupted_writer_fixture(&tmp);
        let writer = &fixture.writer;
        let store = WorkModelStore::new(&writer.project);
        let before = store.read_work_item(&writer.work).unwrap();
        let preserved = fixture
            .protected_files
            .iter()
            .map(|path| (path, fs::read(path).unwrap()))
            .collect::<Vec<_>>();
        restore_interrupted_command(&fixture)
            .env(
                "FLUENT_TEST_INTERRUPTED_RESTORATION_EXIT",
                format!("{}:attempt-1:{}:{point}", writer.work, writer.task_id),
            )
            .assert()
            .code(86);
        assert_restoration_settled(&fixture);
        assert_eq!(
            git_head(&writer.workspace),
            if matches!(point, "after-candidate" | "after-operation") {
                writer.candidate.as_str()
            } else {
                fixture.rejected.as_str()
            },
            "{point}"
        );
        let stopped = store.read_work_item(&writer.work).unwrap();
        assert_eq!(stopped.attempts[0].tasks, before.attempts[0].tasks);
        assert_eq!(
            stopped.attempts[0].cancellation,
            before.attempts[0].cancellation
        );
        for (path, bytes) in &preserved {
            assert_eq!(&fs::read(path).unwrap(), bytes, "{point}");
        }
        let intent_path = restoration_intent_path(&fixture);
        assert_eq!(intent_path.exists(), point != "before-intent");
        let original_intent = intent_path
            .exists()
            .then(|| fs::read(&intent_path).unwrap());
        restore_interrupted_command(&fixture).assert().success();
        assert_restoration_settled(&fixture);
        if let Some(bytes) = original_intent {
            assert_eq!(fs::read(&intent_path).unwrap(), bytes);
        }
        let restored = store.read_work_item(&writer.work).unwrap();
        assert_eq!(restored.attempts[0].tasks, before.attempts[0].tasks);
        assert_eq!(
            restored.attempts[0]
                .recovery_operations
                .iter()
                .filter(|op| op.operation_kind == "interrupted-writer-candidate-restoration")
                .count(),
            1
        );
        let snapshot = persisted_work_snapshot(&writer.project, &writer.work);
        let reflog = git::run_stdout(
            &writer.workspace,
            &["reflog", "show", "--format=%H", "refs/heads/candidate"],
            "snapshot restored reflog",
        )
        .unwrap();
        restore_interrupted_command(&fixture).assert().success();
        assert_eq!(
            persisted_work_snapshot(&writer.project, &writer.work),
            snapshot,
            "duplicate publication: {point}"
        );
        assert_eq!(
            git::run_stdout(
                &writer.workspace,
                &["reflog", "show", "--format=%H", "refs/heads/candidate"],
                "verify restored reflog"
            )
            .unwrap(),
            reflog,
            "duplicate Git effect: {point}"
        );
        assert_eq!(git_head(&writer.workspace), writer.candidate);

        if point == "after-operation" {
            let prompt = capture_recovered_writer(writer, &tmp);
            assert!(prompt.contains(&writer.resolution));
            assert!(prompt.contains(writer.audit.to_str().unwrap()));
            assert!(prompt.contains(writer.area.join("no-change.json").to_str().unwrap()));
            let resumed = store.read_work_item(&writer.work).unwrap();
            assert_eq!(
                resumed.attempts[0].tasks.len(),
                before.attempts[0].tasks.len()
            );
            assert_eq!(resumed.attempts[0].tasks.last().unwrap().id, writer.task_id);
            assert!(resumed.attempts[0].tasks.last().unwrap().output.is_none());
            assert!(
                resumed.attempts[0]
                    .cancellation
                    .as_ref()
                    .unwrap()
                    .resumed_at
                    .is_some()
            );
            assert_restoration_settled(&fixture);
            restore_interrupted_command(&fixture).assert().failure();
        }
    }

    // Every published boundary rejects an intervening stop, source reference,
    // evidence change, or unrelated aggregate edit instead of discarding it.
    for point in [
        "after-intent",
        "after-retain",
        "after-candidate",
        "after-operation",
    ] {
        for drift in ["stop", "source-ref", "review", "work", "intent", "retained"] {
            let tmp = TempDir::new().unwrap();
            let fixture = interrupted_writer_fixture(&tmp);
            let writer = &fixture.writer;
            restore_interrupted_command(&fixture)
                .env(
                    "FLUENT_TEST_INTERRUPTED_RESTORATION_EXIT",
                    format!("{}:attempt-1:{}:{point}", writer.work, writer.task_id),
                )
                .assert()
                .code(86);
            assert_restoration_settled(&fixture);
            let store = WorkModelStore::new(&writer.project);
            match drift {
                "stop" => {
                    // A changed persisted identity is corruption, not a normal
                    // cancellation edit: the model correctly forbids that edit.
                    let path = writer.project.join(format!(
                        ".fluent/work/attempts/{}/attempt-1.json",
                        writer.work
                    ));
                    let mut value: serde_json::Value =
                        serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();
                    value["cancellation"]["requested_at"] =
                        fluent::work_model::now_iso8601().into();
                    fs::write(path, serde_json::to_vec_pretty(&value).unwrap()).unwrap();
                }
                "work" => {
                    let mut item = store.read_work_item(&writer.work).unwrap();
                    item.title.push_str(" with an intervening operator edit");
                    store.write_work_item(&item).unwrap();
                }
                "source-ref" => {
                    commit_file(
                        &writer.project,
                        "intervening.txt",
                        "source changed",
                        "Change source after interruption",
                    );
                }
                "review" => fs::write(&fixture.protected_files[1], "Verdict: pass\n").unwrap(),
                "intent" => {
                    let path = restoration_intent_path(&fixture);
                    let mut bytes = fs::read(&path).unwrap();
                    bytes.push(b'\n');
                    fs::write(path, bytes).unwrap();
                }
                "retained" => {
                    let intent: serde_json::Value = serde_json::from_slice(
                        &fs::read(restoration_intent_path(&fixture)).unwrap(),
                    )
                    .unwrap();
                    git::run(
                        &writer.workspace,
                        &[
                            "update-ref",
                            intent["retained-ref"].as_str().unwrap(),
                            &writer.candidate,
                        ],
                        "model changed retained reference",
                    )
                    .unwrap();
                }
                _ => unreachable!(),
            }
            let snapshot = persisted_work_snapshot(&writer.project, &writer.work);
            let refs = git::run_stdout(
                &writer.workspace,
                &["show-ref"],
                "snapshot changed references",
            )
            .unwrap();
            restore_interrupted_command(&fixture).assert().failure();
            assert_eq!(
                persisted_work_snapshot(&writer.project, &writer.work),
                snapshot,
                "{point}/{drift}"
            );
            assert_eq!(
                git::run_stdout(
                    &writer.workspace,
                    &["show-ref"],
                    "verify changed references"
                )
                .unwrap(),
                refs,
                "{point}/{drift}"
            );
            assert_restoration_settled(&fixture);
        }
    }

    for drift in ["review", "branch", "source-ref"] {
        let tmp = TempDir::new().unwrap();
        let fixture = interrupted_writer_fixture(&tmp);
        let writer = &fixture.writer;
        let barrier = restoration_intent_path(&fixture).with_file_name("after-retain.test-ready");
        std::thread::scope(|scope| {
            let run = scope.spawn(|| {
                restore_interrupted_command(&fixture)
                    .env(
                        "FLUENT_TEST_INTERRUPTED_RESTORATION_PAUSE",
                        format!("{}:attempt-1:{}:after-retain", writer.work, writer.task_id),
                    )
                    .output()
                    .unwrap()
            });
            assert!(poll_until(std::time::Duration::from_secs(10), || barrier.exists()));
            // HEAD remains locked while the candidate branch awaits its CAS.
            assert!(
                !git::run_raw(
                    &writer.workspace,
                    &["symbolic-ref", "HEAD", "refs/heads/unrelated"]
                )
                .unwrap()
                .status
                .success()
            );
            match drift {
                "review" => fs::write(&fixture.protected_files[1], "Verdict: pass\n").unwrap(),
                "branch" => {
                    let tree = git::run_stdout(
                        &writer.workspace,
                        &["rev-parse", "HEAD^{tree}"],
                        "read tree",
                    )
                    .unwrap();
                    let changed = git::run_stdout(
                        &writer.workspace,
                        &["commit-tree", &tree, "-m", "Intervene during restoration"],
                        "create concurrent candidate",
                    )
                    .unwrap();
                    git::run(
                        &writer.project,
                        &[
                            "update-ref",
                            "refs/heads/candidate",
                            &changed,
                            &fixture.rejected,
                        ],
                        "advance candidate concurrently",
                    )
                    .unwrap();
                }
                "source-ref" => {
                    commit_file(
                        &writer.project,
                        "concurrent.txt",
                        "different source",
                        "Advance source during restoration",
                    );
                }
                _ => unreachable!(),
            }
            let refs = git::run_stdout(
                &writer.workspace,
                &["show-ref"],
                "snapshot concurrent changes",
            )
            .unwrap();
            fs::write(barrier.with_extension("release"), "release").unwrap();
            let result = run.join().unwrap();
            assert!(!result.status.success(), "accepted concurrent {drift}");
            assert_eq!(
                git::run_stdout(
                    &writer.workspace,
                    &["show-ref"],
                    "verify concurrent changes"
                )
                .unwrap(),
                refs
            );
        });
        assert_restoration_settled(&fixture);
    }
}

#[cfg(unix)]
#[test]
fn interrupted_writer_candidate_restore_rejects_aliased_owner() {
    for owner in ["task", "execution", "learner", "dispatch"] {
        let tmp = TempDir::new().unwrap();
        let fixture = interrupted_writer_fixture(&tmp);
        let writer = &fixture.writer;
        let outside = tmp.path().join("outside-owner.lock");
        fs::write(&outside, "unrelated owner").unwrap();
        let lock = match owner {
            "task" => fluent::lease::task_lock_path(&writer.project, &writer.work, &writer.task_id),
            "execution" => writer.area.join("execution-owner.lock"),
            "learner" => {
                fluent::lease::learner_lock_path(&writer.project, &writer.work, "attempt-1")
            }
            _ => fluent::queue::dispatch_lease_path(&writer.project, &writer.work),
        };
        fs::create_dir_all(lock.parent().unwrap()).unwrap();
        if lock.exists() {
            fs::remove_file(&lock).unwrap();
        }
        std::os::unix::fs::symlink(&outside, &lock).unwrap();
        let before = restoration_evidence(&fixture);
        restore_interrupted_command(&fixture).assert().failure();
        assert_eq!(restoration_evidence(&fixture), before);
        assert_eq!(git_head(&writer.workspace), fixture.rejected);
        assert_eq!(fs::read_link(&lock).unwrap(), outside);
        assert_eq!(fs::read_to_string(&outside).unwrap(), "unrelated owner");
        fs::remove_file(lock).unwrap();
        restore_interrupted_command(&fixture).assert().success();
        assert_restoration_settled(&fixture);
    }
}

fn restoration_evidence(fixture: &InterruptedWriterFixture) -> Vec<SnapshotEntry> {
    persisted_work_snapshot(&fixture.writer.project, &fixture.writer.work)
        .into_iter()
        .filter(|entry| entry.path.extension().is_none_or(|ext| ext != "lock"))
        .collect()
}

fn restoration_intent_path(fixture: &InterruptedWriterFixture) -> PathBuf {
    fixture.writer.project.join(format!(
        ".fluent/work/artifacts/{}/attempt-1/candidate-ancestry-restorations/{}/intent.json",
        fixture.writer.work, fixture.writer.task_id
    ))
}

#[test]
fn interrupted_writer_candidate_restore_preserves_inherited_assignment() {
    assert_interrupted_writer_restores_inherited_assignment(InterruptedAssignmentContext::Empty);
}

#[test]
fn interrupted_writer_candidate_restore_preserves_frozen_legacy_context() {
    assert_interrupted_writer_restores_inherited_assignment(InterruptedAssignmentContext::Legacy);
}

#[test]
fn interrupted_writer_candidate_restore_preserves_recovered_context() {
    assert_interrupted_writer_restores_inherited_assignment(
        InterruptedAssignmentContext::Recovered,
    );
}

fn assert_interrupted_writer_restores_inherited_assignment(context: InterruptedAssignmentContext) {
    let tmp = TempDir::new().unwrap();
    let fixture = interrupted_writer_fixture_with_context(&tmp, true, true, context);
    let writer = &fixture.writer;
    let store = WorkModelStore::new(&writer.project);
    let before = store.read_work_item(&writer.work).unwrap();
    let source = &before.attempts[0].tasks[2];
    let interrupted = before.attempts[0].tasks.last().unwrap();
    let assignment = interrupted.writer_correction_assignment.as_ref().unwrap();
    if context == InterruptedAssignmentContext::Legacy {
        let historical = source.writer_correction_assignment.as_ref().unwrap();
        let original = &historical.source_task_inputs[0];
        assert_eq!(historical.schema_version, 1);
        assert_eq!(assignment.schema_version, 2);
        let snapshot = &assignment.source_task_inputs[0];
        assert_eq!(snapshot.digest, original.digest);
        assert_eq!(
            format!(
                "sha256:{:x}",
                Sha256::digest(fs::read(writer.project.join(&snapshot.artifact.path)).unwrap())
            ),
            original.digest
        );
        fs::write(
            writer.project.join(&original.artifact.path),
            "# Progress\n\nUpdated after native continuation capture.\n",
        )
        .unwrap();
    }
    assert_ne!(assignment.source_task_id, source.id);
    let receipt: serde_json::Value =
        serde_json::from_slice(&fs::read(&writer.audit).unwrap()).unwrap();
    assert_eq!(receipt["source-writer-task-id"], source.id);
    let protected = fixture
        .protected_files
        .iter()
        .map(|path| (path, fs::read(path).unwrap()))
        .collect::<Vec<_>>();
    restore_interrupted_command(&fixture).assert().success();
    let restored = store.read_work_item(&writer.work).unwrap();
    assert_eq!(restored.attempts[0].tasks, before.attempts[0].tasks);
    assert_eq!(
        restored.attempts[0].cancellation,
        before.attempts[0].cancellation
    );
    assert_eq!(git_head(&writer.workspace), writer.candidate);
    for (path, bytes) in protected {
        assert_eq!(fs::read(path).unwrap(), bytes);
    }
    let audit: serde_json::Value =
        serde_json::from_slice(&fs::read(restoration_intent_path(&fixture)).unwrap()).unwrap();
    assert_eq!(audit["source-task-id"], source.id);
    assert_eq!(
        audit["assignment-source"]["task-id"],
        assignment.source_task_id
    );
    assert_eq!(
        audit["assignment-source"]["candidate-commit"],
        assignment.source_candidate_commit
    );
    let snapshot = restoration_evidence(&fixture);
    restore_interrupted_command(&fixture).assert().success();
    assert_eq!(restoration_evidence(&fixture), snapshot);
    assert_restoration_settled(&fixture);
    let prompt = capture_recovered_writer(writer, &tmp);
    assert!(prompt.contains(&writer.resolution));
    let resumed = store.read_work_item(&writer.work).unwrap();
    assert_eq!(
        resumed.attempts[0].tasks.len(),
        before.attempts[0].tasks.len()
    );
    assert_eq!(
        resumed.attempts[0]
            .tasks
            .last()
            .unwrap()
            .writer_correction_assignment,
        interrupted.writer_correction_assignment
    );
    assert!(resumed.attempts[0].tasks.last().unwrap().output.is_none());
    assert_restoration_settled(&fixture);
}

#[test]
fn interrupted_writer_candidate_restore_rejects_frozen_context_drift() {
    for change in [
        "snapshot",
        "provenance",
        "snapshot-path",
        "provenance-path",
        "snapshot-digest",
        "findings",
        "source",
        "evidence",
        "historical-digest",
    ] {
        let tmp = TempDir::new().unwrap();
        let fixture = interrupted_writer_fixture_with_context(
            &tmp,
            true,
            true,
            InterruptedAssignmentContext::Legacy,
        );
        let writer = &fixture.writer;
        let store = WorkModelStore::new(&writer.project);
        let task_path = store
            .work_task_path(&writer.work, "attempt-1", &writer.task_id)
            .unwrap();
        let mut task: serde_json::Value =
            serde_json::from_slice(&fs::read(&task_path).unwrap()).unwrap();
        let assignment = &mut task["writer_correction_assignment"];
        let snapshot = writer.project.join(
            assignment["source_task_inputs"][0]["artifact"]["path"]
                .as_str()
                .unwrap(),
        );
        let provenance = writer.project.join(
            assignment["evidence"][1]["artifact"]["path"]
                .as_str()
                .unwrap(),
        );
        match change {
            "snapshot" => fs::write(snapshot, "changed snapshot").unwrap(),
            "provenance" => fs::write(provenance, "changed provenance").unwrap(),
            "snapshot-path" | "provenance-path" => {
                let input = if change == "snapshot-path" {
                    &mut assignment["source_task_inputs"][0]
                } else {
                    &mut assignment["evidence"][1]
                };
                let original = input["artifact"]["path"].as_str().unwrap();
                let replacement = format!("{original}.copy");
                fs::copy(
                    writer.project.join(original),
                    writer.project.join(&replacement),
                )
                .unwrap();
                input["artifact"]["path"] = replacement.into();
            }
            "snapshot-digest" => {
                fs::write(snapshot, "changed snapshot").unwrap();
                assignment["source_task_inputs"][0]["digest"] =
                    format!("sha256:{:x}", Sha256::digest(b"changed snapshot")).into();
            }
            "findings" => assignment["findings"][0]["requirement"] = "Different obligation".into(),
            "source" => {
                assignment["source_task_id"] = "attempt-1-write-2".into();
                assignment["source_candidate_commit"] = writer.candidate.clone().into();
            }
            "evidence" => {
                let evidence = writer.project.join(
                    assignment["evidence"][0]["artifact"]["path"]
                        .as_str()
                        .unwrap(),
                );
                fs::write(evidence, "Changed immutable review").unwrap();
                assignment["evidence"][0]["digest"] =
                    format!("sha256:{:x}", Sha256::digest(b"Changed immutable review")).into();
            }
            "historical-digest" => {
                let source_path = store
                    .work_task_path(&writer.work, "attempt-1", "attempt-1-write-2")
                    .unwrap();
                let mut source: serde_json::Value =
                    serde_json::from_slice(&fs::read(&source_path).unwrap()).unwrap();
                source["writer_correction_assignment"]["source_task_inputs"][0]["digest"] =
                    format!("sha256:{:x}", Sha256::digest(b"other historical bytes")).into();
                fs::write(source_path, serde_json::to_vec_pretty(&source).unwrap()).unwrap();
            }
            _ => unreachable!(),
        }
        fs::write(task_path, serde_json::to_vec_pretty(&task).unwrap()).unwrap();
        let before = restoration_evidence(&fixture);
        let refs = git::run_stdout(&writer.workspace, &["show-ref"], "snapshot refs").unwrap();
        restore_interrupted_command(&fixture).assert().failure();
        assert_eq!(restoration_evidence(&fixture), before, "{change}");
        assert_eq!(
            git::run_stdout(&writer.workspace, &["show-ref"], "check refs").unwrap(),
            refs,
            "{change}"
        );
        assert_eq!(git_head(&writer.workspace), fixture.rejected, "{change}");
        assert_restoration_settled(&fixture);
    }
}

#[test]
fn interrupted_writer_candidate_restore_rejects_context_audit_drift() {
    for change in [
        "missing-operation",
        "operation-task",
        "audit",
        "operation",
        "missing-audit",
    ] {
        let tmp = TempDir::new().unwrap();
        let fixture = interrupted_writer_fixture_with_context(
            &tmp,
            true,
            true,
            InterruptedAssignmentContext::Recovered,
        );
        let writer = &fixture.writer;
        let item = WorkModelStore::new(&writer.project)
            .read_work_item(&writer.work)
            .unwrap();
        let audit = item.attempts[0]
            .artifacts
            .iter()
            .find(|artifact| artifact.producer_id == "assignment-context-recovery")
            .unwrap();
        match change {
            "audit" => {
                let path = writer.project.join(&audit.path);
                let mut value = read_json_path(&path);
                value["attempt_digest"] = "sha256:changed".into();
                write_json_path(&path, &value);
            }
            "missing-audit" => fs::remove_file(writer.project.join(&audit.path)).unwrap(),
            "operation" | "operation-task" | "missing-operation" => {
                let path = writer.project.join(format!(
                    ".fluent/work/attempts/{}/attempt-1.json",
                    writer.work
                ));
                let mut value = read_json_path(&path);
                let records = value["recovery_operations"].as_array_mut().unwrap();
                let index = records
                    .iter()
                    .position(|record| record["operation-kind"] == "assignment-context-recovery")
                    .unwrap();
                match change {
                    "missing-operation" => {
                        records.remove(index);
                    }
                    "operation-task" => records[index]["task-id"] = "attempt-1-write-1".into(),
                    _ => records[index]["authorization"] = "Changed resolution".into(),
                }
                write_json_path(&path, &value);
            }
            _ => unreachable!(),
        }
        let before = restoration_evidence(&fixture);
        let refs = git::run_stdout(&writer.workspace, &["show-ref"], "snapshot refs").unwrap();
        restore_interrupted_command(&fixture).assert().failure();
        assert_eq!(restoration_evidence(&fixture), before, "{change}");
        assert_eq!(
            git::run_stdout(&writer.workspace, &["show-ref"], "check refs").unwrap(),
            refs,
            "{change}"
        );
        assert_eq!(git_head(&writer.workspace), fixture.rejected, "{change}");
        assert_restoration_settled(&fixture);
    }
}

#[test]
fn interrupted_writer_candidate_restore_rejects_broken_assignment_lineage() {
    for change in ["missing", "changed"] {
        let tmp = TempDir::new().unwrap();
        let fixture = interrupted_writer_fixture_with_lineage(&tmp, true, true);
        let writer = &fixture.writer;
        let source_path = WorkModelStore::new(&writer.project)
            .work_task_path(&writer.work, "attempt-1", "attempt-1-write-2")
            .unwrap();
        let mut source: serde_json::Value =
            serde_json::from_slice(&fs::read(&source_path).unwrap()).unwrap();
        if change == "missing" {
            source
                .as_object_mut()
                .unwrap()
                .remove("writer_correction_assignment");
        } else {
            source["writer_correction_assignment"]["findings"][0]["requirement"] =
                "An unrelated assigned obligation".into();
        }
        // Corrupt only this synthetic source record; the receiving assignment
        // remains valid against W1 but must no longer qualify as a W2 carry.
        fs::write(source_path, serde_json::to_vec_pretty(&source).unwrap()).unwrap();
        let before = restoration_evidence(&fixture);
        let refs = git::run_stdout(
            &writer.workspace,
            &["show-ref"],
            "snapshot rejected lineage refs",
        )
        .unwrap();
        restore_interrupted_command(&fixture)
            .assert()
            .failure()
            .stderr(predicate::str::contains("assignment"));
        assert_eq!(restoration_evidence(&fixture), before);
        assert_eq!(
            git::run_stdout(
                &writer.workspace,
                &["show-ref"],
                "check rejected lineage refs"
            )
            .unwrap(),
            refs
        );
        assert_restoration_settled(&fixture);
    }
}

#[test]
fn interrupted_writer_candidate_restore_replays_legacy_intent() {
    let tmp = TempDir::new().unwrap();
    let fixture = interrupted_writer_fixture(&tmp);
    let writer = &fixture.writer;
    restore_interrupted_command(&fixture)
        .env(
            "FLUENT_TEST_INTERRUPTED_RESTORATION_EXIT",
            format!("{}:attempt-1:{}:after-intent", writer.work, writer.task_id),
        )
        .assert()
        .code(86);
    assert_restoration_settled(&fixture);
    let path = restoration_intent_path(&fixture);
    let mut intent: serde_json::Value = serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();
    intent["schema-version"] = 1.into();
    intent.as_object_mut().unwrap().remove("assignment-source");
    // Keep native field order: the v1 bytes are the v2 bytes with only its new
    // optional source object removed and the schema changed.
    let current = fs::read_to_string(&path).unwrap();
    let start = current.find("  \"assignment-source\": {").unwrap();
    let end = start + current[start..].find("  },\n").unwrap() + "  },\n".len();
    let mut legacy = current[..start].to_string();
    legacy.push_str(&current[end..]);
    legacy = legacy.replacen("\"schema-version\": 2", "\"schema-version\": 1", 1);
    assert_eq!(
        serde_json::from_str::<serde_json::Value>(&legacy).unwrap(),
        intent
    );
    fs::write(&path, &legacy).unwrap();
    restore_interrupted_command(&fixture).assert().success();
    assert_eq!(fs::read_to_string(&path).unwrap(), legacy);
    let before = restoration_evidence(&fixture);
    restore_interrupted_command(&fixture).assert().success();
    assert_eq!(restoration_evidence(&fixture), before);
    assert_eq!(git_head(&writer.workspace), writer.candidate);
    assert_restoration_settled(&fixture);
}

#[test]
fn interrupted_writer_candidate_restore_rejects_symbolic_branch_substitution() {
    for substitute in [false, true] {
        let tmp = TempDir::new().unwrap();
        let fixture = interrupted_writer_fixture(&tmp);
        let writer = &fixture.writer;
        let unrelated = "refs/heads/unrelated";
        git::run(
            &writer.project,
            &["update-ref", unrelated, &fixture.rejected],
            "create unrelated branch at the rejected candidate",
        )
        .unwrap();
        let barrier = restoration_intent_path(&fixture).with_file_name("after-retain.test-ready");
        let store = WorkModelStore::new(&writer.project);
        let before = store.read_work_item(&writer.work).unwrap();
        std::thread::scope(|scope| {
            let run = scope.spawn(|| {
                restore_interrupted_command(&fixture)
                    .env(
                        "FLUENT_TEST_INTERRUPTED_RESTORATION_PAUSE",
                        format!("{}:attempt-1:{}:after-retain", writer.work, writer.task_id),
                    )
                    .output()
                    .unwrap()
            });
            assert!(poll_until(std::time::Duration::from_secs(10), || barrier.exists()));
            if substitute {
                git::run(
                    &writer.project,
                    &["symbolic-ref", "refs/heads/candidate", unrelated],
                    "substitute a symbolic candidate reference during restoration",
                )
                .unwrap();
            }
            let intent = fs::read(restoration_intent_path(&fixture)).unwrap();
            let refs = git::run_stdout(
                &writer.workspace,
                &["show-ref"],
                "snapshot candidate reference substitution",
            )
            .unwrap();
            fs::write(barrier.with_extension("release"), "release").unwrap();
            let result = run.join().unwrap();
            assert_eq!(
                result.status.success(),
                !substitute,
                "unexpected restoration result: {}",
                String::from_utf8_lossy(&result.stderr)
            );
            assert_eq!(
                git::run_stdout(
                    &writer.project,
                    &["rev-parse", unrelated],
                    "check unrelated branch"
                )
                .unwrap(),
                fixture.rejected
            );
            assert_eq!(fs::read(restoration_intent_path(&fixture)).unwrap(), intent);
            if substitute {
                assert_eq!(
                    git::run_stdout(
                        &writer.workspace,
                        &["show-ref"],
                        "check substituted refs are untouched"
                    )
                    .unwrap(),
                    refs
                );
                assert_eq!(
                    git::run_stdout(
                        &writer.project,
                        &["symbolic-ref", "--no-recurse", "refs/heads/candidate"],
                        "check substituted reference type"
                    )
                    .unwrap(),
                    unrelated
                );
                assert_eq!(
                    store.read_work_item(&writer.work).unwrap(),
                    before,
                    "rejection must not publish a recovery operation or change Work state"
                );
            } else {
                assert_eq!(git_head(&writer.workspace), writer.candidate);
            }
        });
        assert_restoration_settled(&fixture);
    }
}

fn assert_restoration_settled(fixture: &InterruptedWriterFixture) {
    let writer = &fixture.writer;
    let head_lock = PathBuf::from(
        git::run_stdout(
            &writer.workspace,
            &["rev-parse", "--git-path", "HEAD.lock"],
            "locate HEAD lock",
        )
        .unwrap(),
    );
    assert!(
        poll_until(std::time::Duration::from_secs(3), || !head_lock.exists()),
        "Git owner must settle before fixture cleanup"
    );
    assert!(!fluent::lease::is_leased(&fluent::lease::task_lock_path(
        &writer.project,
        &writer.work,
        &writer.task_id
    )));
    assert!(!fluent::lease::is_leased(
        &writer.area.join("execution-owner.lock")
    ));
    assert!(!fluent::execution::execution_is_live(&writer.area.join("execution.json")).unwrap());
}

fn writer_recovery_fixture(tmp: &TempDir) -> WriterRecoveryFixture {
    writer_recovery_fixture_with_authority(tmp, true)
}

fn writer_recovery_fixture_with_authority(tmp: &TempDir, authorize: bool) -> WriterRecoveryFixture {
    use fluent::work_model::{
        AttemptStatus, PauseKind, WorkItem, WriterOutcome, WriterRun, WriterRunKind,
    };
    let project = setup_git_project(tmp).canonicalize().unwrap();
    let token: String = tmp
        .path()
        .file_name()
        .unwrap()
        .to_string_lossy()
        .chars()
        .filter(char::is_ascii_alphanumeric)
        .collect();
    let work = format!("recovery-{token}");
    let mut item = WorkItem::planned(&work, "Deliver saved recovery instructions");
    item.add_initial_attempt("attempt-1").unwrap();
    let workspace_ref = item.attempts[0].tasks[0].workspace_access.writes[0].clone();
    git::run(
        &project,
        &["worktree", "add", "-b", "candidate", &workspace_ref.path],
        "create recovery workspace",
    )
    .unwrap();
    let workspace = project.join(&workspace_ref.path).canonicalize().unwrap();
    let base = git_head(&workspace);
    commit_file(
        &workspace,
        "candidate.txt",
        &format!("candidate {token}\n"),
        "Add recovery candidate",
    );
    let candidate = git_head(&workspace);
    let contract = fluent::work_model::WriterCompletionContract {
        version: WRITER_COMPLETION_CONTRACT_VERSION,
        requirements: vec![WriterCompletionRequirement {
            responsibility: Some(CompletionResponsibility::Writer),
            id: format!("behavior:recovery-{token}:b1"),
            kind: WriterCompletionRequirementKind::Behavior,
            source: "behaviors.md#recovery:b1".into(),
            requirement: format!("Preserve the pending obligation {token}"),
            verification_refs: Vec::new(),
            command: None,
        }],
    };
    item.attempts[0].writer_completion_contract = Some(contract.clone());
    let source = &mut item.attempts[0].tasks[0];
    source.status = TaskStatus::Complete;
    source.output = Some(TaskOutput {
        workspace_id: workspace_ref.id,
        workspace_path: workspace_ref.path,
        source_branch: "main".into(),
        base_commit: Some(base),
        commit: candidate.clone(),
        no_change: None,
        learner_canonicalization: None,
    });
    let source_area = project.join(&source.artifact_area.as_ref().unwrap().path);
    fs::create_dir_all(&source_area).unwrap();
    fs::write(
        source_area.join("transcript.jsonl"),
        "{\"fixture\":\"completed source Writer\"}\n",
    )
    .unwrap();
    fs::write(
        source_area.join("writer-completion.json"),
        serde_json::to_vec_pretty(
            &WriterCompletionMatrix::skeleton(&contract, &source.id, &[], None).unwrap(),
        )
        .unwrap(),
    )
    .unwrap();
    let source_id = source.id.clone();
    let task_id = item.add_next_write_round("attempt-1", vec![]).unwrap();
    let task = item.attempts[0].tasks.last_mut().unwrap();
    task.status = TaskStatus::NeedsUser;
    let area = project.join(&task.artifact_area.as_ref().unwrap().path);
    fs::create_dir_all(&area).unwrap();
    fs::write(
        area.join("writer-completion.json"),
        serde_json::to_vec_pretty(
            &WriterCompletionMatrix::skeleton(&contract, &task_id, &[], None).unwrap(),
        )
        .unwrap(),
    )
    .unwrap();
    let attempt = &mut item.attempts[0];
    attempt.status = AttemptStatus::NeedsUser;
    attempt.pause_kind = Some(PauseKind::WriterCompletion);
    attempt.review_state = Some(AttemptReviewState::NotReviewed);
    attempt.writer_runs.push(WriterRun {
        task_id: source_id,
        outcome: WriterOutcome::Continue,
        kind: WriterRunKind::Initial,
        provider: "claude".into(),
        session_id: None,
        continuation: 0,
        checked_required: 1,
        completed_matrix: 0,
        candidate_commit: candidate.clone(),
    });
    let store = WorkModelStore::new(&project);
    store.create_work_item(&item).unwrap();
    let progress = project.join(format!(
        ".fluent/work/progress/{work}/attempt-1/progress.md"
    ));
    fs::create_dir_all(progress.parent().unwrap()).unwrap();
    fs::write(
        progress,
        "## Required completion\n\n- [x] stale checked entry\n",
    )
    .unwrap();
    let resolution = format!(
        "Resolution {token}: preserve the original commits; inspect the pending matrix and record fresh no-change evidence."
    );
    if authorize {
        fluent_cmd()
            .current_dir(&project)
            .args([
                "attempt",
                "repair-writer-completion",
                &work,
                "attempt-1",
                "--resolution",
                &resolution,
            ])
            .assert()
            .success();
    }
    let audit = project.join(format!(".fluent/work/artifacts/{work}/attempt-1/writer-completion-recoveries/{task_id}/recovery.json"));
    WriterRecoveryFixture {
        project,
        workspace,
        work,
        task_id,
        candidate,
        resolution,
        audit,
        area,
    }
}

fn committed_matrix_recovery_fixture(tmp: &TempDir) -> (WriterRecoveryFixture, Vec<u8>) {
    let fixture = writer_recovery_fixture_with_authority(tmp, false);
    let store = WorkModelStore::new(&fixture.project);
    store
        .mutate_work_item(&fixture.work, |item| {
            let attempt = &mut item.attempts[0];
            attempt.tasks.pop();
            attempt
                .writer_completion_contract
                .as_mut()
                .unwrap()
                .requirements[0]
                .verification_refs =
                vec!["Untestable: fixture candidate has no product behavior".into()];
            attempt
                .writer_completion_contract
                .as_mut()
                .unwrap()
                .requirements
                .push(WriterCompletionRequirement {
                    responsibility: Some(CompletionResponsibility::Host),
                    id: "plan:host-check".into(),
                    kind: WriterCompletionRequirementKind::Plan,
                    source: "plan.md#host-check".into(),
                    requirement: "Verify the recovered candidate on the host".into(),
                    verification_refs: vec![],
                    command: Some(fluent::work_model::PlanCommand {
                        applicability: Default::default(),
                        command: "true".into(),
                        working_directory: ".".into(),
                        environment: Default::default(),
                        source_row: "plan:host-check".into(),
                    }),
                });
            Ok(())
        })
        .unwrap();
    fs::remove_dir_all(&fixture.area).unwrap();
    let item = store.read_work_item(&fixture.work).unwrap();
    let area = fixture.project.join(
        &item.attempts[0].tasks[0]
            .artifact_area
            .as_ref()
            .unwrap()
            .path,
    );
    let malformed = br#"{"schema-version":2,"task-id":"attempt-1-write-1","rows":[{"verification":[{"command":"true","result":"pass; extra text"}]}]}"#.to_vec();
    fs::write(area.join("writer-completion.json"), &malformed).unwrap();
    (fixture, malformed)
}

fn later_committed_matrix_recovery_fixture(tmp: &TempDir) -> (WriterRecoveryFixture, Vec<u8>) {
    let (fixture, _) = committed_matrix_recovery_fixture(tmp);
    later_recovery_from_first_fixture(tmp, fixture, false)
}

fn later_recovery_from_first_fixture(
    tmp: &TempDir,
    fixture: WriterRecoveryFixture,
    targeted_review: bool,
) -> (WriterRecoveryFixture, Vec<u8>) {
    committed_matrix_repair_command(&fixture).assert().success();
    let store = WorkModelStore::new(&fixture.project);
    let approved = store.read_work_item(&fixture.work).unwrap();
    let correction = &approved.attempts[0].tasks[1];
    let area = fixture
        .project
        .join(&correction.artifact_area.as_ref().unwrap().path);
    let bin = tmp.path().join("first-correction-provider");
    write_mock_claude(
        &bin,
        r#"#!/bin/bash
set -eu
if [ "${FLUENT_WORKFLOW_REQUIRE_HOST:-}" = 1 ]; then
  test -r "$RECOVERY_SOURCE_MATRIX"
  test -r "$RECOVERY_OLD_AUDIT"
  test -r "$RECOVERY_CURRENT_AUDIT"
  if printf 'tamper\n' > "$RECOVERY_SOURCE_MATRIX" 2>/dev/null; then exit 91; fi
  if printf 'tamper\n' > "$RECOVERY_OLD_AUDIT" 2>/dev/null; then exit 92; fi
  printf 'denied\n' > "$RECOVERY_AREA/confinement-observed"
fi
python3 - <<'PY'
import json, os
from pathlib import Path
area = Path(os.environ['RECOVERY_AREA'])
matrix = area / 'writer-completion.json'
value = json.loads(matrix.read_text())
for row in value['rows']:
    if row.get('responsibility', 'writer') == 'writer':
        row['state'] = 'complete'
        row['implementation-evidence'] = ['candidate.txt: retained implementation']
        row['verification'] = [{'command': 'true', 'result': 'pass'}]
        if row.get('kind') == 'finding':
            row['applicable-constraints'] = [value['rows'][0]['id']]
matrix.write_text(json.dumps(value))
if os.environ.get('RECOVERY_COMMIT_CORRECTION') != '1':
    (area / 'no-change.json').write_text(json.dumps({'schema_version': 1,
        'declaration_path': os.environ['RECOVERY_AREA_REL'] + '/no-change.json',
        'reason': 'The source candidate already contains the implementation.',
        'verification': [{'command': 'true', 'result': 'pass'}]}))
PY
if [ "${RECOVERY_COMMIT_CORRECTION:-}" = 1 ]; then
  printf 'corrected retained evidence\n' > "$RECOVERY_WORKSPACE/correction.txt"
  git -C "$RECOVERY_WORKSPACE" add correction.txt
  git -C "$RECOVERY_WORKSPACE" commit -m 'Correct retained evidence'
fi
"#,
    );
    write_mock_executable(
        &bin,
        "sandbox-exec",
        "#!/bin/bash\nexec /usr/bin/sandbox-exec \"$@\"\n",
    );
    let require_host = std::env::var("FLUENT_WORKFLOW_REQUIRE_HOST").as_deref() == Ok("1");
    let legacy_source = read_json_path(&fixture.audit)
        .get("source-matrix-sha256")
        .is_none();
    let mut run = fluent_cmd();
    run.current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1"]);
    // The legacy first recovery predates source-input bindings. Exercise its
    // historical no-change result, then confine the later corrective Writer.
    if !require_host || legacy_source {
        run.arg("--no-sandbox");
    }
    let result = run
        .env("PATH", mock_path(&bin))
        .env("RECOVERY_AREA", &area)
        .env(
            "RECOVERY_AREA_REL",
            &correction.artifact_area.as_ref().unwrap().path,
        )
        .env(
            "RECOVERY_SOURCE_MATRIX",
            fixture
                .project
                .join(
                    &approved.attempts[0].tasks[0]
                        .artifact_area
                        .as_ref()
                        .unwrap()
                        .path,
                )
                .join("writer-completion.json"),
        )
        .env("RECOVERY_OLD_AUDIT", &fixture.audit)
        .env("RECOVERY_CURRENT_AUDIT", &fixture.audit)
        .env(
            "FLUENT_WORKFLOW_REQUIRE_HOST",
            if legacy_source {
                "0"
            } else if require_host {
                "1"
            } else {
                "0"
            },
        )
        .assert();
    if legacy_source {
        result
            .failure()
            .stderr(predicate::str::contains("valid no-change declaration"));
    } else {
        result.success();
    }
    if require_host && !legacy_source {
        assert_eq!(
            fs::read(area.join("confinement-observed")).unwrap(),
            b"denied\n"
        );
    }
    let first = store.read_work_item(&fixture.work).unwrap();
    assert_eq!(first.attempts[0].tasks[1].status, TaskStatus::Complete);
    let source_output = first.attempts[0].tasks[1].output.clone().unwrap();
    if targeted_review {
        store
            .mutate_work_item(&fixture.work, |item| {
                item.add_review_tasks("attempt-1", &["tests"])?;
                let review = item.attempts[0].tasks.last_mut().unwrap();
                review.status = TaskStatus::Complete;
                let path = fixture
                    .project
                    .join(&review.artifact_area.as_ref().unwrap().path)
                    .join("review.md");
                fs::create_dir_all(path.parent().unwrap()).unwrap();
                fs::write(
                    path,
                    b"Verdict: fail\n\n## Findings\n- [ ] Check the retained evidence\n",
                )
                .unwrap();
                item.attempts[0].status = fluent::work_model::AttemptStatus::NeedsUser;
                item.attempts[0].pause_kind = Some(fluent::work_model::PauseKind::RoundCap);
                item.attempts[0].review_state = Some(AttemptReviewState::Failed);
                Ok(())
            })
            .unwrap();
        let reviewed = store.read_work_item(&fixture.work).unwrap();
        let review = reviewed.attempts[0].tasks.last().unwrap();
        let review_path = format!("{}/review.md", review.artifact_area.as_ref().unwrap().path);
        let evidence = tmp.path().join("intervening-host-evidence.json");
        fs::write(&evidence, br#"{"schema_version":1,"producer":"fixture host","check":"true","working_directory":".","result":"pass","run_at":"2026-08-03T17:59:47Z","output":"passed"}"#).unwrap();
        fluent_cmd()
            .current_dir(&fixture.project)
            .args([
                "attempt",
                "evidence",
                "attach",
                &fixture.work,
                "attempt-1",
                "--candidate",
                &source_output.commit,
                "--review-artifact",
                &review_path,
                "--evidence-file",
                evidence.to_str().unwrap(),
            ])
            .assert()
            .success();
        let attached = store.read_work_item(&fixture.work).unwrap();
        let targeted = attached.attempts[0].tasks.last().unwrap();
        assert!(targeted.evidence_review_context.is_some());
        store
            .mutate_work_item(&fixture.work, |item| {
                let targeted = item.attempts[0].tasks.last_mut().unwrap();
                targeted.status = TaskStatus::Complete;
                let path = fixture
                    .project
                    .join(&targeted.artifact_area.as_ref().unwrap().path)
                    .join("review.md");
                fs::create_dir_all(path.parent().unwrap()).unwrap();
                fs::write(
                    path,
                    b"Verdict: fail\n\n## Findings\n- [ ] Correct the retained evidence\n",
                )
                .unwrap();
                Ok(())
            })
            .unwrap();
    }
    commit_file(
        &fixture.workspace,
        "later.txt",
        "later candidate\n",
        "Add later candidate",
    );
    let candidate = git_head(&fixture.workspace);
    store.mutate_work_item(&fixture.work, |item| {
        // Seed only the intervening targeted Review and later completed Writer.
        // Both recovery approvals and both corrective Writers use public commands.
        if !targeted_review && !legacy_source {
            let review_id = item.add_review_tasks("attempt-1", &["tests"]).unwrap().pop().unwrap();
            let review = item.attempts[0].tasks.last_mut().unwrap();
            review.status = TaskStatus::Complete;
            let review_area = fixture.project.join(&review.artifact_area.as_ref().unwrap().path);
            fs::create_dir_all(&review_area).unwrap();
            fs::write(review_area.join("review.md"), b"Verdict: fail\n\nA later correction is required.\n").unwrap();
            assert_eq!(review.id, review_id);
        }
        let later_id = if legacy_source {
            item.attempts[0].tasks.last().unwrap().id.clone()
        } else {
            item.add_next_write_round("attempt-1", vec![]).unwrap()
        };
        if targeted_review {
            let targeted = &item.attempts[0].tasks[item.attempts[0].tasks.len() - 2];
            let review_path = format!("{}/review.md", targeted.artifact_area.as_ref().unwrap().path);
            let review_ref = ArtifactRef { producer_id: targeted.id.clone(), path: review_path.clone() };
            let digest = format!("sha256:{:x}", Sha256::digest(fs::read(fixture.project.join(&review_path)).unwrap()));
            let source_id = item.attempts[0].tasks[1].id.clone();
            let source_task_inputs = item.attempts[0].tasks[1].input_artifacts.iter().map(|artifact| {
                WriterCorrectionAssignmentInput {
                    artifact: artifact.clone(),
                    digest: format!("sha256:{:x}", Sha256::digest(fs::read(fixture.project.join(&artifact.path)).unwrap())),
                }
            }).collect();
            let later = item.attempts[0].tasks.last_mut().unwrap();
            later.writer_correction_assignment = Some(WriterCorrectionAssignment {
                schema_version: WRITER_CORRECTION_ASSIGNMENT_SCHEMA_VERSION,
                work_item_id: fixture.work.clone(), attempt_id: "attempt-1".into(),
                writer_task_id: later.id.clone(), source_task_id: source_id,
                source_candidate_commit: source_output.commit.clone(),
                source_task_inputs,
                evidence: vec![WriterCorrectionAssignmentInput { artifact: review_ref, digest }],
                findings: vec![WriterCompletionFinding {
                    id: "finding:tests:retained-evidence".into(), role: "tests".into(),
                    source: review_path, requirement: "Correct the retained evidence".into(),
                }],
                origin: WriterCorrectionAssignmentOrigin::Captured,
            });
        }
        let later = item.attempts[0].tasks.last_mut().unwrap();
        later.status = TaskStatus::Complete;
        later.output = Some(TaskOutput {
            commit: candidate.clone(),
            base_commit: Some(source_output.commit.clone()),
            no_change: None,
            ..source_output.clone()
        });
        let area = fixture.project.join(&later.artifact_area.as_ref().unwrap().path);
        fs::create_dir_all(&area).unwrap();
        fs::write(area.join("transcript.jsonl"), b"later completed Writer\n").unwrap();
        fs::write(
            area.join("writer-completion.json"),
            format!("{{\"task-id\":\"{later_id}\",\"rows\":[{{\"verification\":[{{\"result\":\"pass; extra text\"}}]}}]}}"),
        )
        .unwrap();
        let attempt = &mut item.attempts[0];
        attempt.status = fluent::work_model::AttemptStatus::NeedsUser;
        attempt.pause_kind = Some(fluent::work_model::PauseKind::WriterCompletion);
        attempt.pause_record = None;
        attempt.review_state = Some(AttemptReviewState::NotReviewed);
        Ok(())
    }).unwrap();
    let audit = fs::read(&fixture.audit).unwrap();
    (fixture, audit)
}

#[test]
fn writer_completion_recovery_later_committed_matrix_public_continuation() {
    let tmp = TempDir::new().unwrap();
    let (first, _) = committed_matrix_recovery_fixture(&tmp);
    let (fixture, old_audit) = later_recovery_from_first_fixture(&tmp, first, true);
    let store = WorkModelStore::new(&fixture.project);
    let before = store.read_work_item(&fixture.work).unwrap();
    let prior_tasks = before.attempts[0].tasks.clone();
    let targeted = prior_tasks
        .iter()
        .find(|task| task.evidence_review_context.is_some())
        .unwrap();
    assert_eq!(targeted.status, TaskStatus::Complete);
    let intervening = prior_tasks.last().unwrap();
    let assignment = intervening.writer_correction_assignment.as_ref().unwrap();
    assert_eq!(assignment.source_task_id, prior_tasks[1].id);
    assert_eq!(
        assignment.source_candidate_commit,
        prior_tasks[1].output.as_ref().unwrap().commit
    );
    assert_eq!(assignment.evidence[0].artifact.producer_id, targeted.id);
    assert_eq!(before.attempts[0].evidence_recoveries.len(), 1);
    let targeted_review = fixture
        .project
        .join(&targeted.artifact_area.as_ref().unwrap().path)
        .join("review.md");
    let targeted_bytes = fs::read(&targeted_review).unwrap();
    let guidance = read_work_show_json(&fixture.project, &fixture.work);
    assert!(
        guidance["next-action"]
            .as_str()
            .is_some_and(|action| action.contains("repair-writer-completion")),
        "blocker={}, pause={:?}",
        guidance["recovery-blocker"],
        before.attempts[0].pause_kind
    );
    assert_eq!(
        assignment.evidence[0].artifact.path,
        format!(
            "{}/review.md",
            targeted.artifact_area.as_ref().unwrap().path
        )
    );
    assert_eq!(
        assignment.evidence[0].digest,
        format!("sha256:{:x}", Sha256::digest(&targeted_bytes))
    );
    let later_resolution = "Correct the later malformed matrix";
    fluent_cmd()
        .current_dir(&fixture.project)
        .args([
            "attempt",
            "repair-writer-completion",
            &fixture.work,
            "attempt-1",
            "--resolution",
            later_resolution,
        ])
        .assert()
        .success();
    let after = store.read_work_item(&fixture.work).unwrap();
    assert_eq!(
        after.attempts[0].tasks.len(),
        before.attempts[0].tasks.len() + 1
    );
    assert_eq!(
        after.attempts[0].recovery_operations.len(),
        before.attempts[0].recovery_operations.len() + 1
    );
    assert_eq!(fs::read(&fixture.audit).unwrap(), old_audit);
    assert_eq!(
        &after.attempts[0].tasks[..prior_tasks.len()],
        prior_tasks.as_slice()
    );
    assert_eq!(fs::read(&targeted_review).unwrap(), targeted_bytes);
    assert_eq!(
        after.attempts[0].evidence_recoveries,
        before.attempts[0].evidence_recoveries
    );
    let second = after.attempts[0].tasks.last().unwrap();
    assert_eq!(second.status, TaskStatus::Planned);
    let current_audit = fixture.project.join(format!(
        ".fluent/work/artifacts/{}/attempt-1/writer-completion-recoveries/{}/recovery.json",
        fixture.work, second.id,
    ));
    let second_area = fixture
        .project
        .join(&second.artifact_area.as_ref().unwrap().path);
    let source_area = fixture.project.join(
        before.attempts[0]
            .tasks
            .last()
            .unwrap()
            .artifact_area
            .as_ref()
            .unwrap()
            .path
            .clone(),
    );
    let source_matrix = source_area.join("writer-completion.json");
    let source_bytes = fs::read(&source_matrix).unwrap();
    let bin = tmp.path().join("first-correction-provider");
    let require_host = std::env::var("FLUENT_WORKFLOW_REQUIRE_HOST").as_deref() == Ok("1");
    let mut run = fluent_cmd();
    run.current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1"]);
    if !require_host {
        run.arg("--no-sandbox");
    }
    run.env("PATH", mock_path(&bin))
        .env("RECOVERY_AREA", &second_area)
        .env(
            "RECOVERY_AREA_REL",
            &second.artifact_area.as_ref().unwrap().path,
        )
        .env("RECOVERY_SOURCE_MATRIX", &source_matrix)
        .env("RECOVERY_OLD_AUDIT", &fixture.audit)
        .env("RECOVERY_CURRENT_AUDIT", &current_audit)
        .env("RECOVERY_COMMIT_CORRECTION", "1")
        .env("RECOVERY_WORKSPACE", &fixture.workspace)
        .assert()
        .success();
    if require_host {
        assert_eq!(
            fs::read(second_area.join("confinement-observed")).unwrap(),
            b"denied\n"
        );
    }
    let completed = store.read_work_item(&fixture.work).unwrap();
    assert_eq!(
        completed.attempts[0].tasks.last().unwrap().status,
        TaskStatus::Complete
    );
    assert_ne!(
        completed.attempts[0]
            .tasks
            .last()
            .unwrap()
            .output
            .as_ref()
            .unwrap()
            .commit,
        before.attempts[0]
            .tasks
            .last()
            .unwrap()
            .output
            .as_ref()
            .unwrap()
            .commit
    );
    assert_eq!(fs::read(source_matrix).unwrap(), source_bytes);
    assert_eq!(fs::read(targeted_review).unwrap(), targeted_bytes);
    assert_eq!(
        completed.attempts[0].evidence_recoveries,
        before.attempts[0].evidence_recoveries
    );
    assert_eq!(fs::read(&fixture.audit).unwrap(), old_audit);
    let shown = read_work_show_json(&fixture.project, &fixture.work);
    let next = shown["next-action"].as_str().unwrap().to_string();
    assert!(
        next.contains("evidence attach"),
        "{next}; blocker={}",
        shown["recovery-blocker"]
    );
}

#[test]
fn writer_completion_recovery_later_preserves_output_free_prior_authority() {
    let tmp = TempDir::new().unwrap();
    let first = writer_recovery_fixture_with_authority(&tmp, false);
    let first_store = WorkModelStore::new(&first.project);
    first_store
        .mutate_work_item(&first.work, |item| {
            item.attempts[0]
                .writer_completion_contract
                .as_mut()
                .unwrap()
                .requirements
                .push(WriterCompletionRequirement {
                    responsibility: Some(CompletionResponsibility::Host),
                    id: "plan:host-check".into(),
                    kind: WriterCompletionRequirementKind::Plan,
                    source: "plan.md#host-check".into(),
                    requirement: "Verify the recovered candidate on the host".into(),
                    verification_refs: vec![],
                    command: Some(fluent::work_model::PlanCommand {
                        applicability: Default::default(),
                        command: "true".into(),
                        working_directory: ".".into(),
                        environment: Default::default(),
                        source_row: "plan:host-check".into(),
                    }),
                });
            Ok(())
        })
        .unwrap();
    let initial = first_store.read_work_item(&first.work).unwrap();
    let contract = initial.attempts[0]
        .writer_completion_contract
        .as_ref()
        .unwrap();
    for task in &initial.attempts[0].tasks {
        let path = first
            .project
            .join(&task.artifact_area.as_ref().unwrap().path)
            .join("writer-completion.json");
        fs::write(
            path,
            serde_json::to_vec_pretty(
                &WriterCompletionMatrix::skeleton(contract, &task.id, &[], None).unwrap(),
            )
            .unwrap(),
        )
        .unwrap();
    }
    let (fixture, old_audit) = later_recovery_from_first_fixture(&tmp, first, false);
    let old_authority: serde_json::Value = serde_json::from_slice(&old_audit).unwrap();
    assert!(old_authority.get("source-matrix-sha256").is_none());
    let store = WorkModelStore::new(&fixture.project);
    let before = store.read_work_item(&fixture.work).unwrap();
    let action = read_work_show_json(&fixture.project, &fixture.work)["next-action"]
        .as_str()
        .unwrap()
        .to_string();
    assert!(action.contains("repair-writer-completion"), "{action}");
    let resolution = "Correct a later malformed Writer matrix after output-free recovery";
    let repair = || {
        let mut command = fluent_cmd();
        command.current_dir(&fixture.project).args([
            "attempt",
            "repair-writer-completion",
            &fixture.work,
            "attempt-1",
            "--resolution",
            resolution,
        ]);
        command
    };
    repair().assert().success();
    let approved = store.read_work_item(&fixture.work).unwrap();
    assert_eq!(approved.attempts[0].recovery_operations.len(), 2);
    assert_eq!(fs::read(&fixture.audit).unwrap(), old_audit);
    repair().assert().success();
    assert_eq!(store.read_work_item(&fixture.work).unwrap(), approved);
    let second = approved.attempts[0].tasks.last().unwrap();
    let current_audit = fixture.project.join(format!(
        ".fluent/work/artifacts/{}/attempt-1/writer-completion-recoveries/{}/recovery.json",
        fixture.work, second.id,
    ));
    let new_audit = fs::read(&current_audit).unwrap();
    let area = fixture
        .project
        .join(&second.artifact_area.as_ref().unwrap().path);
    let source = before.attempts[0].tasks.last().unwrap();
    let source_matrix = fixture
        .project
        .join(&source.artifact_area.as_ref().unwrap().path)
        .join("writer-completion.json");
    let mut run = fluent_cmd();
    run.current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1"]);
    if std::env::var("FLUENT_WORKFLOW_REQUIRE_HOST").as_deref() != Ok("1") {
        run.arg("--no-sandbox");
    }
    run.env(
        "PATH",
        mock_path(&tmp.path().join("first-correction-provider")),
    )
    .env("RECOVERY_AREA", &area)
    .env(
        "RECOVERY_AREA_REL",
        &second.artifact_area.as_ref().unwrap().path,
    )
    .env("RECOVERY_SOURCE_MATRIX", &source_matrix)
    .env("RECOVERY_OLD_AUDIT", &fixture.audit)
    .env("RECOVERY_CURRENT_AUDIT", &current_audit)
    .assert()
    .success();
    assert_eq!(
        store.read_work_item(&fixture.work).unwrap().attempts[0]
            .tasks
            .last()
            .unwrap()
            .status,
        TaskStatus::Complete
    );
    assert_eq!(fs::read(&fixture.audit).unwrap(), old_audit);
    assert_eq!(fs::read(current_audit).unwrap(), new_audit);
    let next = read_work_show_json(&fixture.project, &fixture.work);
    assert_eq!(next["attempts"][0]["pause_kind"], "candidate-gate");
    assert!(
        next["next-action"]
            .as_str()
            .is_some_and(|action| action.contains("queue resume"))
    );
}

#[test]
fn writer_completion_recovery_later_replays_exact_incident() {
    let tmp = TempDir::new().unwrap();
    let (fixture, old_audit) = later_committed_matrix_recovery_fixture(&tmp);
    let store = WorkModelStore::new(&fixture.project);
    let before = store.read_work_item(&fixture.work).unwrap();
    committed_matrix_repair_command(&fixture)
        .assert()
        .failure()
        .stderr(predicate::str::contains("distinct authorization decision"));
    assert_eq!(store.read_work_item(&fixture.work).unwrap(), before);
    let resolution = "Approve the later committed Writer correction";
    let repair = || {
        let mut command = fluent_cmd();
        command.current_dir(&fixture.project).args([
            "attempt",
            "repair-writer-completion",
            &fixture.work,
            "attempt-1",
            "--resolution",
            resolution,
        ]);
        command
    };
    repair().assert().success();
    let first = store.read_work_item(&fixture.work).unwrap();
    let new_audit_path = fixture.project.join(format!(
        ".fluent/work/artifacts/{}/attempt-1/writer-completion-recoveries/attempt-1-write-4/recovery.json",
        fixture.work,
    ));
    let new_audit = fs::read(&new_audit_path).unwrap();
    assert_ne!(new_audit, old_audit);
    assert_ne!(new_audit_path, fixture.audit);
    assert_ne!(
        first.attempts[0].recovery_operations[0].operation_id,
        first.attempts[0].recovery_operations[1].operation_id
    );
    repair().assert().success();
    let repeated = store.read_work_item(&fixture.work).unwrap();
    assert_eq!(repeated.attempts[0].tasks, first.attempts[0].tasks);
    assert_eq!(
        repeated.attempts[0].recovery_operations,
        first.attempts[0].recovery_operations
    );
    assert_eq!(fs::read(new_audit_path).unwrap(), new_audit);
    assert_eq!(fs::read(&fixture.audit).unwrap(), old_audit);
}

#[test]
fn writer_completion_recovery_later_rejects_changed_source_and_cancellation() {
    for defect in ["matrix", "candidate", "assignment", "canceled"] {
        let tmp = TempDir::new().unwrap();
        let (fixture, old_audit) = later_committed_matrix_recovery_fixture(&tmp);
        let store = WorkModelStore::new(&fixture.project);
        fluent_cmd()
            .current_dir(&fixture.project)
            .args([
                "attempt",
                "repair-writer-completion",
                &fixture.work,
                "attempt-1",
                "--resolution",
                "Approve later correction",
            ])
            .assert()
            .success();
        let item = store.read_work_item(&fixture.work).unwrap();
        let source = &item.attempts[0].tasks[3];
        match defect {
            "matrix" => fs::write(
                fixture
                    .project
                    .join(&source.artifact_area.as_ref().unwrap().path)
                    .join("writer-completion.json"),
                b"changed matrix",
            )
            .unwrap(),
            "candidate" => {
                commit_file(
                    &fixture.workspace,
                    "drift.txt",
                    "drift\n",
                    "Change later candidate",
                );
            }
            "assignment" => store
                .mutate_work_item(&fixture.work, |item| {
                    let source = &mut item.attempts[0].tasks[3];
                    source
                        .workspace_access
                        .reads
                        .push(source.workspace_access.writes[0].clone());
                    Ok(())
                })
                .unwrap(),
            "canceled" => {
                fluent_cmd()
                    .current_dir(&fixture.project)
                    .args(["attempt", "cancel", &fixture.work, "attempt-1"])
                    .assert()
                    .success();
            }
            _ => unreachable!(),
        }
        let before = snapshot_tree(&fixture.project.join(".fluent/work"));
        fluent_cmd()
            .current_dir(&fixture.project)
            .args([
                "attempt",
                "repair-writer-completion",
                &fixture.work,
                "attempt-1",
                "--resolution",
                "Approve later correction",
            ])
            .assert()
            .failure();
        assert_eq!(
            snapshot_tree(&fixture.project.join(".fluent/work")),
            before,
            "{defect}"
        );
        assert_eq!(fs::read(&fixture.audit).unwrap(), old_audit);
    }
}

