#[test]
fn writer_completion_plan_context_preserves_obligations() {
    let tmp = TempDir::new().unwrap();
    let fixture = writer_completion_plan_fixture(&tmp);
    fluent_cmd()
        .current_dir(&fixture.project)
        .args([
            "attempt",
            "repair-writer-completion",
            &fixture.work,
            "attempt-1",
            "--resolution",
            &fixture.resolution,
        ])
        .assert()
        .success();
    run_writer_completion_plan_successor(&fixture, &tmp, false);
    let store = WorkModelStore::new(&fixture.project);
    let item = store.read_work_item(&fixture.work).unwrap();
    let source = &item.attempts[0].tasks[0];
    let successor = &item.attempts[0].tasks[1];
    let source_matrix: WriterCompletionMatrix = serde_json::from_slice(
        &fs::read(
            fixture
                .project
                .join(&source.artifact_area.as_ref().unwrap().path)
                .join("writer-completion.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert_eq!(source_matrix.rows[0].state, WriterCompletionState::Complete);
    assert_eq!(source_matrix.rows[1].state, WriterCompletionState::Pending);
    assert_eq!(source_matrix.rows[2].state, WriterCompletionState::Pending);
    let area = fixture
        .project
        .join(&successor.artifact_area.as_ref().unwrap().path);
    let context: serde_json::Value =
        serde_json::from_slice(&fs::read(area.join("execution-context.json")).unwrap()).unwrap();
    let pending = context["pending-writer-rows"].as_array().unwrap();
    assert!(
        pending.iter().any(|row| row["id"] == "plan:step-1"),
        "{context}"
    );
    assert!(
        !pending.iter().any(|row| row["id"] == "plan:step-2"),
        "{context}"
    );
    let matrix: WriterCompletionMatrix =
        serde_json::from_slice(&fs::read(area.join("writer-completion.json")).unwrap()).unwrap();
    assert_eq!(matrix.rows[0].state, WriterCompletionState::Complete);
    assert_eq!(matrix.rows[1].state, WriterCompletionState::Complete);
    assert_eq!(matrix.rows[2].state, WriterCompletionState::Pending);
}

#[test]
fn writer_completion_plan_real_sandbox_inputs() {
    if std::env::var("FLUENT_WORKFLOW_REQUIRE_HOST").as_deref() != Ok("1") {
        return;
    }
    assert!(
        Path::new("/usr/bin/sandbox-exec").is_file(),
        "strict host probe requires sandbox-exec"
    );
    let tmp = TempDir::new().unwrap();
    let fixture = writer_completion_plan_fixture(&tmp);
    fluent_cmd()
        .current_dir(&fixture.project)
        .args([
            "attempt",
            "repair-writer-completion",
            &fixture.work,
            "attempt-1",
            "--resolution",
            &fixture.resolution,
        ])
        .assert()
        .success();
    let store = WorkModelStore::new(&fixture.project);
    let item = store.read_work_item(&fixture.work).unwrap();
    let source = &item.attempts[0].tasks[0];
    let successor = &item.attempts[0].tasks[1];
    let area = fixture
        .project
        .join(&successor.artifact_area.as_ref().unwrap().path);
    let source_matrix = fixture
        .project
        .join(&source.artifact_area.as_ref().unwrap().path)
        .join("writer-completion.json");
    let audit = fixture.project.join(format!(
        ".fluent/work/artifacts/{}/attempt-1/writer-completion-recoveries/{}/recovery.json",
        fixture.work, successor.id,
    ));
    let source_bytes = fs::read(&source_matrix).unwrap();
    let audit_bytes = fs::read(&audit).unwrap();
    let outside_roots = tempfile::Builder::new()
        .prefix("fluent-plan-sandbox-")
        .tempdir_in(env!("CARGO_MANIFEST_DIR"))
        .unwrap();
    let unrelated = outside_roots.path().join("unrelated.txt");
    fs::write(&unrelated, "outside fixture\n").unwrap();
    let bin = tmp.path().join("plan-sandbox-provider");
    write_mock_claude(
        &bin,
        r#"#!/bin/bash
set -eu
python3 - "$@" <<'PY'
import hashlib, json, os, sys
from pathlib import Path
prompt = ' '.join(sys.argv[1:])
source_path = Path(os.environ['RECOVERY_SOURCE_MATRIX'])
audit_path = Path(os.environ['RECOVERY_AUDIT'])
context_path = Path(os.environ['RECOVERY_AREA']) / 'execution-context.json'
source = json.loads(source_path.read_text())
audit = json.loads(audit_path.read_text())
context = json.loads(context_path.read_text())
assert audit['resolution'] == os.environ['RECOVERY_RESOLUTION']
assert audit['candidate-commit'] == context['candidate-commit']
assert audit['source-matrix-sha256'] == 'sha256:' + hashlib.sha256(source_path.read_bytes()).hexdigest()
assert any(row['id'] == 'plan:step-1' and row['state'] == 'pending'
           for row in source['rows'])
assert any(row['id'] == 'plan:step-1'
           for row in context['pending-writer-rows'])
assert 'The completed source Writer has completion evidence that needs correction.' in prompt
for delivered in (audit['resolution'], str(audit_path), str(context_path)):
    assert delivered in prompt, delivered
PY
if printf tamper > "$RECOVERY_SOURCE_MATRIX" 2>/dev/null; then exit 91; fi
if printf tamper > "$RECOVERY_AUDIT" 2>/dev/null; then exit 92; fi
if printf tamper > "$RECOVERY_UNRELATED" 2>/dev/null; then exit 93; fi
python3 - <<'PY'
import json, os
from pathlib import Path
area = Path(os.environ['RECOVERY_AREA'])
matrix = area / 'writer-completion.json'
value = json.loads(matrix.read_text())
for row in value['rows']:
    if row.get('responsibility', 'writer') == 'writer':
        row['state'] = 'complete'
        row['implementation-evidence'] = ['candidate.txt: retained implementation']
        row['verification'] = [{'command': 'true', 'result': 'pass'}]
matrix.write_text(json.dumps(value))
(area / 'no-change.json').write_text(json.dumps({
    'schema_version': 1,
    'declaration_path': os.environ['RECOVERY_AREA_REL'] + '/no-change.json',
    'reason': 'The retained candidate already satisfies the Plan row.',
    'verification': [{'command': 'true', 'result': 'pass'}]}))
(area / 'confinement-observed').write_text('denied\n')
PY
"#,
    );
    write_mock_executable(
        &bin,
        "sandbox-exec",
        "#!/bin/bash\nexec /usr/bin/sandbox-exec \"$@\"\n",
    );
    let result = fluent_cmd()
        .current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1"])
        .env("PATH", mock_path(&bin))
        .env("RECOVERY_SOURCE_MATRIX", &source_matrix)
        .env("RECOVERY_AUDIT", &audit)
        .env("RECOVERY_RESOLUTION", &fixture.resolution)
        .env("RECOVERY_UNRELATED", &unrelated)
        .env("RECOVERY_AREA", &area)
        .env(
            "RECOVERY_AREA_REL",
            &successor.artifact_area.as_ref().unwrap().path,
        )
        .output()
        .unwrap();
    assert!(
        result.status.success(),
        "{}\n{}\n{}",
        String::from_utf8_lossy(&result.stdout),
        String::from_utf8_lossy(&result.stderr),
        fs::read_to_string(area.join("provider-stderr.log")).unwrap_or_default()
    );
    assert_eq!(fs::read(&source_matrix).unwrap(), source_bytes);
    assert_eq!(fs::read(&audit).unwrap(), audit_bytes);
    assert_eq!(fs::read(&unrelated).unwrap(), b"outside fixture\n");
    assert_eq!(
        fs::read(area.join("confinement-observed")).unwrap(),
        b"denied\n"
    );
    assert_eq!(
        store.read_work_item(&fixture.work).unwrap().attempts[0].tasks[1].status,
        TaskStatus::Complete
    );
}

#[test]
fn workflow_reachable_failures_have_public_continuation() {
    let tmp = TempDir::new().unwrap();
    let (fixture, malformed) = committed_matrix_recovery_fixture(&tmp);
    let store = WorkModelStore::new(&fixture.project);
    let source = store.read_work_item(&fixture.work).unwrap();
    let source_task = &source.attempts[0].tasks[0];
    let source_matrix = fixture
        .project
        .join(&source_task.artifact_area.as_ref().unwrap().path)
        .join("writer-completion.json");

    let observe = fluent_cmd()
        .current_dir(&fixture.project)
        .args(["work-item", "show", &fixture.work])
        .output()
        .unwrap();
    assert!(observe.status.success());
    let shown: serde_json::Value = serde_json::from_slice(&observe.stdout).unwrap();
    assert!(
        shown["next-action"]
            .as_str()
            .unwrap()
            .contains("repair-writer-completion")
    );
    let repair = fluent_cmd()
        .current_dir(&fixture.project)
        .args([
            "attempt",
            "repair-writer-completion",
            &fixture.work,
            "attempt-1",
            "--resolution",
            &fixture.resolution,
        ])
        .output()
        .unwrap();
    assert!(
        repair.status.success(),
        "{}",
        String::from_utf8_lossy(&repair.stderr)
    );
    let authorized_shown = read_work_show_json(&fixture.project, &fixture.work);
    let authorized = store.read_work_item(&fixture.work).unwrap();
    assert_eq!(authorized.attempts[0].tasks[0], *source_task);
    assert_eq!(fs::read(&source_matrix).unwrap(), malformed);
    let correction = authorized.attempts[0].tasks.last().unwrap();
    assert_eq!(correction.status, TaskStatus::Planned);
    let correction_area = fixture
        .project
        .join(&correction.artifact_area.as_ref().unwrap().path);
    let bin = tmp.path().join("workflow-recovery-provider");
    write_mock_claude(
        &bin,
        r#"#!/bin/bash
set -eu
python3 - <<'PY'
import json, os
from pathlib import Path
area = Path(os.environ['RECOVERY_AREA'])
path = area / 'writer-completion.json'
matrix = json.loads(path.read_text())
for row in matrix['rows']:
    if row.get('responsibility', 'writer') == 'writer':
        row['state'] = 'complete'
        row['implementation-evidence'] = ['candidate.txt: retained source candidate']
        row['verification'] = [{'command': 'true', 'result': 'pass'}]
path.write_text(json.dumps(matrix))
(area / 'no-change.json').write_text(json.dumps({
    'schema_version': 1,
    'declaration_path': os.environ['RECOVERY_AREA_REL'] + '/no-change.json',
    'reason': 'The retained candidate already contains the implementation.',
    'verification': [{'command': 'true', 'result': 'pass'}]}))
PY
"#,
    );
    let require_host = std::env::var("FLUENT_WORKFLOW_REQUIRE_HOST").as_deref() == Ok("1");
    if require_host {
        write_mock_executable(
            &bin,
            "sandbox-exec",
            "#!/bin/bash\nexec /usr/bin/sandbox-exec \"$@\"\n",
        );
    }
    let mut resume = fluent_cmd();
    resume
        .current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1"]);
    if !require_host {
        resume.arg("--no-sandbox");
    }
    let run = resume
        .env("PATH", mock_path(&bin))
        .env("RECOVERY_AREA", &correction_area)
        .env(
            "RECOVERY_AREA_REL",
            &correction.artifact_area.as_ref().unwrap().path,
        )
        .output()
        .unwrap();
    assert!(
        run.status.success(),
        "{}\nprovider stderr: {}",
        String::from_utf8_lossy(&run.stderr),
        fs::read_to_string(correction_area.join("provider-stderr.log")).unwrap_or_default()
    );
    let continued_shown = read_work_show_json(&fixture.project, &fixture.work);
    let continued = store.read_work_item(&fixture.work).unwrap();
    assert_eq!(continued.attempts[0].tasks[1].status, TaskStatus::Complete);
    assert_eq!(continued.attempts[0].tasks[0], *source_task);
    assert_eq!(fs::read(source_matrix).unwrap(), malformed);
    assert_eq!(
        continued.attempts[0]
            .tasks
            .iter()
            .filter(|task| task.kind == TaskKind::Write)
            .count(),
        2
    );

    let trace_dir =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("target/formal/workflow/recovery-observation");
    fs::create_dir_all(&trace_dir).unwrap();
    let snapshots = [
        ("paused-work.json", &shown),
        ("authorized-work.json", &authorized_shown),
        ("continued-work.json", &continued_shown),
    ];
    let mut artifacts = Vec::new();
    for (name, value) in snapshots {
        let bytes = serde_json::to_vec_pretty(value).unwrap();
        fs::write(trace_dir.join(name), &bytes).unwrap();
        artifacts.push(
            serde_json::json!({"path":name,"sha256":format!("{:x}", Sha256::digest(&bytes))}),
        );
    }
    fs::write(trace_dir.join("source-matrix.json"), &malformed).unwrap();
    artifacts.push(serde_json::json!({"path":"source-matrix.json",
        "sha256":format!("{:x}", Sha256::digest(&malformed))}));
    let event = |sequence: u64,
                 boundary: &str,
                 operation: &str,
                 predecessors: Vec<u64>,
                 work: serde_json::Value,
                 exit_code: i32,
                 stdout: String,
                 stderr: String| {
        serde_json::json!({"sequence":sequence,"actor":"operator",
            "operation-id":operation,"generation":null,"boundary":boundary,
            "causal-predecessors":predecessors,"raw-facts":{
                "work":work,"exit-code":exit_code,"stdout":stdout,"stderr":stderr}})
    };
    let binary = fs::read(assert_cmd::cargo::cargo_bin("fluent")).unwrap();
    let trace = serde_json::json!({
    "schema-version":1,"scenario":"malformed-completion-public-recovery",
    "fluent-commit":git_head(Path::new(env!("CARGO_MANIFEST_DIR"))),
    "fluent-binary-sha256":format!("{:x}", Sha256::digest(binary)),
    "model-profile":"recovery-observation","collection-complete":true,
    "artifacts":artifacts,"events":[
        event(1,"paused-observation","work-item-show",vec![],shown,
              observe.status.code().unwrap(),String::from_utf8_lossy(&observe.stdout).into_owned(),
              String::from_utf8_lossy(&observe.stderr).into_owned()),
        event(2,"repair","repair-writer-completion",vec![1],authorized_shown,
              repair.status.code().unwrap(),String::from_utf8_lossy(&repair.stdout).into_owned(),
              String::from_utf8_lossy(&repair.stderr).into_owned()),
        event(3,"resume","attempt-run",vec![2],continued_shown,
              run.status.code().unwrap(),String::from_utf8_lossy(&run.stdout).into_owned(),
              String::from_utf8_lossy(&run.stderr).into_owned()),
    ]});
    fs::write(
        trace_dir.join("production-trace.json"),
        serde_json::to_vec_pretty(&trace).unwrap(),
    )
    .unwrap();
}

#[test]
fn writer_completion_recovery_committed_matrix_public_continuation() {
    let tmp = TempDir::new().unwrap();
    let (fixture, malformed) = committed_matrix_recovery_fixture(&tmp);
    let store = WorkModelStore::new(&fixture.project);
    let source_task = store.read_work_item(&fixture.work).unwrap().attempts[0].tasks[0].clone();
    let source_area = fixture
        .project
        .join(&source_task.artifact_area.as_ref().unwrap().path);
    let action = read_work_show_json(&fixture.project, &fixture.work)["next-action"]
        .as_str()
        .unwrap()
        .to_string();
    assert!(action.contains("repair-writer-completion"), "{action}");
    fluent_cmd()
        .current_dir(&fixture.project)
        .args([
            "attempt",
            "repair-writer-completion",
            &fixture.work,
            "attempt-1",
            "--resolution",
            &fixture.resolution,
        ])
        .assert()
        .success();
    let authorized = store.read_work_item(&fixture.work).unwrap();
    let attempt = &authorized.attempts[0];
    assert_eq!(attempt.tasks[0], source_task);
    assert_eq!(
        attempt.tasks[0].output.as_ref().unwrap().commit,
        fixture.candidate
    );
    assert_eq!(attempt.tasks[1].status, TaskStatus::Planned);
    assert_eq!(
        fs::read(source_area.join("writer-completion.json")).unwrap(),
        malformed
    );
    let correction = &attempt.tasks[1];
    let correction_area = fixture
        .project
        .join(&correction.artifact_area.as_ref().unwrap().path);
    let bin = tmp.path().join("committed-matrix-provider");
    write_mock_claude(
        &bin,
        r#"#!/bin/bash
set -eu
if [ "${FLUENT_WORKFLOW_REQUIRE_HOST:-}" = 1 ]; then
  if printf 'tamper\n' > "$RECOVERY_SOURCE_MATRIX" 2>/dev/null; then
    exit 91
  fi
  printf 'denied\n' > "$RECOVERY_AREA/confinement-observed"
fi
python3 - <<'PY'
import json, os
from pathlib import Path
area = Path(os.environ['RECOVERY_AREA'])
matrix = area / 'writer-completion.json'
value = json.loads(matrix.read_text())
for row in value['rows']:
    if row.get('responsibility', 'writer') == 'writer':
        row['state'] = 'complete'
        row['implementation-evidence'] = ['candidate.txt: retained source candidate']
        row['verification'] = [{'command': 'true', 'result': 'pass'}]
matrix.write_text(json.dumps(value))
(area / 'no-change.json').write_text(json.dumps({'schema_version': 1,
    'declaration_path': os.environ['RECOVERY_AREA_REL'] + '/no-change.json',
    'reason': 'The source candidate already contains the implementation.',
    'verification': [{'command': 'true', 'result': 'pass'}]}))
PY
"#,
    );
    write_mock_executable(
        &bin,
        "sandbox-exec",
        "#!/bin/bash\nexec /usr/bin/sandbox-exec \"$@\"\n",
    );
    let require_host = std::env::var("FLUENT_WORKFLOW_REQUIRE_HOST").as_deref() == Ok("1");
    let mut resume = fluent_cmd();
    resume
        .current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1"]);
    if !require_host {
        resume.arg("--no-sandbox");
    }
    resume
        .env("PATH", mock_path(&bin))
        .env("RECOVERY_AREA", &correction_area)
        .env(
            "RECOVERY_AREA_REL",
            &correction.artifact_area.as_ref().unwrap().path,
        )
        .env(
            "RECOVERY_SOURCE_MATRIX",
            source_area.join("writer-completion.json"),
        )
        .assert()
        .success();
    if require_host {
        assert_eq!(
            fs::read(correction_area.join("confinement-observed")).unwrap(),
            b"denied\n"
        );
    }
    let after = store.read_work_item(&fixture.work).unwrap();
    assert_eq!(after.attempts[0].tasks[0].status, TaskStatus::Complete);
    assert_eq!(after.attempts[0].tasks[1].status, TaskStatus::Complete);
    assert_eq!(
        fs::read(source_area.join("writer-completion.json")).unwrap(),
        malformed
    );
    assert!(
        after.attempts[0]
            .tasks
            .iter()
            .all(|task| task.kind != TaskKind::Tester)
    );
    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin))
        .assert()
        .failure()
        .stderr(predicate::str::contains(
            "requires host action plan:host-check",
        ));
    let next = read_work_show_json(&fixture.project, &fixture.work)["next-action"]
        .as_str()
        .unwrap()
        .to_string();
    assert!(next.contains("evidence attach"), "{next}");
}

#[test]
fn writer_completion_recovery_committed_matrix_rejects_stale_source() {
    for defect in [
        "matrix",
        "transcript",
        "contract",
        "assignment",
        "candidate",
    ] {
        let tmp = TempDir::new().unwrap();
        let (fixture, _) = committed_matrix_recovery_fixture(&tmp);
        let store = WorkModelStore::new(&fixture.project);
        fluent_cmd()
            .current_dir(&fixture.project)
            .args([
                "attempt",
                "repair-writer-completion",
                &fixture.work,
                "attempt-1",
                "--resolution",
                &fixture.resolution,
            ])
            .assert()
            .success();
        let item = store.read_work_item(&fixture.work).unwrap();
        let source_area = fixture.project.join(
            &item.attempts[0].tasks[0]
                .artifact_area
                .as_ref()
                .unwrap()
                .path,
        );
        match defect {
            "matrix" => fs::write(
                source_area.join("writer-completion.json"),
                b"changed malformed bytes",
            )
            .unwrap(),
            "transcript" => fs::write(
                source_area.join("transcript.jsonl"),
                b"changed transcript\n",
            )
            .unwrap(),
            "contract" => store
                .mutate_work_item(&fixture.work, |item| {
                    item.attempts[0]
                        .writer_completion_contract
                        .as_mut()
                        .unwrap()
                        .requirements[0]
                        .requirement
                        .push_str(" changed");
                    Ok(())
                })
                .unwrap(),
            "assignment" => store
                .mutate_work_item(&fixture.work, |item| {
                    let source = &mut item.attempts[0].tasks[0];
                    let reference = source.workspace_access.writes[0].clone();
                    source.workspace_access.reads.push(reference);
                    Ok(())
                })
                .unwrap(),
            "candidate" => commit_file(
                &fixture.workspace,
                "drift.txt",
                "changed\n",
                "Change recovered candidate",
            ),
            _ => unreachable!(),
        }
        let before = snapshot_tree(&fixture.project.join(".fluent/work"));
        fluent_cmd()
            .current_dir(&fixture.project)
            .args([
                "attempt",
                "repair-writer-completion",
                &fixture.work,
                "attempt-1",
                "--resolution",
                &fixture.resolution,
            ])
            .assert()
            .failure();
        assert_eq!(
            snapshot_tree(&fixture.project.join(".fluent/work")),
            before,
            "{defect}"
        );
    }
}

#[test]
fn writer_completion_recovery_committed_matrix_rejects_stale_source_at_start() {
    let tmp = TempDir::new().unwrap();
    let (fixture, _) = committed_matrix_recovery_fixture(&tmp);
    committed_matrix_repair_command(&fixture).assert().success();
    let store = WorkModelStore::new(&fixture.project);
    let approved = store.read_work_item(&fixture.work).unwrap();
    let source = &approved.attempts[0].tasks[0];
    let source_area = fixture
        .project
        .join(&source.artifact_area.as_ref().unwrap().path);
    let source_matrix = source_area.join("writer-completion.json");
    fs::write(&source_matrix, b"changed malformed bytes").unwrap();
    let retained_matrix = fs::read(&source_matrix).unwrap();
    let source_transcript = fs::read(source_area.join("transcript.jsonl")).unwrap();
    let authority = fs::read(&fixture.audit).unwrap();

    let bin = tmp.path().join("stale-source-provider");
    let launched = tmp.path().join("provider-launched");
    write_mock_claude(
        &bin,
        "#!/bin/bash\nset -eu\nprintf 'launched\\n' > \"$RECOVERY_PROVIDER_LAUNCHED\"\nexit 73\n",
    );
    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin))
        .env("RECOVERY_PROVIDER_LAUNCHED", &launched)
        .assert()
        .failure()
        .stderr(predicate::str::contains("recovery source matrix changed"));

    assert!(
        !launched.exists(),
        "stale authority must stop provider launch"
    );
    assert_eq!(store.read_work_item(&fixture.work).unwrap(), approved);
    assert_eq!(fs::read(source_matrix).unwrap(), retained_matrix);
    assert_eq!(
        fs::read(source_area.join("transcript.jsonl")).unwrap(),
        source_transcript
    );
    assert_eq!(fs::read(&fixture.audit).unwrap(), authority);
    assert_eq!(approved.attempts[0].tasks[0].status, TaskStatus::Complete);
    assert_eq!(approved.attempts[0].tasks[1].status, TaskStatus::Planned);
    assert!(
        approved.attempts[0]
            .tasks
            .iter()
            .all(|task| task.kind == TaskKind::Write)
    );
}

