struct SavedWriterAssignmentFixture {
    project: PathBuf,
    work: String,
    source_task_id: String,
    correction_task_id: String,
    source_commit: String,
    corrected_commit: String,
    matrix_path: PathBuf,
    results_path: PathBuf,
}

fn saved_writer_assignment_fixture(tmp: &TempDir) -> SavedWriterAssignmentFixture {
    let work = "saved-writer-assignment".to_string();
    let extractor = "#!/bin/sh\nprintf '%s\\n' '[{\"id\":\"command-0:true\",\"test_harness\":\"shell-harness\",\"status\":\"fail\"}]'\n";
    let (project, source_commit, results_path) = canonical_evidence_fixture_with_extractor(
        tmp,
        &work,
        &["true"],
        serde_json::json!({}),
        Some(extractor),
    );
    let store = WorkModelStore::new(&project);
    let mut item = store.read_work_item(&work).unwrap();
    let source_task_id = item.attempts[0].tasks[0].id.clone();
    let source_output = item.attempts[0].tasks[0].output.clone().unwrap();
    let tester = item.attempts[0]
        .tasks
        .iter()
        .find(|task| task.kind == fluent::work_model::TaskKind::Tester)
        .unwrap()
        .clone();
    let results_relative = results_path
        .strip_prefix(&project)
        .unwrap()
        .to_string_lossy()
        .into_owned();
    let results_input = ArtifactRef {
        producer_id: tester.id.clone(),
        path: results_relative.clone(),
    };
    let contract = fluent::work_model::WriterCompletionContract {
        version: WRITER_COMPLETION_CONTRACT_VERSION,
        requirements: vec![
            WriterCompletionRequirement {
                responsibility: Some(CompletionResponsibility::Writer),
                id: "plan:step-1".into(),
                kind: WriterCompletionRequirementKind::Plan,
                source: "plan.md#step-1".into(),
                requirement: "Preserve the assigned correction".into(),
                verification_refs: Vec::new(),
                command: None,
            },
            WriterCompletionRequirement {
                responsibility: Some(CompletionResponsibility::Writer),
                id: "behavior:fresh-verification:b1".into(),
                kind: WriterCompletionRequirementKind::Behavior,
                source: "behaviors.md#fresh-verification:b1".into(),
                requirement: "THE SYSTEM SHALL verify the corrected candidate.".into(),
                verification_refs: vec![
                    r#"{"kind":"command","command":"true","command_index":0}"#.into(),
                ],
                command: None,
            },
        ],
    };
    item.attempts[0].writer_completion_contract = Some(contract.clone());
    let correction_task_id = item
        .add_next_write_round("attempt-1", vec![results_input.clone()])
        .unwrap();
    let workspace = if Path::new(&source_output.workspace_path).is_absolute() {
        PathBuf::from(&source_output.workspace_path)
    } else {
        project.join(&source_output.workspace_path)
    };
    let workspace = workspace.canonicalize().unwrap();
    commit_file(
        &workspace,
        ".fluent/extract-tester-results",
        "#!/bin/sh\nprintf '%s\\n' '[]'\n",
        "Make corrected Tester pass",
    );
    let corrected_commit = git_head(&workspace);
    assert_ne!(source_commit, corrected_commit);
    {
        let correction = item.attempts[0]
            .tasks
            .iter_mut()
            .find(|task| task.id == correction_task_id)
            .unwrap();
        correction.status = TaskStatus::Complete;
        correction.output = Some(TaskOutput {
            workspace_id: source_output.workspace_id.clone(),
            workspace_path: source_output.workspace_path.clone(),
            source_branch: source_output.source_branch.clone(),
            base_commit: Some(source_commit.clone()),
            commit: corrected_commit.clone(),
            no_change: None,
            learner_canonicalization: None,
        });
    }
    item.attempts[0].status = fluent::work_model::AttemptStatus::NeedsUser;
    item.attempts[0].review_state = Some(fluent::work_model::AttemptReviewState::NotReviewed);
    item.attempts[0].pause_kind = Some(fluent::work_model::PauseKind::WriterCompletion);

    let mut historical = item.attempts[0].clone();
    historical.tasks.pop();
    historical.status = fluent::work_model::AttemptStatus::Reviewing;
    historical.pause_kind = None;
    historical.pause_recovery = None;
    historical.pause_record = None;
    let assessment =
        fluent::verification_assessment::assess_current_verification(&project, &historical)
            .unwrap();
    let findings = assessment
        .candidate_defects()
        .into_iter()
        .map(|row| WriterCompletionFinding {
            id: format!("finding:verification:{}", row.id),
            role: "verification".into(),
            source: row.source.clone(),
            requirement: row.diagnostics.join("; "),
        })
        .collect::<Vec<_>>();
    assert_eq!(findings.len(), 1, "fixture must preserve one source defect");
    let mut matrix =
        WriterCompletionMatrix::skeleton(&contract, &correction_task_id, &findings, None).unwrap();
    for row in &mut matrix.rows {
        row.state = WriterCompletionState::Complete;
        row.implementation_evidence =
            vec!["The corrected candidate preserves the source assignment.".into()];
        row.verification = vec![WriterVerificationClaim {
            command: "cargo test saved_writer_assignment".into(),
            result: WriterVerificationResult::Pass,
        }];
        if row.kind == WriterCompletionRequirementKind::Finding {
            row.applicable_constraints = vec!["plan:step-1".into()];
        }
    }
    matrix
        .status_against(&contract, &correction_task_id, &findings)
        .unwrap();
    let matrix_path = project.join(
        item.attempts[0]
            .tasks
            .iter()
            .find(|task| task.id == correction_task_id)
            .unwrap()
            .artifact_area
            .as_ref()
            .unwrap()
            .path
            .clone(),
    );
    let matrix_path = matrix_path.join("writer-completion.json");
    fs::create_dir_all(matrix_path.parent().unwrap()).unwrap();
    fs::write(&matrix_path, serde_json::to_vec_pretty(&matrix).unwrap()).unwrap();
    fs::write(
        matrix_path.parent().unwrap().join("transcript.jsonl"),
        "{}\n",
    )
    .unwrap();
    store.write_work_item(&item).unwrap();
    let saved = store.read_work_item(&work).unwrap();
    assert!(
        saved.attempts[0]
            .tasks
            .last()
            .unwrap()
            .writer_correction_assignment
            .is_none()
    );

    SavedWriterAssignmentFixture {
        project,
        work,
        source_task_id,
        correction_task_id,
        source_commit,
        corrected_commit,
        matrix_path,
        results_path,
    }
}

