// Model the historical source continuation before invoking public Task execution.
fn assignment_context_fixture() -> RetiredCommitStyleBinaryFixture {
    use fluent::work_model::*;
    let fixture = make_current_commit_style_binary_fixture();
    let store = WorkModelStore::new(&fixture.project_root);
    let mut item = store.read_work_item("work-1").unwrap();
    let mut initial = item.attempts[0].tasks[0].clone();
    initial.id = "attempt-1-initial-writer".into();
    initial.artifact_area.as_mut().unwrap().path =
        ".fluent/work/artifacts/work-1/attempt-1/attempt-1-initial-writer".into();
    let output = initial.output.as_mut().unwrap();
    output.commit = output.base_commit.take().unwrap();
    item.attempts[0].tasks.insert(0, initial);
    let attempt = &mut item.attempts[0];
    let progress = ".fluent/work/progress/work-1/attempt-1/progress.md";
    let handoff = ".fluent/work/artifacts/work-1/attempt-1/required-progress-needs-user.md";
    for path in [
        progress,
        handoff,
        ".fluent/work/artifacts/work-1/attempt-1/writer-completion-needs-user.md",
    ] {
        let full = fixture.project_root.join(path);
        fs::create_dir_all(full.parent().unwrap()).unwrap();
        fs::write(full, format!("Original context: {path}\n")).unwrap();
        attempt.tasks[1].input_artifacts.push(ArtifactRef {
            producer_id: "required-progress".into(),
            path: path.into(),
        });
    }
    let contract: WriterCompletionContract = serde_json::from_value(serde_json::json!({
        "version": WRITER_COMPLETION_CONTRACT_VERSION,
        "requirements": [{"id":"plan:host", "kind":"plan", "source":"plan.md#host",
            "requirement":"Run the host check", "responsibility":"host",
            "verification-refs":["true"],
            "command":{"command":"true","working-directory":".","source-row":"plan:host"}}]
    }))
    .unwrap();
    attempt.writer_completion_contract = Some(contract.clone());
    let source = &attempt.tasks[1];
    let matrix = WriterCompletionMatrix::skeleton(&contract, &source.id, &[], None).unwrap();
    fs::write(
        fixture
            .project_root
            .join(&source.artifact_area.as_ref().unwrap().path)
            .join("writer-completion.json"),
        serde_json::to_vec_pretty(&matrix).unwrap(),
    )
    .unwrap();
    attempt.tasks[2].status = TaskStatus::Planned;
    attempt.tasks[2].completed_at = None;
    attempt.status = AttemptStatus::Planned;
    attempt.pause_kind = None;
    attempt.pause_record = None;
    store.write_work_item(&item).unwrap();
    fixture
}

fn run_assignment_context_correction(fixture: &RetiredCommitStyleBinaryFixture) {
    let bin = fixture._root.path().join("context-provider");
    write_mock_claude(
        &bin,
        r##"#!/bin/bash
set -eu
printf 'Updated by Writer\n' >> "$CONTEXT_PROGRESS"
printf 'Updated handoff\n' > "$CONTEXT_HANDOFF"
jq '.rows |= map(if .responsibility == "host" then . else .state = "complete" | ."implementation-evidence" = ["Remove blocked.txt"] | .verification = [{"command":"true","result":"pass"}] | ."applicable-constraints" = ["none: the gate finding concerns project policy"] end)' "$CONTEXT_MATRIX" > "$CONTEXT_MATRIX.tmp"
mv "$CONTEXT_MATRIX.tmp" "$CONTEXT_MATRIX"
git rm blocked.txt
git commit -m "Remove blocked candidate" -m "- Satisfy the project check"
"##,
    );
    fluent_cmd()
        .current_dir(&fixture.project_root)
        .args([
            "task",
            "run",
            "work-1",
            "attempt-1",
            "attempt-1-write-2",
            "--no-sandbox",
        ])
        .env("PATH", mock_path(&bin))
        .env(
            "CONTEXT_PROGRESS",
            fixture
                .project_root
                .join(".fluent/work/progress/work-1/attempt-1/progress.md"),
        )
        .env(
            "CONTEXT_HANDOFF",
            fixture
                .project_root
                .join(".fluent/work/artifacts/work-1/attempt-1/required-progress-needs-user.md"),
        )
        .env(
            "CONTEXT_MATRIX",
            fixture.project_root.join(
                ".fluent/work/artifacts/work-1/attempt-1/attempt-1-write-2/writer-completion.json",
            ),
        )
        .assert()
        .success();
}

#[test]
fn assignment_context_snapshot_survives_progress_updates() {
    for queued in [false, true] {
        let fixture = assignment_context_fixture();
        run_assignment_context_correction(&fixture);
        let item = work_item_value(&fixture.project_root, "work-1");
        let assignment = &item["attempts"][0]["tasks"][2]["writer_correction_assignment"];
        for input in assignment["source_task_inputs"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|input| input["artifact"]["producer_id"] == "required-progress")
        {
            assert!(
                input["artifact"]["path"]
                    .as_str()
                    .unwrap()
                    .contains("/assignment-context/")
            );
            let bytes = fs::read(
                fixture
                    .project_root
                    .join(input["artifact"]["path"].as_str().unwrap()),
            )
            .unwrap();
            assert!(
                String::from_utf8(bytes)
                    .unwrap()
                    .starts_with("Original context:")
            );
        }
        if queued {
            fluent_cmd()
                .current_dir(&fixture.project_root)
                .args(["attempt", "cancel", "work-1", "attempt-1"])
                .assert()
                .success();
            fluent_cmd()
                .current_dir(&fixture.project_root)
                .args(["queue", "resume", "work-1", "--attempt", "attempt-1"])
                .assert()
                .success();
            let dispatch = fluent::scheduler::pick_next_queued(&fixture.project_root)
                .unwrap()
                .unwrap();
            fluent::scheduler::dispatch_one(
                &fixture.project_root,
                &dispatch,
                &EvidenceCliRunner {
                    bin: fixture._root.path().join("context-provider"),
                },
            )
            .unwrap();
        } else {
            fluent_cmd()
                .current_dir(&fixture.project_root)
                .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
                .assert()
                .success();
        }
        let after = work_item_value(&fixture.project_root, "work-1");
        assert_eq!(after["attempts"][0]["pause_kind"], "writer-completion");
        assert!(
            after["attempts"][0]["pause_record"]["next-operation"]["command"]
                .as_str()
                .unwrap()
                .contains("--plan-row plan:host")
        );
        assert_eq!(after["attempts"][0]["tasks"].as_array().unwrap().len(), 3);
        assert_eq!(
            after["attempts"][0]["tasks"][2]["writer_correction_assignment"],
            *assignment
        );
    }
}

// Import a settled version-one assignment as historical input. All subsequent
// recovery and continuation use public commands.
fn legacy_assignment_context_fixture() -> (RetiredCommitStyleBinaryFixture, String, PathBuf) {
    let fixture = assignment_context_fixture();
    run_assignment_context_correction(&fixture);
    let store = WorkModelStore::new(&fixture.project_root);
    store
        .mutate_work_item("work-1", |item| {
            item.attempts[0].status = fluent::work_model::AttemptStatus::NeedsUser;
            item.attempts[0].pause_kind = Some(fluent::work_model::PauseKind::WriterCompletion);
            item.attempts[0].review_state = Some(AttemptReviewState::NotReviewed);
            Ok(())
        })
        .unwrap();
    let record = fixture
        .project_root
        .join(".fluent/work/tasks/work-1/attempt-1/attempt-1-write-2.json");
    let mut value: serde_json::Value = serde_json::from_slice(&fs::read(&record).unwrap()).unwrap();
    let assignment = &mut value["writer_correction_assignment"];
    let mut originals = Vec::new();
    for binding in assignment["evidence"].as_array().unwrap() {
        if binding["artifact"]["producer_id"] == "writer-assignment-context" {
            let original: serde_json::Value = serde_json::from_slice(
                &fs::read(
                    fixture
                        .project_root
                        .join(binding["artifact"]["path"].as_str().unwrap()),
                )
                .unwrap(),
            )
            .unwrap();
            originals.push(original);
        }
    }
    let original_file = fixture
        ._root
        .path()
        .canonicalize()
        .unwrap()
        .join("original-progress.md");
    for original in originals {
        let path = original["artifact"]["path"].as_str().unwrap();
        if path.ends_with("/progress.md") {
            fs::write(&original_file, format!("Original context: {path}\n")).unwrap();
        } else {
            // This incident needs recovery for progress only; handoff still matches.
            fs::write(
                fixture.project_root.join(path),
                format!("Original context: {path}\n"),
            )
            .unwrap();
        }
        let input = assignment["source_task_inputs"]
            .as_array_mut()
            .unwrap()
            .iter_mut()
            .find(|input| input["digest"] == original["digest"])
            .unwrap();
        *input = original;
    }
    assignment["schema_version"] = 1.into();
    assignment["evidence"]
        .as_array_mut()
        .unwrap()
        .retain(|input| input["artifact"]["producer_id"] != "writer-assignment-context");
    fs::write(record, serde_json::to_vec_pretty(&value).unwrap()).unwrap();
    fs::remove_dir_all(
        fixture
            .project_root
            .join(".fluent/work/artifacts/work-1/attempt-1/assignment-context"),
    )
    .unwrap();
    let task = store.read_work_item_snapshot("work-1").unwrap().attempts[0].tasks[2].clone();
    let digest = format!(
        "sha256:{:x}",
        Sha256::digest(
            serde_json::to_vec(task.writer_correction_assignment.as_ref().unwrap()).unwrap()
        )
    );
    (fixture, digest, original_file)
}

fn assignment_context_recovery_command(
    fixture: &RetiredCommitStyleBinaryFixture,
    digest: &str,
    original: &Path,
) -> LoggedCommand {
    assignment_context_recovery_command_for_input(
        fixture,
        digest,
        original,
        ".fluent/work/progress/work-1/attempt-1/progress.md",
    )
}

fn assignment_context_recovery_command_for_input(
    fixture: &RetiredCommitStyleBinaryFixture,
    digest: &str,
    original: &Path,
    input: &str,
) -> LoggedCommand {
    let mut command = fluent_cmd();
    command.current_dir(&fixture.project_root).args([
        "attempt",
        "recover-assignment-context",
        "work-1",
        "attempt-1",
        "--task",
        "attempt-1-write-2",
        "--candidate",
        &git_head(&fixture.workspace),
        "--assignment-digest",
        digest,
        "--input",
        input,
        "--original-file",
        original.to_str().unwrap(),
        "--resolution",
        "Retain the proven original progress bytes",
    ]);
    command
}

#[test]
fn assignment_context_recovery_preserves_original_bytes() {
    let (fixture, digest, original) = legacy_assignment_context_fixture();
    let before = work_item_value(&fixture.project_root, "work-1");
    let progress = fixture
        .project_root
        .join(".fluent/work/progress/work-1/attempt-1/progress.md");
    let current = fs::read(&progress).unwrap();
    let original_bytes = fs::read(&original).unwrap();
    assignment_context_recovery_command(&fixture, &digest, &original)
        .assert()
        .success();
    let after = work_item_value(&fixture.project_root, "work-1");
    assert_eq!(
        after["attempts"][0]["status"],
        before["attempts"][0]["status"]
    );
    assert_eq!(
        after["attempts"][0]["tasks"][1],
        before["attempts"][0]["tasks"][1]
    );
    let mut expected_task = before["attempts"][0]["tasks"][2].clone();
    expected_task["writer_correction_assignment"] =
        after["attempts"][0]["tasks"][2]["writer_correction_assignment"].clone();
    assert_eq!(expected_task, after["attempts"][0]["tasks"][2]);
    let binding = &expected_task["writer_correction_assignment"]["source_task_inputs"][1];
    assert_eq!(
        fs::read(
            fixture
                .project_root
                .join(binding["artifact"]["path"].as_str().unwrap())
        )
        .unwrap(),
        original_bytes
    );
    assert_eq!(fs::read(progress).unwrap(), current);
    assert_eq!(fs::read(original).unwrap(), original_bytes);
    assert_eq!(
        after["attempts"][0]["recovery_operations"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    assert_eq!(after["attempts"][0]["tasks"].as_array().unwrap().len(), 3);
}

#[test]
fn assignment_context_snapshot_rejects_changed_evidence() {
    for finding in [false, true] {
        let fixture = assignment_context_fixture();
        run_assignment_context_correction(&fixture);
        let item = work_item_value(&fixture.project_root, "work-1");
        let assignment = &item["attempts"][0]["tasks"][2]["writer_correction_assignment"];
        let input = if finding {
            &assignment["evidence"][0]
        } else {
            &assignment["source_task_inputs"][0]
        };
        let path = fixture
            .project_root
            .join(input["artifact"]["path"].as_str().unwrap());
        let mut bytes = fs::read(&path).unwrap();
        bytes.extend_from_slice(b"\n");
        fs::write(&path, bytes).unwrap();
        fluent_cmd()
            .current_dir(&fixture.project_root)
            .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
            .assert()
            .success();
        let after = work_item_value(&fixture.project_root, "work-1");
        assert_eq!(after["attempts"][0]["tasks"], item["attempts"][0]["tasks"]);
        assert_eq!(after["attempts"][0]["status"], "needs-user");
        let handoff = fs::read_dir(
            fixture
                .project_root
                .join(".fluent/work/artifacts/work-1/attempt-1"),
        )
        .unwrap()
        .filter_map(Result::ok)
        .filter(|e| e.file_name().to_string_lossy().ends_with("needs-user.md"))
        .map(|e| fs::read_to_string(e.path()).unwrap())
        .collect::<String>();
        assert!(
            handoff.contains("changed") || handoff.contains("digest"),
            "{handoff}"
        );
    }
}

#[test]
fn assignment_context_recovery_rejects_unsafe_inputs() {
    for case in [
        "digest",
        "assignment",
        "candidate",
        "dirty",
        "directory",
        "symlink",
        "evidence",
        "missing",
        "live-task",
        "live-execution",
        "context-symlink",
        "unrelated",
        "alias",
    ] {
        let (fixture, digest, original) = legacy_assignment_context_fixture();
        let mut requested_digest = digest.clone();
        let mut input = ".fluent/work/progress/work-1/attempt-1/progress.md";
        let mut owner = None;
        match case {
            "missing" => fs::remove_file(&original).unwrap(),
            "live-task" => owner = Some(fluent::lease::acquire(&fluent::lease::task_lock_path(&fixture.project_root, "work-1", "attempt-1-write-2")).unwrap()),
            "live-execution" => owner = Some(fluent::lease::acquire(&fixture.project_root.join(".fluent/work/artifacts/work-1/attempt-1/attempt-1-write-2/execution-owner.lock")).unwrap()),
            "context-symlink" => {
                let path = fixture.project_root.join(input);
                fs::remove_file(&path).unwrap();
                std::os::unix::fs::symlink(&original, path).unwrap();
            },
            "unrelated" => input = ".fluent/work/artifacts/work-1/inputs/0000-context.md",
            "alias" => input = ".fluent/work/progress/work-1/attempt-1/./progress.md",
            "digest" => fs::write(&original, "replacement bytes").unwrap(),
            "assignment" => requested_digest = format!("sha256:{}", "0".repeat(64)),
            "candidate" => commit_file(
                &fixture.workspace,
                "later.txt",
                "later\n",
                "Add later candidate",
            ),
            "dirty" => fs::write(fixture.workspace.join("candidate.txt"), "dirty\n").unwrap(),
            "directory" => {
                fs::remove_file(&original).unwrap();
                fs::create_dir(&original).unwrap();
            }
            "symlink" => {
                fs::remove_file(&original).unwrap();
                std::os::unix::fs::symlink(
                    fixture
                        .project_root
                        .join(".fluent/work/progress/work-1/attempt-1/progress.md"),
                    &original,
                )
                .unwrap();
            }
            "evidence" => fs::write(&fixture.gate_path, "changed finding").unwrap(),
            _ => unreachable!(),
        }
        let before = snapshot_tree(&fixture.project_root);
        let workspace = snapshot_tree(&fixture.workspace);
        let expected = match case {
            "digest" => "original bytes do not match",
            "assignment" => "saved assignment digest",
            "candidate" | "dirty" => "candidate is stale",
            "directory" => "unsupported recovery file",
            "symlink" => "traverses a symlink",
            "context-symlink" => "unsafe path",
            "missing" => "No such file",
            "live-task" => "live owner",
            "live-execution" => "live execution owner",
            "unrelated" => "not recognized mutable",
            "alias" => "not assigned",
            "evidence" => "Writer assignment input changed",
            _ => unreachable!(),
        };
        assignment_context_recovery_command_for_input(
            &fixture,
            &requested_digest,
            &original,
            input,
        )
        .assert()
        .failure()
        .stderr(predicate::str::contains(expected));
        assert_eq!(snapshot_tree(&fixture.project_root), before, "{case}");
        assert_eq!(snapshot_tree(&fixture.workspace), workspace, "{case}");
        drop(owner);
    }
}

#[test]
fn assignment_context_recovery_is_idempotent() {
    for interruption in [
        None,
        Some("audit"),
        Some("journal"),
        Some("attempt"),
        Some("task"),
        Some("children"),
    ] {
        let (fixture, digest, original) = legacy_assignment_context_fixture();
        let initial = work_item_value(&fixture.project_root, "work-1");
        let progress = fixture
            .project_root
            .join(".fluent/work/progress/work-1/attempt-1/progress.md");
        let current_context = fs::read(&progress).unwrap();
        let original_context = fs::read(&original).unwrap();
        if let Some(point) = interruption {
            assignment_context_recovery_command(&fixture, &digest, &original)
                .env("FLUENT_TEST_ASSIGNMENT_CONTEXT_INTERRUPT", point)
                .assert()
                .code(86);
        }
        let first = assignment_context_recovery_command(&fixture, &digest, &original)
            .output()
            .unwrap();
        assert!(
            first.status.success(),
            "{interruption:?}: {}",
            String::from_utf8_lossy(&first.stderr)
        );
        let before = snapshot_tree(&fixture.project_root);
        let second = assignment_context_recovery_command(&fixture, &digest, &original)
            .output()
            .unwrap();
        assert!(
            second.status.success(),
            "{}",
            String::from_utf8_lossy(&second.stderr)
        );
        assert_eq!(second.stdout, first.stdout);
        assert_eq!(snapshot_tree(&fixture.project_root), before);
        let recovered = work_item_value(&fixture.project_root, "work-1");
        assert_eq!(
            recovered["attempts"][0]["recovery_operations"]
                .as_array()
                .unwrap()
                .len(),
            1
        );
        let mut expected_tasks = initial["attempts"][0]["tasks"].clone();
        expected_tasks[2]["writer_correction_assignment"] =
            recovered["attempts"][0]["tasks"][2]["writer_correction_assignment"].clone();
        assert_eq!(recovered["attempts"][0]["tasks"], expected_tasks);
        assert_eq!(
            recovered["attempts"][0]["status"],
            initial["attempts"][0]["status"]
        );
        assert_eq!(fs::read(&progress).unwrap(), current_context);
        assert_eq!(fs::read(&original).unwrap(), original_context);
        fluent_cmd()
            .current_dir(&fixture.project_root)
            .args(["attempt", "cancel", "work-1", "attempt-1"])
            .assert()
            .success();
        let stopped = snapshot_tree(&fixture.project_root);
        assignment_context_recovery_command(&fixture, &digest, &original)
            .assert()
            .success();
        assert_eq!(
            snapshot_tree(&fixture.project_root),
            stopped,
            "replay must retain a later stop"
        );
    }
}

