#[test]
fn assignment_context_recovery_rejects_unmatched_pending_publication() {
    for point in ["journal", "attempt", "task", "children"] {
        let (fixture, digest, original) = legacy_assignment_context_fixture();
        assignment_context_recovery_command(&fixture, &digest, &original)
            .env("FLUENT_TEST_ASSIGNMENT_CONTEXT_INTERRUPT", point)
            .assert()
            .code(86);
        let before = snapshot_tree(&fixture.project_root);
        assignment_context_recovery_command(&fixture, "sha256:wrong", &original)
            .assert()
            .failure();
        assert_eq!(snapshot_tree(&fixture.project_root), before);
        assignment_context_recovery_command_for_input(
            &fixture,
            &digest,
            &original,
            ".fluent/work/artifacts/work-1/attempt-1/writer-completion-needs-user.md",
        )
        .assert()
        .failure();
        assert_eq!(snapshot_tree(&fixture.project_root), before);

        let task_path = fixture
            .project_root
            .join(".fluent/work/tasks/work-1/attempt-1/attempt-1-write-2.json");
        let task_bytes = fs::read(&task_path).unwrap();
        let mut task: serde_json::Value = serde_json::from_slice(&task_bytes).unwrap();
        task["status"] = "running".into();
        fs::write(&task_path, serde_json::to_vec_pretty(&task).unwrap()).unwrap();
        let changed = snapshot_tree(&fixture.project_root);
        assignment_context_recovery_command(&fixture, &digest, &original)
            .assert()
            .failure();
        assert_eq!(snapshot_tree(&fixture.project_root), changed);
        fs::write(&task_path, &task_bytes).unwrap();

        let attempt_path = fixture
            .project_root
            .join(".fluent/work/attempts/work-1/attempt-1.json");
        let attempt_bytes = fs::read(&attempt_path).unwrap();
        let mut attempt: serde_json::Value = serde_json::from_slice(&attempt_bytes).unwrap();
        attempt["cancellation"] = serde_json::json!({
            "requested_at": "2026-09-16T00:00:00Z",
            "settled_at": "2026-09-16T00:00:00Z"
        });
        fs::write(&attempt_path, serde_json::to_vec_pretty(&attempt).unwrap()).unwrap();
        let changed = snapshot_tree(&fixture.project_root);
        assignment_context_recovery_command(&fixture, &digest, &original)
            .assert()
            .failure();
        assert_eq!(snapshot_tree(&fixture.project_root), changed);
        fs::write(&attempt_path, &attempt_bytes).unwrap();

        let lock =
            fluent::lease::task_lock_path(&fixture.project_root, "work-1", "attempt-1-write-2");
        let owner = fluent::lease::acquire(&lock).unwrap();
        let owned = snapshot_tree(&fixture.project_root);
        assignment_context_recovery_command(&fixture, &digest, &original)
            .assert()
            .failure();
        assert_eq!(snapshot_tree(&fixture.project_root), owned);
        drop(owner);

        let journal_path = fixture
            .project_root
            .join(".fluent/work/transactions/work-1.json");
        let journal_bytes = fs::read(&journal_path).unwrap();
        let mut journal = read_json_path(&journal_path);
        assert_eq!(journal["schema_version"], 14);
        journal["assignment_context_base"]["attempts"][0]["status"] = "planned".into();
        write_json_path(&journal_path, &journal);
        let changed = snapshot_tree(&fixture.project_root);
        assignment_context_recovery_command(&fixture, &digest, &original)
            .assert()
            .failure();
        assert_eq!(snapshot_tree(&fixture.project_root), changed);
        fs::write(&journal_path, journal_bytes).unwrap();

        let audit_path = journal["work_item"]["attempts"][0]["artifacts"]
            .as_array()
            .unwrap()
            .iter()
            .find(|a| a["producer_id"] == "assignment-context-recovery")
            .unwrap()["path"]
            .as_str()
            .unwrap();
        let audit_path = fixture.project_root.join(audit_path);
        let audit_bytes = fs::read(&audit_path).unwrap();
        let mut audit = read_json_path(&audit_path);
        audit["attempt_digest"] = "changed audit".into();
        write_json_path(&audit_path, &audit);
        let changed = snapshot_tree(&fixture.project_root);
        assignment_context_recovery_command(&fixture, &digest, &original)
            .assert()
            .failure();
        assert_eq!(snapshot_tree(&fixture.project_root), changed);
        fs::write(audit_path, audit_bytes).unwrap();
        assignment_context_recovery_command(&fixture, &digest, &original)
            .assert()
            .success();
    }
}

#[test]
fn assignment_context_recovery_resumes_same_attempt() {
    for queued in [false, true] {
        let (fixture, digest, original) = legacy_assignment_context_fixture();
        assignment_context_recovery_command(&fixture, &digest, &original)
            .assert()
            .success();
        let recovered = work_item_value(&fixture.project_root, "work-1");
        let args = if queued {
            vec!["queue", "resume", "work-1", "--attempt", "attempt-1"]
        } else {
            vec!["attempt", "run", "work-1", "attempt-1", "--no-sandbox"]
        };
        fluent_cmd()
            .current_dir(&fixture.project_root)
            .args(args)
            .assert()
            .failure()
            .stderr(predicate::str::contains("requires host action plan:host"));
        let after = work_item_value(&fixture.project_root, "work-1");
        assert_eq!(after["attempts"].as_array().unwrap().len(), 1);
        assert_eq!(
            after["attempts"][0]["tasks"],
            recovered["attempts"][0]["tasks"]
        );
        assert_eq!(
            after["attempts"][0]["recovery_operations"],
            recovered["attempts"][0]["recovery_operations"]
        );
        assert!(
            after["next-action"]
                .as_str()
                .unwrap()
                .contains("--plan-row plan:host")
        );
        assert!(merge_candidates_are_empty(&after));
    }
}

