fn assignment_context_recovery_inspection_is_read_only() {
    for interruption in [
        None,
        Some("audit"),
        Some("journal"),
        Some("attempt"),
        Some("task"),
        Some("children"),
    ] {
        let (fixture, digest, original) = legacy_assignment_context_fixture();
        if let Some(point) = interruption {
            assignment_context_recovery_command(&fixture, &digest, &original)
                .env("FLUENT_TEST_ASSIGNMENT_CONTEXT_INTERRUPT", point)
                .assert()
                .code(86);
        }
        let before = snapshot_tree(&fixture.project_root);
        for args in [
            vec!["status"],
            vec!["work-item", "show", "work-1"],
            vec!["attempt", "show", "work-1", "attempt-1"],
            vec!["task", "show", "work-1", "attempt-1", "attempt-1-write-2"],
        ] {
            let output = fluent_cmd()
                .current_dir(&fixture.project_root)
                .args(&args)
                .output()
                .unwrap();
            if matches!(interruption, Some("attempt" | "task" | "children")) && args[0] != "status"
            {
                assert!(
                    !output.status.success(),
                    "withhold a partially published aggregate"
                );
            } else {
                assert!(
                    output.status.success(),
                    "{}",
                    String::from_utf8_lossy(&output.stderr)
                );
            }
            assert_eq!(
                snapshot_tree(&fixture.project_root),
                before,
                "{interruption:?}"
            );
        }
        if matches!(interruption, Some("attempt" | "task" | "children")) {
            continue;
        }
        let value = work_item_value(&fixture.project_root, "work-1");
        assert!(
            value["next-action"]
                .as_str()
                .unwrap()
                .contains("recover-assignment-context"),
            "{value}"
        );
        assert_eq!(snapshot_tree(&fixture.project_root), before);
    }
}

#[test]
fn assignment_context_recovery_concurrent_requests_and_stale_publication() {
    let (fixture, digest, original) = legacy_assignment_context_fixture();
    let mut first = assignment_context_recovery_command(&fixture, &digest, &original);
    let mut second = assignment_context_recovery_command(&fixture, &digest, &original);
    let (a, b) = std::thread::scope(|scope| {
        let a = scope.spawn(move || first.output().unwrap());
        let b = scope.spawn(move || second.output().unwrap());
        (a.join().unwrap(), b.join().unwrap())
    });
    assert!(a.status.success(), "{}", String::from_utf8_lossy(&a.stderr));
    assert!(b.status.success(), "{}", String::from_utf8_lossy(&b.stderr));
    assert_eq!(a.stdout, b.stdout);
    let after = work_item_value(&fixture.project_root, "work-1");
    assert_eq!(
        after["attempts"][0]["recovery_operations"]
            .as_array()
            .unwrap()
            .len(),
        1
    );

    let (fixture, digest, original) = legacy_assignment_context_fixture();
    assignment_context_recovery_command(&fixture, &digest, &original)
        .env("FLUENT_TEST_ASSIGNMENT_CONTEXT_INTERRUPT", "audit")
        .assert()
        .code(86);
    fluent_cmd()
        .current_dir(&fixture.project_root)
        .args(["attempt", "cancel", "work-1", "attempt-1"])
        .assert()
        .success();
    let stopped = snapshot_tree(&fixture.project_root);
    assignment_context_recovery_command(&fixture, &digest, &original)
        .assert()
        .failure()
        .stderr(predicate::str::contains(
            "Attempt changed after interrupted publication",
        ));
    assert_eq!(snapshot_tree(&fixture.project_root), stopped);
}

#[test]
fn assignment_context_compatibility_refuses_published_and_pending_bindings() {
    let binary = writer_assignment_old_reader(
        "FLUENT_USAGE_LIMIT_OLD_BIN",
        "5c670fdd9eec7eda22e93aee4ea619f1c60f7a70",
    );
    for pending in [false, true] {
        for inner in [false, true] {
            let (fixture, digest, original) = legacy_assignment_context_fixture();
            let mut recover = assignment_context_recovery_command(&fixture, &digest, &original);
            if pending {
                recover
                    .env("FLUENT_TEST_ASSIGNMENT_CONTEXT_INTERRUPT", "journal")
                    .assert()
                    .code(86);
            } else {
                recover.assert().success();
            }
            let mut restore = Vec::new();
            if inner {
                // Expose the assignment fence behind the newer envelopes.
                let path = fixture.project_root.join(".fluent/work/items/work-1.json");
                restore.push((path.clone(), fs::read(&path).unwrap()));
                let mut record = read_json_path(&path);
                record["schema_version"] = 6.into();
                record["model_writer_version"]["schema_version"] = 4.into();
                write_json_path(&path, &record);
                let path = fixture
                    .project_root
                    .join(".fluent/work/attempts/work-1/attempt-1.json");
                restore.push((path.clone(), fs::read(&path).unwrap()));
                let mut record = read_json_path(&path);
                record["schema_version"] = 6.into();
                write_json_path(&path, &record);
                if pending {
                    let path = fixture
                        .project_root
                        .join(".fluent/work/transactions/work-1.json");
                    restore.push((path.clone(), fs::read(&path).unwrap()));
                    let mut record = read_json_path(&path);
                    record["schema_version"] = 5.into();
                    write_json_path(&path, &record);
                }
            }
            let before = snapshot_tree(&fixture.project_root);
            let output = Command::new(&binary)
                .current_dir(&fixture.project_root)
                .env("FLUENT_NO_UPDATE_CHECK", "1")
                .args(["work-item", "upgrade", "work-1"])
                .output()
                .unwrap();
            assert!(!output.status.success());
            if inner {
                assert!(
                    String::from_utf8_lossy(&output.stderr)
                        .contains("unsupported Writer correction assignment schema version 2"),
                    "{}",
                    String::from_utf8_lossy(&output.stderr)
                );
            }
            assert_eq!(snapshot_tree(&fixture.project_root), before);
            // Restore the fixture's deliberately lowered envelopes before
            // replaying the genuine journal and its authorized base proof.
            for (path, bytes) in restore {
                fs::write(path, bytes).unwrap();
            }
            // The current reader can finish a real pending publication.
            if pending {
                WorkModelStore::new(&fixture.project_root)
                    .read_work_item("work-1")
                    .unwrap();
            }
        }
    }
}

