fn writer_assignment_prelaunch_probe_script() -> &'static str {
    r##"#!/bin/bash
record="${FLUENT_WRITER_ASSIGNMENT_RECORD:?}"
task="${FLUENT_WRITER_ASSIGNMENT_TASK:?}"
probe="${FLUENT_WRITER_ASSIGNMENT_PROBE:?}"
jq -e --arg task "$task" \
  'select(.id == $task) | .writer_correction_assignment != null' \
  "$record" >/dev/null || exit 91
printf 'assignment-present\n' > "$probe"
printf 'production correction\n' > production-correction.txt
git add production-correction.txt
git commit -m "Apply production correction" >/dev/null
exit 0
"##
}

fn prepare_production_correction(fixture: &SavedWriterAssignmentFixture) -> WorkModelStore {
    let store = WorkModelStore::new(&fixture.project);
    let mut item = store.read_work_item(&fixture.work).unwrap();
    let contract = item.attempts[0].writer_completion_contract.clone().unwrap();
    let mut source_matrix =
        WriterCompletionMatrix::skeleton(&contract, &fixture.source_task_id, &[], None).unwrap();
    for row in &mut source_matrix.rows {
        row.state = WriterCompletionState::Complete;
        row.implementation_evidence = vec!["The source Writer completed the approved plan.".into()];
        row.verification = vec![WriterVerificationClaim {
            command: "true".into(),
            result: WriterVerificationResult::Pass,
        }];
    }
    source_matrix
        .status_against(&contract, &fixture.source_task_id, &[])
        .unwrap();
    let source_matrix_path = item.attempts[0]
        .tasks
        .iter()
        .find(|task| task.id == fixture.source_task_id)
        .unwrap()
        .artifact_area
        .as_ref()
        .map(|area| {
            fixture
                .project
                .join(&area.path)
                .join("writer-completion.json")
        })
        .unwrap();
    fs::write(
        &source_matrix_path,
        serde_json::to_vec_pretty(&source_matrix).unwrap(),
    )
    .unwrap();

    let correction = item.attempts[0]
        .tasks
        .iter_mut()
        .find(|task| task.id == fixture.correction_task_id)
        .unwrap();
    correction.status = TaskStatus::Planned;
    correction.output = None;
    correction.started_at = None;
    correction.completed_at = None;
    item.attempts[0].status = fluent::work_model::AttemptStatus::Planned;
    item.attempts[0].review_state = Some(AttemptReviewState::NotReviewed);
    item.attempts[0].pause_kind = None;
    item.attempts[0].pause_recovery = None;
    item.attempts[0].completed_at = None;
    store.write_work_item(&item).unwrap();
    store
}

fn run_production_correction(
    fixture: &SavedWriterAssignmentFixture,
    writer_bin: &Path,
) -> WorkModelStore {
    let store = prepare_production_correction(fixture);
    write_mock_claude(
        writer_bin,
        r##"#!/bin/bash
printf 'production correction\n' > production-correction.txt
git add production-correction.txt
git commit -m "Apply production correction" >/dev/null
exit 0
"##,
    );
    fluent_cmd()
        .current_dir(&fixture.project)
        .args([
            "task",
            "run",
            &fixture.work,
            "attempt-1",
            &fixture.correction_task_id,
            "--no-sandbox",
        ])
        .env("PATH", mock_path(writer_bin))
        .assert()
        .success();
    store
}

fn run_production_correction_with_prelaunch_probe(
    fixture: &SavedWriterAssignmentFixture,
    writer_bin: &Path,
    probe: &Path,
) -> WorkModelStore {
    let store = prepare_production_correction(fixture);
    write_mock_claude(writer_bin, writer_assignment_prelaunch_probe_script());
    fluent_cmd()
        .current_dir(&fixture.project)
        .args([
            "task",
            "run",
            &fixture.work,
            "attempt-1",
            &fixture.correction_task_id,
            "--no-sandbox",
        ])
        .env("PATH", mock_path(writer_bin))
        .env(
            "FLUENT_WRITER_ASSIGNMENT_RECORD",
            fixture.project.join(format!(
                ".fluent/work/tasks/{}/{}/{}.json",
                fixture.work, "attempt-1", fixture.correction_task_id
            )),
        )
        .env("FLUENT_WRITER_ASSIGNMENT_TASK", &fixture.correction_task_id)
        .env("FLUENT_WRITER_ASSIGNMENT_PROBE", probe)
        .assert()
        .success();
    store
}

#[test]
fn corrective_writer_assignment_binds_source_evidence() {
    let tmp = TempDir::new().unwrap();
    let fixture = saved_writer_assignment_fixture(&tmp);
    let writer_bin = tmp.path().join("bin-production-correction-writer");
    let store = run_production_correction(&fixture, &writer_bin);

    let source_results_path = fixture
        .results_path
        .strip_prefix(&fixture.project)
        .unwrap()
        .to_string_lossy()
        .into_owned();
    let captured = store.read_work_item(&fixture.work).unwrap();
    let correction = captured.attempts[0]
        .tasks
        .iter()
        .find(|task| task.id == fixture.correction_task_id)
        .unwrap();
    let output = correction.output.as_ref().unwrap();
    assert_ne!(output.commit, fixture.corrected_commit);
    let assignment = correction.writer_correction_assignment.as_ref().unwrap();
    assert_eq!(assignment.source_task_id, fixture.source_task_id);
    assert_eq!(assignment.source_candidate_commit, fixture.source_commit);
    assert_eq!(assignment.evidence.len(), 1);
    assert_eq!(assignment.evidence[0].artifact.path, source_results_path);
    assert_eq!(
        assignment.evidence[0].digest,
        format!(
            "sha256:{:x}",
            Sha256::digest(fs::read(&fixture.results_path).unwrap())
        )
    );
    assert_eq!(assignment.findings.len(), 1);
    let finding = &assignment.findings[0];
    assert_eq!(finding.role, "verification");
    assert_eq!(finding.source, source_results_path);
    assert!(!finding.id.is_empty());
    assert!(!finding.requirement.is_empty());

    let matrix = read_json_path(&fixture.matrix_path);
    let matrix_finding = matrix["rows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["id"] == finding.id)
        .expect("the completion matrix retains the assigned finding row");
    assert_eq!(matrix_finding["state"], "complete");
    assert_eq!(
        matrix_finding["requirement"].as_str().unwrap(),
        format!(
            "Address verification review finding: {}",
            finding.requirement
        )
    );

    let review_bin = tmp.path().join("bin-production-correction-gate");
    write_mock_claude(&review_bin, recovery_review_and_learner_mock_script());
    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&review_bin))
        .assert()
        .success();

    let value = work_item_value(&fixture.project, &fixture.work);
    let attempt = &value["attempts"][0];
    let tasks = attempt["tasks"].as_array().unwrap();
    let correction_index = tasks
        .iter()
        .position(|task| task["id"] == fixture.correction_task_id)
        .unwrap();
    assert!(
        tasks[correction_index + 1..]
            .iter()
            .any(|task| task["kind"] == "review"),
        "the production completion gate must admit reviews after the assignment"
    );
    assert!(
        tasks.iter().any(|task| {
            task["kind"] == "tester"
                && task["status"] == "complete"
                && task["review_context"]["candidate_commit"] == output.commit
        }),
        "the corrected candidate must reach its own final Tester"
    );
    let stored_assignment = tasks
        .iter()
        .find(|task| task["id"] == fixture.correction_task_id)
        .unwrap()["writer_correction_assignment"]
        .clone();
    assert_eq!(stored_assignment["source_task_id"], fixture.source_task_id);
    assert_eq!(
        stored_assignment["source_candidate_commit"],
        fixture.source_commit
    );
    assert_eq!(attempt["status"], "complete");
}

