fn recovery_review_and_learner_mock_script() -> &'static str {
    r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  mkdir -p "$(dirname "$DRAFT")"
  printf '%s\n' '{"learning_summary":"recovered","follow_ups":[]}' > "$DRAFT"
else
  if printf '%s' "$PROMPT" | grep -q "You are the Writer"; then
    printf 'writer\n' >> "$(dirname "$0")/writer-invocations"
  fi
  printf 'Verdict: %s\n\nRecovered review.\n' "${RECOVERY_REVIEW_VERDICT:-pass}" > review.md
fi
exit 0
"##
}

#[test]
fn saved_writer_assignment_recovers_through_public_resume() {
    let tmp = TempDir::new().unwrap();
    let fixture = saved_writer_assignment_fixture(&tmp);
    let bin_dir = tmp.path().join("bin-saved-writer-foreground");
    write_mock_claude(&bin_dir, recovery_review_and_learner_mock_script());

    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
        .assert()
        .success()
        .stdout(predicate::str::contains("Queued resume"));
    let dispatch = fluent::scheduler::pick_next_queued(&fixture.project)
        .unwrap()
        .unwrap();
    fluent::scheduler::dispatch_one(
        &fixture.project,
        &dispatch,
        &EvidenceCliRunner {
            bin: bin_dir.clone(),
        },
    )
    .unwrap();

    let value = work_item_value(&fixture.project, &fixture.work);
    let attempt = &value["attempts"][0];
    let tasks = attempt["tasks"].as_array().unwrap();
    assert_eq!(
        tasks.iter().filter(|task| task["kind"] == "write").count(),
        2,
        "foreground recovery must not rerun or append a Writer"
    );
    let assignment = tasks
        .iter()
        .find(|task| task["id"] == fixture.correction_task_id)
        .unwrap()["writer_correction_assignment"]
        .as_object()
        .unwrap();
    assert_eq!(assignment["origin"], "legacy-reconstructed");
    assert_eq!(assignment["source_task_id"], fixture.source_task_id);
    assert_eq!(assignment["source_candidate_commit"], fixture.source_commit);
    assert!(
        !bin_dir.join("writer-invocations").exists(),
        "saved recovery must not invoke the completed Writer"
    );
    assert_eq!(attempt["status"], "complete");
    let correction_index = tasks
        .iter()
        .position(|task| task["id"] == fixture.correction_task_id)
        .unwrap();
    let final_tester_index = tasks
        .iter()
        .enumerate()
        .rev()
        .find(|(_, task)| {
            task["kind"] == "tester"
                && task["status"] == "complete"
                && task["review_context"]["candidate_commit"] == fixture.corrected_commit
        })
        .map(|(index, _)| index)
        .expect("recovery must run a final Tester for the corrected candidate");
    assert!(final_tester_index > correction_index);
    assert!(
        tasks[correction_index + 1..final_tester_index]
            .iter()
            .all(|task| task["kind"] == "review"),
        "ordinary reviews must precede the corrected candidate's final Tester"
    );
}

#[test]
fn corrected_candidate_reaches_reviews_before_final_tester() {
    let tmp = TempDir::new().unwrap();
    let fixture = saved_writer_assignment_fixture(&tmp);
    let bin_dir = tmp.path().join("bin-saved-writer-review-gate");
    write_mock_claude(&bin_dir, recovery_review_and_learner_mock_script());

    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .env("RECOVERY_REVIEW_VERDICT", "uncertain")
        .assert()
        .success()
        .stdout(predicate::str::contains("needs user input"));

    let value = work_item_value(&fixture.project, &fixture.work);
    let attempt = &value["attempts"][0];
    assert_eq!(attempt["status"], "needs-user");
    assert_eq!(attempt["pause_kind"], "uncertain");
    assert!(
        !bin_dir.join("writer-invocations").exists(),
        "completion-gate recovery must not relaunch the completed Writer"
    );
    let tasks = attempt["tasks"].as_array().unwrap();
    let correction_index = tasks
        .iter()
        .position(|task| task["id"] == fixture.correction_task_id)
        .unwrap();
    let reviews = &tasks[correction_index + 1..];
    assert!(!reviews.is_empty());
    assert!(reviews.iter().all(|task| task["kind"] == "review"));
    assert!(reviews.iter().all(|task| task["status"] == "complete"));
    assert!(
        reviews
            .iter()
            .all(|task| task["review_context"]["candidate_commit"] == fixture.corrected_commit),
        "every admitted review must bind to the corrected candidate"
    );
    assert!(
        !tasks.iter().any(|task| {
            task["kind"] == "tester"
                && task["review_context"]["candidate_commit"] == fixture.corrected_commit
        }),
        "the corrected candidate's final Tester is not admitted before reviews pass"
    );
    assert!(merge_candidates_are_empty(&value));
}

#[test]
fn saved_writer_assignment_resume_rejects_unsafe_state() {
    let tmp = TempDir::new().unwrap();
    let fixture = saved_writer_assignment_fixture(&tmp);
    let store = WorkModelStore::new(&fixture.project);
    let before = persisted_work_snapshot(&fixture.project, &fixture.work);
    let candidate_workspace = if Path::new(
        &store.read_work_item(&fixture.work).unwrap().attempts[0]
            .tasks
            .last()
            .unwrap()
            .output
            .as_ref()
            .unwrap()
            .workspace_path,
    )
    .is_absolute()
    {
        PathBuf::from(
            &store.read_work_item(&fixture.work).unwrap().attempts[0]
                .tasks
                .last()
                .unwrap()
                .output
                .as_ref()
                .unwrap()
                .workspace_path,
        )
    } else {
        fixture.project.join(
            &store.read_work_item(&fixture.work).unwrap().attempts[0]
                .tasks
                .last()
                .unwrap()
                .output
                .as_ref()
                .unwrap()
                .workspace_path,
        )
    };
    fs::write(candidate_workspace.join("unsafe-untracked.txt"), "dirty\n").unwrap();

    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
        .assert()
        .failure()
        .stderr(predicate::str::contains("clean and unchanged"));
    let after = persisted_work_snapshot(&fixture.project, &fixture.work);
    assert_eq!(
        before, after,
        "unsafe recovery must not publish an assignment"
    );
    assert!(
        store.read_work_item(&fixture.work).unwrap().attempts[0]
            .tasks
            .last()
            .unwrap()
            .writer_correction_assignment
            .is_none()
    );
}

#[test]
fn saved_writer_assignment_rejects_unverifiable_legacy_source_binding() {
    for queued in [false, true] {
        let tmp = TempDir::new().unwrap();
        let fixture = saved_writer_assignment_fixture(&tmp);
        let store = WorkModelStore::new(&fixture.project);
        store
            .mutate_work_item(&fixture.work, |item| {
                let correction = item.attempts[0]
                    .tasks
                    .iter_mut()
                    .find(|task| task.id == fixture.correction_task_id)
                    .unwrap();
                let tester_input = correction
                    .input_artifacts
                    .iter_mut()
                    .find(|artifact| artifact.path.ends_with("/tester-results.json"))
                    .expect("legacy correction must retain Tester evidence");
                tester_input.producer_id = "untrusted-tester".into();
                Ok(())
            })
            .unwrap();
        let before = persisted_work_snapshot(&fixture.project, &fixture.work);

        let mut command = fluent_cmd();
        command.current_dir(&fixture.project);
        if queued {
            command.args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"]);
        } else {
            command.args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"]);
        }
        command
            .assert()
            .failure()
            .stderr(predicate::str::contains(
                "legacy Writer assignment is not safe to recover",
            ))
            .stderr(predicate::str::contains(
                "legacy Tester evidence is not bound to the original complete Tester",
            ));

        assert_eq!(
            persisted_work_snapshot(&fixture.project, &fixture.work),
            before,
            "unverifiable legacy recovery must not mutate persisted state"
        );
        let stored = store.read_work_item(&fixture.work).unwrap();
        let attempt = &stored.attempts[0];
        assert_eq!(attempt.status, fluent::work_model::AttemptStatus::NeedsUser);
        assert_eq!(
            attempt.pause_kind,
            Some(fluent::work_model::PauseKind::WriterCompletion)
        );
        let correction = attempt
            .tasks
            .iter()
            .find(|task| task.id == fixture.correction_task_id)
            .unwrap();
        assert!(correction.writer_correction_assignment.is_none());
        let correction_index = attempt
            .tasks
            .iter()
            .position(|task| task.id == fixture.correction_task_id)
            .unwrap();
        assert!(
            !attempt.tasks[correction_index + 1..]
                .iter()
                .any(|task| task.kind == fluent::work_model::TaskKind::Review)
        );
        assert!(
            fluent::queue::read_ledger(&fixture.project, &fixture.work)
                .unwrap()
                .is_none(),
            "rejected recovery must not create a queued dispatch"
        );
    }
}

