fn assert_saved_assignment_recovery_blocked_by_live_owner(
    fixture: &SavedWriterAssignmentFixture,
    queued: bool,
    expected_diagnostic: &str,
) {
    let before = persisted_work_snapshot(&fixture.project, &fixture.work);
    let mut command = fluent_cmd();
    command.current_dir(&fixture.project);
    if queued {
        command.args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"]);
    } else {
        command.args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"]);
    }
    command
        .assert()
        .failure()
        .stderr(predicate::str::contains(
            "legacy Writer assignment is not safe to recover",
        ))
        .stderr(predicate::str::contains(expected_diagnostic));
    assert_eq!(
        persisted_work_snapshot(&fixture.project, &fixture.work),
        before,
        "live-owner recovery must not mutate persisted state"
    );
    let stored = WorkModelStore::new(&fixture.project)
        .read_work_item(&fixture.work)
        .unwrap();
    let attempt = &stored.attempts[0];
    assert_eq!(attempt.status, fluent::work_model::AttemptStatus::NeedsUser);
    assert_eq!(
        attempt.pause_kind,
        Some(fluent::work_model::PauseKind::WriterCompletion)
    );
    let correction_index = attempt
        .tasks
        .iter()
        .position(|task| task.id == fixture.correction_task_id)
        .unwrap();
    assert!(
        attempt.tasks[correction_index]
            .writer_correction_assignment
            .is_none(),
        "live-owner recovery must not publish an assignment"
    );
    assert!(
        !attempt.tasks[correction_index + 1..]
            .iter()
            .any(|task| task.kind == fluent::work_model::TaskKind::Review),
        "live-owner recovery must not create downstream reviews"
    );
    assert!(
        fluent::queue::read_ledger(&fixture.project, &fixture.work)
            .unwrap()
            .is_none(),
        "rejected live-owner recovery must not create a queued dispatch"
    );
}

fn complete_saved_assignment_recovery(
    fixture: &SavedWriterAssignmentFixture,
    queued: bool,
    bin_dir: &Path,
) {
    write_mock_claude(bin_dir, recovery_review_and_learner_mock_script());
    if queued {
        fluent_cmd()
            .current_dir(&fixture.project)
            .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
            .assert()
            .success()
            .stdout(predicate::str::contains("Queued resume"));
        let dispatch = fluent::scheduler::pick_next_queued(&fixture.project)
            .unwrap()
            .expect("settled owner should permit queued recovery");
        fluent::scheduler::dispatch_one(
            &fixture.project,
            &dispatch,
            &EvidenceCliRunner {
                bin: bin_dir.to_path_buf(),
            },
        )
        .unwrap();
    } else {
        fluent_cmd()
            .current_dir(&fixture.project)
            .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
            .env("PATH", mock_path(bin_dir))
            .assert()
            .success();
    }

    let stored = WorkModelStore::new(&fixture.project)
        .read_work_item(&fixture.work)
        .unwrap();
    let attempt = &stored.attempts[0];
    assert_eq!(attempt.status, fluent::work_model::AttemptStatus::Complete);
    let correction = attempt
        .tasks
        .iter()
        .find(|task| task.id == fixture.correction_task_id)
        .unwrap();
    let assignment = correction
        .writer_correction_assignment
        .as_ref()
        .expect("settled owner should permit legacy assignment recovery");
    assert_eq!(
        assignment.origin,
        WriterCorrectionAssignmentOrigin::LegacyReconstructed
    );
    assert_eq!(assignment.source_task_id, fixture.source_task_id);
    assert_eq!(assignment.source_candidate_commit, fixture.source_commit);
    assert!(
        !bin_dir.join("writer-invocations").exists(),
        "settled-owner recovery must not rerun the completed Writer"
    );
}

#[test]
fn saved_writer_assignment_recovery_waits_for_live_task_owner() {
    for queued in [false, true] {
        let tmp = TempDir::new().unwrap();
        let fixture = saved_writer_assignment_fixture(&tmp);
        let task_lock = fluent::lease::task_lock_path(
            &fixture.project,
            &fixture.work,
            &fixture.correction_task_id,
        );
        let owner = fluent::lease::acquire(&task_lock).unwrap();
        assert!(fluent::lease::is_leased(&task_lock));
        assert_saved_assignment_recovery_blocked_by_live_owner(
            &fixture,
            queued,
            &format!("Task {} still has a live owner", fixture.correction_task_id),
        );
        drop(owner);
        let bin_dir = tmp.path().join(if queued {
            "bin-live-task-owner-queued"
        } else {
            "bin-live-task-owner-foreground"
        });
        complete_saved_assignment_recovery(&fixture, queued, &bin_dir);
    }
}

fn hold_live_execution_owner(
    fixture: &SavedWriterAssignmentFixture,
) -> (fluent::lease::TaskLease, PathBuf) {
    let stored = WorkModelStore::new(&fixture.project)
        .read_work_item(&fixture.work)
        .unwrap();
    let correction = stored.attempts[0]
        .tasks
        .iter()
        .find(|task| task.id == fixture.correction_task_id)
        .unwrap();
    let artifact_area = correction.artifact_area.as_ref().unwrap();
    let record_path =
        fluent::execution::record_path_for_artifact(&fixture.project, &artifact_area.path);
    let identity_lock = record_path.with_file_name("execution-owner.lock");
    let owner = fluent::lease::acquire(&identity_lock).unwrap();
    let now = fluent::work_model::now_iso8601();
    let record = fluent::execution::ExecutionRecord {
        schema_version: 1,
        state: fluent::execution::ExecutionState::Running,
        owner_pid: std::process::id(),
        leader_pid: std::process::id(),
        process_group_id: std::process::id(),
        started_at: now.clone(),
        heartbeat_at: now,
        settled_at: None,
        attempt_owner: Some(fluent::execution::AttemptExecutionOwner {
            project_root: fixture.project.clone(),
            work_item_id: fixture.work.clone(),
            attempt_id: "attempt-1".into(),
        }),
        launch_generation: None,
    };
    fs::write(&record_path, serde_json::to_vec_pretty(&record).unwrap()).unwrap();
    (owner, record_path)
}

#[test]
fn saved_writer_assignment_recovery_waits_for_live_execution_owner() {
    for queued in [false, true] {
        let tmp = TempDir::new().unwrap();
        let fixture = saved_writer_assignment_fixture(&tmp);
        let (owner, record_path) = hold_live_execution_owner(&fixture);
        assert!(fluent::execution::execution_is_live(&record_path).unwrap());
        assert_saved_assignment_recovery_blocked_by_live_owner(
            &fixture,
            queued,
            &format!(
                "Task {} still owns a live execution",
                fixture.correction_task_id
            ),
        );
        drop(owner);
        let mut settled: fluent::execution::ExecutionRecord =
            serde_json::from_slice(&fs::read(&record_path).unwrap()).unwrap();
        settled.state = fluent::execution::ExecutionState::Settled;
        settled.settled_at = Some(fluent::work_model::now_iso8601());
        fs::write(&record_path, serde_json::to_vec_pretty(&settled).unwrap()).unwrap();
        assert!(!fluent::execution::execution_is_live(&record_path).unwrap());
        let bin_dir = tmp.path().join(if queued {
            "bin-live-execution-owner-queued"
        } else {
            "bin-live-execution-owner-foreground"
        });
        complete_saved_assignment_recovery(&fixture, queued, &bin_dir);
    }
}

#[test]
fn corrective_writer_assignment_rejects_invalid_authority() {
    let tmp = TempDir::new().unwrap();
    let fixture = saved_writer_assignment_fixture(&tmp);

    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
        .assert()
        .success();
    // Leave the recovered assignment persisted while removing only its queued
    // dispatch, so the foreground run reaches the completion gate.
    fluent::queue::cancel_active(&fixture.project, &fixture.work).unwrap();
    let assigned = WorkModelStore::new(&fixture.project)
        .read_work_item(&fixture.work)
        .unwrap();
    let assignment = assigned.attempts[0]
        .tasks
        .iter()
        .find(|task| task.id == fixture.correction_task_id)
        .unwrap()
        .writer_correction_assignment
        .as_ref()
        .unwrap();
    let altered_path = fixture.project.join(&assignment.evidence[0].artifact.path);
    let mut altered = fs::read(&altered_path).unwrap();
    altered.push(b'\n');
    fs::write(&altered_path, altered).unwrap();

    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .assert()
        .success()
        .stdout(predicate::str::contains("needs user input"));

    let value = work_item_value(&fixture.project, &fixture.work);
    let attempt = &value["attempts"][0];
    assert_eq!(attempt["status"], "needs-user");
    assert_eq!(attempt["pause_kind"], "writer-completion");
    let handoff = fs::read_to_string(fixture.project.join(format!(
        ".fluent/work/artifacts/{}/attempt-1/writer-completion-needs-user.md",
        fixture.work
    )))
    .unwrap();
    assert!(handoff.contains("Writer correction assignment is unverifiable"));
    assert!(handoff.contains(&assignment.evidence[0].artifact.path));
    let tasks = attempt["tasks"].as_array().unwrap();
    assert_eq!(
        tasks.len(),
        assigned.attempts[0].tasks.len(),
        "invalid authority must not append downstream Tasks"
    );
    let correction_index = tasks
        .iter()
        .position(|task| task["id"] == fixture.correction_task_id)
        .unwrap();
    assert_eq!(correction_index + 1, tasks.len());
    assert!(
        !tasks[correction_index + 1..]
            .iter()
            .any(|task| task["kind"] == "review"),
        "invalid assignment authority must block downstream reviews"
    );
}

#[test]
fn corrective_writer_assignment_rejects_invalid_authority_through_queued_resume() {
    let tmp = TempDir::new().unwrap();
    let fixture = saved_writer_assignment_fixture(&tmp);
    let writer_bin = tmp.path().join("bin-queued-assignment-authority");
    let store = run_production_correction(&fixture, &writer_bin);
    store
        .mutate_work_item(&fixture.work, |item| {
            let attempt = &mut item.attempts[0];
            attempt.status = fluent::work_model::AttemptStatus::NeedsUser;
            attempt.review_state = Some(AttemptReviewState::NotReviewed);
            attempt.pause_kind = Some(fluent::work_model::PauseKind::WriterCompletion);
            attempt.pause_recovery = None;
            attempt.pause_record = None;
            attempt.completed_at = None;
            Ok(())
        })
        .unwrap();
    let assigned = store.read_work_item(&fixture.work).unwrap();
    let assignment = assigned.attempts[0]
        .tasks
        .iter()
        .find(|task| task.id == fixture.correction_task_id)
        .unwrap()
        .writer_correction_assignment
        .as_ref()
        .unwrap();
    let altered_path = fixture.project.join(&assignment.evidence[0].artifact.path);
    let mut altered = fs::read(&altered_path).unwrap();
    altered.push(b'\n');
    fs::write(&altered_path, altered).unwrap();
    let before = persisted_work_snapshot(&fixture.project, &fixture.work);

    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
        .assert()
        .failure()
        .stderr(predicate::str::contains("Writer assignment input changed"));

    let after = persisted_work_snapshot(&fixture.project, &fixture.work);
    assert_eq!(
        before, after,
        "rejected queued recovery must not mutate storage"
    );
    let value = work_item_value(&fixture.project, &fixture.work);
    let attempt = &value["attempts"][0];
    assert_eq!(attempt["status"], "needs-user");
    assert_eq!(attempt["pause_kind"], "writer-completion");
    assert_eq!(
        attempt["tasks"].as_array().unwrap().len(),
        assigned.attempts[0].tasks.len(),
        "invalid authority must not append downstream Tasks"
    );
    let correction_index = attempt["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .position(|task| task["id"] == fixture.correction_task_id)
        .unwrap();
    assert!(
        !attempt["tasks"].as_array().unwrap()[correction_index + 1..]
            .iter()
            .any(|task| task["kind"] == "review"),
        "invalid queued assignment authority must block downstream reviews"
    );
}

#[test]
fn saved_writer_assignment_recovery_preserves_history() {
    let tmp = TempDir::new().unwrap();
    let fixture = saved_writer_assignment_fixture(&tmp);
    let store = WorkModelStore::new(&fixture.project);
    let before = store.read_work_item(&fixture.work).unwrap();
    let tasks_before = before.attempts[0].tasks.clone();
    let correction_output_before = before.attempts[0]
        .tasks
        .last()
        .unwrap()
        .output
        .clone()
        .unwrap();
    let matrix_before = fs::read(&fixture.matrix_path).unwrap();
    let results_before = fs::read(&fixture.results_path).unwrap();
    let bin_dir = tmp.path().join("bin-saved-writer-history");
    write_mock_claude(&bin_dir, recovery_review_and_learner_mock_script());

    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .assert()
        .success();

    let after = store.read_work_item(&fixture.work).unwrap();
    for task_before in tasks_before {
        let task_after = after.attempts[0]
            .tasks
            .iter()
            .find(|task| task.id == task_before.id)
            .unwrap_or_else(|| panic!("recovery dropped pre-existing Task {}", task_before.id));
        let mut expected = task_before;
        let mut actual = task_after.clone();
        // Recovery is authorized to add the reconstructed host-owned assignment
        // to the completed correction Task. Every other durable Task field,
        // including every other assignment, is historical state and must remain
        // byte-equivalent in structure.
        if expected.id == fixture.correction_task_id {
            expected.writer_correction_assignment = None;
            actual.writer_correction_assignment = None;
        }
        assert_eq!(actual, expected, "recovery changed Task history");
    }
    let correction = after.attempts[0]
        .tasks
        .iter()
        .find(|task| task.id == fixture.correction_task_id)
        .unwrap();
    assert_eq!(correction.status, TaskStatus::Complete);
    assert_eq!(
        correction.output.as_ref().unwrap(),
        &correction_output_before
    );
    assert_eq!(fs::read(&fixture.matrix_path).unwrap(), matrix_before);
    assert_eq!(fs::read(&fixture.results_path).unwrap(), results_before);
    assert_eq!(fixture.corrected_commit, correction_output_before.commit);
    let candidate_workspace = if Path::new(&correction_output_before.workspace_path).is_absolute() {
        PathBuf::from(&correction_output_before.workspace_path)
    } else {
        fixture
            .project
            .join(&correction_output_before.workspace_path)
    };
    assert_eq!(git_head(&candidate_workspace), fixture.corrected_commit);
    assert!(
        !bin_dir.join("writer-invocations").exists(),
        "saved foreground recovery must not invoke the completed Writer"
    );
    assert_eq!(
        after.attempts[0].status,
        fluent::work_model::AttemptStatus::Complete
    );
}

#[test]
fn saved_writer_assignment_resume_is_idempotent() {
    let tmp = TempDir::new().unwrap();
    let fixture = saved_writer_assignment_fixture(&tmp);

    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
        .assert()
        .success()
        .stdout(predicate::str::contains("Queued resume"));
    let first_count = dispatch_count(&fixture.project, &fixture.work);
    let first_dispatch_id = fluent::queue::read_ledger(&fixture.project, &fixture.work)
        .unwrap()
        .unwrap()
        .active()
        .unwrap()
        .dispatch_id
        .clone();
    let first = work_item_value(&fixture.project, &fixture.work);
    assert_eq!(
        first["attempts"][0]["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|task| task["kind"] == "write")
            .count(),
        2
    );

    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
        .assert()
        .success()
        .stdout(predicate::str::contains("already queued"));
    assert_eq!(dispatch_count(&fixture.project, &fixture.work), first_count);
    let second_dispatch_id = fluent::queue::read_ledger(&fixture.project, &fixture.work)
        .unwrap()
        .unwrap()
        .active()
        .unwrap()
        .dispatch_id
        .clone();
    assert_eq!(
        second_dispatch_id, first_dispatch_id,
        "repeated queue resume must reuse the active dispatch identity"
    );
    let second = work_item_value(&fixture.project, &fixture.work);
    assert_eq!(
        second["attempts"][0]["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|task| task["kind"] == "write")
            .count(),
        2,
        "repeated queue resume must not append a Writer"
    );
    assert_eq!(
        second["attempts"][0]["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|task| task["id"] == fixture.correction_task_id)
            .unwrap()["writer_correction_assignment"]["origin"],
        "legacy-reconstructed"
    );

    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["attempt", "cancel", &fixture.work, "attempt-1"])
        .assert()
        .success();
    let stopped = work_item_value(&fixture.project, &fixture.work);
    assert!(stopped["attempts"][0]["cancellation"]["requested_at"].is_string());
    assert!(stopped["attempts"][0]["cancellation"]["resumed_at"].is_null());
    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
        .assert()
        .failure()
        .stderr(predicate::str::contains(
            "active dispatch was admitted before the current cancellation",
        ));
    let after_stop = work_item_value(&fixture.project, &fixture.work);
    assert!(after_stop["attempts"][0]["cancellation"]["resumed_at"].is_null());
    assert_eq!(dispatch_count(&fixture.project, &fixture.work), first_count);
}

#[test]
fn release_suite_process_guard_reports_scoped_leaks() {
    let tmp = TempDir::new().unwrap();
    let root = tmp.path().join("fixture-root");
    fs::create_dir_all(&root).unwrap();
    let inventory = tmp.path().join("processes.tsv");
    let guard =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("scripts/release-test-process-guard.sh");
    let leak = format!("4242\tfluent scheduler\t{}\n", root.display());
    let output = Command::new("bash")
        .arg(&guard)
        .arg("bash")
        .args([
            "-c",
            "printf '%s' \"$FLUENT_TEST_GUARD_LEAK\" > \"$FLUENT_TEST_PROCESS_INVENTORY\"",
        ])
        .env("FLUENT_RELEASE_TEST_ROOTS", &root)
        .env("FLUENT_TEST_PROCESS_INVENTORY", &inventory)
        .env("FLUENT_TEST_GUARD_LEAK", leak)
        .output()
        .unwrap();

    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(!output.status.success(), "guard accepted a scoped leak");
    assert!(stderr.contains("pid=4242"), "diagnostic: {stderr}");
    assert!(
        stderr.contains("kind=fluent scheduler"),
        "diagnostic: {stderr}"
    );
    assert!(
        stderr.contains(&format!("root={}", root.display())),
        "diagnostic: {stderr}"
    );
}

