#[cfg(unix)]
struct OwnedFixtureProcess {
    child: Option<Child>,
    group: i32,
}

#[cfg(unix)]
impl OwnedFixtureProcess {
    fn spawn(command: &mut Command) -> Self {
        use std::os::unix::process::CommandExt;

        command.process_group(0);
        let child = command.spawn().unwrap();
        let group = i32::try_from(child.id()).unwrap();
        Self {
            child: Some(child),
            group,
        }
    }

    fn id(&self) -> u32 {
        self.child
            .as_ref()
            .expect("fixture child is available")
            .id()
    }

    fn wait(&mut self) -> std::io::Result<std::process::ExitStatus> {
        let result = self
            .child
            .as_mut()
            .expect("fixture child is available")
            .wait();
        self.terminate_and_wait();
        result
    }

    fn wait_with_output(&mut self) -> std::io::Result<std::process::Output> {
        let result = self
            .child
            .take()
            .expect("fixture child is available")
            .wait_with_output();
        self.terminate_and_wait();
        result
    }

    fn try_wait(&mut self) -> std::io::Result<Option<std::process::ExitStatus>> {
        self.child
            .as_mut()
            .expect("fixture child is available")
            .try_wait()
    }

    fn terminate_and_wait(&mut self) {
        self.terminate_and_wait_result()
            .expect("fixture process group must terminate and be reaped");
    }

    // macOS may report EPERM for an exited fixture leader's empty group.
    // Accept that only after observing the owned child exit; a live same-user
    // descendant keeps its group signalable and still needs the normal sweep.
    fn signal_owned_group(&mut self, signal: i32) -> std::io::Result<bool> {
        let leader_exited = match self.child.as_mut() {
            Some(child) => child.try_wait()?.is_some(),
            None => true, // wait_with_output already reaped this owned child.
        };
        match signal_fixture_group(self.group, signal) {
            Ok(()) => Ok(true),
            Err(error)
                if cfg!(target_os = "macos")
                    && leader_exited
                    && error.raw_os_error() == Some(libc::EPERM) =>
            {
                Ok(false)
            }
            Err(error) => Err(error),
        }
    }

    fn terminate_and_wait_result(&mut self) -> std::io::Result<()> {
        if !self.signal_owned_group(libc::SIGTERM)? {
            return Ok(());
        }
        if let Some(child) = self.child.as_mut() {
            wait_for_fixture_child(child, std::time::Duration::from_secs(2))?;
        }
        if fixture_group_is_gone(self.group, std::time::Duration::from_secs(2)) {
            if let Some(child) = self.child.as_mut() {
                child.wait()?;
            }
            return Ok(());
        }

        if !self.signal_owned_group(libc::SIGKILL)? {
            return Ok(());
        }
        if let Some(child) = self.child.as_mut() {
            child.wait()?;
        }
        if fixture_group_is_gone(self.group, std::time::Duration::from_secs(2)) {
            Ok(())
        } else {
            Err(std::io::Error::other(format!(
                "fixture process group {} survived SIGTERM and SIGKILL",
                self.group
            )))
        }
    }
}

#[cfg(unix)]
fn signal_fixture_group(group: i32, signal: i32) -> std::io::Result<()> {
    if unsafe { libc::kill(-group, signal) } == -1 {
        let error = std::io::Error::last_os_error();
        if error.raw_os_error() != Some(libc::ESRCH) {
            return Err(error);
        }
    }
    Ok(())
}

#[cfg(unix)]
fn fixture_group_is_gone(group: i32, timeout: std::time::Duration) -> bool {
    poll_until(timeout, || {
        (unsafe { libc::kill(-group, 0) }) == -1
            && std::io::Error::last_os_error().raw_os_error() == Some(libc::ESRCH)
    })
}

#[cfg(unix)]
fn wait_for_fixture_child(child: &mut Child, timeout: std::time::Duration) -> std::io::Result<()> {
    let deadline = std::time::Instant::now() + timeout;
    loop {
        if child.try_wait()?.is_some() || std::time::Instant::now() >= deadline {
            return Ok(());
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
    }
}

#[cfg(unix)]
impl Drop for OwnedFixtureProcess {
    fn drop(&mut self) {
        self.terminate_and_wait();
    }
}

#[cfg(unix)]
#[test]
fn long_lived_fixture_reaps_its_process_group() {
    let pid_file = TempDir::new().unwrap();
    let leader = {
        let mut command = Command::new("/bin/sh");
        command.args([
            "-c",
            "sleep 60 & echo $! > \"$1\"; wait",
            "fixture-process-group",
            &pid_file.path().join("descendant.pid").to_string_lossy(),
        ]);
        let process = OwnedFixtureProcess::spawn(&mut command);
        let leader = process.id();
        assert!(poll_until(std::time::Duration::from_secs(2), || {
            pid_file.path().join("descendant.pid").exists()
        }));
        drop(process);
        leader
    };

    let descendant: i32 = fs::read_to_string(pid_file.path().join("descendant.pid"))
        .unwrap()
        .trim()
        .parse()
        .unwrap();
    for pid in [leader as i32, descendant] {
        assert!(
            poll_until(std::time::Duration::from_secs(2), || {
                (unsafe { libc::kill(pid, 0) }) == -1
                    && std::io::Error::last_os_error().raw_os_error() == Some(libc::ESRCH)
            }),
            "fixture process {pid} must be reaped with its process group"
        );
    }
}

#[cfg(unix)]
#[test]
fn long_lived_fixture_escalates_when_group_ignores_term() {
    let pid_file = TempDir::new().unwrap();
    let process = {
        let mut command = Command::new("/bin/sh");
        command.args([
            "-c",
            "trap '' TERM; (sleep 60) & echo $! > \"$1\"; wait",
            "fixture-process-group",
            &pid_file.path().join("descendant.pid").to_string_lossy(),
        ]);
        OwnedFixtureProcess::spawn(&mut command)
    };
    let leader = process.id();
    assert!(poll_until(std::time::Duration::from_secs(2), || {
        pid_file.path().join("descendant.pid").exists()
    }));
    drop(process);

    assert!(fixture_group_is_gone(
        i32::try_from(leader).unwrap(),
        std::time::Duration::from_secs(2)
    ));
}

#[cfg(unix)]
#[test]
fn completed_fixture_process_reaps_remaining_group() {
    let pid_file = TempDir::new().unwrap();
    let mut command = Command::new("/bin/sh");
    command.args([
        "-c",
        "sleep 60 & echo $! > \"$1\"",
        "fixture-process-group",
        &pid_file.path().join("descendant.pid").to_string_lossy(),
    ]);
    let mut process = OwnedFixtureProcess::spawn(&mut command);
    let output = process.wait_with_output().unwrap();
    assert!(output.status.success());

    let descendant: i32 = fs::read_to_string(pid_file.path().join("descendant.pid"))
        .unwrap()
        .trim()
        .parse()
        .unwrap();
    assert!(poll_until(std::time::Duration::from_secs(2), || {
        (unsafe { libc::kill(descendant, 0) }) == -1
            && std::io::Error::last_os_error().raw_os_error() == Some(libc::ESRCH)
    }));
}

