/// Wait for a fixture process up to `timeout`, tearing down its complete
/// process group on either outcome so a capture regression cannot hang the
/// suite or leave a writer descendant behind.
#[cfg(unix)]
fn wait_with_timeout(
    process: &mut OwnedFixtureProcess,
    timeout: std::time::Duration,
) -> Option<std::process::ExitStatus> {
    let deadline = std::time::Instant::now() + timeout;
    loop {
        match process.try_wait().unwrap() {
            Some(status) => {
                process.terminate_and_wait();
                return Some(status);
            }
            None => {
                if std::time::Instant::now() >= deadline {
                    process.terminate_and_wait();
                    return None;
                }
                std::thread::sleep(std::time::Duration::from_millis(50));
            }
        }
    }
}

#[cfg(unix)]
#[test]
fn writer_completes_when_oversized_transcript_record_cannot_be_mirrored() {
    // Reproduce the original failure comfortably above any plausible host pipe
    // capacity: a transcript record larger than 1 MiB followed by another
    // record, with the writer's stderr left unread. The byte pump must persist
    // every byte and drain through coder exit without the unread console
    // stalling capture, so the writer completes and both records land in the
    // transcript.
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let bin_dir = tmp.path().join("bin");
    write_mock_claude(
        &bin_dir,
        r##"#!/bin/bash
big=$(head -c 1500000 /dev/zero | tr '\0' 'x')
printf '{"type":"big","data":"%s"}\n' "$big"
printf '{"type":"after-oversized-record"}\n'
printf 'task output\n' > task-output.txt
git add task-output.txt
git commit -m "Add task output" >/dev/null
exit 0
"##,
    );

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["work-item", "create", "work-1", "--title", "Pump test"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();

    // Launch the writer directly with its console (stderr) piped but never
    // drained, so the console sink cannot be emptied while the coder streams its
    // oversized record. stdout is drained on a thread: it carries unrelated
    // inherited coder output and is not the console path under test.
    let mut command = std::process::Command::new(env!("CARGO_BIN_EXE_fluent"));
    command
        .current_dir(&main_dir)
        .args([
            "task",
            "run",
            "work-1",
            "attempt-1",
            "attempt-1-write-1",
            "--no-sandbox",
        ])
        .env("PATH", mock_path(&bin_dir))
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .env("FLUENT_MAX_TASK_RETRIES", "0")
        .env_remove("FLUENT_TASK_KIND")
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    let mut child = OwnedFixtureProcess::spawn(&mut command);

    let mut stdout = child.child.as_mut().unwrap().stdout.take().unwrap();
    let drain_stdout = std::thread::spawn(move || {
        let mut sink = Vec::new();
        let _ = std::io::Read::read_to_end(&mut stdout, &mut sink);
    });

    let status = wait_with_timeout(&mut child, std::time::Duration::from_secs(60))
        .expect("writer must complete instead of blocking on an unread console");
    let _ = drain_stdout.join();
    assert!(
        status.success(),
        "writer should complete despite the unread oversized console preview"
    );

    let transcript =
        main_dir.join(".fluent/work/artifacts/work-1/attempt-1/attempt-1-write-1/transcript.jsonl");
    let content = fs::read(&transcript).unwrap();
    assert!(
        content.len() > 1_500_000,
        "the full >1 MiB oversized record must persist; got {} bytes",
        content.len()
    );
    assert!(
        content
            .windows(b"after-oversized-record".len())
            .any(|w| w == b"after-oversized-record"),
        "the record after the oversized one must still be captured"
    );

    // The pump status is a durable diagnostic recording completed capture.
    let status_file = main_dir
        .join(".fluent/work/artifacts/work-1/attempt-1/attempt-1-write-1/transcript-pump.json");
    let status_json: serde_json::Value =
        serde_json::from_slice(&fs::read(&status_file).unwrap()).unwrap();
    assert_eq!(status_json["state"], "complete");
    assert_eq!(status_json["schema_version"], 5);
}

#[cfg(unix)]
#[test]
fn writer_completes_under_sustained_previews_on_an_unread_console() {
    // A sustained flood of records — several MiB of bounded previews, far more
    // than a 64 KiB stderr pipe can hold — with the writer's stderr piped and
    // never drained. The sink declines live previews rather than mirroring them,
    // so the flood cannot saturate the console and stall Fluent's own
    // control-plane output. The whole writer process must complete within a
    // deadline, drive its post-coder Attempt transition (task state and pump
    // status), and count every declined preview: `dropped_console == records`.
    // A design that mirrored previews into this non-terminal console would fill
    // the pipe and block the writer, failing this regression.
    const RECORDS: usize = 2000;
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let bin_dir = tmp.path().join("bin");
    write_mock_claude(
        &bin_dir,
        r##"#!/bin/bash
i=0
pad=$(head -c 2000 /dev/zero | tr '\0' 'a')
while [ $i -lt 2000 ]; do
  printf '{"type":"rec","n":%d,"pad":"%s"}\n' "$i" "$pad"
  i=$((i+1))
done
printf 'task output\n' > task-output.txt
git add task-output.txt
git commit -m "Add task output" >/dev/null
exit 0
"##,
    );

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["work-item", "create", "work-1", "--title", "Pump test"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();

    // Pipe stderr and never drain it: that is the saturated-console condition.
    // stdout is drained on a thread; it carries unrelated inherited output.
    let mut command = std::process::Command::new(env!("CARGO_BIN_EXE_fluent"));
    command
        .current_dir(&main_dir)
        .args([
            "task",
            "run",
            "work-1",
            "attempt-1",
            "attempt-1-write-1",
            "--no-sandbox",
        ])
        .env("PATH", mock_path(&bin_dir))
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .env("FLUENT_MAX_TASK_RETRIES", "0")
        .env_remove("FLUENT_TASK_KIND")
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    let mut child = OwnedFixtureProcess::spawn(&mut command);

    let mut stdout = child.child.as_mut().unwrap().stdout.take().unwrap();
    let drain_stdout = std::thread::spawn(move || {
        let mut sink = Vec::new();
        let _ = std::io::Read::read_to_end(&mut stdout, &mut sink);
    });

    let status = wait_with_timeout(&mut child, std::time::Duration::from_secs(60))
        .expect("writer must complete instead of blocking on the saturated console");
    let _ = drain_stdout.join();
    let mut stderr = Vec::new();
    if let Some(mut pipe) = child
        .child
        .as_mut()
        .and_then(|process| process.stderr.take())
    {
        let _ = std::io::Read::read_to_end(&mut pipe, &mut stderr);
    }
    assert!(
        status.success(),
        "writer should complete despite sustained previews on an unread console: {}",
        String::from_utf8_lossy(&stderr)
    );

    let transcript =
        main_dir.join(".fluent/work/artifacts/work-1/attempt-1/attempt-1-write-1/transcript.jsonl");
    let content = fs::read(&transcript).unwrap();
    assert!(
        content.len() > 64 * 1024,
        "the sustained flood must persist in full; got {} bytes",
        content.len()
    );
    assert!(
        content
            .windows(br#""n":1999"#.len())
            .any(|w| w == br#""n":1999"#),
        "the last record of the sustained flood must be captured"
    );

    // The post-coder Attempt transition ran after the coder committed its output.
    let writer_workspace = tmp.path().join("work-6-work-1-attempt-1");
    assert!(
        writer_workspace.join("task-output.txt").exists(),
        "the writer must commit output in its workspace before Fluent completes the Task"
    );

    // The pump status is byte-truthful: capture completed, every record counted,
    // and every declined preview accounted as a drop.
    let status_file = main_dir
        .join(".fluent/work/artifacts/work-1/attempt-1/attempt-1-write-1/transcript-pump.json");
    let status_json: serde_json::Value =
        serde_json::from_slice(&fs::read(&status_file).unwrap()).unwrap();
    assert_eq!(status_json["state"], "complete");
    assert_eq!(
        status_json["records"].as_u64().unwrap(),
        RECORDS as u64,
        "every emitted record must be counted"
    );
    assert_eq!(
        status_json["dropped_console"].as_u64().unwrap(),
        status_json["records"].as_u64().unwrap(),
        "a declined console must count every preview as dropped"
    );
}

#[test]
fn transcript_pump_write_failure_pauses_resumably_end_to_end() {
    // End-to-end: a transcript-pump infrastructure failure during a write task
    // must record a resumable transcript-pump pause (not a terminal write-round
    // cap), keep the coder out of the generic retry budget, and — once the
    // operator fixes the transport — resume through `fluent attempt run` to a
    // Merge Candidate. The failure is injected by making the write transcript
    // path a directory, so the pump cannot create its transcript file.
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let bin_dir = tmp.path().join("bin");
    write_mock_claude(
        &bin_dir,
        r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
case "$PWD" in
  */work-*-work-1-attempt-1)
    printf '{"type":"result","subtype":"success"}\n'
    # Sleep before committing so the first run — where the pump fails at once —
    # is terminated before it can commit. The resumed run captures normally and
    # then commits, producing the Task output.
    sleep 2
    printf 'task output\n' > task-output.txt
    git add task-output.txt
    git commit -m "Add task output" >/dev/null 2>&1
    ;;
  *)
    printf 'Verdict: pass\n\nLooks good.\n' > review.md
    ;;
esac
exit 0
"##,
    );

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["work-item", "create", "work-1", "--title", "Pump resume"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();

    // Break the transport: occupy the write transcript path with a directory so
    // the pump's File::create fails immediately while the coder is alive.
    let artifact_dir = main_dir.join(".fluent/work/artifacts/work-1/attempt-1/attempt-1-write-1");
    let transcript = artifact_dir.join("transcript.jsonl");
    fs::create_dir_all(&transcript).unwrap();

    // First run: the pump fails. A generous retry budget must not be spent.
    let _ = fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .env("FLUENT_MAX_TASK_RETRIES", "3")
        .output()
        .unwrap();

    // Attempts and tasks are split-stored beside the item.
    let attempt_json: serde_json::Value = serde_json::from_str(
        &fs::read_to_string(main_dir.join(".fluent/work/attempts/work-1/attempt-1.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        attempt_json["pause_kind"], "transcript-pump",
        "a pump failure must record the resumable transcript-pump pause, not a round cap: {attempt_json}"
    );
    assert_eq!(attempt_json["status"], "needs-user");

    let task_json: serde_json::Value = serde_json::from_str(
        &fs::read_to_string(
            main_dir.join(".fluent/work/tasks/work-1/attempt-1/attempt-1-write-1.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert_eq!(
        task_json["status"], "needs-user",
        "a resumable pump failure marks the Task NeedsUser, not a hard Failed"
    );

    // The pump status is the durable diagnostic that named the transport fault.
    let pump_status: serde_json::Value =
        serde_json::from_slice(&fs::read(artifact_dir.join("transcript-pump.json")).unwrap())
            .unwrap();
    assert_eq!(pump_status["state"], "failed");

    // Fix the transport, then resume. The Attempt reopens, retries the write
    // task, and drives to a Merge Candidate.
    fs::remove_dir_all(&transcript).unwrap();
    let resumed = fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .output()
        .unwrap();
    let stdout = String::from_utf8_lossy(&resumed.stdout);
    let stderr = String::from_utf8_lossy(&resumed.stderr);
    assert!(
        resumed.status.success(),
        "resume after fixing the transport must succeed: stdout={stdout}\nstderr={stderr}"
    );
    assert!(
        stdout.contains("Merge Candidate attempt-1-merge-candidate is ready"),
        "resume must drive to a Merge Candidate; got:\n{stdout}"
    );

    // The retried write captured its transcript to a real file this time.
    assert!(
        transcript.is_file(),
        "the retried write must capture its transcript to a file"
    );
    assert!(
        !fs::read(&transcript).unwrap().is_empty(),
        "the retried transcript must hold the coder's output"
    );
}

#[test]
fn transcript_pump_late_failure_after_commit_resumes_without_second_commit() {
    // The commit-before-late-failure contract. The writer commits its output and
    // THEN fails on a transcript-pump infrastructure error (a 401 whose phase
    // preservation cannot complete). On resume, the persisted baseline keeps the
    // already-produced commit as the Task output, so the resumed coder need not
    // manufacture a second commit, and the Task output records the original
    // pre-write baseline. The late failure is not charged to the generic retry
    // budget: exactly one writer invocation runs before the pause.
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let bin_dir = tmp.path().join("bin");
    let counter = tmp.path().join("writer-count");
    let mock = r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
# The Learner runs in the attempt worktree too. It must succeed so the
# advancement gate admits the Merge Candidate; it writes an empty handoff and
# never touches the writer counter.
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  if [ -n "$DRAFT" ]; then
    mkdir -p "$(dirname "$DRAFT")"
    printf '%s\n' '{"learning_summary":"none","follow_ups":[]}' > "$DRAFT"
  fi
  exit 0
fi
case "$PWD" in
  */work-*-work-1-attempt-1)
    C="__COUNTER__"
    n=$(cat "$C" 2>/dev/null || echo 0); n=$((n+1)); echo "$n" > "$C"
    if [ "$n" -eq 1 ]; then
      printf 'task output\n' > task-output.txt
      git add task-output.txt
      git commit -m "Add task output" >/dev/null 2>&1
      echo '{"type":"result","api_error_status":401,"request_id":"r"}'
      exit 1
    fi
    printf '{"type":"result","subtype":"success"}\n'
    exit 0
    ;;
  *)
    printf 'Verdict: pass\n\nok.\n' > review.md
    ;;
esac
exit 0
"##
    .replace("__COUNTER__", counter.to_str().unwrap());
    write_mock_claude(&bin_dir, &mock);

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["work-item", "create", "work-1", "--title", "Late pump"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();

    // Occupy the write transcript's phase-0 slot with a directory so the 401's
    // phase preservation fails late — after the coder has already committed.
    let artifact_dir = main_dir.join(".fluent/work/artifacts/work-1/attempt-1/attempt-1-write-1");
    fs::create_dir_all(artifact_dir.join("transcript.0.jsonl")).unwrap();

    // First run: commit, then late pump failure. A generous retry budget must
    // not be spent.
    let _ = fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .env("FLUENT_MAX_TASK_RETRIES", "3")
        .output()
        .unwrap();

    assert_eq!(
        fs::read_to_string(&counter).unwrap().trim(),
        "1",
        "the late pump failure must not be retried: exactly one writer invocation"
    );
    let attempt_json: serde_json::Value = serde_json::from_str(
        &fs::read_to_string(main_dir.join(".fluent/work/attempts/work-1/attempt-1.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        attempt_json["pause_kind"], "transcript-pump",
        "a late pump failure must record a resumable transcript-pump pause: {attempt_json}"
    );

    let baseline = fs::read_to_string(artifact_dir.join("write-baseline-commit"))
        .unwrap()
        .trim()
        .to_string();

    // Fix the transport and resume.
    fs::remove_dir_all(artifact_dir.join("transcript.0.jsonl")).unwrap();
    let resumed = fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .output()
        .unwrap();
    let stdout = String::from_utf8_lossy(&resumed.stdout);
    let stderr = String::from_utf8_lossy(&resumed.stderr);
    assert!(
        resumed.status.success(),
        "resume must succeed without a second commit: stdout={stdout}\nstderr={stderr}"
    );
    assert!(
        stdout.contains("Merge Candidate attempt-1-merge-candidate is ready"),
        "resume must drive to a Merge Candidate; got:\n{stdout}"
    );

    // The resumed writer ran exactly once more and did NOT commit again.
    assert_eq!(
        fs::read_to_string(&counter).unwrap().trim(),
        "2",
        "resume runs the writer once more"
    );

    // The completed Task adopted the ORIGINAL baseline and the first run's commit
    // as its output — no artificial second commit.
    let task_json: serde_json::Value = serde_json::from_str(
        &fs::read_to_string(
            main_dir.join(".fluent/work/tasks/work-1/attempt-1/attempt-1-write-1.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert_eq!(task_json["status"], "complete");
    assert_eq!(
        task_json["output"]["base_commit"], baseline,
        "the resumed Task output must keep the original pre-write baseline"
    );
}

#[test]
fn initial_claude_writer_runs_once_without_pre_writer_expertise_seed() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let bin_dir = tmp.path().join("bin-single-writer");
    let counter_path = tmp.path().join("call-counter");

    write_mock_claude(
        &bin_dir,
        &format!(
            r##"#!/bin/bash
COUNTER="{}"
count=0
if [ -f "$COUNTER" ]; then count=$(cat "$COUNTER"); fi
count=$((count + 1))
printf '%s\n' "$count" > "$COUNTER"
printf 'task output\n' > task-output.txt
git add task-output.txt
git commit -m "Add task output" >/dev/null
exit 0
"##,
            counter_path.display()
        ),
    );

    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "work-item",
            "create",
            "work-1",
            "--title",
            "Single writer test",
        ])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();

    let output = fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "task",
            "run",
            "work-1",
            "attempt-1",
            "attempt-1-write-1",
            "--no-sandbox",
        ])
        .env("PATH", mock_path(&bin_dir))
        .env("FLUENT_MAX_TASK_RETRIES", "0")
        .output()
        .unwrap();

    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(
        output.status.success(),
        "the initial Writer should succeed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        stderr
    );
    assert!(String::from_utf8_lossy(&output.stdout).contains("Completed Task attempt-1-write-1"));
    assert_eq!(
        fs::read_to_string(&counter_path).unwrap().trim(),
        "1",
        "the first Write Task must launch only the Writer, without a seed-model call"
    );

    let task: serde_json::Value = serde_json::from_slice(
        &fs::read(main_dir.join(".fluent/work/tasks/work-1/attempt-1/attempt-1-write-1.json"))
            .unwrap(),
    )
    .unwrap();
    let base = task["output"]["base_commit"].as_str().unwrap();
    let candidate = task["output"]["commit"].as_str().unwrap();
    let workspace = main_dir.join(task["output"]["workspace_path"].as_str().unwrap());
    assert_eq!(
        git::run_stdout(
            &workspace,
            &["rev-list", "--count", &format!("{base}..{candidate}")],
            "count initial Writer commits",
        )
        .unwrap(),
        "1",
        "the candidate must contain only the Writer commit"
    );
    assert_eq!(
        git::run_stdout(
            &workspace,
            &["diff", "--name-only", base, candidate],
            "inspect initial Writer candidate scope",
        )
        .unwrap(),
        "task-output.txt",
        "Fluent must not add project expertise before review"
    );
    assert!(
        !workspace.join(".fluent/expertise/INDEX.md").exists(),
        "project expertise remains absent until the post-review Learner"
    );
}

/// A mock coder that drives write and review rounds like `loop_mock_script`, but
/// makes the Learner invocation fail by exiting non-zero.
fn learner_failing_mock_script() -> String {
    r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
if [ -z "$PROMPT" ]; then exit 0; fi
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  exit 1
fi
case "$PWD" in
  */work-6-work-1-attempt-1)
    printf 'loop output\n' > loop-output.txt
    git add loop-output.txt
    git commit -m "Add loop output" >/dev/null 2>&1
    ;;
  *)
    printf 'Verdict: pass\n\nLoop review.\n' > review.md
    ;;
esac
exit 0
"##
    .to_string()
}

fn write_readiness_counting_learner_mock(bin_dir: &Path, provider: &str, learner_script: &str) {
    let learner_body = learner_script
        .strip_prefix("#!/bin/bash\n")
        .unwrap_or(learner_script);
    let readiness = match provider {
        "claude" => {
            "if [ \"$1 $2 $3\" = \"auth status --json\" ]; then printf 'ready\\n' >> \"${READINESS_LOG:?}\"; printf '{\\\"loggedIn\\\":true}\\n'; exit 0; fi"
        }
        "pi" => {
            "if [ \"$1\" = \"--version\" ]; then printf 'ready\\n' >> \"${READINESS_LOG:?}\"; exit 0; fi"
        }
        _ => panic!("unsupported readiness-counting provider: {provider}"),
    };
    write_mock_executable(
        bin_dir,
        provider,
        &format!(
            "#!/bin/bash\n{readiness}\n{}{}",
            PROVIDER_READINESS_MOCK_PRELUDE
                .strip_prefix("#!/bin/bash\n")
                .unwrap(),
            learner_body
        ),
    );
}

fn assert_learner_readiness_is_not_rechecked_after_reservation(provider: &str) {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let bin_dir = tmp.path().join(format!("bin-learner-{provider}-readiness"));
    let readiness_log = tmp.path().join("readiness.log");
    write_readiness_counting_learner_mock(&bin_dir, provider, &learner_failing_mock_script());

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["work-item", "create", "work-1", "--title", "Learner"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "attempt",
            "create",
            "work-1",
            "attempt-1",
            "--coder",
            provider,
        ])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .env("READINESS_LOG", &readiness_log)
        .assert()
        .success();

    let readiness_before_retry = fs::read_to_string(&readiness_log).unwrap().lines().count();
    write_readiness_counting_learner_mock(
        &bin_dir,
        provider,
        &learner_mock_script(r#"{"learning_summary":"learned","follow_ups":[]}"#),
    );
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .env("READINESS_LOG", &readiness_log)
        .assert()
        .success();

    let readiness_after_retry = fs::read_to_string(&readiness_log).unwrap().lines().count();
    assert_eq!(
        readiness_after_retry - readiness_before_retry,
        1,
        "the {provider} Learner must use its pre-reservation readiness check rather than run a second one after reserving"
    );
}

#[test]
fn claude_learner_uses_one_readiness_check_per_reserved_run() {
    assert_learner_readiness_is_not_rechecked_after_reservation("claude");
}

#[test]
fn pi_learner_uses_one_readiness_check_per_reserved_run() {
    assert_learner_readiness_is_not_rechecked_after_reservation("pi");
}

#[test]
fn learner_failure_blocks_candidate_readiness() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let bin_dir = tmp.path().join("bin-learner-fail");
    write_mock_claude(&bin_dir, &learner_failing_mock_script());

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["work-item", "create", "work-1", "--title", "Learner"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();

    let output = fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .output()
        .unwrap();
    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);

    // Reviews pass and the run itself does not error, but a non-succeeded Learner
    // blocks advancement: the candidate is not ready and cannot land.
    assert!(
        output.status.success(),
        "the run reports the block without erroring: stdout={stdout} stderr={stderr}"
    );
    assert!(
        stdout.contains("is not ready") && stdout.contains("Learner run is failed"),
        "a failed learner blocks candidate readiness with the durable reason; got:\n{stdout}"
    );
    assert!(
        !stdout.contains("Merge Candidate attempt-1-merge-candidate is ready"),
        "a failed learner must not advance the candidate to ready; got:\n{stdout}"
    );
    assert!(
        stderr.contains("learner failed"),
        "operator is warned about the learner failure; got:\n{stderr}"
    );

    let value = read_work_show_json(&main_dir, "work-1");
    assert_eq!(value["attempts"][0]["learning"]["status"], "failed");
    assert_eq!(value["merge_candidates"].as_array().unwrap().len(), 1);
    assert!(
        !main_dir
            .join(".fluent/work/artifacts/work-1/attempt-1/learner/handoff.json")
            .exists(),
        "a failed learner run persists no handoff"
    );
}

#[test]
fn learner_retry_completes_existing_record_idempotently() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let bin_dir = tmp.path().join("bin-learner-retry");
    write_mock_claude(&bin_dir, &learner_failing_mock_script());

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["work-item", "create", "work-1", "--title", "Learner"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .assert()
        .success();

    let failed = read_work_show_json(&main_dir, "work-1");
    assert_eq!(failed["attempts"][0]["learning"]["status"], "failed");

    // A successful retry completes the same record with one handoff.
    write_mock_claude(
        &bin_dir,
        &learner_mock_script(
            r#"{"learning_summary":"learned","follow_ups":[{"id":"fu-1","summary":"Follow up","corrective":false}]}"#,
        ).replacen("  DRAFT=", "  mkdir -p .fluent/expertise\n  printf 'Retain learned context\\n' > .fluent/expertise/retry.md\n  DRAFT=",1),
    );
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .assert()
        .success();

    let value = read_work_show_json(&main_dir, "work-1");
    assert_eq!(value["attempts"][0]["learning"]["status"], "succeeded");
    assert_eq!(value["attempts"][0]["learning"]["runs"], 2);

    let handoff = read_json_path(
        &main_dir.join(".fluent/work/artifacts/work-1/attempt-1/learner/handoff.json"),
    );
    let follow_ups = handoff["follow_ups"].as_array().unwrap();
    assert_eq!(
        follow_ups.len(),
        1,
        "one accepted follow-up, not duplicated"
    );
    assert_eq!(follow_ups[0]["id"], "fu-1");
    let candidate = main_dir.join("../work-6-work-1-attempt-1");
    let changed = git::run_stdout(
        &candidate,
        &[
            "diff",
            "--name-only",
            failed["merge_candidates"][0]["candidate_commit"]
                .as_str()
                .unwrap(),
            value["merge_candidates"][0]["candidate_commit"]
                .as_str()
                .unwrap(),
        ],
        "learner delta",
    )
    .unwrap();
    record_integrated_facts(
        "learning_capture",
        "FLUENT_INTEGRATED_LEARNING_CAPTURE_TRACE",
        &tmp,
        &[
            ("failed", "attempt-run", serde_json::json!({"work":failed})),
            (
                "retried",
                "attempt-run",
                serde_json::json!({"work":value,"handoff":handoff,"handoff-bytes":fs::read_to_string(main_dir.join(".fluent/work/artifacts/work-1/attempt-1/learner/handoff.json")).unwrap(),"head":git_head(&candidate),"changed":changed,"confinement":"not-required"}),
            ),
        ],
    );
}

