#[test]
fn learner_handoff_does_not_materialize_before_land() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let bin_dir = tmp.path().join("bin-learner-inert");
    write_mock_claude(
        &bin_dir,
        &learner_mock_script(
            r#"{"learning_summary":"learned","follow_ups":[{"id":"fu-1","summary":"Follow up later","corrective":false}]}"#,
        ),
    );

    create_and_run_learner_attempt(&main_dir, &bin_dir);

    // The handoff exists but is inert: no Observation, no derived Work Item.
    let handoff_path =
        main_dir.join(".fluent/work/artifacts/work-1/attempt-1/learner/handoff.json");
    assert!(handoff_path.exists());

    let items_dir = main_dir.join(".fluent/work/items");
    let item_count = fs::read_dir(&items_dir)
        .map(|entries| {
            entries
                .filter_map(|entry| entry.ok())
                .filter(|entry| {
                    entry
                        .path()
                        .extension()
                        .map(|e| e == "json")
                        .unwrap_or(false)
                })
                .count()
        })
        .unwrap_or(0);
    assert_eq!(item_count, 1, "the learner must not derive a Work Item");

    let observations_dir = main_dir.join(".fluent/observations");
    let observation_count = fs::read_dir(&observations_dir)
        .map(|entries| {
            entries
                .filter_map(|entry| entry.ok())
                .filter(|entry| entry.path().extension().map(|e| e == "md").unwrap_or(false))
                .count()
        })
        .unwrap_or(0);
    assert_eq!(
        observation_count, 0,
        "the learner must not create an Observation before land"
    );
}

// --- Land-gated learner handoff materialization (Step 1) ---

/// A mock coder that drives write and review rounds, writes a Learner follow-up
/// draft (verbatim `draft_json`), and performs a real `git rebase` when handed
/// the rebase prompt during a land.
fn learner_land_mock_script(draft_json: &str) -> String {
    format!(
        r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
if [ -z "$PROMPT" ]; then exit 0; fi
if printf '%s' "$PROMPT" | grep -q "Rebase the candidate branch"; then
  TARGET=$(printf '%s' "$PROMPT" | grep -o 'onto `[^`]*`' | sed 's/onto `//;s/`//')
  git rebase "$TARGET" 2>/dev/null
  exit $?
fi
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  if [ -n "$DRAFT" ]; then
    mkdir -p "$(dirname "$DRAFT")"
    cat > "$DRAFT" <<'DRAFTJSON'
{draft_json}
DRAFTJSON
  fi
  exit 0
fi
case "$PWD" in
  */work-6-work-1-attempt-1)
    printf 'loop output\n' > loop-output.txt
    git add loop-output.txt
    git commit -m "Add loop output" >/dev/null 2>&1
    ;;
  *)
    printf 'Verdict: pass\n\nLoop review.\n' > review.md
    ;;
esac
exit 0
"##
    )
}

/// A role-aware coder for the Local Preview release proof. The origin Learner
/// leaves one expertise edit for Fluent to canonicalize and one trusted
/// corrective follow-up; the descendant Learner emits an empty handoff. Both
/// writers make distinct commits, while every reviewer passes.
fn local_preview_flywheel_mock_script(origin_draft_json: &str) -> String {
    format!(
        r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
if [ -z "$PROMPT" ]; then exit 0; fi
if [ -n "${{MOCK_PROMPT_LOG:-}}" ]; then
  printf '%s\n' "$PROMPT" >> "$MOCK_PROMPT_LOG"
fi
if printf '%s' "$PROMPT" | grep -q "Rebase the candidate branch"; then
  TARGET=$(printf '%s' "$PROMPT" | grep -o 'onto `[^`]*`' | sed 's/onto `//;s/`//')
  git rebase "$TARGET" 2>/dev/null
  exit $?
fi
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  if [ -n "$DRAFT" ]; then
    mkdir -p "$(dirname "$DRAFT")"
    case "$PWD" in
      */work-6-work-1-attempt-1)
        mkdir -p .fluent/expertise/learnings
        printf '# Local Preview learning\n\nThe release path preserves one canonical expertise delta.\n' \
          > .fluent/expertise/learnings/local-preview.md
        cat > "$DRAFT" <<'ORIGINDRAFT'
{origin_draft_json}
ORIGINDRAFT
        ;;
      *)
        printf '%s\n' '{{"learning_summary":"descendant complete","follow_ups":[]}}' > "$DRAFT"
        ;;
    esac
  fi
  exit 0
fi
case "$PWD" in
  */work-*-attempt-1)
    case "$PWD" in
      */work-6-work-1-attempt-1) OUTPUT=origin-output.txt ;;
      *) OUTPUT=descendant-output.txt ;;
    esac
    printf 'release proof output\n' > "$OUTPUT"
    git add "$OUTPUT"
    git commit -m "Build Local Preview fixture" >/dev/null 2>&1
    ;;
  *)
    printf 'Verdict: pass\n\nLocal Preview review passed.\n' > review.md
    ;;
esac
exit 0
"##
    )
}

/// Land the sole Merge Candidate of `work-1`, driving the rebase with `bin_dir`.
fn land_work_1(main_dir: &Path, bin_dir: &Path, no_post_merge_review: bool) {
    let mut args = vec![
        "merge-candidate",
        "land",
        "work-1",
        "attempt-1-merge-candidate",
        "--no-sandbox",
    ];
    if no_post_merge_review {
        args.push("--no-post-merge-review");
    }
    fluent_cmd()
        .current_dir(main_dir)
        .args(&args)
        .env("PATH", mock_path(bin_dir))
        .assert()
        .success();
}

/// Create and run work-1/attempt-1 with a first Learner that fails: reviews pass
/// and the merge candidate materializes with its worktree, branch, and reflog,
/// but the failed Learner withholds the ready banner and leaves the candidate
/// non-landable. This mirrors [`create_and_run_learner_attempt`] for the
/// post-land recovery scenarios, whose mocks intentionally fail the first run —
/// the landing gate now rejects a non-succeeded Learner, so the ready banner
/// those scenarios must not assert never appears.
fn create_and_run_failed_learner_attempt(main_dir: &Path, bin_dir: &Path) {
    fluent_cmd()
        .current_dir(main_dir)
        .args(["work-item", "create", "work-1", "--title", "Learner"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(bin_dir))
        .assert()
        .success()
        .stdout(predicate::str::contains("is ready").not())
        .stderr(predicate::str::contains(
            "re-run the Learner before landing",
        ));
}

/// Reproduce the durable state a legacy or interrupted land left behind for a
/// candidate whose Learner failed: the target branch fast-forwarded to the
/// candidate tip and the candidate recorded Merged, while the Attempt's Learning
/// stays failed and the managed candidate worktree, branch, and reflog remain
/// registered for a handoff-only retry.
///
/// The real land route now refuses to advance a non-succeeded Learner, so
/// post-land recovery scenarios can no longer drive it to reach the merged
/// state. This mirrors `finalize_merge`/`record_candidate_merged` exactly: it
/// rebases the retained candidate onto its target (a no-op when the candidate is
/// already based, and the same immutable rebase provenance when the target
/// diverged), fast-forwards the target, and stamps the terminal Merged state.
fn simulate_legacy_land(main_dir: &Path) {
    use fluent::work_model::{
        MergeCandidateMergeState, MergeCandidateMergeStatus, MergeReviewState, TaskKind,
        TaskStatus, WorkModelStore, set_merge_candidate_terminal,
    };

    let store = WorkModelStore::new(main_dir);
    let mut item = store
        .read_work_item("work-1")
        .expect("read work-1 after the failed Learner run");
    let candidate = item
        .merge_candidates
        .first()
        .expect("a merge candidate exists after the failed Learner run")
        .clone();
    let candidate_id = candidate.id.clone();
    let attempt_id = candidate.attempt_id.clone();
    let target_branch = candidate.target_branch.clone();
    let source_dir = main_dir.join(&candidate.source_workspace.path);

    let accepted_base = git::run_stdout(
        main_dir,
        &["rev-parse", &target_branch],
        "resolve target head",
    )
    .unwrap()
    .trim()
    .to_string();
    let tip_before = git::run_stdout(&source_dir, &["rev-parse", "HEAD"], "candidate tip")
        .unwrap()
        .trim()
        .to_string();
    git::run(
        &source_dir,
        &["rebase", &target_branch],
        "rebase retained candidate onto target",
    )
    .unwrap();
    let merged_commit =
        git::run_stdout(&source_dir, &["rev-parse", "HEAD"], "resolve candidate tip")
            .unwrap()
            .trim()
            .to_string();
    git::run(
        main_dir,
        &["checkout", &target_branch],
        "checkout target branch",
    )
    .unwrap();
    git::run(
        main_dir,
        &["merge", "--ff-only", &merged_commit],
        "fast-forward target branch",
    )
    .unwrap();

    // When a diverged target forced a real rebase, mirror the provenance rewrite
    // the merge executor performs: Write outputs and their commit artifacts move
    // to the new tip so the candidate stays structurally valid. An already based
    // candidate is a no-op and keeps its original recorded provenance.
    if merged_commit != tip_before
        && let Some(attempt) = item
            .attempts
            .iter_mut()
            .find(|attempt| attempt.id == attempt_id)
    {
        let write_task_ids: std::collections::HashSet<String> = attempt
            .tasks
            .iter()
            .filter(|task| task.kind == TaskKind::Write && task.status == TaskStatus::Complete)
            .map(|task| task.id.clone())
            .collect();
        for task in &mut attempt.tasks {
            if task.kind == TaskKind::Write && task.status == TaskStatus::Complete {
                if let Some(output) = &mut task.output {
                    output.base_commit = Some(accepted_base.clone());
                    output.commit = merged_commit.clone();
                }
            }
        }
        for artifact in &mut attempt.artifacts {
            if write_task_ids.contains(&artifact.producer_id) {
                artifact.path = merged_commit.clone();
            }
        }
    }

    let candidate = item
        .merge_candidates
        .iter_mut()
        .find(|entry| entry.id == candidate_id)
        .expect("the resolved candidate remains present");
    candidate.candidate_commit = merged_commit.clone();
    candidate.merge_review_state = MergeReviewState::Passed;
    candidate.merge_state = MergeCandidateMergeState {
        status: MergeCandidateMergeStatus::Merged,
        merged_commit: Some(merged_commit),
        failure_reason: None,
        check_artifacts: Vec::new(),
        review_artifacts: Vec::new(),
        auto_merge_skipped: None,
        follow_up_failure: None,
        landing_intent: None,
    };
    set_merge_candidate_terminal(candidate, MergeCandidateMergeStatus::Merged);
    store
        .write_work_item(&item)
        .expect("persist the merged candidate");
}

/// A learner mock that fails its first run and succeeds on retry, keyed by a
/// counter guard file so a post-land retry (which runs after land) drives the
/// handoff-only path. The sandboxed retry cannot write shared temp, so it
/// records observability — its run marker, the prompt it received, and the
/// commit it saw — on stdout, which the host captures in the durable per-run
/// transcript. On the successful run it writes `draft_json` and, when
/// `commit_expertise` is set, commits an expertise change that a handoff-only
/// run must discard.
fn post_land_learner_mock_script(
    counter: &Path,
    draft_json: &str,
    commit_expertise: bool,
) -> String {
    let counter = counter.display().to_string();
    let expertise = if commit_expertise {
        "  mkdir -p .fluent/expertise\n  printf 'late knowledge\\n' > .fluent/expertise/late.md\n  git add .fluent/expertise/late.md\n  git commit -m \"Update expertise\" >/dev/null 2>&1\n"
    } else {
        ""
    };
    format!(
        r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
if [ -z "$PROMPT" ]; then exit 0; fi
if printf '%s' "$PROMPT" | grep -q "Rebase the candidate branch"; then
  TARGET=$(printf '%s' "$PROMPT" | grep -o 'onto `[^`]*`' | sed 's/onto `//;s/`//')
  git rebase "$TARGET" 2>/dev/null
  exit $?
fi
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  echo "LEARNER_RUN"
  echo "LEARNER_PROMPT_BEGIN"
  printf '%s\n' "$PROMPT"
  echo "LEARNER_PROMPT_END"
  if [ ! -f "{counter}" ]; then
    touch "{counter}"
    exit 1
  fi
  printf 'LEARNER_HEAD %s\n' "$(git rev-parse HEAD)"
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  if [ -n "$DRAFT" ]; then
    mkdir -p "$(dirname "$DRAFT")"
    printf '%s\n' '{draft_json}' > "$DRAFT"
  fi
{expertise}  exit 0
fi
case "$PWD" in
  */work-6-work-1-attempt-1)
    printf 'loop output\n' > loop-output.txt
    git add loop-output.txt
    git commit -m "Add loop output" >/dev/null 2>&1
    ;;
  *)
    printf 'Verdict: pass\n\nLoop review.\n' > review.md
    ;;
esac
exit 0
"##
    )
}

/// A learner mock whose post-land retry first emits a schema-invalid draft (a
/// follow-up with no id), then, given the schema-repair prompt, emits a valid
/// corrected draft. It announces each phase on stdout so the test can confirm
/// the repair ran and the semantic audit did not rerun.
fn schema_repair_learner_mock_script(counter: &Path) -> String {
    format!(
        r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
if [ -z "$PROMPT" ]; then exit 0; fi
if [ "$PROMPT" = "ok" ]; then exit 0; fi
if printf '%s' "$PROMPT" | grep -q "Rebase the candidate branch"; then
  TARGET=$(printf '%s' "$PROMPT" | grep -o 'onto `[^`]*`' | sed 's/onto `//;s/`//')
  git rebase "$TARGET" 2>/dev/null
  exit $?
fi
if printf '%s' "$PROMPT" | grep -q "failed schema validation"; then
  echo "SCHEMA_REPAIR_RUN"
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  mkdir -p "$(dirname "$DRAFT")"
  printf '%s\n' '{{"learning_summary":"repaired","follow_ups":[{{"id":"fu-1","summary":"Recovered finding","corrective":false}}]}}' > "$DRAFT"
  exit 0
fi
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  if [ ! -f "{counter}" ]; then touch "{counter}"; exit 1; fi
  echo "LEARNER_RUN"
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  mkdir -p "$(dirname "$DRAFT")"
  printf '%s\n' '{{"learning_summary":"invalid","follow_ups":[{{"id":"","summary":"Missing id finding"}}]}}' > "$DRAFT"
  exit 0
fi
case "$PWD" in
  */work-6-work-1-attempt-1)
    printf 'loop output\n' > loop-output.txt
    git add loop-output.txt
    git commit -m "Add loop output" >/dev/null 2>&1
    ;;
  *) printf 'Verdict: pass\n\nLoop review.\n' > review.md ;;
esac
exit 0
"##,
        counter = counter.display()
    )
}

/// A learner mock whose retry dirties the candidate, announces that state, and
/// waits for the test to release it before committing. This makes a land/retry
/// overlap deterministic instead of relying on scheduler timing.
fn contended_learner_mock_script(
    counter: &Path,
    retry_started: &Path,
    retry_release: &Path,
) -> String {
    format!(
        r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
if [ -z "$PROMPT" ]; then exit 0; fi
if printf '%s' "$PROMPT" | grep -q "Rebase the candidate branch"; then
  TARGET=$(printf '%s' "$PROMPT" | grep -o 'onto `[^`]*`' | sed 's/onto `//;s/`//')
  git rebase "$TARGET" 2>/dev/null
  exit $?
fi
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  if [ ! -f "{}" ]; then
    touch "{}"
    exit 1
  fi
  printf 'transient learner write\n' > transient-learner.txt 2>/dev/null
  git add transient-learner.txt 2>/dev/null
  # Announce the serialized mutation window twice: a shared-temp marker for an
  # unsandboxed pre-land race, and a stdout marker the host captures in the
  # durable transcript for a sandboxed post-land retry that cannot write it.
  echo "RETRY_STARTED"
  touch "{}" 2>/dev/null
  while [ ! -f "{}" ]; do sleep 0.02; done
  git commit -m "Update expertise" >/dev/null 2>&1
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  mkdir -p "$(dirname "$DRAFT")"
  printf '%s\n' '{{"learning_summary":"won before land","follow_ups":[]}}' > "$DRAFT"
  exit 0
fi
case "$PWD" in
  */work-6-work-1-attempt-1)
    printf 'loop output\n' > loop-output.txt
    git add loop-output.txt
    git commit -m "Add loop output" >/dev/null 2>&1
    ;;
  *)
    printf 'Verdict: pass\n\nLoop review.\n' > review.md
    ;;
esac
exit 0
"##,
        counter.display(),
        counter.display(),
        retry_started.display(),
        retry_release.display(),
    )
}

/// A pre-land Learner race mock: the first run fails so the Attempt keeps a real
/// pending Merge Candidate, and the retry recovers by committing a confined
