/// Re-run the completed Attempt to retry a failed Learner.
fn rerun_learner_attempt(main_dir: &Path, bin_dir: &Path) -> std::process::Output {
    write_mock_sandbox_exec(bin_dir);
    fluent_cmd()
        .current_dir(main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(bin_dir))
        .env("SANDBOX_EXEC_LOG", bin_dir.join("sandbox-exec.log"))
        .output()
        .unwrap()
}

macro_rules! require_successful_trusted_retry {
    ($output:expr) => {{
        let output = $output;
        if !real_sandbox_exec_is_usable() {
            assert!(!output.status.success());
            assert!(
                String::from_utf8_lossy(&output.stderr)
                    .contains("follow-up recovery remains pending")
            );
            return;
        }
        assert!(
            output.status.success(),
            "trusted retry failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }};
}

fn rerun_learner_attempt_with_system_sandbox(
    main_dir: &Path,
    bin_dir: &Path,
) -> std::process::Output {
    fs::remove_file(bin_dir.join("sandbox-exec")).unwrap();
    fluent_cmd()
        .current_dir(main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(bin_dir))
        .output()
        .unwrap()
}

fn rerun_learner_attempt_sandboxed(main_dir: &Path, bin_dir: &Path) -> std::process::Output {
    fs::remove_file(bin_dir.join("sandbox-exec")).unwrap();
    fluent_cmd()
        .current_dir(main_dir)
        .args(["attempt", "run", "work-1", "attempt-1"])
        .env("PATH", mock_path(bin_dir))
        .env("CLAUDE_CODE_OAUTH_TOKEN", "mock-token")
        .output()
        .unwrap()
}

fn real_sandbox_exec_is_usable() -> bool {
    std::process::Command::new("/usr/bin/sandbox-exec")
        .args(["-p", "(version 1)(allow default)", "/usr/bin/true"])
        .status()
        .map(|status| status.success())
        .unwrap_or(false)
}

fn merged_commit_of(main_dir: &Path) -> String {
    work_item_value(main_dir, "work-1")["merge_candidates"][0]["merge_state"]["merged_commit"]
        .as_str()
        .unwrap()
        .to_string()
}

/// Concatenate every durable Learner transcript for work-1/attempt-1 across all
/// host-owned run directories: each `learner/runs/run-<N>/transcript.jsonl` plus
/// the immutable `transcript.<phase>.jsonl` siblings a refreshing retry
/// preserves. The sandboxed handoff-only retry cannot write shared temp, so it
/// records its observability on stdout, which the host captures here on the
/// managed run surface.
fn learner_transcripts(main_dir: &Path) -> String {
    let runs = main_dir.join(".fluent/work/artifacts/work-1/attempt-1/learner/runs");
    let mut transcripts: Vec<(String, String)> = Vec::new();
    if let Ok(run_dirs) = fs::read_dir(&runs) {
        for run in run_dirs.filter_map(|e| e.ok()) {
            let run_name = run.file_name().to_string_lossy().to_string();
            if let Ok(entries) = fs::read_dir(run.path()) {
                for entry in entries.filter_map(|e| e.ok()) {
                    let name = entry.file_name().to_string_lossy().to_string();
                    if name.starts_with("transcript")
                        && name.ends_with(".jsonl")
                        && let Ok(body) = fs::read_to_string(entry.path())
                    {
                        transcripts.push((format!("{run_name}/{name}"), body));
                    }
                }
            }
        }
    }
    transcripts.sort_by(|a, b| a.0.cmp(&b.0));
    transcripts
        .into_iter()
        .map(|(_, body)| body)
        .collect::<Vec<_>>()
        .join("\n")
}

/// The number of Learner coder runs recorded across all durable transcripts.
fn learner_run_count(main_dir: &Path) -> usize {
    learner_transcripts(main_dir)
        .lines()
        .filter(|line| *line == "LEARNER_RUN")
        .count()
}

/// The open Observation files in a project, sorted by id.
fn open_observation_files(main_dir: &Path) -> Vec<String> {
    let dir = main_dir.join(".fluent/observations");
    let mut files: Vec<String> = fs::read_dir(&dir)
        .map(|entries| {
            entries
                .filter_map(|e| e.ok())
                .filter(|e| e.path().extension().map(|x| x == "md").unwrap_or(false))
                .map(|e| e.file_name().to_string_lossy().to_string())
                .collect()
        })
        .unwrap_or_default();
    files.sort();
    files
}

fn work_item_json_count(main_dir: &Path) -> usize {
    let items_dir = main_dir.join(".fluent/work/items");
    fs::read_dir(&items_dir)
        .map(|entries| {
            entries
                .filter_map(|e| e.ok())
                .filter(|e| e.path().extension().map(|x| x == "json").unwrap_or(false))
                .count()
        })
        .unwrap_or(0)
}

