#[test]
fn workflow_cleanup_holds_eligibility_through_removal() {
    use fluent::work_model::{AttemptStatus, WorkItem};
    let tmp = TempDir::new().unwrap();
    let project = setup_git_project(&tmp);
    let store = WorkModelStore::new(&project);
    let mut item = WorkItem::planned("cleanup-locked", "Protect cleanup eligibility");
    item.add_initial_attempt("attempt-1").unwrap();
    item.attempts[0].status = AttemptStatus::Failed;
    item.attempts[0].tasks[0].status = TaskStatus::Failed;
    store.create_work_item(&item).unwrap();
    let reached = tmp.path().join("cleanup-locked-reached");
    let release = tmp.path().join("cleanup-locked-release");
    let mut command = std::process::Command::new(assert_cmd::cargo::cargo_bin("fluent"));
    command
        .current_dir(&project)
        .args(["cleanup", "--apply"])
        .env("FLUENT_TEST_CLEANUP_LOCKED_ITEM", "cleanup-locked")
        .env("FLUENT_TEST_CLEANUP_LOCKED_REACHED", &reached)
        .env("FLUENT_TEST_CLEANUP_LOCKED_RELEASE", &release)
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    let mut child = OwnedFixtureProcess::spawn(&mut command);
    for _ in 0..500 {
        if reached.exists() {
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
    }
    assert!(
        reached.exists(),
        "cleanup did not reach the locked boundary"
    );
    let mutation_started = tmp.path().join("cleanup-mutation-started");
    let mutation_finished = tmp.path().join("cleanup-mutation-finished");
    let project_for_mutation = project.clone();
    let mutation_finished_for_thread = mutation_finished.clone();
    let mutation = std::thread::spawn(move || {
        fs::write(&mutation_started, b"started").unwrap();
        let result =
            WorkModelStore::new(&project_for_mutation).mutate_work_item("cleanup-locked", |item| {
                item.attempts[0].status = AttemptStatus::NeedsUser;
                item.attempts[0].tasks[0].status = TaskStatus::NeedsUser;
                Ok(())
            });
        fs::write(&mutation_finished_for_thread, b"finished").unwrap();
        result
    });
    for _ in 0..500 {
        if tmp.path().join("cleanup-mutation-started").exists() {
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
    }
    assert!(tmp.path().join("cleanup-mutation-started").exists());
    std::thread::sleep(std::time::Duration::from_millis(100));
    assert!(
        !mutation_finished.exists(),
        "mutation bypassed cleanup's model lock"
    );
    fs::write(&release, b"continue").unwrap();
    let output = child.wait_with_output().unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(mutation.join().unwrap().is_err());
    assert!(store.read_work_item("cleanup-locked").is_err());
}

#[test]
fn cleanup_waits_for_recovery_then_rereads_the_completed_origin() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let counter = tmp.path().join("learner-counter-cleanup-race");
    let retry_started = tmp.path().join("cleanup-race-started");
    let retry_release = tmp.path().join("cleanup-race-release");
    let bin_dir = tmp.path().join("bin-cleanup-race");
    write_mock_claude(
        &bin_dir,
        &contended_learner_mock_script(&counter, &retry_started, &retry_release),
    );

    create_and_run_failed_learner_attempt(&main_dir, &bin_dir);
    simulate_legacy_land(&main_dir);
    if !real_sandbox_exec_is_usable() {
        let retry = rerun_learner_attempt(&main_dir, &bin_dir);
        assert!(!retry.status.success());
        fluent_cmd()
            .current_dir(&main_dir)
            .args(["cleanup", "--apply"])
            .assert()
            .success();
        assert!(main_dir.join(".fluent/work/items/work-1.json").exists());
        return;
    }
    write_mock_sandbox_exec(&bin_dir);
    let mut retry = {
        let mut command = std::process::Command::new(assert_cmd::cargo::cargo_bin("fluent"));
        command
            .current_dir(&main_dir)
            .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
            .env("PATH", mock_path(&bin_dir))
            .env("SANDBOX_EXEC_LOG", bin_dir.join("sandbox-exec.log"))
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        OwnedFixtureProcess::spawn(&mut command)
    };
    // The sandboxed retry cannot write shared temp, so it announces its
    // mutation window on stdout, which the host captures in the durable
    // transcript.
    for _ in 0..500 {
        if learner_transcripts(&main_dir).contains("RETRY_STARTED") {
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
    }
    assert!(
        learner_transcripts(&main_dir).contains("RETRY_STARTED"),
        "recovery reached its serialized mutation window"
    );

    let mut cleanup = {
        let mut command = std::process::Command::new(assert_cmd::cargo::cargo_bin("fluent"));
        command
            .current_dir(&main_dir)
            .args(["cleanup", "--apply"])
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        OwnedFixtureProcess::spawn(&mut command)
    };
    let lock_path = fs::canonicalize(main_dir.join(".fluent/work/locks/land.lock")).unwrap();
    let lock_text = lock_path.to_string_lossy().into_owned();
    let cleanup_pid = cleanup.id().to_string();
    let mut cleanup_reached_lock = false;
    for _ in 0..200 {
        let output = std::process::Command::new("/usr/sbin/lsof")
            .args(["-a", "-p", &cleanup_pid, "-Fn", "--", &lock_text])
            .output()
            .unwrap();
        let expected = format!("n{}", lock_path.display());
        if output.status.success()
            && String::from_utf8_lossy(&output.stdout)
                .lines()
                .any(|line| line == expected)
        {
            cleanup_reached_lock = true;
            break;
        }
        if cleanup.try_wait().unwrap().is_some() {
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
    }
    fs::write(&retry_release, "release\n").unwrap();
    assert!(
        cleanup_reached_lock,
        "cleanup reached the shared recovery boundary"
    );

    let retry_output = retry.wait_with_output().unwrap();
    let cleanup_output = cleanup.wait_with_output().unwrap();
    assert!(
        retry_output.status.success(),
        "recovery failed: {}",
        String::from_utf8_lossy(&retry_output.stderr)
    );
    assert!(
        cleanup_output.status.success(),
        "cleanup failed: {}",
        String::from_utf8_lossy(&cleanup_output.stderr)
    );
    assert!(
        !main_dir.join(".fluent/work/items/work-1.json").exists(),
        "cleanup's locked reread observes completed recovery and removes the origin"
    );
}

#[test]
fn post_land_handoff_only_ignores_no_sandbox_and_preserves_live_git() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let counter = tmp.path().join("learner-counter-hostile");
    let bin_dir = tmp.path().join("bin-hostile-git");
    write_mock_claude(
        &bin_dir,
        &hostile_post_land_learner_mock_script(
            &counter,
            &main_dir,
            &main_dir.join("../work-6-work-1-attempt-1"),
            &main_dir.join(".git"),
        ),
    );

    create_and_run_failed_learner_attempt(&main_dir, &bin_dir);
    simulate_legacy_land(&main_dir);
    let merged = merged_commit_of(&main_dir);
    fs::write(
        main_dir.join("preexisting-staged.txt"),
        "staged before retry\n",
    )
    .unwrap();
    git::run(
        &main_dir,
        &["add", "preexisting-staged.txt"],
        "stage preexisting target file",
    )
    .unwrap();
    fs::write(
        main_dir.join("preexisting-untracked.txt"),
        "untracked before retry\n",
    )
    .unwrap();
    let executable = main_dir.join("preexisting-executable");
    fs::write(&executable, "#!/bin/sh\nexit 0\n").unwrap();
    #[cfg(unix)]
    {
        use std::os::unix::ffi::OsStringExt;
        use std::os::unix::fs::{PermissionsExt, symlink};

        fs::set_permissions(&executable, fs::Permissions::from_mode(0o755)).unwrap();
        let outside = tmp.path().join("outside-symlink-target");
        fs::write(&outside, "outside stays unchanged\n").unwrap();
        symlink(&outside, main_dir.join("preexisting-link")).unwrap();
        fs::create_dir_all(main_dir.join(".fluent")).unwrap();
        let non_utf_path = main_dir
            .join(".fluent")
            .join(std::ffi::OsString::from_vec(b"non-utf8-\xff".to_vec()));
        let _ = fs::write(non_utf_path, b"non-UTF-8 path stays unchanged\n");
    }
    fs::write(
        main_dir.join("README.md"),
        "# Test\n\nunstaged before retry\n",
    )
    .unwrap();
    git::run(
        &main_dir,
        &["update-index", "--assume-unchanged", "loop-output.txt"],
        "set preexisting index flag",
    )
    .unwrap();
    git::run(
        &main_dir,
        &["update-index", "--skip-worktree", ".gitignore"],
        "set preexisting skip-worktree flag",
    )
    .unwrap();
    let preserved_paths = [
        "README.md",
        "preexisting-staged.txt",
        "preexisting-untracked.txt",
        "preexisting-executable",
        "loop-output.txt",
        ".gitignore",
    ];
    let target_bytes_before = preserved_paths
        .iter()
        .map(|path| (*path, fs::read(main_dir.join(path)).unwrap()))
        .collect::<Vec<_>>();
    let staged_blob_before = git::run_stdout(
        &main_dir,
        &["show", ":preexisting-staged.txt"],
        "read staged target blob before hostile retry",
    )
    .unwrap();
    let target_status_before = git::run_stdout(
        &main_dir,
        &["status", "--porcelain", "--untracked-files=all"],
        "target status before hostile retry",
    )
    .unwrap();
    let index_flags_before = git::run_stdout(
        &main_dir,
        &["ls-files", "-v", "loop-output.txt", ".gitignore"],
        "target index flags before hostile retry",
    )
    .unwrap();
    let retry_output = rerun_learner_attempt_with_system_sandbox(&main_dir, &bin_dir);

    if real_sandbox_exec_is_usable() {
        assert!(
            retry_output.status.success(),
            "trusted sandbox retry failed: {}",
            String::from_utf8_lossy(&retry_output.stderr)
        );
        let handoff: serde_json::Value = serde_json::from_str(
            &fs::read_to_string(
                main_dir.join(fluent::learner::handoff_path_rel("work-1", "attempt-1")),
            )
            .unwrap(),
        )
        .unwrap();
        let sandbox_results = handoff["learning"]["summary"].as_str().unwrap();
        assert!(sandbox_results.contains("hostile project="));
        assert!(!sandbox_results.contains("live_target_write=0"));
        assert!(!sandbox_results.contains("live_target_index=0"));
        assert!(!sandbox_results.contains("retained_write=0"));
        assert!(!sandbox_results.contains("retained_index=0"));
        assert!(!sandbox_results.contains("shared_ref=0"));
        assert!(!sandbox_results.contains("origin_present=0"));
        assert!(sandbox_results.contains("prompt_leak=1"));
    } else {
        assert!(!retry_output.status.success());
        assert!(
            String::from_utf8_lossy(&retry_output.stderr)
                .contains("follow-up recovery remains pending")
        );
        assert_eq!(
            work_item_value(&main_dir, "work-1")["attempts"][0]["learning"]["status"],
            "failed",
            "handoff-only --no-sandbox must fail closed when trusted Seatbelt is unavailable"
        );
    }

    assert_eq!(
        git::run_stdout(&main_dir, &["rev-parse", "HEAD"], "target HEAD").unwrap(),
        merged
    );
    let candidate = main_dir.join("../work-6-work-1-attempt-1");
    assert_eq!(
        work_item_value(&main_dir, "work-1")["merge_candidates"][0]["candidate_commit"],
        merged,
        "the persisted candidate commit remains the merged commit"
    );
    if real_sandbox_exec_is_usable() {
        assert!(
            !candidate.exists(),
            "successful recovery removes the retained candidate worktree"
        );
    } else {
        assert!(
            candidate.exists(),
            "failed-closed recovery retains the candidate for a later retry"
        );
    }
    assert!(!main_dir.join("target-mutated.txt").exists());
    assert!(!main_dir.join("live-target-mutated.txt").exists());
    assert_eq!(
        git::run_stdout(
            &main_dir,
            &["status", "--porcelain", "--untracked-files=all"],
            "target status after hostile retry",
        )
        .unwrap(),
        target_status_before,
        "isolation preserves staged, unstaged, and untracked target state"
    );
    assert_eq!(
        git::run_stdout(
            &main_dir,
            &["ls-files", "-v", "loop-output.txt", ".gitignore"],
            "target index flags after hostile retry",
        )
        .unwrap(),
        index_flags_before,
        "isolation preserves complete index flags"
    );
    for (path, expected) in target_bytes_before {
        assert_eq!(
            fs::read(main_dir.join(path)).unwrap(),
            expected,
            "isolation preserves the bytes of {path}"
        );
    }
    assert_eq!(
        git::run_stdout(
            &main_dir,
            &["show", ":preexisting-staged.txt"],
            "read staged target blob after hostile retry",
        )
        .unwrap(),
        staged_blob_before,
        "isolation preserves staged blob bytes"
    );
    #[cfg(unix)]
    {
        use std::os::unix::ffi::OsStringExt;
        use std::os::unix::fs::PermissionsExt;

        assert_eq!(
            fs::read_link(main_dir.join("preexisting-link")).unwrap(),
            tmp.path().join("outside-symlink-target")
        );
        assert_eq!(
            fs::read(tmp.path().join("outside-symlink-target")).unwrap(),
            b"outside stays unchanged\n"
        );
        assert_eq!(
            fs::metadata(&executable).unwrap().permissions().mode() & 0o777,
            0o755
        );
        let non_utf_path = main_dir
            .join(".fluent")
            .join(std::ffi::OsString::from_vec(b"non-utf8-\xff".to_vec()));
        if non_utf_path.exists() {
            assert_eq!(
                fs::read(non_utf_path).unwrap(),
                b"non-UTF-8 path stays unchanged\n"
            );
        }
    }
    assert!(
        !git::run_raw(
            &main_dir,
            &["show-ref", "--verify", "--quiet", "refs/heads/unauthorized"],
        )
        .unwrap()
        .status
        .success(),
        "unauthorized refs are removed"
    );
    if real_sandbox_exec_is_usable() {
        assert_eq!(
            work_item_value(&main_dir, "work-1")["attempts"][0]["learning"]["status"],
            "succeeded",
            "denied hostile writes must not discard the managed handoff"
        );
    }
}

/// Write a mock `security` that answers the Claude Code Keychain lookup with a
/// non-expiring credential carrying `token`, and refuses every other service.
fn write_mock_security(bin_dir: &Path, token: &str) {
    fs::create_dir_all(bin_dir).unwrap();
    let script = format!(
        r##"#!/bin/bash
case "$*" in
  *"Claude Code-credentials"*)
    printf '%s' '{{"claudeAiOauth":{{"accessToken":"{token}","expiresAt":9999999999999}}}}'
    exit 0
    ;;
  *) exit 1 ;;
esac
"##
    );
    let path = bin_dir.join("security");
    fs::write(&path, script).unwrap();
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(&path, fs::Permissions::from_mode(0o755)).unwrap();
    }
}

/// Run the completed Attempt's failed Learner as an effectively sandboxed
/// handoff-only retry, with a stripped credential environment so only host-side
/// injection can supply a token. Removes the failing `sandbox-exec` stub so the
/// trusted system launcher is used.
fn rerun_learner_trusted(
    main_dir: &Path,
    bin_dir: &Path,
    extra_env: &[(&str, &str)],
) -> std::process::Output {
    let _ = fs::remove_file(bin_dir.join("sandbox-exec"));
    let mut cmd = fluent_cmd();
    cmd.current_dir(main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(bin_dir))
        .env(
            "FLUENT_TEST_FIXTURE_PROVIDER_CREDENTIAL",
            "CLAUDE_CODE_OAUTH_TOKEN",
        )
        .env("FLUENT_TEST_ALLOW_CREDENTIAL_FIXTURES", "1")
        .env_remove("CLAUDE_CODE_OAUTH_TOKEN")
        .env_remove("ANTHROPIC_API_KEY");
    for (key, value) in extra_env {
        cmd.env(key, value);
    }
    cmd.output().unwrap()
}

/// A learner mock that fails its pre-land run (recording the counter while
/// unsandboxed), then on the trusted handoff-only retry reports the
/// `CLAUDE_CODE_OAUTH_TOKEN` it received into the draft's learning summary.
fn credential_probe_learner_mock_script(counter: &Path) -> String {
    format!(
        r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
if [ -z "$PROMPT" ]; then exit 0; fi
if [ "$PROMPT" = "ok" ]; then exit 0; fi
if printf '%s' "$PROMPT" | grep -q "Rebase the candidate branch"; then
  TARGET=$(printf '%s' "$PROMPT" | grep -o 'onto `[^`]*`' | sed 's/onto `//;s/`//')
  git rebase "$TARGET" 2>/dev/null
  exit $?
fi
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  if [ ! -f "{counter}" ]; then touch "{counter}"; exit 1; fi
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  mkdir -p "$(dirname "$DRAFT")"
  TOKEN="${{CLAUDE_CODE_OAUTH_TOKEN:-MISSING}}"
  printf '{{"learning_summary":"oauth=%s","follow_ups":[]}}\n' "$TOKEN" > "$DRAFT"
  exit 0
fi
case "$PWD" in
  */work-6-work-1-attempt-1)
    printf 'loop output\n' > loop-output.txt
    git add loop-output.txt
    git commit -m "Add loop output" >/dev/null 2>&1
    ;;
  *) printf 'Verdict: pass\n\nLoop review.\n' > review.md ;;
esac
exit 0
"##,
        counter = counter.display()
    )
}

/// A learner mock whose trusted handoff-only retry probes its temp access: it
/// writes to `$TMPDIR` (the private scratch) and to shared `/private/tmp`, then
/// reports both outcomes and the `$TMPDIR` path into the learning summary.
fn temp_probe_learner_mock_script(counter: &Path) -> String {
    format!(
        r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
if [ -z "$PROMPT" ]; then exit 0; fi
if [ "$PROMPT" = "ok" ]; then exit 0; fi
if printf '%s' "$PROMPT" | grep -q "Rebase the candidate branch"; then
  TARGET=$(printf '%s' "$PROMPT" | grep -o 'onto `[^`]*`' | sed 's/onto `//;s/`//')
  git rebase "$TARGET" 2>/dev/null
  exit $?
fi
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  if [ ! -f "{counter}" ]; then touch "{counter}"; exit 1; fi
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  mkdir -p "$(dirname "$DRAFT")"
  printf 'private\n' > "$TMPDIR/probe.txt" 2>/dev/null; PRIVATE=$?
  printf 'shared\n' > "/private/tmp/fluent-b2-$$.txt" 2>/dev/null; SHARED=$?
  printf '{{"learning_summary":"tmpdir=%s private=%s shared=%s","follow_ups":[]}}\n' \
    "$TMPDIR" "$PRIVATE" "$SHARED" > "$DRAFT"
  exit 0
fi
case "$PWD" in
  */work-6-work-1-attempt-1)
    printf 'loop output\n' > loop-output.txt
    git add loop-output.txt
    git commit -m "Add loop output" >/dev/null 2>&1
    ;;
  *) printf 'Verdict: pass\n\nLoop review.\n' > review.md ;;
esac
exit 0
"##,
        counter = counter.display()
    )
}

/// A learner mock whose trusted handoff-only retry emits a 401 result on its
/// first attempt (recording a marker in the writable private scratch so it
/// persists across the one-refresh retry) and then succeeds on the retry.
fn auth_401_learner_mock_script(counter: &Path) -> String {
    format!(
        r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
if [ -z "$PROMPT" ]; then exit 0; fi
if [ "$PROMPT" = "ok" ]; then exit 0; fi
if printf '%s' "$PROMPT" | grep -q "Rebase the candidate branch"; then
  TARGET=$(printf '%s' "$PROMPT" | grep -o 'onto `[^`]*`' | sed 's/onto `//;s/`//')
  git rebase "$TARGET" 2>/dev/null
  exit $?
fi
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  if [ ! -f "{counter}" ]; then touch "{counter}"; exit 1; fi
  MARK="$TMPDIR/auth-401-seen"
  if [ ! -f "$MARK" ]; then
    printf 'seen\n' > "$MARK"
    printf '{{"type":"result","api_error_status":401,"request_id":"req-learner-401"}}\n'
    exit 1
  fi
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  mkdir -p "$(dirname "$DRAFT")"
  printf '{{"type":"result","api_error_status":0,"request_id":"req-learner-ok"}}\n'
  printf '{{"learning_summary":"recovered after refresh","follow_ups":[]}}\n' > "$DRAFT"
  exit 0
fi
case "$PWD" in
  */work-6-work-1-attempt-1)
    printf 'loop output\n' > loop-output.txt
    git add loop-output.txt
    git commit -m "Add loop output" >/dev/null 2>&1
    ;;
  *) printf 'Verdict: pass\n\nLoop review.\n' > review.md ;;
esac
exit 0
"##,
        counter = counter.display()
    )
}

