#[test]
fn trusted_learner_auth_401_refreshes_from_transcript() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let counter = tmp.path().join("learner-counter-auth");
    let bin_dir = tmp.path().join("bin-learner-auth");
    write_mock_claude(&bin_dir, &auth_401_learner_mock_script(&counter));
    write_mock_security(&bin_dir, "auth-probe-token");

    create_and_run_failed_learner_attempt(&main_dir, &bin_dir);
    simulate_legacy_land(&main_dir);

    let retry_output = rerun_learner_trusted(
        &main_dir,
        &bin_dir,
        &[("CLAUDE_CODE_OAUTH_TOKEN", "auth-probe-token")],
    );
    if !real_sandbox_exec_is_usable() {
        assert!(!retry_output.status.success());
        return;
    }
    let stderr = String::from_utf8_lossy(&retry_output.stderr);
    assert!(
        retry_output.status.success(),
        "trusted auth retry failed: {stderr}"
    );
    assert!(
        stderr.contains("Auth 401 detected"),
        "the one-refresh policy must fire on a 401: {stderr}"
    );
    assert!(
        stderr.contains("Recovered after credential refresh"),
        "the Learner must continue automatically after one refresh: {stderr}"
    );

    // The host captures each run's transcript on the host-owned run surface.
    // The refreshing retry truncates its live transcript, so the session-ending
    // 401 is preserved in an immutable per-phase sibling the sandboxed coder
    // cannot write.
    let runs = main_dir.join(".fluent/work/artifacts/work-1/attempt-1/learner/runs");
    let mut has_live_transcript = false;
    let mut preserved_401 = false;
    for run in fs::read_dir(&runs)
        .expect("the host-owned run surface must exist")
        .filter_map(|e| e.ok())
    {
        let live = run.path().join("transcript.jsonl");
        if live.exists() && !fs::read_to_string(&live).unwrap().trim().is_empty() {
            has_live_transcript = true;
        }
        let phase = run.path().join("transcript.0.jsonl");
        if phase.exists()
            && fs::read_to_string(&phase)
                .unwrap()
                .contains("req-learner-401")
        {
            preserved_401 = true;
        }
    }
    assert!(
        has_live_transcript,
        "a non-empty transcript must be captured on the host-owned run surface"
    );
    assert!(
        preserved_401,
        "the pre-refresh phase must capture the session-ending 401 as an immutable artifact"
    );

    let handoff: serde_json::Value =
        read_json_path(&main_dir.join(fluent::learner::handoff_path_rel("work-1", "attempt-1")));
    assert_eq!(
        handoff["learning"]["summary"], "recovered after refresh",
        "the Learner must continue automatically after the refresh"
    );
}

#[test]
fn sandboxed_post_land_coder_runs_and_is_denied() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let counter = tmp.path().join("learner-counter-sandbox-hostile");
    let bin_dir = tmp.path().join("bin-sandbox-hostile");
    write_mock_claude(
        &bin_dir,
        &hostile_post_land_learner_mock_script(
            &counter,
            &main_dir,
            &main_dir.join("../work-6-work-1-attempt-1"),
            &main_dir.join(".git"),
        ),
    );

    create_and_run_failed_learner_attempt(&main_dir, &bin_dir);
    simulate_legacy_land(&main_dir);
    let merged = merged_commit_of(&main_dir);
    let retry_output = rerun_learner_attempt_sandboxed(&main_dir, &bin_dir);

    if !real_sandbox_exec_is_usable() {
        assert!(!retry_output.status.success());
        assert!(
            String::from_utf8_lossy(&retry_output.stderr)
                .contains("follow-up recovery remains pending")
        );
        assert_eq!(
            work_item_value(&main_dir, "work-1")["attempts"][0]["learning"]["status"],
            "failed",
            "an unavailable trusted sandbox must fail closed instead of reporting success"
        );
        assert_eq!(git_head(&main_dir), merged);
        assert!(!main_dir.join("live-target-mutated.txt").exists());
        return;
    }
    assert!(
        retry_output.status.success(),
        "trusted sandbox retry failed: {}",
        String::from_utf8_lossy(&retry_output.stderr)
    );

    let handoff: serde_json::Value = serde_json::from_str(
        &fs::read_to_string(
            main_dir.join(fluent::learner::handoff_path_rel("work-1", "attempt-1")),
        )
        .unwrap(),
    )
    .unwrap();
    let sandbox_results = handoff["learning"]["summary"].as_str().unwrap();
    assert!(sandbox_results.contains("hostile project="));
    assert!(!sandbox_results.contains("live_target_write=0"));
    assert!(!sandbox_results.contains("live_target_index=0"));
    assert!(!sandbox_results.contains("retained_write=0"));
    assert!(!sandbox_results.contains("retained_index=0"));
    assert!(!sandbox_results.contains("shared_ref=0"));
    assert!(!sandbox_results.contains("origin_present=0"));
    assert!(sandbox_results.contains("prompt_leak=1"));
    for operation in [
        "target_write",
        "target_index",
        "ref_write",
        "candidate_write",
        "candidate_index",
    ] {
        assert!(
            !sandbox_results.contains(&format!("{operation}=0")),
            "the real handoff-only sandbox must deny {operation}: {sandbox_results}"
        );
    }

    // The host records the run's evidence on its own run surface, which the
    // sandboxed coder — confined to a disposable clone with no path to the live
    // project — cannot replace, delete, or truncate. The transcript and the
    // submitted-draft snapshot survive the hostile run intact.
    let runs = main_dir.join(".fluent/work/artifacts/work-1/attempt-1/learner/runs");
    let mut recorded_submitted_draft = false;
    let mut recorded_transcript = false;
    for run in fs::read_dir(&runs)
        .expect("the host-owned run surface must exist")
        .filter_map(|e| e.ok())
    {
        let submitted = run.path().join("submitted-draft.json");
        if submitted.exists()
            && fs::read_to_string(&submitted)
                .unwrap()
                .contains("hostile project=")
        {
            recorded_submitted_draft = true;
        }
        if run.path().join("transcript.jsonl").exists() {
            recorded_transcript = true;
        }
    }
    assert!(
        recorded_submitted_draft,
        "the host must snapshot the submitted draft as immutable run evidence"
    );
    assert!(
        recorded_transcript,
        "the host must own the run transcript on its own run surface"
    );

    let candidate = main_dir.join("../work-6-work-1-attempt-1");
    assert_eq!(git_head(&main_dir), merged);
    assert_eq!(
        work_item_value(&main_dir, "work-1")["merge_candidates"][0]["candidate_commit"],
        merged
    );
    assert!(!candidate.exists());
    assert!(!main_dir.join("target-mutated.txt").exists());
    assert!(
        !git::run_raw(
            &main_dir,
            &["show-ref", "--verify", "--quiet", "refs/heads/unauthorized"],
        )
        .unwrap()
        .status
        .success(),
        "the effective Seatbelt profile denies shared-Git ref writes"
    );
}

