fn write_work_item_json(project_root: &Path, id: &str, title: &str) {
    let items_dir = project_root.join(".fluent/work/items");
    fs::create_dir_all(&items_dir).unwrap();
    fs::write(
        items_dir.join(format!("{id}.json")),
        format!(
            r#"{{
  "id": "{id}",
  "title": "{title}"
}}
"#
        ),
    )
    .unwrap();
}

fn read_work_show_json(project_root: &Path, work_item_id: &str) -> serde_json::Value {
    let output = fluent_cmd()
        .current_dir(project_root)
        .args(["work-item", "show", work_item_id])
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "work-item show failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    serde_json::from_slice(&output.stdout).unwrap()
}

fn work_task_record_path(
    project_root: &Path,
    work_item_id: &str,
    attempt_id: &str,
    task_id: &str,
) -> PathBuf {
    project_root
        .join(".fluent/work/tasks")
        .join(work_item_id)
        .join(attempt_id)
        .join(format!("{task_id}.json"))
}

fn read_json_value(path: &Path) -> serde_json::Value {
    serde_json::from_str(&fs::read_to_string(path).unwrap()).unwrap()
}

fn write_json_value(path: &Path, value: &serde_json::Value) {
    fs::write(path, serde_json::to_string_pretty(value).unwrap()).unwrap();
}

/// Compare two JSON-serialized texts semantically (ignore field order).
/// Use this when a test asserts a JSON file was not modified by Fluent:
/// Fluent's struct-order serde output and the test helper's alphabetical
/// serde_json::Value output produce equal Values but unequal text.
fn assert_json_unchanged(path: &Path, before: &str) {
    let current: serde_json::Value =
        serde_json::from_str(&fs::read_to_string(path).unwrap()).unwrap();
    let baseline: serde_json::Value = serde_json::from_str(before).unwrap();
    assert_eq!(current, baseline, "JSON at {} was modified", path.display());
}

fn write_planned_followup_task(main_dir: &Path, input_artifacts: Vec<serde_json::Value>) {
    let value = read_work_show_json(main_dir, "work-1");
    let attempt = &value["attempts"][0];
    let initial_write = attempt["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .find(|task| task["id"] == "attempt-1-write-1")
        .unwrap();
    let output = &initial_write["output"];
    let task_count = attempt["tasks"].as_array().unwrap().len();
    let task = serde_json::json!({
        "order": task_count,
        "id": "attempt-1-write-2",
        "kind": "write",
        "role": "author",
        "work_item_id": "work-1",
        "attempt_id": "attempt-1",
        "workspace_access": {
            "reads": [],
            "writes": [
                {
                    "id": output["workspace_id"],
                    "path": output["workspace_path"]
                }
            ]
        },
        "artifact_area": {
            "path": ".fluent/work/artifacts/work-1/attempt-1/attempt-1-write-2"
        },
        "input_artifacts": input_artifacts
    });
    let task_path = work_task_record_path(main_dir, "work-1", "attempt-1", "attempt-1-write-2");
    write_json_value(&task_path, &task);

    let attempt_path = main_dir
        .join(".fluent/work/attempts")
        .join("work-1")
        .join("attempt-1.json");
    let mut attempt_record = read_json_value(&attempt_path);
    attempt_record["status"] = serde_json::Value::String("planned".to_string());
    attempt_record["review_state"] = serde_json::Value::String("failed".to_string());
    write_json_value(&attempt_path, &attempt_record);
}

// -------------------------------------------------------------------------
// Cleanup
// -------------------------------------------------------------------------

fn cleanup_terminal_attempt(
    main: &Path,
    item: &str,
    attempt: &str,
    status: &str,
    target: Option<&str>,
) -> (PathBuf, String) {
    fluent_cmd()
        .current_dir(main)
        .args(["attempt", "create", item, attempt])
        .assert()
        .success();
    let attempt_path = main.join(format!(".fluent/work/attempts/{item}/{attempt}.json"));
    let task_id = format!("{attempt}-write-1");
    let task_path = main.join(format!(
        ".fluent/work/tasks/{item}/{attempt}/{task_id}.json"
    ));
    let mut record = read_json_path(&attempt_path);
    record["status"] = serde_json::json!(status);
    write_json_path(&attempt_path, &record);
    let mut task = read_json_path(&task_path);
    task["status"] = serde_json::json!(if target.is_some() { "complete" } else { status });
    let workspace = task["workspace_access"]["writes"][0]["path"]
        .as_str()
        .unwrap()
        .to_string();
    if let Some(target) = target {
        task["output"] = serde_json::json!({
            "workspace_id": "candidate", "workspace_path": workspace,
            "source_branch": target, "commit": git_head(main)
        });
    }
    write_json_path(&task_path, &task);
    (
        main.join(workspace),
        format!("work/{item}/{attempt}/{task_id}"),
    )
}

#[test]
fn cleanup_retains_unmerged_source_across_attempts() {
    let tmp = TempDir::new().unwrap();
    let main = setup_git_project(&tmp);
    let bin = run_plain_attempt(&main, &tmp, "cleanup-landed-first");
    land_work_1(&main, &bin, true);
    let store = WorkModelStore::new(&main);
    let landed = store.read_work_item("work-1").unwrap();
    assert_eq!(
        landed.merge_candidates[0].merge_state.status,
        fluent::work_model::MergeCandidateMergeStatus::Merged
    );
    assert!(landed.attempts[0].learning.as_ref().unwrap().is_succeeded());
    let first_attempt = main.join(".fluent/work/attempts/work-1/attempt-1.json");
    let first_artifacts = main.join(".fluent/work/artifacts/work-1/attempt-1");
    let first_candidate =
        main.join(".fluent/work/merge-candidates/work-1/attempt-1-merge-candidate.json");
    assert!(first_attempt.exists() && first_artifacts.exists() && first_candidate.exists());

    let (second_path, second_branch) =
        cleanup_terminal_attempt(&main, "work-1", "attempt-2", "failed", Some("main"));
    git::run(
        &main,
        &[
            "worktree",
            "add",
            second_path.to_str().unwrap(),
            "-b",
            &second_branch,
            "HEAD",
        ],
        "create second cleanup candidate",
    )
    .unwrap();
    fs::write(second_path.join("pending.txt"), "unmerged source").unwrap();
    git::run(
        &second_path,
        &["add", "pending.txt"],
        "stage pending source",
    )
    .unwrap();
    git::run(
        &second_path,
        &["commit", "-m", "Add pending source"],
        "commit pending source",
    )
    .unwrap();
    for args in [vec!["cleanup"], vec!["cleanup", "--apply"]] {
        fluent_cmd()
            .current_dir(&main)
            .args(args)
            .assert()
            .success()
            .stdout(predicate::str::contains("retained Work Item work-1"))
            .stdout(predicate::str::contains(&second_branch))
            .stdout(predicate::str::contains("not integrated"));
        assert!(first_attempt.exists() && first_artifacts.exists() && first_candidate.exists());
        assert!(second_path.join("pending.txt").exists());
        assert!(
            main.join(".fluent/work/attempts/work-1/attempt-2.json")
                .exists()
        );
        assert_eq!(
            store.read_work_item("work-1").unwrap().merge_candidates[0]
                .merge_state
                .status,
            fluent::work_model::MergeCandidateMergeStatus::Merged
        );
    }
}

#[test]
fn cleanup_preserves_earlier_integrated_source_when_later_source_is_unmerged() {
    let tmp = TempDir::new().unwrap();
    let main = setup_git_project(&tmp);
    fluent_cmd()
        .current_dir(&main)
        .args([
            "work-item",
            "create",
            "work-whole",
            "--title",
            "Whole cleanup",
        ])
        .assert()
        .success();
    let (first_path, first_branch) =
        cleanup_terminal_attempt(&main, "work-whole", "attempt-1", "failed", Some("main"));
    let (second_path, second_branch) =
        cleanup_terminal_attempt(&main, "work-whole", "attempt-2", "failed", Some("main"));
    for (path, branch) in [(&first_path, &first_branch), (&second_path, &second_branch)] {
        git::run(
            &main,
            &[
                "worktree",
                "add",
                path.to_str().unwrap(),
                "-b",
                branch,
                "HEAD",
            ],
            "create cleanup candidate",
        )
        .unwrap();
    }
    fs::write(second_path.join("pending.txt"), "unmerged source").unwrap();
    git::run(
        &second_path,
        &["add", "pending.txt"],
        "stage pending source",
    )
    .unwrap();
    git::run(
        &second_path,
        &["commit", "-m", "Add pending source"],
        "commit pending source",
    )
    .unwrap();
    let artifact = main.join(".fluent/work/artifacts/work-whole/attempt-1/keep.txt");
    fs::create_dir_all(artifact.parent().unwrap()).unwrap();
    fs::write(&artifact, "keep first Attempt artifacts").unwrap();
    let first_attempt = main.join(".fluent/work/attempts/work-whole/attempt-1.json");
    let second_attempt = main.join(".fluent/work/attempts/work-whole/attempt-2.json");
    let first_task = main.join(".fluent/work/tasks/work-whole/attempt-1/attempt-1-write-1.json");
    let second_task = main.join(".fluent/work/tasks/work-whole/attempt-2/attempt-2-write-1.json");

    for args in [vec!["cleanup"], vec!["cleanup", "--apply"]] {
        fluent_cmd()
            .current_dir(&main)
            .args(args)
            .assert()
            .success()
            .stdout(predicate::str::contains("retained Work Item work-whole"))
            .stdout(predicate::str::contains(&second_branch))
            .stdout(predicate::str::contains("not integrated"));
        for (path, branch) in [(&first_path, &first_branch), (&second_path, &second_branch)] {
            assert!(path.exists(), "worktree {} was removed", path.display());
            assert!(
                git::run_raw(
                    &main,
                    &[
                        "show-ref",
                        "--verify",
                        "--quiet",
                        &format!("refs/heads/{branch}")
                    ],
                )
                .unwrap()
                .status
                .success(),
                "branch {branch} was removed"
            );
            assert!(
                git::run_stdout(
                    &main,
                    &["worktree", "list", "--porcelain"],
                    "list worktrees"
                )
                .unwrap()
                .contains(&format!(
                    "worktree {}",
                    path.canonicalize().unwrap().display()
                )),
                "worktree {} was unregistered",
                path.display()
            );
        }
        for record in [
            &first_attempt,
            &second_attempt,
            &first_task,
            &second_task,
            &artifact,
        ] {
            assert!(record.exists(), "record {} was removed", record.display());
        }
        assert!(main.join(".fluent/work/items/work-whole.json").exists());
    }
}

#[test]
fn cleanup_retains_pending_file_changes() {
    for mode in ["staged", "unstaged", "untracked"] {
        let tmp = TempDir::new().unwrap();
        let main = setup_git_project(&tmp);
        fluent_cmd()
            .current_dir(&main)
            .args([
                "work-item",
                "create",
                "work-edits",
                "--title",
                "Edits cleanup",
            ])
            .assert()
            .success();
        let (path, branch) =
            cleanup_terminal_attempt(&main, "work-edits", "attempt-1", "failed", Some("main"));
        git::run(
            &main,
            &[
                "worktree",
                "add",
                path.to_str().unwrap(),
                "-b",
                &branch,
                "HEAD",
            ],
            "create cleanup candidate",
        )
        .unwrap();
        if mode != "untracked" {
            fs::write(path.join("edits.txt"), "base").unwrap();
            git::run(&path, &["add", "edits.txt"], "stage base").unwrap();
            git::run(&path, &["commit", "-m", "Add base"], "commit base").unwrap();
            git::run(&main, &["merge", "--ff-only", &branch], "integrate base").unwrap();
        }
        fs::write(path.join("edits.txt"), "pending").unwrap();
        if mode == "staged" {
            git::run(&path, &["add", "edits.txt"], "stage edit").unwrap();
        }
        for args in [vec!["cleanup"], vec!["cleanup", "--apply"]] {
            fluent_cmd()
                .current_dir(&main)
                .args(args)
                .assert()
                .success()
                .stdout(predicate::str::contains("retained Work Item work-edits"))
                .stdout(predicate::str::contains(
                    path.file_name().unwrap().to_str().unwrap(),
                ))
                .stdout(predicate::str::contains("pending file changes"));
        }
        assert_eq!(
            fs::read_to_string(path.join("edits.txt")).unwrap(),
            "pending"
        );
        assert!(main.join(".fluent/work/items/work-edits.json").exists());
    }
}

#[test]
fn cleanup_retains_unverifiable_source() {
    for mode in [
        "missing-target",
        "unresolved-target",
        "conflicting-target",
        "unregistered",
        "detached",
        "failed-probe",
    ] {
        let tmp = TempDir::new().unwrap();
        let main = setup_git_project(&tmp);
        fluent_cmd()
            .current_dir(&main)
            .args([
                "work-item",
                "create",
                "work-unknown",
                "--title",
                "Unknown source",
            ])
            .assert()
            .success();
        let target = match mode {
            "missing-target" => None,
            "unresolved-target" => Some("absent-target"),
            _ => Some("main"),
        };
        let (path, branch) =
            cleanup_terminal_attempt(&main, "work-unknown", "attempt-1", "failed", target);
        if mode == "unregistered" {
            fs::create_dir_all(&path).unwrap();
            fs::write(path.join("source.txt"), "keep").unwrap();
        } else {
            git::run(
                &main,
                &[
                    "worktree",
                    "add",
                    path.to_str().unwrap(),
                    "-b",
                    &branch,
                    "HEAD",
                ],
                "create cleanup candidate",
            )
            .unwrap();
            if mode == "conflicting-target" {
                let first_task =
                    main.join(".fluent/work/tasks/work-unknown/attempt-1/attempt-1-write-1.json");
                let second_task =
                    main.join(".fluent/work/tasks/work-unknown/attempt-1/attempt-1-write-2.json");
                let mut followup = read_json_path(&first_task);
                followup["id"] = serde_json::json!("attempt-1-write-2");
                followup["order"] = serde_json::json!(1);
                followup["output"]["source_branch"] = serde_json::json!("other-target");
                write_json_path(&second_task, &followup);
                let candidate_path =
                    main.join(".fluent/work/merge-candidates/work-unknown/candidate-1.json");
                fs::create_dir_all(candidate_path.parent().unwrap()).unwrap();
                write_json_path(
                    &candidate_path,
                    &serde_json::json!({
                        "id": "candidate-1",
                        "attempt_id": "attempt-1",
                        "source_workspace": {"id": "candidate", "path": path.strip_prefix(&main).unwrap()},
                        "target_workspace": {"id": "target", "path": "."},
                        "source_branch": "other-target",
                        "target_branch": "other-target",
                        "candidate_commit": git_head(&main),
                        "review_state": "failed",
                        "merge_state": {"status": "failed"}
                    }),
                );
            }
            if mode == "detached" {
                fs::write(path.join("source.txt"), "detached source").unwrap();
                git::run(&path, &["add", "source.txt"], "stage detached source").unwrap();
                git::run(
                    &path,
                    &["commit", "-m", "Add detached source"],
                    "commit detached source",
                )
                .unwrap();
                git::run(&path, &["checkout", "--detach"], "detach candidate HEAD").unwrap();
                git::run(&main, &["branch", "-D", &branch], "remove candidate branch").unwrap();
            } else if mode == "failed-probe" {
                fs::write(path.join(".git"), "gitdir: /missing/cleanup/gitdir\n").unwrap();
            }
        }
        let reason = match mode {
            "missing-target" => "missing or conflicting target branch identity",
            "unresolved-target" => "resolve cleanup target branch",
            "conflicting-target" => "missing or conflicting target branch identity",
            "unregistered" => "not a registered worktree",
            "detached" => "not integrated",
            "failed-probe" => "check candidate ownership",
            _ => unreachable!(),
        };
        for args in [vec!["cleanup"], vec!["cleanup", "--apply"]] {
            fluent_cmd()
                .current_dir(&main)
                .args(args)
                .assert()
                .success()
                .stdout(predicate::str::contains("retained Work Item work-unknown"))
                .stdout(predicate::str::contains(
                    path.file_name().unwrap().to_str().unwrap(),
                ))
                .stdout(predicate::str::contains(reason));
        }
        assert!(main.join(".fluent/work/items/work-unknown.json").exists());
        assert!(path.exists());
    }
}

#[test]
fn cleanup_retains_one_item_when_its_git_probe_fails() {
    for probe in ["branch", "worktree-list"] {
        let tmp = TempDir::new().unwrap();
        let main = setup_git_project(&tmp);
        for id in ["work-bad-probe", "work-safe-probe"] {
            fluent_cmd()
                .current_dir(&main)
                .args(["work-item", "create", id, "--title", id])
                .assert()
                .success();
        }
        let (path, branch) =
            cleanup_terminal_attempt(&main, "work-bad-probe", "attempt-1", "failed", Some("main"));
        cleanup_terminal_attempt(
            &main,
            "work-safe-probe",
            "attempt-1",
            "failed",
            Some("main"),
        );
        git::run(
            &main,
            &[
                "worktree",
                "add",
                path.to_str().unwrap(),
                "-b",
                &branch,
                "HEAD",
            ],
            "create probed Work source",
        )
        .unwrap();
        let fake_bin = tmp.path().join("fake-git");
        let marker = tmp.path().join("probe-failed");
        let script = if probe == "branch" {
            r#"#!/bin/sh
case " $* " in
  *" show-ref --verify --quiet refs/heads/work/work-bad-probe/attempt-1/attempt-1-write-1 "*)
    echo 'injected branch probe failure' >&2
    exit 128 ;;
esac
exec /usr/bin/git "$@"
"#
        } else {
            r#"#!/bin/sh
case " $* " in
  *" worktree list --porcelain "*)
    if [ ! -e "$FLUENT_GIT_PROBE_MARKER" ]; then
      touch "$FLUENT_GIT_PROBE_MARKER"
      echo 'injected worktree probe failure' >&2
      exit 128
    fi ;;
esac
exec /usr/bin/git "$@"
"#
        };
        write_mock_executable(&fake_bin, "git", script);
        let path_env = format!("{}:{}", fake_bin.display(), std::env::var("PATH").unwrap());
        let reason = if probe == "branch" {
            "Failed to check Work branch"
        } else {
            "inspect worktree registrations"
        };
        for args in [vec!["cleanup"], vec!["cleanup", "--apply"]] {
            if marker.exists() {
                fs::remove_file(&marker).unwrap();
            }
            fluent_cmd()
                .current_dir(&main)
                .args(&args)
                .env("PATH", &path_env)
                .env("FLUENT_GIT_PROBE_MARKER", &marker)
                .assert()
                .success()
                .stdout(predicate::str::contains(
                    "retained Work Item work-bad-probe",
                ))
                .stdout(predicate::str::contains(reason))
                .stdout(predicate::str::contains(if probe == "branch" {
                    branch.as_str()
                } else {
                    path.file_name().unwrap().to_str().unwrap()
                }))
                .stdout(predicate::str::contains(if args.len() == 1 {
                    "would clean Work Item work-safe-probe"
                } else {
                    "cleaned Work Item work-safe-probe"
                }));
            assert!(main.join(".fluent/work/items/work-bad-probe.json").exists());
            assert!(path.exists());
            assert!(
                git::run_raw(
                    &main,
                    &[
                        "show-ref",
                        "--verify",
                        "--quiet",
                        &format!("refs/heads/{branch}")
                    ]
                )
                .unwrap()
                .status
                .success()
            );
        }
        assert!(
            !main
                .join(".fluent/work/items/work-safe-probe.json")
                .exists()
        );
    }
}

