    let retained_record = read_json_path(&retained_task);
    let path = main.join(
        retained_record["workspace_access"]["writes"][0]["path"]
            .as_str()
            .unwrap(),
    );
    let branch = "work/work-retained/attempt-1/attempt-1-write-1";
