#[test]
fn cleanup_reports_changed_source_asset() {
    let tmp = TempDir::new().unwrap();
    let main = setup_git_project(&tmp);
    fs::write(main.join("integrated.txt"), "integrated").unwrap();
    git::run(&main, &["add", "integrated.txt"], "stage integrated source").unwrap();
    git::run(
        &main,
        &["commit", "-m", "Add integrated source"],
        "create integrated tip",
    )
    .unwrap();
    fluent_cmd()
        .current_dir(&main)
        .args([
            "work-item",
            "create",
            "work-moving",
            "--title",
            "Moving source",
        ])
        .assert()
        .success();
    let (_, branch) =
        cleanup_terminal_attempt(&main, "work-moving", "attempt-1", "failed", Some("main"));
    git::run(
        &main,
        &["branch", &branch, "HEAD~1"],
        "create integrated Work branch",
    )
    .unwrap();
    let reached = tmp.path().join("assessed");
    let release = tmp.path().join("release");
    let mut command = std::process::Command::new(assert_cmd::cargo::cargo_bin("fluent"));
    command
        .current_dir(&main)
        .args(["cleanup", "--apply"])
        .env("FLUENT_TEST_CLEANUP_ASSESSED_ITEM", "work-moving")
        .env("FLUENT_TEST_CLEANUP_ASSESSED_REACHED", &reached)
        .env("FLUENT_TEST_CLEANUP_ASSESSED_RELEASE", &release)
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    let mut child = OwnedFixtureProcess::spawn(&mut command);
    wait_for_cleanup_barrier(&reached);
    git::run(
        &main,
        &[
            "update-ref",
            &format!("refs/heads/{branch}"),
            &git_head(&main),
        ],
        "advance integrated Work branch",
    )
    .unwrap();
    fs::write(&release, b"continue").unwrap();
    let output = child.wait_with_output().unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(
        stdout.contains("retained Work Item work-moving"),
        "{stdout}"
    );
    assert!(stdout.contains(&branch), "{stdout}");
    assert!(stdout.contains("identity changed"), "{stdout}");
    assert!(main.join(".fluent/work/items/work-moving.json").exists());
}

fn wait_for_cleanup_barrier(reached: &Path) {
    for _ in 0..500 {
        if reached.exists() {
            return;
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
    }
    panic!("cleanup did not reach {}", reached.display());
}

#[test]
fn cleanup_refuses_late_source_changes() {
    for change in ["head", "dirty", "ref"] {
        let tmp = TempDir::new().unwrap();
        let main = setup_git_project(&tmp);
        fluent_cmd()
            .current_dir(&main)
            .args(["work-item", "create", "work-late", "--title", "Late source"])
            .assert()
            .success();
        let (path, branch) =
            cleanup_terminal_attempt(&main, "work-late", "attempt-1", "failed", Some("main"));
        if change == "ref" {
            git::run(&main, &["branch", &branch, "HEAD"], "create Work branch").unwrap();
        } else {
            git::run(
                &main,
                &[
                    "worktree",
                    "add",
                    path.to_str().unwrap(),
                    "-b",
                    &branch,
                    "HEAD",
                ],
                "create Work candidate",
            )
            .unwrap();
        }
        let reached = tmp.path().join("before-remove");
        let release = tmp.path().join("release");
        let mut command = std::process::Command::new(assert_cmd::cargo::cargo_bin("fluent"));
        command
            .current_dir(&main)
            .args(["cleanup", "--apply"])
            .env("FLUENT_TEST_CLEANUP_REMOVE_ITEM", "work-late")
            .env("FLUENT_TEST_CLEANUP_REMOVE_REACHED", &reached)
            .env("FLUENT_TEST_CLEANUP_REMOVE_RELEASE", &release)
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        let mut child = OwnedFixtureProcess::spawn(&mut command);
        wait_for_cleanup_barrier(&reached);
        if change == "ref" {
            let new_tip = git::run_stdout(
                &main,
                &[
                    "commit-tree",
                    "HEAD^{tree}",
                    "-p",
                    "HEAD",
                    "-m",
                    "Advance Work ref",
                ],
                "create late Work commit",
            )
            .unwrap();
            git::run(
                &main,
                &["update-ref", &format!("refs/heads/{branch}"), &new_tip],
                "advance Work ref",
            )
            .unwrap();
        } else {
            fs::write(path.join("late.txt"), "late source").unwrap();
            if change == "head" {
                git::run(&path, &["add", "late.txt"], "stage late source").unwrap();
                git::run(
                    &path,
                    &["commit", "-m", "Add late source"],
                    "advance candidate HEAD",
                )
                .unwrap();
            }
        }
        fs::write(&release, b"continue").unwrap();
        let output = child.wait_with_output().unwrap();
        assert!(
            !output.status.success(),
            "{change}: {}",
            String::from_utf8_lossy(&output.stdout)
        );
        assert!(main.join(".fluent/work/items/work-late.json").exists());
        assert!(
            git::run_raw(
                &main,
                &[
                    "show-ref",
                    "--verify",
                    "--quiet",
                    &format!("refs/heads/{branch}")
                ]
            )
            .unwrap()
            .status
            .success()
        );
        if change != "ref" {
            assert!(path.join("late.txt").exists());
        }
    }
}

#[test]
fn cleanup_rechecks_source_before_removal() {
    for change in ["file edit", "branch advance"] {
        let tmp = TempDir::new().unwrap();
        let main = setup_git_project(&tmp);
        fluent_cmd()
            .current_dir(&main)
            .args([
                "work-item",
                "create",
                "work-race",
                "--title",
                "Race cleanup",
            ])
            .assert()
            .success();
        let (path, branch) =
            cleanup_terminal_attempt(&main, "work-race", "attempt-1", "failed", Some("main"));
        git::run(
            &main,
            &[
                "worktree",
                "add",
                path.to_str().unwrap(),
                "-b",
                &branch,
                "HEAD",
            ],
            "create cleanup candidate",
        )
        .unwrap();
        let reached = tmp.path().join("selected");
        let release = tmp.path().join("release");
        let mut command = std::process::Command::new(assert_cmd::cargo::cargo_bin("fluent"));
        command
            .current_dir(&main)
            .args(["cleanup", "--apply"])
            .env("FLUENT_TEST_CLEANUP_SELECTED", &reached)
            .env("FLUENT_TEST_CLEANUP_RELEASE", &release)
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        let mut child = OwnedFixtureProcess::spawn(&mut command);
        for _ in 0..500 {
            if reached.exists() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(reached.exists());
        fs::write(path.join("late.txt"), "late edit").unwrap();
        if change == "branch advance" {
            git::run(&path, &["add", "late.txt"], "stage late edit").unwrap();
            git::run(
                &path,
                &["commit", "-m", "Add late edit"],
                "advance cleanup branch",
            )
            .unwrap();
        }
        fs::write(&release, b"continue").unwrap();
        let output = child.wait_with_output().unwrap();
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
        assert!(String::from_utf8_lossy(&output.stdout).contains("retained Work Item work-race"));
        assert!(path.join("late.txt").exists());
        assert!(main.join(".fluent/work/items/work-race.json").exists());
        assert!(
            git::run_raw(
                &main,
                &[
                    "show-ref",
                    "--verify",
                    "--quiet",
                    &format!("refs/heads/{branch}")
                ]
            )
            .unwrap()
            .status
            .success()
        );
    }
}

#[test]
fn cleanup_work_items_dry_run_and_apply_manage_state_worktree_and_branch() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["work-item", "create", "work-1", "--title", "Cleanup work"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "work-item",
            "create",
            "work-active",
            "--title",
            "Active work",
        ])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-active", "attempt-1"])
        .assert()
        .success();

    let item_path = main_dir.join(".fluent/work/items/work-1.json");
    let attempt_path = main_dir.join(".fluent/work/attempts/work-1/attempt-1.json");
    let task_path = main_dir.join(".fluent/work/tasks/work-1/attempt-1/attempt-1-write-1.json");
    let mut attempt = read_json_path(&attempt_path);
    attempt["status"] = serde_json::Value::String("complete".to_string());
    write_json_path(&attempt_path, &attempt);
    let mut task = read_json_path(&task_path);
    task["status"] = serde_json::Value::String("complete".to_string());
    task["artifact_area"] = serde_json::json!({
        "path": ".fluent/work/artifacts/work-1/attempt-1/attempt-1-write-1"
    });
    task["output"] = serde_json::json!({
        "workspace_id": "candidate",
        "workspace_path": "../work-6-work-1-attempt-1",
        "source_branch": "main",
        "commit": git_head(&main_dir)
    });
    write_json_path(&task_path, &task);

    let artifact_dir = main_dir.join(".fluent/work/artifacts/work-1/attempt-1/attempt-1-write-1");
    let artifact_parent = main_dir.join(".fluent/work/artifacts/work-1/attempt-1");
    fs::create_dir_all(&artifact_dir).unwrap();
    fs::write(artifact_dir.join("result.md"), "artifact").unwrap();

    let worktree_dir = main_dir.join("../work-6-work-1-attempt-1");
    let branch_name = "work/work-1/attempt-1/attempt-1-write-1";
    git::run(
        &main_dir,
        &[
            "worktree",
            "add",
            worktree_dir.to_str().unwrap(),
            "-b",
            branch_name,
            "HEAD",
        ],
        "create worktree",
    )
    .unwrap();

    let active_item_path = main_dir.join(".fluent/work/items/work-active.json");
    let active_attempt_path = main_dir.join(".fluent/work/attempts/work-active/attempt-1.json");
    let active_task_path =
        main_dir.join(".fluent/work/tasks/work-active/attempt-1/attempt-1-write-1.json");
    let mut active_attempt = read_json_path(&active_attempt_path);
    active_attempt["status"] = serde_json::Value::String("executing".to_string());
    write_json_path(&active_attempt_path, &active_attempt);
    let mut active_task = read_json_path(&active_task_path);
    active_task["status"] = serde_json::Value::String("executing".to_string());
    active_task["artifact_area"] = serde_json::json!({
        "path": ".fluent/work/artifacts/work-active/attempt-1/attempt-1-active"
    });
    write_json_path(&active_task_path, &active_task);

    let active_artifact_dir =
        main_dir.join(".fluent/work/artifacts/work-active/attempt-1/attempt-1-active");
    fs::create_dir_all(&active_artifact_dir).unwrap();
    fs::write(active_artifact_dir.join("result.md"), "active artifact").unwrap();

    let active_worktree_dir = main_dir.join("../work-11-work-active-attempt-1");
    let active_branch_name = "work/work-active/attempt-1/attempt-1-write-1";
    git::run(
        &main_dir,
        &[
            "worktree",
            "add",
            active_worktree_dir.to_str().unwrap(),
            "-b",
            active_branch_name,
            "HEAD",
        ],
        "create active worktree",
    )
    .unwrap();

    fluent_cmd()
        .current_dir(&main_dir)
        .arg("cleanup")
        .assert()
        .success()
        .stdout(predicate::str::contains("would clean Work Item work-1"))
        .stdout(predicate::str::contains("would remove registered worktree"))
        .stdout(predicate::str::contains("would remove Work branch"))
        .stdout(predicate::str::contains("would remove Work artifact"))
        .stdout(predicate::str::contains("work-active").not());

    assert!(item_path.exists());
    assert!(worktree_dir.is_dir());
    assert!(artifact_dir.is_dir());
    assert!(artifact_parent.is_dir());
    assert!(active_item_path.exists());
    assert!(active_worktree_dir.is_dir());
    assert!(active_artifact_dir.is_dir());

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["cleanup", "--apply"])
        .assert()
        .success()
        .stdout(predicate::str::contains("cleaned Work Item work-1"))
        .stdout(predicate::str::contains("removed registered worktree"))
        .stdout(predicate::str::contains("removed Work branch"));

    assert!(!item_path.exists());
    assert!(!attempt_path.exists());
    assert!(!task_path.exists());
    assert!(active_item_path.exists());
    assert!(active_attempt_path.exists());
    assert!(active_task_path.exists());
    assert!(!worktree_dir.exists());
    assert!(!artifact_dir.exists());
    assert!(!artifact_parent.exists());
    assert!(active_worktree_dir.is_dir());
    assert!(active_artifact_dir.is_dir());

    let branch_check = git::run_raw(
        &main_dir,
        &[
            "show-ref",
            "--verify",
            "--quiet",
            &format!("refs/heads/{branch_name}"),
        ],
    )
    .unwrap();
    assert!(!branch_check.status.success());

    let active_branch_check = git::run_raw(
        &main_dir,
        &[
            "show-ref",
            "--verify",
            "--quiet",
            &format!("refs/heads/{active_branch_name}"),
        ],
    )
    .unwrap();
    assert!(active_branch_check.status.success());

    git::run(
        &main_dir,
        &[
            "worktree",
            "remove",
            "--force",
            active_worktree_dir.to_str().unwrap(),
        ],
        "remove active worktree",
    )
    .unwrap();
}

#[test]
fn cleanup_work_items_reports_and_removes_orphan_artifact_roots() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "work-item",
            "create",
            "work-active",
            "--title",
            "Active work",
        ])
        .assert()
        .success();

    let artifacts_dir = main_dir.join(".fluent/work/artifacts");
    let orphan_artifact_root = artifacts_dir.join("work-orphan");
    let active_artifact_root = artifacts_dir.join("work-active");
    let file_entry = artifacts_dir.join("not-a-directory");
    fs::create_dir_all(orphan_artifact_root.join("attempt-1/task-1")).unwrap();
    fs::write(
        orphan_artifact_root.join("attempt-1/task-1/result.md"),
        "orphan artifact",
    )
    .unwrap();
    fs::create_dir_all(active_artifact_root.join("attempt-1/task-1")).unwrap();
    fs::write(
        active_artifact_root.join("attempt-1/task-1/result.md"),
        "active artifact",
    )
    .unwrap();
    fs::write(&file_entry, "keep file entries").unwrap();

    fluent_cmd()
        .current_dir(&main_dir)
        .arg("cleanup")
        .assert()
        .success()
        .stdout(predicate::str::contains(
            "would remove orphan Work artifact root",
        ))
        .stdout(predicate::str::contains("work-orphan"))
        .stdout(predicate::str::contains("work-active").not())
        .stdout(predicate::str::contains("not-a-directory").not());

    assert!(orphan_artifact_root.is_dir());
    assert!(active_artifact_root.is_dir());
    assert!(file_entry.is_file());

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["cleanup", "--apply"])
        .assert()
        .success()
        .stdout(predicate::str::contains(
            "removed orphan Work artifact root",
        ))
        .stdout(predicate::str::contains("work-orphan"))
        .stdout(predicate::str::contains("work-active").not())
        .stdout(predicate::str::contains("not-a-directory").not());

    assert!(!orphan_artifact_root.exists());
    assert!(active_artifact_root.is_dir());
    assert!(file_entry.is_file());
}

#[test]
