#[test]
fn cleanup_apply_fails_closed_for_a_missing_locked_registration() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "work-item",
            "create",
            "work-locked",
            "--title",
            "Locked cleanup work",
        ])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-locked", "attempt-1"])
        .assert()
        .success();
    let attempt_path = main_dir.join(".fluent/work/attempts/work-locked/attempt-1.json");
    let task_path =
        main_dir.join(".fluent/work/tasks/work-locked/attempt-1/attempt-1-write-1.json");
    let mut attempt = read_json_path(&attempt_path);
    attempt["status"] = serde_json::Value::String("failed".to_string());
    write_json_path(&attempt_path, &attempt);
    let mut task = read_json_path(&task_path);
    task["status"] = serde_json::Value::String("complete".to_string());
    let workspace_path = task["workspace_access"]["writes"][0]["path"]
        .as_str()
        .unwrap()
        .to_string();
    task["output"] = serde_json::json!({
        "workspace_id": "candidate", "workspace_path": workspace_path,
        "source_branch": "main", "commit": git_head(&main_dir)
    });
    write_json_path(&task_path, &task);
    let workspace = main_dir.join(&workspace_path);
    let workspace_text = workspace.to_string_lossy().into_owned();
    git::run(
        &main_dir,
        &["worktree", "add", "--detach", &workspace_text, "HEAD"],
        "register locked CLI cleanup worktree",
    )
    .unwrap();
    git::run(
        &main_dir,
        &["worktree", "lock", "--reason", "test", &workspace_text],
        "lock CLI cleanup worktree",
    )
    .unwrap();
    fs::remove_dir_all(&workspace).unwrap();

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["cleanup", "--apply"])
        .assert()
        .failure()
        .stderr(predicate::str::contains("remove registered worktree"));

    assert!(
        main_dir
            .join(".fluent/work/items/work-locked.json")
            .exists()
    );
    let registrations = git::run_stdout(
        &main_dir,
        &["worktree", "list", "--porcelain"],
        "inspect retained locked registration",
    )
    .unwrap();
    assert!(registrations.contains(workspace.file_name().unwrap().to_str().unwrap()));
}

#[test]
fn cleanup_retains_unmerged_head_in_missing_registered_worktree() {
    let tmp = TempDir::new().unwrap();
    let main = setup_git_project(&tmp);
    fluent_cmd()
        .current_dir(&main)
        .args([
            "work-item",
            "create",
            "work-missing-head",
            "--title",
            "Missing source",
        ])
        .assert()
        .success();
    let (path, _branch) = cleanup_terminal_attempt(
        &main,
        "work-missing-head",
        "attempt-1",
        "failed",
        Some("main"),
    );
    git::run(
        &main,
        &[
            "worktree",
            "add",
            "--detach",
            path.to_str().unwrap(),
            "HEAD",
        ],
        "create detached cleanup candidate",
    )
    .unwrap();
    fs::write(path.join("source.txt"), "unmerged source").unwrap();
    git::run(&path, &["add", "source.txt"], "stage detached source").unwrap();
    git::run(
        &path,
        &["commit", "-m", "Add detached source"],
        "commit detached source",
    )
    .unwrap();
    let source_head = git::run_stdout(&path, &["rev-parse", "HEAD"], "read detached HEAD").unwrap();
    fs::remove_dir_all(&path).unwrap();
    let artifact = main.join(".fluent/work/artifacts/work-missing-head/attempt-1/keep.txt");
    fs::create_dir_all(artifact.parent().unwrap()).unwrap();
    fs::write(&artifact, "keep source evidence").unwrap();
    let item = main.join(".fluent/work/items/work-missing-head.json");
    let attempt = main.join(".fluent/work/attempts/work-missing-head/attempt-1.json");
    let task = main.join(".fluent/work/tasks/work-missing-head/attempt-1/attempt-1-write-1.json");

    for args in [vec!["cleanup"], vec!["cleanup", "--apply"]] {
        fluent_cmd()
            .current_dir(&main)
            .args(args)
            .assert()
            .success()
            .stdout(predicate::str::contains(
                "retained Work Item work-missing-head",
            ))
            .stdout(predicate::str::contains(
                path.file_name().unwrap().to_str().unwrap(),
            ))
            .stdout(predicate::str::contains("not integrated"));
        for record in [&item, &attempt, &task, &artifact] {
            assert!(record.exists(), "record {} was removed", record.display());
        }
        assert!(!path.exists());
        let registrations = git::run_stdout(
            &main,
            &["worktree", "list", "--porcelain"],
            "inspect retained registration",
        )
        .unwrap();
        assert!(registrations.contains(path.file_name().unwrap().to_str().unwrap()));
        assert!(registrations.contains(source_head.trim()));
    }
}

#[test]
fn cleanup_work_items_selects_failed_terminal_and_skips_pending_merge_candidate() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "work-item",
            "create",
            "work-failed",
            "--title",
            "Failed work",
        ])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-failed", "attempt-1"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "work-item",
            "create",
            "work-pending-merge",
            "--title",
            "Pending merge work",
        ])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-pending-merge", "attempt-1"])
        .assert()
        .success();

    let failed_item_path = main_dir.join(".fluent/work/items/work-failed.json");
    let failed_attempt_path = main_dir.join(".fluent/work/attempts/work-failed/attempt-1.json");
    let failed_task_path =
        main_dir.join(".fluent/work/tasks/work-failed/attempt-1/attempt-1-write-1.json");
    let mut failed_attempt = read_json_path(&failed_attempt_path);
    failed_attempt["status"] = serde_json::Value::String("failed".to_string());
    write_json_path(&failed_attempt_path, &failed_attempt);
    let mut failed_task = read_json_path(&failed_task_path);
    failed_task["status"] = serde_json::Value::String("failed".to_string());
    write_json_path(&failed_task_path, &failed_task);

    let pending_item_path = main_dir.join(".fluent/work/items/work-pending-merge.json");
    let pending_workspace = "../work-18-work-pending-merge-attempt-1";
    let head = git_head(&main_dir);
    let pending_attempt_path =
        main_dir.join(".fluent/work/attempts/work-pending-merge/attempt-1.json");
    let pending_task_path =
        main_dir.join(".fluent/work/tasks/work-pending-merge/attempt-1/attempt-1-write-1.json");
    let mut pending_attempt = read_json_path(&pending_attempt_path);
    pending_attempt["status"] = serde_json::Value::String("complete".to_string());
    pending_attempt["review_state"] = serde_json::Value::String("passed".to_string());
    write_json_path(&pending_attempt_path, &pending_attempt);
    let mut pending_task = read_json_path(&pending_task_path);
    pending_task["status"] = serde_json::Value::String("complete".to_string());
    pending_task["output"] = serde_json::json!({
        "workspace_id": "candidate",
        "workspace_path": pending_workspace,
        "source_branch": "main",
        "commit": head
    });
    write_json_path(&pending_task_path, &pending_task);
    let pending_candidate_path =
        main_dir.join(".fluent/work/merge-candidates/work-pending-merge/candidate-1.json");
    fs::create_dir_all(pending_candidate_path.parent().unwrap()).unwrap();
    write_json_path(
        &pending_candidate_path,
        &serde_json::json!({
            "id": "candidate-1",
            "attempt_id": "attempt-1",
            "source_workspace": {
                "id": "candidate",
                "path": pending_workspace
            },
            "target_workspace": {
                "id": "target",
                "path": "."
            },
            "source_branch": "main",
            "target_branch": "main",
            "candidate_commit": head,
            "review_state": "pending",
            "merge_state": {
                "status": "pending"
            }
        }),
    );

    fluent_cmd()
        .current_dir(&main_dir)
        .arg("cleanup")
        .assert()
        .success()
        .stdout(predicate::str::contains(
            "would clean Work Item work-failed",
        ))
        .stdout(predicate::str::contains("work-pending-merge").not());

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["cleanup", "--apply"])
        .assert()
        .success()
        .stdout(predicate::str::contains("cleaned Work Item work-failed"))
        .stdout(predicate::str::contains("work-pending-merge").not());

    assert!(!failed_item_path.exists());
    assert!(!failed_attempt_path.exists());
    assert!(!failed_task_path.exists());
    assert!(pending_item_path.exists());
    assert!(pending_attempt_path.exists());
    assert!(pending_task_path.exists());
    assert!(pending_candidate_path.exists());
}

