// =========================================================================
// Queue command matrix (behavior-scoped)
// =========================================================================

fn latest_dispatch_status(project_root: &Path, work_item_id: &str) -> String {
    let value = read_json_path(
        &project_root
            .join(".fluent/work/queue")
            .join(format!("{work_item_id}.json")),
    );
    value["dispatches"]
        .as_array()
        .and_then(|d| d.last())
        .and_then(|d| d["status"].as_str())
        .unwrap_or("")
        .to_string()
}

fn dispatch_count(project_root: &Path, work_item_id: &str) -> usize {
    let value = read_json_path(
        &project_root
            .join(".fluent/work/queue")
            .join(format!("{work_item_id}.json")),
    );
    value["dispatches"].as_array().map(|d| d.len()).unwrap_or(0)
}

fn run_scheduler_until_dispatch_status(
    project_root: &Path,
    work_item_id: &str,
    bin_dir: &Path,
    expected_status: &str,
) -> std::process::Output {
    let mut scheduler = {
        let mut command = std::process::Command::new(assert_cmd::cargo::cargo_bin("fluent"));
        command
            .current_dir(project_root)
            .env("PATH", mock_path(bin_dir))
            .env("FLUENT_NO_UPDATE_CHECK", "1")
            .env("FLUENT_TEST_HOST_SANDBOX_PREFLIGHT", "pass")
            .env("FLUENT_TEST_HERMETIC_PROVIDERS", "1")
            .env("FLUENT_MAX_TASK_RETRIES", "0")
            .env_remove("FLUENT_TASK_KIND")
            .args(["scheduler", "run", "--poll-seconds", "1"])
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        OwnedFixtureProcess::spawn(&mut command)
    };
    let reached_terminal = poll_until(std::time::Duration::from_secs(60), || {
        matches!(
            latest_dispatch_status(project_root, work_item_id).as_str(),
            "candidate-ready" | "failed" | "needs-user" | "canceled" | "blocked"
        )
    });
    let actual_status = latest_dispatch_status(project_root, work_item_id);
    send_signal(scheduler.id(), "TERM");
    let output = scheduler.wait_with_output().unwrap();
    assert!(
        reached_terminal,
        "scheduler did not reach a terminal status within 60 seconds; status={actual_status}; stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(
        output.status.success(),
        "scheduler did not drain cleanly: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(
        actual_status,
        expected_status,
        "scheduler reached the wrong terminal status: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    output
}

fn write_scheduler_claude(bin_dir: &Path, script: &str) {
    write_mock_claude(bin_dir, script);
    fs::remove_file(bin_dir.join("sandbox-exec")).unwrap();
}

fn learner_only_success_mock_script() -> &'static str {
    r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
if ! printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  exit 86
fi
DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
mkdir -p "$(dirname "$DRAFT")"
printf '%s\n' '{"learning_summary":"learned","follow_ups":[]}' > "$DRAFT"
exit 0
"##
}

#[test]
fn scheduler_resume_retries_only_a_failed_learner() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let bin_dir = tmp.path().join("bin-scheduler-learner-retry");
    write_scheduler_claude(&bin_dir, &learner_failing_mock_script());

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["work-item", "create", "work-1", "--title", "Learner"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["queue", "add", "work-1"])
        .assert()
        .success();

    let first_scheduler =
        run_scheduler_until_dispatch_status(&main_dir, "work-1", &bin_dir, "blocked");
    let before = read_work_show_json(&main_dir, "work-1");
    let tasks_before = before["attempts"][0]["tasks"].as_array().unwrap().len();
    let commit_before = before["merge_candidates"][0]["candidate_commit"].clone();
    assert_eq!(
        before["attempts"][0]["learning"]["status"],
        "failed",
        "first scheduler stopped before the expected Learner failure: model={before}; stdout={} stderr={}",
        String::from_utf8_lossy(&first_scheduler.stdout),
        String::from_utf8_lossy(&first_scheduler.stderr)
    );

    write_scheduler_claude(&bin_dir, learner_only_success_mock_script());
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["queue", "resume", "work-1", "--attempt", "attempt-1"])
        .assert()
        .success();
    run_scheduler_until_dispatch_status(&main_dir, "work-1", &bin_dir, "candidate-ready");

    let after = read_work_show_json(&main_dir, "work-1");
    assert_eq!(
        after["attempts"][0]["tasks"].as_array().unwrap().len(),
        tasks_before,
        "the scheduler retry must not add Writer, Tester, or reviewer Tasks"
    );
    assert_eq!(
        after["merge_candidates"][0]["candidate_commit"], commit_before,
        "the scheduler retry must preserve the tested candidate"
    );
    assert_eq!(after["attempts"][0]["learning"]["status"], "succeeded");
    assert_eq!(after["attempts"][0]["learning"]["runs"], 2);

    let ledger = read_json_path(&queue_ledger_path(&main_dir, "work-1"));
    let dispatches = ledger["dispatches"].as_array().unwrap();
    assert_eq!(dispatches.len(), 2);
    assert_eq!(dispatches[0]["status"], "blocked");
    assert_eq!(dispatches[1]["status"], "candidate-ready");
    assert_eq!(dispatches[1]["bound_attempt_id"], "attempt-1");
    assert_eq!(dispatches[1]["resume_of_dispatch_id"], "dispatch-1");
}

fn learner_terminal_history_fixture(tmp: &TempDir) -> (PathBuf, String, PathBuf, Vec<u8>) {
    learner_terminal_history_fixture_with_mode(tmp, false)
}

fn learner_terminal_history_fixture_with_mode(
    tmp: &TempDir,
    no_expertise: bool,
) -> (PathBuf, String, PathBuf, Vec<u8>) {
    use fluent::work_model::*;

    let fixture = writer_recovery_fixture_with_authority(tmp, false);
    let store = WorkModelStore::new(&fixture.project);
    store
        .mutate_work_item(&fixture.work, |item| {
            let attempt = &mut item.attempts[0];
            // This fixture's synthetic behavior has no canonical Tester command.
            attempt
                .writer_completion_contract
                .as_mut()
                .unwrap()
                .requirements[0]
                .verification_refs =
                vec!["Untestable: fixture candidate has no product behavior".into()];
            let mut stale = attempt.tasks[1].clone();
            stale.id = "attempt-1-write-3".into();
            stale.status = TaskStatus::Planned;
            stale.artifact_area = Some(TaskArtifactArea {
                path: work_artifact_path(&fixture.work, "attempt-1", &stale.id),
            });
            attempt.tasks.push(stale);
            if no_expertise {
                item.learner_mode = LearnerMode::NoExpertise;
            }
            Ok(())
        })
        .unwrap();
    fluent_cmd()
        .current_dir(&fixture.project)
        .args([
            "attempt",
            "repair-writer-completion",
            &fixture.work,
            "attempt-1",
            "--resolution",
            &fixture.resolution,
        ])
        .assert()
        .success();
    let recovered = store.read_work_item(&fixture.work).unwrap();
    assert_eq!(
        recovered.attempts[0].tasks[2].status,
        TaskStatus::Superseded
    );
    store
        .mutate_work_item(&fixture.work, |item| {
            let attempt = &mut item.attempts[0];
            attempt.tasks[1].status = TaskStatus::Complete;
            attempt.tasks[1].output = attempt.tasks[0].output.clone();
            item.add_review_tasks("attempt-1", &fluent::review::REVIEWERS)?;
            let attempt = &mut item.attempts[0];
            for task in attempt
                .tasks
                .iter_mut()
                .filter(|task| task.kind == TaskKind::Review)
            {
                task.status = TaskStatus::Complete;
            }
            attempt.status = AttemptStatus::Complete;
            attempt.pause_kind = None;
            attempt.review_state = Some(AttemptReviewState::Passed);
            item.create_or_get_merge_candidate("attempt-1")?;
            Ok(())
        })
        .unwrap();
    let ready = store.read_work_item(&fixture.work).unwrap();
    for task in ready.attempts[0]
        .tasks
        .iter()
        .filter(|task| task.kind == TaskKind::Review)
    {
        let path = fixture
            .project
            .join(&task.artifact_area.as_ref().unwrap().path)
            .join("review.md");
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(path, "Verdict: pass\n\nRecovered candidate reviewed.\n").unwrap();
    }
    let history = fixture
        .project
        .join(
            &ready.attempts[0].tasks[2]
                .artifact_area
                .as_ref()
                .unwrap()
                .path,
        )
        .join("history.txt");
    fs::create_dir_all(history.parent().unwrap()).unwrap();
    let bytes = b"preserve superseded Writer evidence\n".to_vec();
    fs::write(history, &bytes).unwrap();
    let bin = tmp.path().join("bin-recovered-learner");
    if no_expertise {
        write_mock_claude(&bin, &learner_failing_mock_script());
    } else {
        write_scheduler_claude(&bin, &learner_failing_mock_script());
    }
    fluent_cmd()
        .current_dir(&fixture.project)
        .env("PATH", mock_path(&bin))
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .assert()
        .success();
    let failed = store.read_work_item(&fixture.work).unwrap();
    assert!(
        failed.attempts[0]
            .learning
            .as_ref()
            .is_some_and(AttemptLearning::is_failed)
    );
    (fixture.project, fixture.work, bin, bytes)
}

