#[test]
fn attempt_evidence_attach_preserves_exact_evidence_and_identity() {
    use fluent::work_model::{AttemptStatus, TaskOutput, TaskStatus, WorkItem, WorkModelStore};

    let tmp = TempDir::new().unwrap();
    let project = setup_git_project(&tmp);
    let candidate = git_head(&project);
    let store = WorkModelStore::new(&project);
    let mut item = WorkItem::planned("evidence-attach", "Attach host evidence");
    item.add_initial_attempt("attempt-1").unwrap();
    let writer = &mut item.attempts[0].tasks[0];
    writer.status = TaskStatus::Complete;
    writer.output = Some(TaskOutput {
        workspace_id: "candidate".to_string(),
        workspace_path: project.display().to_string(),
        source_branch: "main".to_string(),
        base_commit: None,
        commit: candidate.clone(),
        no_change: None,
        learner_canonicalization: None,
    });
    item.add_review_tasks("attempt-1", &["architecture"])
        .unwrap();
    item.attempts[0].status = AttemptStatus::Reviewing;
    let reviewer = item.attempts[0].tasks.last_mut().unwrap();
    reviewer.status = TaskStatus::Complete;
    let review_path = format!(
        "{}/review.md",
        reviewer.artifact_area.as_ref().unwrap().path
    );
    fs::create_dir_all(project.join(&review_path).parent().unwrap()).unwrap();
    fs::write(
        project.join(&review_path),
        "Verdict: fail\n\n## Findings\n- [ ] Need host proof\n",
    )
    .unwrap();
    store.create_work_item(&item).unwrap();

    let evidence = tmp.path().join("host-evidence.json");
    let evidence_bytes = br#"{"schema_version":1,"producer":"trusted host","check":"fluent tester check","working_directory":"/repo","result":"pass","run_at":"2026-08-03T17:59:47Z","output":"ok\n"}"#;
    fs::write(&evidence, evidence_bytes).unwrap();
    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "attach",
            "evidence-attach",
            "attempt-1",
            "--candidate",
            &candidate,
            "--evidence-file",
            evidence.to_str().unwrap(),
            "--review-artifact",
            &review_path,
        ])
        .assert()
        .success();

    let shown = work_item_value(&project, "evidence-attach");
    let recovery = &shown["attempts"][0]["evidence_recoveries"][0];
    assert_eq!(recovery["candidate_commit"], candidate);
    assert_eq!(
        recovery["attachment"]["digest"],
        format!("sha256:{:x}", Sha256::digest(evidence_bytes))
    );
    let snapshot = project.join(recovery["attachment"]["snapshot_path"].as_str().unwrap());
    assert_eq!(fs::read(&snapshot).unwrap(), evidence_bytes);
    let retained: serde_json::Value =
        serde_json::from_slice(&fs::read(&snapshot).unwrap()).unwrap();
    assert_eq!(retained["producer"], "trusted host");
    assert_eq!(retained["check"], "fluent tester check");
    assert_eq!(retained["result"], "pass");
    assert_eq!(retained["run_at"], "2026-08-03T17:59:47Z");
    let tasks = shown["attempts"][0]["tasks"].as_array().unwrap();
    assert_eq!(
        tasks.iter().filter(|task| task["kind"] == "write").count(),
        1
    );
    assert_eq!(
        tasks
            .iter()
            .filter(|task| task["evidence_review_context"].is_object())
            .count(),
        1
    );
}

#[test]
fn attempt_evidence_attach_plans_targeted_reviews_without_writer() {
    use fluent::work_model::{AttemptStatus, TaskOutput, TaskStatus, WorkItem, WorkModelStore};

    let tmp = TempDir::new().unwrap();
    let project = setup_git_project(&tmp);
    let candidate = git_head(&project);
    let store = WorkModelStore::new(&project);
    let mut item = WorkItem::planned("evidence-target", "Target host evidence reviews");
    item.add_initial_attempt("attempt-1").unwrap();
    let writer = &mut item.attempts[0].tasks[0];
    writer.status = TaskStatus::Complete;
    writer.output = Some(TaskOutput {
        workspace_id: "candidate".to_string(),
        workspace_path: project.display().to_string(),
        source_branch: "main".to_string(),
        base_commit: None,
        commit: candidate.clone(),
        no_change: None,
        learner_canonicalization: None,
    });
    item.add_review_tasks("attempt-1", &["architecture", "tests"])
        .unwrap();
    item.attempts[0].status = AttemptStatus::Reviewing;
    let paths = item.attempts[0]
        .tasks
        .iter_mut()
        .filter(|task| task.kind == fluent::work_model::TaskKind::Review)
        .map(|task| {
            task.status = TaskStatus::Complete;
            let path = format!("{}/review.md", task.artifact_area.as_ref().unwrap().path);
            fs::create_dir_all(project.join(&path).parent().unwrap()).unwrap();
            fs::write(project.join(&path), "Verdict: fail\n").unwrap();
            path
        })
        .collect::<Vec<_>>();
    store.create_work_item(&item).unwrap();
    let evidence = tmp.path().join("evidence.json");
    fs::write(&evidence, br#"{"schema_version":1,"producer":"host","check":"check","working_directory":"/repo","result":"pass","run_at":"2026-08-03T17:59:47Z","output":"ok"}"#).unwrap();
    let mut args = vec![
        "attempt",
        "evidence",
        "attach",
        "evidence-target",
        "attempt-1",
        "--candidate",
        &candidate,
        "--evidence-file",
        evidence.to_str().unwrap(),
    ];
    for path in &paths {
        args.push("--review-artifact");
        args.push(path);
    }
    fluent_cmd()
        .current_dir(&project)
        .args(args)
        .assert()
        .success();

    fluent_cmd()
        .current_dir(&project)
        .args([
            "queue",
            "resume",
            "evidence-target",
            "--attempt",
            "attempt-1",
        ])
        .assert()
        .success()
        .stdout(predicate::str::contains(
            "Queued resume of Attempt attempt-1 for Work Item evidence-target",
        ));

    let shown = work_item_value(&project, "evidence-target");
    let tasks = shown["attempts"][0]["tasks"].as_array().unwrap();
    assert_eq!(
        tasks.iter().filter(|task| task["kind"] == "write").count(),
        1
    );
    assert_eq!(
        tasks.iter().filter(|task| task["kind"] == "test").count(),
        0
    );
    let targeted = tasks
        .iter()
        .filter(|task| task["evidence_review_context"].is_object())
        .collect::<Vec<_>>();
    assert_eq!(targeted.len(), 2);
    assert!(targeted.iter().all(|task| {
        paths
            .iter()
            .any(|path| task["evidence_review_context"]["prior_review_artifact"] == *path)
    }));
}

fn setup_focused_evidence_fixture(
    tmp: &TempDir,
    work_item_id: &str,
    role: &str,
    review_body: &str,
) -> (PathBuf, String, String) {
    let project = setup_git_project(tmp);
    create_focused_evidence_item(project, work_item_id, role, review_body)
}

fn create_focused_evidence_item(
    project: PathBuf,
    work_item_id: &str,
    role: &str,
    review_body: &str,
) -> (PathBuf, String, String) {
    use fluent::work_model::{
        AttemptReviewState, AttemptStatus, PauseKind, TaskOutput, TaskStatus, WorkItem,
        WorkModelStore,
    };

    let candidate = git_head(&project);
    let store = WorkModelStore::new(&project);
    let mut item = WorkItem::planned(work_item_id, "Run focused reviewer evidence");
    item.add_initial_attempt("attempt-1").unwrap();
    let writer = &mut item.attempts[0].tasks[0];
    writer.status = TaskStatus::Complete;
    writer.output = Some(TaskOutput {
        workspace_id: "candidate".to_string(),
        workspace_path: project.display().to_string(),
        source_branch: "main".to_string(),
        base_commit: None,
        commit: candidate.clone(),
        no_change: None,
        learner_canonicalization: None,
    });
    item.add_review_tasks("attempt-1", &[role]).unwrap();
    let reviewer = item.attempts[0].tasks.last_mut().unwrap();
    reviewer.status = TaskStatus::Complete;
    let review_path = format!(
        "{}/review.md",
        reviewer.artifact_area.as_ref().unwrap().path
    );
    fs::create_dir_all(project.join(&review_path).parent().unwrap()).unwrap();
    fs::write(project.join(&review_path), review_body).unwrap();
    item.attempts[0].status = AttemptStatus::NeedsUser;
    item.attempts[0].pause_kind = Some(PauseKind::RoundCap);
    item.attempts[0].review_state = Some(AttemptReviewState::Failed);
    store.create_work_item(&item).unwrap();
    (project, candidate, review_path)
}

fn accept_focused_verification(project: &Path, work: &str) -> anyhow::Result<()> {
    let store = fluent::work_model::WorkModelStore::new(project);
    let item = store.read_work_item(work)?;
    let task = item.attempts[0]
        .tasks
        .iter()
        .find(|task| task.kind == fluent::work_model::TaskKind::Verification)
        .unwrap();
    fluent::verification::accept(
        project,
        &store,
        task,
        &fluent::content::ContentResolver::new(Some(project)),
    )?;
    Ok(())
}

#[test]
fn focused_evidence_run_schedules_candidate_bound_verification_task() {
    let tmp = TempDir::new().unwrap();
    let (project, candidate, review_path) = setup_focused_evidence_fixture(
        &tmp,
        "scheduled-evidence",
        "tests",
        "Verdict: fail\nEvidence-Command: printf scheduled\nEvidence-Working-Directory: .\n",
    );
    for _ in 0..2 {
        fluent_cmd()
            .current_dir(&project)
            .args([
                "attempt",
                "evidence",
                "run",
                "scheduled-evidence",
                "attempt-1",
                "--review-artifact",
                &review_path,
            ])
            .assert()
            .success()
            .stdout(predicate::str::contains("Scheduled verification Task"));
    }
    let shown = work_item_value(&project, "scheduled-evidence");
    let attempt = &shown["attempts"][0];
    let tasks = attempt["tasks"].as_array().unwrap();
    let verification = tasks
        .iter()
        .filter(|task| task["kind"] == "verification")
        .collect::<Vec<_>>();
    assert_eq!(verification.len(), 1);
    let task = verification[0];
    assert_eq!(task["status"].as_str().unwrap_or("planned"), "planned");
    assert_eq!(task["work_item_id"], "scheduled-evidence");
    assert_eq!(task["attempt_id"], "attempt-1");
    assert_eq!(task["verification_context"]["candidate_commit"], candidate);
    assert_eq!(
        task["verification_context"]["checker"]["command"],
        "printf scheduled"
    );
    assert_eq!(
        task["verification_context"]["checker"]["working_directory"],
        "."
    );
    assert!(
        task["verification_context"]["checker_digest"]
            .as_str()
            .unwrap()
            .starts_with("sha256:")
    );
    assert!(
        task["workspace_access"]["writes"]
            .as_array()
            .unwrap()
            .is_empty()
    );
    assert!(
        attempt["evidence_recoveries"]
            .as_array()
            .is_none_or(|entries| entries.is_empty())
    );
    assert!(
        !project
            .join(task["artifact_area"]["path"].as_str().unwrap())
            .join("stdout.log")
            .exists()
    );
    assert_eq!(git_head(&project), candidate);
}

