fn setup_paused_code_change_classification_fixture_with_result_and_session(
    tmp: &TempDir,
    work_item_id: &str,
    evidence_result: &str,
    real_session: bool,
) -> (PathBuf, String, String, String, String, String) {
    let (project, candidate, prior_review_path, evidence) =
        setup_failed_evidence_recovery_fixture_with_session(tmp, work_item_id, real_session);
    let mut evidence_document: serde_json::Value =
        serde_json::from_slice(&fs::read(&evidence).unwrap()).unwrap();
    evidence_document["result"] = serde_json::Value::String(evidence_result.to_string());
    fs::write(
        &evidence,
        serde_json::to_vec_pretty(&evidence_document).unwrap(),
    )
    .unwrap();
    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "attach",
            work_item_id,
            "attempt-1",
            "--candidate",
            &candidate,
            "--evidence-file",
            evidence.to_str().unwrap(),
            "--review-artifact",
            &prior_review_path,
        ])
        .assert()
        .success();
    let store = WorkModelStore::new(&project);
    let targeted_path = store
        .mutate_work_item(work_item_id, |item| {
            let targeted = item.attempts[0].tasks.last_mut().unwrap();
            targeted.status = fluent::work_model::TaskStatus::Complete;
            targeted.completed_at = Some(fluent::work_model::now_iso8601());
            Ok(format!(
                "{}/review.md",
                targeted.artifact_area.as_ref().unwrap().path
            ))
        })
        .unwrap();
    fs::create_dir_all(project.join(&targeted_path).parent().unwrap()).unwrap();
    fs::write(
        project.join(&targeted_path),
        "Verdict: fail\nDisposition: evidence-needed\nExternal-Condition: Restore the host launch network.\nAdditional-Proof: Attach a rerun after restoring it.\n",
    )
    .unwrap();
    fluent_cmd()
        .current_dir(&project)
        .args(["attempt", "run", work_item_id, "attempt-1", "--no-sandbox"])
        .assert()
        .success();
    let shown = work_item_value(&project, work_item_id);
    let recovery = &shown["attempts"][0]["evidence_recoveries"][0];
    let evidence_digest = recovery["attachment"]["digest"].as_str().unwrap();
    let snapshot_path = recovery["attachment"]["snapshot_path"].as_str().unwrap();
    (
        project,
        candidate,
        prior_review_path,
        targeted_path,
        evidence_digest.to_string(),
        snapshot_path.to_string(),
    )
}

struct LegacyClassifiedRecovery {
    attempt_path: PathBuf,
    operation_id: String,
    writer_id: String,
    audit_path: String,
    audit: Vec<u8>,
}

fn persist_legacy_classified_recovery(
    project: &Path,
    work_item_id: &str,
    candidate: &str,
    targeted_path: &str,
    evidence_digest: &str,
) -> LegacyClassifiedRecovery {
    let store = WorkModelStore::new(project);
    let attempt_path = store.work_attempt_path(work_item_id, "attempt-1").unwrap();
    let mut legacy_attempt = read_json_path(&attempt_path);
    let recovery_id = legacy_attempt["evidence_recoveries"][0]["id"]
        .as_str()
        .unwrap()
        .to_string();
    let review_digest =
        legacy_attempt["evidence_recoveries"][0]["code_change_classification"]["review_digest"]
            .as_str()
            .unwrap()
            .to_string();
    let authorization_digest = legacy_attempt["evidence_recoveries"][0]
        ["code_change_classification"]["authorization_digest"]
        .as_str()
        .unwrap()
        .to_string();
    let writer_id =
        legacy_attempt["evidence_recoveries"][0]["code_change_classification"]["writer_task_id"]
            .as_str()
            .unwrap()
            .to_string();
    let current_operation_id =
        legacy_attempt["evidence_recoveries"][0]["code_change_classification"]["operation_id"]
            .as_str()
            .unwrap()
            .to_string();
    let current_audit_path = legacy_attempt["evidence_recoveries"][0]["code_change_classification"]
        ["audit_artifact"]["path"]
        .as_str()
        .unwrap()
        .to_string();
    let legacy_operation_material = format!(
        "attempt-1\0{candidate}\0{recovery_id}\0{targeted_path}\0{review_digest}\0{evidence_digest}\0{authorization_digest}"
    );
    let legacy_operation_id = format!(
        "host-evidence-classification-{:x}",
        Sha256::digest(legacy_operation_material.as_bytes())
    );
    let legacy_audit_path = format!(
        ".fluent/work/artifacts/{work_item_id}/attempt-1/{legacy_operation_id}/classification.json"
    );
    let mut legacy_audit = fs::read(project.join(&current_audit_path)).unwrap();
    let disposition_line = b"  \"disposition\": \"code-change\",\n";
    let disposition_start = legacy_audit
        .windows(disposition_line.len())
        .position(|window| window == disposition_line)
        .expect("new audit includes the disposition field");
    legacy_audit.drain(disposition_start..disposition_start + disposition_line.len());
    legacy_audit = String::from_utf8(legacy_audit)
        .unwrap()
        .replace(&current_operation_id, &legacy_operation_id)
        .into_bytes();
    fs::create_dir_all(project.join(&legacy_audit_path).parent().unwrap()).unwrap();
    fs::write(project.join(&legacy_audit_path), legacy_audit.clone()).unwrap();
    fs::remove_file(project.join(&current_audit_path)).unwrap();

    {
        let recovery = &mut legacy_attempt["evidence_recoveries"][0];
        let classification = &mut recovery["code_change_classification"];
        classification["operation_id"] = serde_json::Value::String(legacy_operation_id.clone());
        classification["audit_artifact"] = serde_json::json!({
            "producer_id": legacy_operation_id.clone(),
            "path": legacy_audit_path.clone(),
        });
        classification
            .as_object_mut()
            .unwrap()
            .remove("disposition");
        recovery["targets"][0]
            .as_object_mut()
            .unwrap()
            .remove("review_digest");
    }
    for artifact in legacy_attempt["artifacts"].as_array_mut().unwrap() {
        if artifact["path"] == current_audit_path {
            *artifact = serde_json::json!({
                "producer_id": legacy_operation_id.clone(),
                "path": legacy_audit_path.clone(),
            });
        }
    }
    let writer_path = store
        .work_task_path(work_item_id, "attempt-1", &writer_id)
        .unwrap();
    let mut legacy_writer = read_json_path(&writer_path);
    for input in legacy_writer["input_artifacts"].as_array_mut().unwrap() {
        if input["path"] == current_audit_path {
            *input = serde_json::json!({
                "producer_id": legacy_operation_id.clone(),
                "path": legacy_audit_path.clone(),
            });
        }
    }
    write_json_path(&attempt_path, &legacy_attempt);
    write_json_path(&writer_path, &legacy_writer);

    LegacyClassifiedRecovery {
        attempt_path,
        operation_id: legacy_operation_id,
        writer_id,
        audit_path: legacy_audit_path,
        audit: legacy_audit,
    }
}

struct ManagedWorktreeCleanup {
    project: PathBuf,
    workspace: PathBuf,
}

impl Drop for ManagedWorktreeCleanup {
    fn drop(&mut self) {
        let workspace = self.workspace.to_string_lossy().into_owned();
        let _ = git::run(
            &self.project,
            &["worktree", "remove", "--force", &workspace],
            "remove classified Writer fixture worktree",
        );
    }
}

fn bind_candidate_to_managed_sibling(
    project: &Path,
    work_item_id: &str,
    candidate: &str,
) -> ManagedWorktreeCleanup {
    let workspace_relative =
        fluent::work_model::initial_candidate_workspace_path(work_item_id, "attempt-1");
    let workspace_name = Path::new(&workspace_relative)
        .file_name()
        .expect("managed candidate workspace has a name");
    let workspace_path = project
        .parent()
        .expect("fixture project has a parent")
        .join(workspace_name);
    if workspace_path.exists() {
        assert_eq!(git_head(&workspace_path), candidate);
    } else {
        git::run(
            project,
            &[
                "worktree",
                "add",
                "--detach",
                workspace_path.to_str().unwrap(),
                candidate,
            ],
            "create managed candidate fixture worktree",
        )
        .unwrap();
    }
    let cleanup = ManagedWorktreeCleanup {
        project: project.to_path_buf(),
        workspace: workspace_path,
    };

    let store = WorkModelStore::new(project);
    let workspace_relative_for_model = workspace_relative.clone();
    store
        .mutate_work_item(work_item_id, |item| {
            let attempt = &mut item.attempts[0];
            for task in &mut attempt.tasks {
                for workspace in task
                    .workspace_access
                    .reads
                    .iter_mut()
                    .chain(task.workspace_access.writes.iter_mut())
                {
                    if workspace.id == "candidate" {
                        workspace.path = workspace_relative_for_model.clone();
                    }
                }
                if let Some(context) = task.review_context.as_mut()
                    && context.candidate_workspace_id == "candidate"
                {
                    context.candidate_workspace_path = workspace_relative_for_model.clone();
                }
                if let Some(output) = task.output.as_mut()
                    && output.workspace_id == "candidate"
                {
                    output.workspace_path = workspace_relative_for_model.clone();
                }
            }
            Ok(())
        })
        .unwrap();
    cleanup
}

#[test]
fn attempt_evidence_attach_recovers_failed_no_change_writer_in_same_attempt() {
    let tmp = TempDir::new().unwrap();
    let (project, candidate, review_path, evidence) =
        setup_failed_evidence_recovery_fixture(&tmp, "evidence-recover");

    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "attach",
            "evidence-recover",
            "attempt-1",
            "--candidate",
            &candidate,
            "--evidence-file",
            evidence.to_str().unwrap(),
            "--review-artifact",
            &review_path,
        ])
        .assert()
        .success();

    let shown = work_item_value(&project, "evidence-recover");
    let attempt = &shown["attempts"][0];
    assert_eq!(attempt["status"], "reviewing");
    assert_eq!(
        attempt["evidence_recoveries"][0]["candidate_commit"],
        candidate
    );
    assert_eq!(
        attempt["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|task| task["kind"] == "write")
            .count(),
        2,
        "the failed Writer remains historical; attachment adds no Writer"
    );
    let tasks = attempt["tasks"].as_array().unwrap();
    assert!(tasks.iter().any(|task| {
        task["kind"] == "write" && task["status"] == "failed" && task["output"].is_null()
    }));
    assert!(
        tasks
            .iter()
            .any(|task| task["evidence_review_context"].is_object())
    );
}

#[test]
fn attempt_evidence_attach_supersedes_interrupted_output_free_evidence_correction() {
    let tmp = TempDir::new().unwrap();
    let (project, candidate, review_path, evidence) =
        setup_failed_evidence_recovery_fixture(&tmp, "evidence-interrupted-correction");

    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "attach",
            "evidence-interrupted-correction",
            "attempt-1",
            "--candidate",
            &candidate,
            "--evidence-file",
            evidence.to_str().unwrap(),
            "--review-artifact",
            &review_path,
        ])
        .assert()
        .success();

    let store = fluent::work_model::WorkModelStore::new(&project);
    let targeted_review_path = store
        .mutate_work_item("evidence-interrupted-correction", |item| {
            let attempt = &mut item.attempts[0];
            let targeted = attempt.tasks.last_mut().unwrap();
            targeted.status = fluent::work_model::TaskStatus::Complete;
            targeted.completed_at = Some(fluent::work_model::now_iso8601());
            let path = format!(
                "{}/review.md",
                targeted.artifact_area.as_ref().unwrap().path
            );
            Ok((targeted.id.clone(), path))
        })
        .unwrap();
    fs::create_dir_all(project.join(&targeted_review_path.1).parent().unwrap()).unwrap();
    fs::write(
        project.join(&targeted_review_path.1),
        "Verdict: fail\nDisposition: code-change\n",
    )
    .unwrap();
    store
        .mutate_work_item("evidence-interrupted-correction", |item| {
            item.add_next_write_round(
                "attempt-1",
                vec![fluent::work_model::ArtifactRef {
                    producer_id: targeted_review_path.0.clone(),
                    path: targeted_review_path.1.clone(),
                }],
            )?;
            let attempt = &mut item.attempts[0];
            let correction = attempt.tasks.last_mut().unwrap();
            correction.status = fluent::work_model::TaskStatus::NeedsUser;
            correction.completed_at = Some(fluent::work_model::now_iso8601());
            attempt.status = fluent::work_model::AttemptStatus::NeedsUser;
            attempt.pause_kind = Some(fluent::work_model::PauseKind::Interrupted);
            attempt.review_state = Some(fluent::work_model::AttemptReviewState::Failed);
            attempt.evidence_recoveries[0].state =
                fluent::work_model::EvidenceRecoveryState::Complete;
            Ok(())
        })
        .unwrap();

    let replacement = tmp.path().join("replacement-evidence.json");
    fs::write(&replacement, br#"{"schema_version":1,"producer":"host","check":"check","working_directory":"/repo","result":"pass","run_at":"2026-08-03T18:01:47Z","output":"replacement passed"}"#).unwrap();
    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "attach",
            "evidence-interrupted-correction",
            "attempt-1",
            "--candidate",
            &candidate,
            "--evidence-file",
            replacement.to_str().unwrap(),
            "--review-artifact",
            &targeted_review_path.1,
        ])
        .assert()
        .failure();
    let rejected = work_item_value(&project, "evidence-interrupted-correction");
    assert_eq!(rejected["attempts"][0]["status"], "needs-user");
    assert_eq!(
        rejected["attempts"][0]["evidence_recoveries"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    assert!(
        rejected["attempts"][0]["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .any(|task| task["kind"] == "write" && task["status"] == "needs-user")
    );
    store
        .mutate_work_item("evidence-interrupted-correction", |item| {
            item.attempts[0].evidence_recoveries[0].state =
                fluent::work_model::EvidenceRecoveryState::CodeChange;
            Ok(())
        })
        .unwrap();
    let correction_id = rejected["attempts"][0]["tasks"]
        .as_array()
        .unwrap()
        .last()
        .unwrap()["id"]
        .as_str()
        .unwrap();
    let live_owner = fluent::lease::acquire(&fluent::lease::task_lock_path(
        &project,
        "evidence-interrupted-correction",
        correction_id,
    ))
    .unwrap();
    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "attach",
            "evidence-interrupted-correction",
            "attempt-1",
            "--candidate",
            &candidate,
            "--evidence-file",
            replacement.to_str().unwrap(),
            "--review-artifact",
            &targeted_review_path.1,
        ])
        .assert()
        .failure();
    drop(live_owner);
    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "attach",
            "evidence-interrupted-correction",
            "attempt-1",
            "--candidate",
            &candidate,
            "--evidence-file",
            replacement.to_str().unwrap(),
            "--review-artifact",
            &targeted_review_path.1,
        ])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "attach",
            "evidence-interrupted-correction",
            "attempt-1",
            "--candidate",
            &candidate,
            "--evidence-file",
            replacement.to_str().unwrap(),
            "--review-artifact",
            &targeted_review_path.1,
        ])
        .assert()
        .success();

    let shown = work_item_value(&project, "evidence-interrupted-correction");
    let attempt = &shown["attempts"][0];
    assert_eq!(attempt["status"], "reviewing");
    assert!(attempt["pause_kind"].is_null());
    assert_eq!(attempt["evidence_recoveries"].as_array().unwrap().len(), 2);
    let tasks = attempt["tasks"].as_array().unwrap();
    assert!(tasks.iter().any(|task| {
        task["kind"] == "write"
            && task["status"] == "superseded"
            && task["output"].is_null()
            && task["input_artifacts"][0]["producer_id"] == targeted_review_path.0
    }));
    assert_eq!(git_head(&project), candidate);
}

