#[test]
fn host_evidence_classification_rejects_existing_merge_candidate_without_mutation() {
    let tmp = TempDir::new().unwrap();
    let run_suffix = tmp
        .path()
        .file_name()
        .expect("fixture TempDir has a name")
        .to_string_lossy();
    let work_item_id = format!("evidence-classify-merge-candidate-{run_suffix}");
    let (project, candidate, _prior_review_path, targeted_path, digest, _snapshot_path) =
        setup_paused_code_change_classification_fixture(&tmp, &work_item_id);
    let store = WorkModelStore::new(&project);
    store
        .mutate_work_item(&work_item_id, |item| {
            let attempt = &mut item.attempts[0];
            let failed_writer = attempt
                .tasks
                .iter_mut()
                .find(|task| {
                    task.kind == fluent::work_model::TaskKind::Write
                        && task.status == fluent::work_model::TaskStatus::Failed
                })
                .expect("fixture has a failed source-correction Writer");
            failed_writer.status = fluent::work_model::TaskStatus::Superseded;
            attempt.status = fluent::work_model::AttemptStatus::Complete;
            attempt.pause_kind = None;
            attempt.completed_at = None;
            attempt.review_state = Some(fluent::work_model::AttemptReviewState::Passed);
            let candidate_id = item
                .create_or_get_merge_candidate("attempt-1")
                .expect("fixture should create a valid Merge Candidate");
            assert_eq!(candidate_id, "attempt-1-merge-candidate");
            let candidate = item
                .merge_candidates
                .last()
                .expect("Merge Candidate was appended");
            assert_eq!(candidate.attempt_id, "attempt-1");
            assert_eq!(
                candidate.candidate_commit,
                item.attempts[0].tasks[0].output.as_ref().unwrap().commit
            );
            assert_eq!(candidate.candidate_commit, git_head(&project));

            let attempt = &mut item.attempts[0];
            let failed_writer = attempt
                .tasks
                .iter_mut()
                .find(|task| {
                    task.kind == fluent::work_model::TaskKind::Write && task.output.is_none()
                })
                .expect("fixture retains its corrective Writer");
            failed_writer.status = fluent::work_model::TaskStatus::Failed;
            attempt.status = fluent::work_model::AttemptStatus::NeedsUser;
            attempt.pause_kind = Some(fluent::work_model::PauseKind::HostSandbox);
            attempt.completed_at = Some(fluent::work_model::now_iso8601());
            Ok(())
        })
        .unwrap();

    let resolution = "The failed candidate-bound check needs a source correction.";
    let before_model = work_item_value(&project, &work_item_id);
    assert_eq!(
        before_model["merge_candidates"].as_array().unwrap().len(),
        1
    );
    assert_eq!(
        before_model["merge_candidates"][0]["attempt_id"],
        "attempt-1"
    );
    assert_eq!(
        before_model["merge_candidates"][0]["candidate_commit"],
        candidate
    );
    let before_persisted = persisted_work_snapshot(&project, &work_item_id);
    let before_head = git_head(&project);
    let output = fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "classify",
            work_item_id.as_str(),
            "attempt-1",
            "--candidate",
            candidate.as_str(),
            "--review-artifact",
            targeted_path.as_str(),
            "--evidence-digest",
            digest.as_str(),
            "--resolution",
            resolution,
        ])
        .output()
        .unwrap();
    assert!(
        !output.status.success(),
        "classification with existing Merge Candidate unexpectedly succeeded: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(
        String::from_utf8_lossy(&output.stderr)
            .contains("a Merge Candidate already owns this candidate")
    );
    assert_eq!(work_item_value(&project, &work_item_id), before_model);
    assert_eq!(
        persisted_work_snapshot(&project, &work_item_id),
        before_persisted,
        "classification changed persisted model or artifacts"
    );
    assert_eq!(git_head(&project), before_head);
}

#[test]
fn review_coverage_requires_all_roles_after_host_correction() {
    let tmp = TempDir::new().unwrap();
    let run_suffix = tmp
        .path()
        .file_name()
        .expect("fixture TempDir has a name")
        .to_string_lossy();
    let work_item_id = format!("evidence-classify-writer-{run_suffix}");
    let (project, candidate, _prior_review_path, targeted_path, digest, snapshot_path) =
        setup_paused_code_change_classification_fixture(&tmp, &work_item_id);
    let _workspace_cleanup = bind_candidate_to_managed_sibling(&project, &work_item_id, &candidate);
    let resolution = "The failed candidate-bound check needs a source correction.";
    let classify_args = [
        "attempt",
        "evidence",
        "classify",
        &work_item_id,
        "attempt-1",
        "--candidate",
        candidate.as_str(),
        "--review-artifact",
        targeted_path.as_str(),
        "--evidence-digest",
        digest.as_str(),
        "--resolution",
        resolution,
    ];
    let classify_output = fluent_cmd()
        .current_dir(&project)
        .args(classify_args)
        .output()
        .unwrap();
    assert!(
        classify_output.status.success(),
        "classification failed: stdout={} stderr={}",
        String::from_utf8_lossy(&classify_output.stdout),
        String::from_utf8_lossy(&classify_output.stderr)
    );
    let classify_stdout = String::from_utf8_lossy(&classify_output.stdout).into_owned();
    let next_command = classify_stdout
        .lines()
        .find_map(|line| line.strip_prefix("Next: "))
        .expect("classification must emit a queue-resume next command");
    assert_eq!(
        next_command,
        format!("fluent queue resume {work_item_id} --attempt attempt-1")
    );
    let next_args = next_command.split_whitespace().skip(1).collect::<Vec<_>>();
    fluent_cmd()
        .current_dir(&project)
        .args(next_args)
        .assert()
        .success();
    let classified = work_item_value(&project, &work_item_id);
    let attempt = &classified["attempts"][0];
    let writer_id =
        attempt["evidence_recoveries"][0]["code_change_classification"]["writer_task_id"]
            .as_str()
            .unwrap()
            .to_string();
    let audit_path =
        attempt["evidence_recoveries"][0]["code_change_classification"]["audit_artifact"]["path"]
            .as_str()
            .unwrap()
            .to_string();

    let bin_dir = tmp.path().join("bin-classified-writer");
    let prompt_path = tmp.path().join("classified-writer-prompt");
    write_mock_claude(
        &bin_dir,
        &format!(
            r##"#!/bin/bash
set -euo pipefail
prompt=''
while [ "$#" -gt 0 ]; do
  if [ "$1" = "-p" ]; then
    shift
    prompt="${{1:-}}"
    break
  fi
  shift
done
if [ -z "$prompt" ]; then
  exit 0
fi
printf '%s' "$prompt" > "{}"
printf 'classified source correction\n' >> README.md
git add README.md
git commit -m "Apply classified source correction" >/dev/null
exit 0
"##,
            prompt_path.display()
        ),
    );
    let run = fluent_cmd()
        .current_dir(&project)
        .args([
            "task",
            "run",
            &work_item_id,
            "attempt-1",
            &writer_id,
            "--no-sandbox",
        ])
        .env("PATH", mock_path(&bin_dir))
        .output()
        .unwrap();
    assert!(
        run.status.success(),
        "classified Writer failed: stdout={} stderr={}",
        String::from_utf8_lossy(&run.stdout),
        String::from_utf8_lossy(&run.stderr)
    );
    let prompt = fs::read_to_string(&prompt_path).unwrap();
    assert!(prompt.contains(&candidate), "prompt lost candidate binding");
    assert!(
        prompt.contains(&targeted_path),
        "prompt lost review binding"
    );
    let after = work_item_value(&project, &work_item_id);
    let after_attempt = &after["attempts"][0];
    let writer = after_attempt["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .find(|task| task["id"] == writer_id)
        .unwrap();
    assert_eq!(writer["status"], "complete");
    assert_eq!(
        writer["output"]["workspace_path"],
        fluent::work_model::initial_candidate_workspace_path(&work_item_id, "attempt-1")
    );
    assert!(
        writer["input_artifacts"]
            .as_array()
            .unwrap()
            .iter()
            .any(|input| {
                input["producer_id"] == "host-evidence" && input["path"] == snapshot_path
            })
    );
    assert!(
        writer["input_artifacts"]
            .as_array()
            .unwrap()
            .iter()
            .any(|input| { input["producer_id"] == audit_path || input["path"] == audit_path })
    );
    assert_ne!(writer["output"]["commit"], candidate);
    assert_eq!(after_attempt["status"], "executing");

    let review_bin = tmp.path().join("bin-classified-writer-review");
    write_mock_claude(
        &review_bin,
        &learner_mock_script(r#"{"learning_summary":"classified","follow_ups":[]}"#),
    );
    fluent_cmd()
        .current_dir(&project)
        .args(["attempt", "run", &work_item_id, "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&review_bin))
        .assert()
        .success();
    let completed = work_item_value(&project, &work_item_id);
    let completed_attempt = &completed["attempts"][0];
    assert_eq!(completed_attempt["status"], "complete");
    let ordinary = completed_attempt["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|task| {
            task["kind"] == "review"
                && task["status"] == "complete"
                && task["evidence_review_context"].is_null()
                && task["review_context"]["candidate_commit"] == writer["output"]["commit"]
        })
        .map(|task| task["role"].as_str().unwrap())
        .collect::<Vec<_>>();
    assert_eq!(
        ordinary,
        review::REVIEWERS,
        "host correction must establish every ordinary domain"
    );
    let final_tester = completed_attempt["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .position(|task| task["kind"] == "tester")
        .unwrap();
    assert!(
        completed_attempt["tasks"].as_array().unwrap()[final_tester + 1..]
            .iter()
            .all(|task| task["kind"] != "review"),
        "ordinary review must precede final Tester"
    );

    assert_eq!(
        completed_attempt["evidence_recoveries"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    assert!(
        completed_attempt["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .any(|task| { task["id"] == "attempt-1-write-2" && task["status"] == "superseded" })
    );
    assert!(
        completed_attempt["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .all(|task| {
                task["kind"] != "write"
                    || task["status"] == "complete"
                    || task["status"] == "superseded"
            })
    );
}

#[test]
fn review_coverage_resume_keeps_targeted_and_ordinary_scope_separate() {
    use fluent::work_model::*;
    for saved_stage in ["review", "tester", "learning"] {
        let tmp = TempDir::new().unwrap();
        let work = format!(
            "coverage-scope-{}",
            tmp.path().file_name().unwrap().to_string_lossy()
        );
        let (project, candidate, prior_review) = setup_focused_evidence_fixture(
            &tmp,
            &work,
            "tests",
            "Verdict: fail\n\n- [ ] Need host proof\n",
        );
        let _cleanup = bind_candidate_to_managed_sibling(&project, &work, &candidate);
        let evidence = tmp.path().join("host-proof.json");
        fs::write(
            &evidence,
            serde_json::to_vec(&serde_json::json!({
                "schema_version":1, "producer":"fixture host", "check":"true",
                "working_directory":".", "result":"pass", "run_at":"2026-09-16T00:00:00Z",
                "output":"passed"
            }))
            .unwrap(),
        )
        .unwrap();
        fluent_cmd()
            .current_dir(&project)
            .args([
                "attempt",
                "evidence",
                "attach",
                &work,
                "attempt-1",
                "--candidate",
                &candidate,
                "--evidence-file",
                evidence.to_str().unwrap(),
                "--review-artifact",
                &prior_review,
            ])
            .assert()
            .success();
        let store = WorkModelStore::new(&project);
        let writer_area = project.join(
            &store.read_work_item(&work).unwrap().attempts[0].tasks[0]
                .artifact_area
                .as_ref()
                .unwrap()
                .path,
        );
        fs::create_dir_all(&writer_area).unwrap();
        fs::write(
            writer_area.join("transcript.jsonl"),
            "saved Writer transcript\n",
        )
        .unwrap();
        let targeted = store.read_work_item(&work).unwrap().attempts[0]
            .tasks
            .last()
            .unwrap()
            .clone();
        let bin = tmp.path().join("review-bin");
        write_mock_claude(
            &bin,
            &learner_mock_script(r#"{"learning_summary":"coverage","follow_ups":[]}"#),
        );
        fluent_cmd()
            .current_dir(&project)
            .args([
                "task",
                "run",
                &work,
                "attempt-1",
                &targeted.id,
                "--no-sandbox",
            ])
            .env("PATH", mock_path(&bin))
            .assert()
            .success();
        // Import the historical pre-Learning state produced by the old selector.
        // Everything after this fixture boundary uses public resume commands.
        if saved_stage == "tester" {
            store
                .mutate_work_item(&work, |item| {
                    item.add_final_tester_task("attempt-1")?;
                    Ok(())
                })
                .unwrap();
        }
        if saved_stage == "learning" {
            store
                .mutate_work_item(&work, |item| {
                    item.attempts[0].status = AttemptStatus::Complete;
                    item.attempts[0].review_state = Some(AttemptReviewState::Passed);
                    item.create_or_get_merge_candidate("attempt-1")?;
                    Ok(())
                })
                .unwrap();
        }
        let before = store.read_work_item(&work).unwrap();
        let targeted_bytes = fs::read(
            project
                .join(&targeted.artifact_area.as_ref().unwrap().path)
                .join("review.md"),
        )
        .unwrap();
        fluent_cmd()
            .current_dir(&project)
            .args(["attempt", "run", &work, "attempt-1", "--no-sandbox"])
            .env("PATH", mock_path(&bin))
            .assert()
            .success();
        let after = store.read_work_item(&work).unwrap();
        let attempt = &after.attempts[0];
        let fresh = &attempt.tasks[before.attempts[0].tasks.len()..];
        let roles = fresh
            .iter()
            .filter(|task| task.kind == TaskKind::Review)
            .map(|task| task.role.as_str())
            .collect::<Vec<_>>();
        assert_eq!(
            roles,
            review::REVIEWERS,
            "targeted Tests must not replace ordinary Tests or other domains"
        );
        assert!(fresh.iter().all(|task| task.kind != TaskKind::Write));
        assert_eq!(
            attempt.evidence_recoveries[0].state,
            EvidenceRecoveryState::Complete
        );
        assert!(attempt.learning.as_ref().unwrap().is_succeeded());
        let tester = attempt
            .tasks
            .iter()
            .find(|task| task.kind == TaskKind::Tester)
            .unwrap();
        for review in fresh.iter().filter(|task| task.kind == TaskKind::Review) {
            assert!(
                review.completed_at.as_ref().unwrap() <= tester.started_at.as_ref().unwrap(),
                "saved Tester must wait for every ordinary review"
            );
        }
        assert!(
            attempt
                .tasks
                .iter()
                .filter(|task| task.kind == TaskKind::Review)
                .all(|task| task.status == TaskStatus::Complete)
        );
        assert_eq!(
            fs::read(
                project
                    .join(&targeted.artifact_area.as_ref().unwrap().path)
                    .join("review.md")
            )
            .unwrap(),
            targeted_bytes
        );
        for historical in before.attempts[0]
            .tasks
            .iter()
            .filter(|task| task.status == TaskStatus::Complete)
        {
            assert_eq!(
                attempt
                    .tasks
                    .iter()
                    .find(|task| task.id == historical.id)
                    .unwrap(),
                historical
            );
        }
        fluent_cmd()
            .current_dir(&project)
            .args(["attempt", "run", &work, "attempt-1", "--no-sandbox"])
            .env("PATH", mock_path(&bin))
            .assert()
            .success();
        let repeated = store.read_work_item(&work).unwrap();
        assert_eq!(
            repeated.attempts[0].tasks, attempt.tasks,
            "resume must not duplicate completed reviews or Writers"
        );
    }
}

fn review_coverage_carry_forward_landing(stale: bool, matching_target_content: bool) {
    use fluent::work_model::*;
    let tmp = TempDir::new().unwrap();
    let work = format!(
        "coverage-carry-{}",
        tmp.path().file_name().unwrap().to_string_lossy()
    );
    let project = setup_git_project(&tmp);
    let candidate = git_head(&project);
    let store = WorkModelStore::new(&project);
    let mut item = WorkItem::planned(&work, "Retain ordinary domain review");
    item.add_initial_attempt("attempt-1").unwrap();
    item.attempts[0].tasks[0].status = TaskStatus::Complete;
    item.attempts[0].tasks[0].output = Some(TaskOutput {
        workspace_id: "candidate".into(),
        workspace_path: project.display().to_string(),
        source_branch: "main".into(),
        base_commit: Some(candidate.clone()),
        commit: candidate.clone(),
        no_change: None,
        learner_canonicalization: None,
    });
    item.add_review_tasks("attempt-1", review::REVIEWERS)
        .unwrap();
    for task in &mut item.attempts[0].tasks[1..] {
        task.status = TaskStatus::Complete;
        let area = project.join(&task.artifact_area.as_ref().unwrap().path);
        fs::create_dir_all(&area).unwrap();
        fs::write(area.join("review.md"), "Verdict: pass\n").unwrap();
    }
    store.create_work_item(&item).unwrap();
    let cleanup = bind_candidate_to_managed_sibling(&project, &work, &candidate);
    let mut item = store.read_work_item(&work).unwrap();
    let ordinary = item.attempts[0].tasks[1..].to_vec();
    // Saved successive corrections: the second delta must not hide a domain
    // invalidated by the first correction but never reviewed again.
    let later_path = if stale {
        "tests/corrected.rs"
    } else {
        "README.md"
    };
    fs::create_dir_all(cleanup.workspace.join("tests")).unwrap();
    for (path, contents) in [
        ("skills/follow-up.md", "skill correction"),
        (later_path, "later correction"),
    ] {
        fs::write(cleanup.workspace.join(path), contents).unwrap();
        git::run(&cleanup.workspace, &["add", path], "stage saved correction").unwrap();
        git::run(
            &cleanup.workspace,
            &["commit", "-m", "Update saved candidate"],
            "commit saved correction",
        )
        .unwrap();
        let mut output = item.attempts[0]
            .tasks
            .iter()
            .rev()
            .find(|task| task.kind == TaskKind::Write)
            .unwrap()
            .output
            .clone()
            .unwrap();
        output.commit = git_head(&cleanup.workspace);
        let documentation = &ordinary[0];
        item.add_next_write_round(
            "attempt-1",
            vec![ArtifactRef {
                producer_id: documentation.id.clone(),
                path: format!(
                    "{}/review.md",
                    documentation.artifact_area.as_ref().unwrap().path
                ),
            }],
        )
        .unwrap();
        let writer = item.attempts[0].tasks.last_mut().unwrap();
        writer.status = TaskStatus::Complete;
        writer.output = Some(output);
        let area = project.join(&writer.artifact_area.as_ref().unwrap().path);
        fs::create_dir_all(&area).unwrap();
        fs::write(area.join("transcript.jsonl"), "saved Writer transcript\n").unwrap();
    }
    store.write_work_item(&item).unwrap();
    let previous_tasks = item.attempts[0].tasks.clone();
    let bin = tmp.path().join("review-bin");
    write_mock_claude(
        &bin,
        &learner_mock_script(r#"{"learning_summary":"coverage","follow_ups":[]}"#),
    );
    fluent_cmd()
        .current_dir(&project)
        .args(["attempt", "run", &work, "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin))
        .assert()
        .success();
    let after = store.read_work_item(&work).unwrap();
    let attempt = &after.attempts[0];
    let roles = attempt.tasks[previous_tasks.len()..]
        .iter()
        .filter(|task| task.kind == TaskKind::Review)
        .map(|task| task.role.as_str())
        .collect::<Vec<_>>();
    if stale {
        assert_eq!(roles, ["documentation", "skills", "tests"]);
    } else {
        assert_eq!(roles, ["documentation", "skills"]);
    }
    assert_eq!(
        &attempt.tasks[..previous_tasks.len()],
        previous_tasks.as_slice()
    );
    assert!(attempt.learning.as_ref().unwrap().is_succeeded());
    fluent_cmd()
        .current_dir(&project)
        .args(["attempt", "run", &work, "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin))
        .assert()
        .success();
    assert_eq!(
        store.read_work_item(&work).unwrap().attempts[0].tasks,
        attempt.tasks
    );
    if cleanup.workspace.join("review.md").exists() {
        fs::remove_file(cleanup.workspace.join("review.md")).unwrap();
    }
    if stale {
        store
            .mutate_work_item(&work, |item| {
                let tasks = &mut item.attempts[0].tasks;
                let index = tasks
                    .iter()
                    .rposition(|task| task.kind == TaskKind::Review && task.role == "tests")
                    .unwrap();
                tasks.remove(index);
                Ok(())
            })
            .unwrap();
    }
    write_mock_claude(&bin, "#!/bin/bash\ngit rebase main >/dev/null 2>&1\n");
    let ready = work_item_value(&project, &work);
    let before_land = if matching_target_content {
        fs::create_dir_all(project.join("tests")).unwrap();
        fs::write(project.join("tests/corrected.rs"), "later correction").unwrap();
        git::run(
            &project,
            &["add", "tests/corrected.rs"],
            "stage matching target test",
        )
        .unwrap();
        git::run(
            &project,
            &["commit", "-m", "Add matching target test"],
            "commit matching target test",
        )
        .unwrap();
        git_head(&project)
    } else {
        advance_tester_target(&project)
    };
    let landing = fluent_cmd()
        .current_dir(&project)
        .args([
            "merge-candidate",
            "land",
            &work,
            "--no-sandbox",
            "--no-post-merge-review",
        ])
        .env("PATH", mock_path(&bin))
        .assert();
    if stale {
        landing.failure().stderr(predicate::str::contains(
            "ordinary tests review binding changed before landing",
        ));
        assert_eq!(git_head(&project), before_land);
        return;
    }
    landing.success();
    assert_ne!(git_head(&project), before_land);
    assert_eq!(
        work_item_value(&project, &work)["merge_candidates"][0]["merge_state"]["status"],
        "merged"
    );
    let trace_output = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("target/formal/workflow/evidence-status/carried-production");
    record_evidence_status_trace(&project, &work, &ready, &before_land, &trace_output);
}

#[test]
fn review_coverage_preserves_valid_ordinary_carry_forward() {
    review_coverage_carry_forward_landing(false, false);
}

#[test]
fn workflow_landing_rejects_stale_carried_review() {
    review_coverage_carry_forward_landing(true, false);
}

#[test]
fn workflow_landing_rejects_stale_review_with_matching_target_content() {
    review_coverage_carry_forward_landing(true, true);
}

#[test]
fn classified_recovery_continues_through_tester_and_later_host_evidence() {
    let tmp = TempDir::new().unwrap();
    let run_suffix = tmp
        .path()
        .file_name()
        .expect("fixture TempDir has a name")
        .to_string_lossy();
    let work_item_id = format!("evidence-classify-e2e-{run_suffix}");
    let (project, candidate, _prior_review_path, targeted_path, digest, snapshot_path) =
        setup_paused_code_change_classification_fixture(&tmp, &work_item_id);
    let _workspace_cleanup = bind_candidate_to_managed_sibling(&project, &work_item_id, &candidate);
    let resolution = "The failed candidate-bound check needs a source correction.";
    let classify_args = [
        "attempt",
        "evidence",
        "classify",
        &work_item_id,
        "attempt-1",
        "--candidate",
        candidate.as_str(),
        "--review-artifact",
        targeted_path.as_str(),
        "--evidence-digest",
        digest.as_str(),
        "--resolution",
        resolution,
    ];
    fluent_cmd()
        .current_dir(&project)
        .args(classify_args)
        .assert()
        .success();
    let classified = work_item_value(&project, &work_item_id);
    let writer_id = classified["attempts"][0]["evidence_recoveries"][0]
        ["code_change_classification"]["writer_task_id"]
        .as_str()
        .unwrap()
        .to_string();
    fluent_cmd()
        .current_dir(&project)
        .args(["queue", "resume", &work_item_id, "--attempt", "attempt-1"])
        .assert()
        .success();

    let writer_bin = tmp.path().join("bin-classified-e2e-writer");
    write_mock_claude(
        &writer_bin,
        r##"#!/bin/bash
HAS_PROMPT=0
for arg in "$@"; do
  if [ "$arg" = "-p" ]; then HAS_PROMPT=1; break; fi
done
if [ "$HAS_PROMPT" = 0 ]; then exit 0; fi
mkdir -p tests
printf 'classified source correction\n' >> README.md
printf 'print("readiness")\n' > tests/readiness.py
git add README.md tests/readiness.py
git commit -m "Apply classified source correction" >/dev/null
exit 0
"##,
    );
    fluent_cmd()
        .current_dir(&project)
        .args([
            "task",
            "run",
            &work_item_id,
            "attempt-1",
            &writer_id,
            "--no-sandbox",
        ])
        .env("PATH", mock_path(&writer_bin))
        .assert()
        .success();

    let matrix_path = project.join(format!(
        ".fluent/work/artifacts/{work_item_id}/attempt-1/{writer_id}/writer-completion.json"
    ));
    fs::create_dir_all(matrix_path.parent().unwrap()).unwrap();
    fs::write(
        &matrix_path,
        serde_json::to_vec_pretty(&fluent::work_model::WriterCompletionMatrix {
            schema_version: 1,
            task_id: writer_id.clone(),
            rows: vec![fluent::work_model::WriterCompletionRow {
                responsibility: None,
                id: "behavior:e2e:b1".to_string(),
                kind: fluent::work_model::WriterCompletionRequirementKind::Behavior,
                source: "behaviors.md#b1".to_string(),
                requirement: "The readiness check remains runnable.".to_string(),
                verification_refs: vec!["python3 tests/readiness.py".to_string()],
                command: None,
                state: fluent::work_model::WriterCompletionState::Complete,
                implementation_evidence: vec!["tests/readiness.py".to_string()],
                verification: vec![fluent::work_model::WriterVerificationClaim {
                    command: "python3 tests/readiness.py".to_string(),
                    result: fluent::work_model::WriterVerificationResult::Pass,
                }],
                applicable_constraints: Vec::new(),
            }],
        })
        .unwrap(),
    )
    .unwrap();

    let store = WorkModelStore::new(&project);
    store
        .mutate_work_item(&work_item_id, |item| {
            item.attempts[0].writer_completion_contract =
                Some(fluent::work_model::WriterCompletionContract {
                    version: fluent::work_model::WRITER_COMPLETION_CONTRACT_VERSION,
                    requirements: vec![fluent::work_model::WriterCompletionRequirement {
                        responsibility: None,
                        id: "behavior:e2e:b1".to_string(),
                        kind: fluent::work_model::WriterCompletionRequirementKind::Behavior,
                        source: "behaviors.md#b1".to_string(),
                        requirement: "The readiness check remains runnable.".to_string(),
                        verification_refs: vec!["python3 tests/readiness.py".to_string()],
                        command: None,
                    }],
                });
            Ok(())
        })
        .unwrap();

    let review_bin = tmp.path().join("bin-classified-e2e-review");
    write_mock_claude(
        &review_bin,
        &learner_mock_script(r#"{"learning_summary":"e2e","follow_ups":[]}"#),
    );
    let tester = fluent_cmd()
        .current_dir(&project)
        .args(["attempt", "run", &work_item_id, "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&review_bin))
        .output()
        .unwrap();
    assert!(
        tester.status.success(),
        "final Tester did not reach host-evidence pause: stdout={} stderr={}",
        String::from_utf8_lossy(&tester.stdout),
        String::from_utf8_lossy(&tester.stderr)
    );
    let paused = work_item_value(&project, &work_item_id);
    assert_eq!(paused["attempts"][0]["status"], "needs-user");
    assert_eq!(paused["attempts"][0]["pause_kind"], "host-evidence");
    for role in [
        "documentation",
        "behaviors",
        "architecture",
        "skills",
        "tests",
    ] {
        assert!(
            paused["attempts"][0]["tasks"]
                .as_array()
                .unwrap()
                .iter()
                .any(|task| {
                    task["kind"] == "review"
                        && task["role"] == role
                        && task["status"] == "complete"
                        && task["evidence_review_context"].is_null()
                }),
            "native resume must complete ordinary {role} review before final Tester"
        );
    }
    assert!(
        paused["attempts"][0]["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .any(|task| task["kind"] == "tester" && task["status"] == "complete")
    );
    let gate_path = paused["attempts"][0]["artifacts"]
        .as_array()
        .unwrap()
        .iter()
        .rev()
        .find_map(|artifact| {
            artifact["path"]
                .as_str()
                .filter(|path| path.ends_with("/candidate-gate.json"))
        })
        .expect("final Tester must publish a rejected candidate gate")
        .to_string();
    let latest_candidate = paused["attempts"][0]["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .rev()
        .find(|task| task["kind"] == "write" && task["status"] == "complete")
        .and_then(|task| task["output"]["commit"].as_str())
        .unwrap()
        .to_string();
    assert_ne!(latest_candidate, candidate);

    let evidence = tmp.path().join("e2e-gate-evidence.json");
    fs::write(
        &evidence,
        br#"{"schema_version":1,"producer":"host","check":"python3 tests/readiness.py","working_directory":".","result":"pass","run_at":"2026-09-02T00:00:00Z","output":"ready"}"#,
    )
    .unwrap();
    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "attach",
            &work_item_id,
            "attempt-1",
            "--candidate",
            &latest_candidate,
            "--evidence-file",
            evidence.to_str().unwrap(),
            "--review-artifact",
            &gate_path,
        ])
        .assert()
        .success();
    let targeted_review_id =
        work_item_value(&project, &work_item_id)["attempts"][0]["evidence_recoveries"]
            .as_array()
            .unwrap()
            .last()
            .and_then(|recovery| recovery["targets"][0]["review_task_id"].as_str())
            .unwrap()
            .to_string();
    fluent_cmd()
        .current_dir(&project)
        .args([
            "task",
            "run",
            &work_item_id,
            "attempt-1",
            &targeted_review_id,
            "--no-sandbox",
        ])
        .env("PATH", mock_path(&review_bin))
        .assert()
        .success();

    let resumed = fluent_cmd()
        .current_dir(&project)
        .args(["attempt", "run", &work_item_id, "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&review_bin))
        .output()
        .unwrap();
    assert!(
        resumed.status.success(),
        "host-evidence continuation failed: stdout={} stderr={}",
        String::from_utf8_lossy(&resumed.stdout),
        String::from_utf8_lossy(&resumed.stderr)
    );
    let completed = work_item_value(&project, &work_item_id);
    let attempt = &completed["attempts"][0];
    assert_eq!(attempt["status"], "complete");
    assert_eq!(attempt["evidence_recoveries"][0]["state"], "code-change");
    assert_eq!(attempt["evidence_recoveries"][1]["state"], "complete");
    assert_eq!(attempt["evidence_recoveries"].as_array().unwrap().len(), 2);
    assert_eq!(
        attempt["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|task| task["kind"] == "write")
            .count(),
        3,
        "the classified recovery adds one Writer without duplicating it"
    );
    assert!(
        attempt["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .any(|task| { task["id"] == targeted_review_id && task["status"] == "complete" })
    );
    assert!(
        attempt["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .any(|task| { task["kind"] == "tester" && task["status"] == "complete" })
    );
    assert!(
        completed["merge_candidates"]
            .as_array()
            .is_some_and(|candidates| {
                candidates.iter().any(|candidate| {
                    candidate["attempt_id"] == "attempt-1"
                        && candidate["candidate_commit"] == latest_candidate
                })
            })
    );
    assert_eq!(
        attempt["evidence_recoveries"][0]["attachment"]["snapshot_path"],
        snapshot_path
    );
    assert_eq!(
        attempt["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|task| task["id"] == "attempt-1-write-2")
            .and_then(|task| task["status"].as_str()),
        Some("superseded"),
        "the failed source Writer remains as superseded history after recovery"
    );
}

