#[test]
fn classified_host_evidence_scheduler_claim_dispatches_one_writer() {
    let tmp = TempDir::new().unwrap();
    let run_suffix = tmp
        .path()
        .file_name()
        .expect("fixture TempDir has a name")
        .to_string_lossy();
    let work_item_id = format!("evidence-classify-scheduler-{run_suffix}");
    let (project, candidate, _prior_review_path, targeted_path, digest, _snapshot_path) =
        setup_paused_code_change_classification_fixture(&tmp, &work_item_id);
    let workspace_cleanup = bind_candidate_to_managed_sibling(&project, &work_item_id, &candidate);
    let resolution = "The failed candidate-bound check needs a source correction.";
    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "classify",
            work_item_id.as_str(),
            "attempt-1",
            "--candidate",
            &candidate,
            "--review-artifact",
            &targeted_path,
            "--evidence-digest",
            &digest,
            "--resolution",
            resolution,
        ])
        .assert()
        .success();

    let classified = work_item_value(&project, &work_item_id);
    let writer_id = classified["attempts"][0]["evidence_recoveries"][0]
        ["code_change_classification"]["writer_task_id"]
        .as_str()
        .unwrap()
        .to_string();
    fluent_cmd()
        .current_dir(&project)
        .args(["queue", "resume", &work_item_id, "--attempt", "attempt-1"])
        .assert()
        .success();
    assert_eq!(dispatch_count(&project, &work_item_id), 1);
    assert_eq!(latest_dispatch_status(&project, &work_item_id), "queued");

    let marker = tmp.path().join("classified-scheduler-writer-invocations");
    let bin_dir = tmp.path().join("classified-scheduler-writer-bin");
    let marker_path = marker.to_string_lossy();
    let writer_workspace_suffix = format!("{work_item_id}-attempt-1");
    let script = format!(
        r##"#!/bin/bash
set -euo pipefail
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  mkdir -p "$(dirname "$DRAFT")"
  printf '%s\n' '{{"learning_summary":"learned","follow_ups":[]}}' > "$DRAFT"
else
case "$PWD" in
  *{writer_workspace_suffix})
    printf invoked >> "{marker_path}"
    printf 'scheduler classified correction\n' >> README.md
    git add README.md
    git commit -m "Apply scheduler classified correction" >/dev/null
    ;;
  *)
    printf 'Verdict: pass\n\nScheduler follow-up review.\n' > review.md
    ;;
esac
fi
exit 0
"##
    );
    write_scheduler_claude(&bin_dir, &script);

    let scheduler_output =
        run_scheduler_until_dispatch_status(&project, &work_item_id, &bin_dir, "candidate-ready");

    let completed = work_item_value(&project, &work_item_id);
    let writer = completed["attempts"][0]["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .find(|task| task["id"] == writer_id)
        .expect("scheduler must retain the classified Writer");
    assert_eq!(
        writer["status"],
        "complete",
        "scheduler did not complete the classified Writer: {completed}; stdout={}; stderr={}",
        String::from_utf8_lossy(&scheduler_output.stdout),
        String::from_utf8_lossy(&scheduler_output.stderr)
    );
    let output = writer["output"].as_object().expect("Writer has output");
    assert_ne!(output["commit"], candidate);
    assert_eq!(
        fs::read_to_string(&marker).unwrap(),
        "invoked",
        "scheduler claimed or dispatched the classified Writer more than once"
    );
    assert_eq!(dispatch_count(&project, &work_item_id), 1);
    assert_eq!(
        latest_dispatch_status(&project, &work_item_id),
        "candidate-ready"
    );
    assert_eq!(git_head(&workspace_cleanup.workspace), output["commit"]);
}

#[test]
fn legacy_unqualified_host_evidence_can_be_classified_for_code_change() {
    let tmp = TempDir::new().unwrap();
    let (project, candidate, prior_review_path, evidence) =
        setup_failed_evidence_recovery_fixture(&tmp, "evidence-classify-legacy");
    fs::write(
        &evidence,
        br#"{"schema_version":1,"producer":"host","check":"check","working_directory":"/repo","result":"fail","run_at":"2026-08-03T17:59:47Z","output":"failed"}"#,
    )
    .unwrap();
    let resolution = "The legacy failed candidate-bound check needs a source correction.";
    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "attach",
            "evidence-classify-legacy",
            "attempt-1",
            "--candidate",
            &candidate,
            "--evidence-file",
            evidence.to_str().unwrap(),
            "--review-artifact",
            &prior_review_path,
        ])
        .assert()
        .success();

    let store = fluent::work_model::WorkModelStore::new(&project);
    let targeted_path = store
        .mutate_work_item("evidence-classify-legacy", |item| {
            let targeted = item.attempts[0].tasks.last_mut().unwrap();
            targeted.status = fluent::work_model::TaskStatus::Complete;
            targeted.completed_at = Some(fluent::work_model::now_iso8601());
            Ok(format!(
                "{}/review.md",
                targeted.artifact_area.as_ref().unwrap().path
            ))
        })
        .unwrap();
    fs::create_dir_all(project.join(&targeted_path).parent().unwrap()).unwrap();
    fs::write(
        project.join(&targeted_path),
        "Verdict: fail\nDisposition: evidence-needed\n",
    )
    .unwrap();
    let evidence_digest =
        work_item_value(&project, "evidence-classify-legacy")["attempts"][0]["evidence_recoveries"]
            [0]["attachment"]["digest"]
            .as_str()
            .unwrap()
            .to_string();
    store
        .mutate_work_item("evidence-classify-legacy", |item| {
            let attempt = &mut item.attempts[0];
            attempt.evidence_recoveries[0].state =
                fluent::work_model::EvidenceRecoveryState::NeedsEvidence;
            attempt.evidence_recoveries[0].targets[0].review_digest = None;
            attempt.status = fluent::work_model::AttemptStatus::NeedsUser;
            attempt.pause_kind = Some(fluent::work_model::PauseKind::Uncertain);
            attempt.review_state = Some(fluent::work_model::AttemptReviewState::Failed);
            attempt.completed_at = Some(fluent::work_model::now_iso8601());
            Ok(())
        })
        .unwrap();

    let first = fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "classify",
            "evidence-classify-legacy",
            "attempt-1",
            "--candidate",
            &candidate,
            "--review-artifact",
            &targeted_path,
            "--evidence-digest",
            &evidence_digest,
            "--resolution",
            resolution,
        ])
        .output()
        .unwrap();
    assert!(
        first.status.success(),
        "legacy classification failed: stdout={} stderr={}",
        String::from_utf8_lossy(&first.stdout),
        String::from_utf8_lossy(&first.stderr)
    );
    let shown = work_item_value(&project, "evidence-classify-legacy");
    assert_eq!(shown["attempts"][0]["status"], "planned");
    assert_eq!(
        shown["attempts"][0]["evidence_recoveries"][0]["state"],
        "code-change"
    );
    assert_eq!(
        shown["attempts"][0]["evidence_recoveries"][0]["targets"][0]["review_digest"],
        format!(
            "sha256:{:x}",
            sha2::Sha256::digest(fs::read(project.join(&targeted_path)).unwrap())
        )
    );
    let classification =
        &shown["attempts"][0]["evidence_recoveries"][0]["code_change_classification"];
    let audit_path = classification["audit_artifact"]["path"].as_str().unwrap();
    let first_model = shown.clone();
    let first_persisted = persisted_work_snapshot(&project, "evidence-classify-legacy");
    let first_audit = fs::read(project.join(audit_path)).unwrap();
    let snapshot_path =
        first_model["attempts"][0]["evidence_recoveries"][0]["attachment"]["snapshot_path"]
            .as_str()
            .unwrap()
            .to_string();
    let first_snapshot = fs::read(project.join(&snapshot_path)).unwrap();
    let first_review = fs::read(project.join(&targeted_path)).unwrap();
    let first_tasks = first_model["attempts"][0]["tasks"].clone();
    let first_recoveries = first_model["attempts"][0]["evidence_recoveries"].clone();

    let replay = fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "classify",
            "evidence-classify-legacy",
            "attempt-1",
            "--candidate",
            &candidate,
            "--review-artifact",
            &targeted_path,
            "--evidence-digest",
            &evidence_digest,
            "--resolution",
            resolution,
        ])
        .output()
        .unwrap();
    assert!(
        replay.status.success(),
        "legacy classification replay failed: stdout={} stderr={}",
        String::from_utf8_lossy(&replay.stdout),
        String::from_utf8_lossy(&replay.stderr)
    );
    assert_eq!(replay.stdout, first.stdout);
    let replayed = work_item_value(&project, "evidence-classify-legacy");
    assert_eq!(replayed, first_model);
    assert_eq!(
        replayed["attempts"][0]["tasks"], first_tasks,
        "legacy replay changed Task history"
    );
    assert_eq!(
        replayed["attempts"][0]["evidence_recoveries"], first_recoveries,
        "legacy replay changed recovery history"
    );
    assert_eq!(
        persisted_work_snapshot(&project, "evidence-classify-legacy"),
        first_persisted,
        "legacy replay changed persisted artifacts"
    );
    assert_eq!(fs::read(project.join(audit_path)).unwrap(), first_audit);
    assert_eq!(
        fs::read(project.join(&snapshot_path)).unwrap(),
        first_snapshot
    );
    assert_eq!(
        fs::read(project.join(&targeted_path)).unwrap(),
        first_review
    );
    assert_eq!(git_head(&project), candidate);

    fluent_cmd()
        .current_dir(&project)
        .args([
            "queue",
            "resume",
            "evidence-classify-legacy",
            "--attempt",
            "attempt-1",
        ])
        .assert()
        .success();
}

#[test]
fn legacy_classified_host_evidence_replays_queues_and_starts_writer() {
    let tmp = TempDir::new().unwrap();
    let run_suffix = tmp
        .path()
        .file_name()
        .expect("fixture TempDir has a name")
        .to_string_lossy();
    let work_item_id = format!("evidence-classify-legacy-persisted-{run_suffix}");
    let (project, candidate, _prior_review_path, targeted_path, evidence_digest, _snapshot_path) =
        setup_paused_code_change_classification_fixture(&tmp, &work_item_id);
    let _workspace_cleanup = bind_candidate_to_managed_sibling(&project, &work_item_id, &candidate);
    let resolution = "The failed candidate-bound check needs a source correction.";
    let classify_args = [
        "attempt",
        "evidence",
        "classify",
        work_item_id.as_str(),
        "attempt-1",
        "--candidate",
        candidate.as_str(),
        "--review-artifact",
        targeted_path.as_str(),
        "--evidence-digest",
        evidence_digest.as_str(),
        "--resolution",
        resolution,
    ];
    fluent_cmd()
        .current_dir(&project)
        .args(classify_args)
        .assert()
        .success();

    let legacy = persist_legacy_classified_recovery(
        &project,
        &work_item_id,
        &candidate,
        &targeted_path,
        &evidence_digest,
    );
    let attempt_path = legacy.attempt_path;
    let legacy_operation_id = legacy.operation_id;
    let writer_id = legacy.writer_id;
    let legacy_audit_path = legacy.audit_path;
    let legacy_audit = legacy.audit;

    let expected_review_digest = format!(
        "sha256:{:x}",
        Sha256::digest(fs::read(project.join(&targeted_path)).unwrap())
    );
    let clear_target_digest = || {
        let mut attempt = read_json_path(&attempt_path);
        attempt["evidence_recoveries"][0]["targets"][0]
            .as_object_mut()
            .unwrap()
            .remove("review_digest");
        write_json_path(&attempt_path, &attempt);
    };

    let replay = fluent_cmd()
        .current_dir(&project)
        .args(classify_args)
        .output()
        .unwrap();
    assert!(
        replay.status.success(),
        "legacy classified replay failed: stdout={} stderr={}",
        String::from_utf8_lossy(&replay.stdout),
        String::from_utf8_lossy(&replay.stderr)
    );
    let replayed = work_item_value(&project, &work_item_id);
    assert_eq!(
        replayed["attempts"][0]["evidence_recoveries"][0]["targets"][0]["review_digest"],
        expected_review_digest
    );
    assert_eq!(
        replayed["attempts"][0]["evidence_recoveries"][0]["code_change_classification"]["operation_id"],
        legacy_operation_id
    );
    assert_eq!(
        fs::read(project.join(&legacy_audit_path)).unwrap(),
        legacy_audit
    );

    clear_target_digest();
    let store = WorkModelStore::new(&project);
    store
        .mutate_work_item(&work_item_id, |item| {
            let attempt = &mut item.attempts[0];
            attempt.status = fluent::work_model::AttemptStatus::NeedsUser;
            attempt.pause_kind = Some(fluent::work_model::PauseKind::Interrupted);
            attempt.pause_recovery = None;
            attempt.completed_at = Some(fluent::work_model::now_iso8601());
            let writer = attempt
                .tasks
                .iter_mut()
                .find(|task| task.id == writer_id)
                .unwrap();
            writer.status = fluent::work_model::TaskStatus::NeedsUser;
            writer.started_at = Some(fluent::work_model::now_iso8601());
            Ok(())
        })
        .unwrap();
    let legacy_model = store.read_work_item(&work_item_id).unwrap();
    assert_eq!(
        legacy_model.attempts[0].status,
        fluent::work_model::AttemptStatus::NeedsUser
    );
    assert_eq!(
        legacy_model.attempts[0].tasks.last().unwrap().status,
        fluent::work_model::TaskStatus::NeedsUser
    );
    fluent_cmd()
        .current_dir(&project)
        .args([
            "queue",
            "resume",
            work_item_id.as_str(),
            "--attempt",
            "attempt-1",
        ])
        .assert()
        .success();
    let queued = work_item_value(&project, &work_item_id);
    assert_eq!(
        queued["attempts"][0]["evidence_recoveries"][0]["targets"][0]["review_digest"],
        expected_review_digest
    );
    assert_eq!(
        fs::read(project.join(&legacy_audit_path)).unwrap(),
        legacy_audit
    );

    store
        .mutate_work_item(&work_item_id, |item| {
            fluent::work_model::reopen_attempt(&mut item.attempts[0]);
            Ok(())
        })
        .unwrap();
    clear_target_digest();
    let bin_dir = tmp.path().join("legacy-classified-writer-bin");
    write_mock_claude(
        &bin_dir,
        r##"#!/bin/bash
set -euo pipefail
for arg in "$@"; do
  if [ "$arg" = "-p" ]; then
    printf 'legacy classified correction\n' >> README.md
    git add README.md
    git commit -m "Apply legacy classified correction" >/dev/null
    break
  fi
done
exit 0
"##,
    );
    fluent_cmd()
        .current_dir(&project)
        .args([
            "task",
            "run",
            work_item_id.as_str(),
            "attempt-1",
            &writer_id,
            "--no-sandbox",
        ])
        .env("PATH", mock_path(&bin_dir))
        .assert()
        .success();
    let started = work_item_value(&project, &work_item_id);
    let started_writer = started["attempts"][0]["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .find(|task| task["id"] == writer_id)
        .unwrap();
    assert_eq!(started_writer["status"], "complete");
    assert!(
        started_writer["output"].is_object(),
        "legacy queue resume did not start the classified Writer"
    );
    assert_eq!(
        started["attempts"][0]["evidence_recoveries"][0]["targets"][0]["review_digest"],
        expected_review_digest
    );
    assert_eq!(
        fs::read(project.join(&legacy_audit_path)).unwrap(),
        legacy_audit
    );
}

#[test]
fn legacy_classified_host_evidence_queue_rejects_stale_candidate_without_mutation() {
    let tmp = TempDir::new().unwrap();
    let run_suffix = tmp
        .path()
        .file_name()
        .expect("fixture TempDir has a name")
        .to_string_lossy();
    let work_item_id = format!("evidence-classify-legacy-stale-{run_suffix}");
    let (project, candidate, _prior_review_path, targeted_path, evidence_digest, _snapshot_path) =
        setup_paused_code_change_classification_fixture(&tmp, &work_item_id);
    let workspace_cleanup = bind_candidate_to_managed_sibling(&project, &work_item_id, &candidate);
    let resolution = "The failed candidate-bound check needs a source correction.";
    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "classify",
            work_item_id.as_str(),
            "attempt-1",
            "--candidate",
            &candidate,
            "--review-artifact",
            &targeted_path,
            "--evidence-digest",
            &evidence_digest,
            "--resolution",
            resolution,
        ])
        .assert()
        .success();
    let _legacy = persist_legacy_classified_recovery(
        &project,
        &work_item_id,
        &candidate,
        &targeted_path,
        &evidence_digest,
    );

    commit_file(
        &workspace_cleanup.workspace,
        "stale-candidate.txt",
        "stale candidate\n",
        "Make candidate stale",
    );
    let before_model = persisted_work_snapshot(&project, &work_item_id);
    let queue_path = queue_ledger_path(&project, &work_item_id);
    let before_queue = fs::read(&queue_path).ok();
    let before_candidate_head = git_head(&workspace_cleanup.workspace);
    let before_candidate_status = git::run_stdout(
        &workspace_cleanup.workspace,
        &["status", "--porcelain", "--untracked-files=all"],
        "inspect stale candidate cleanliness",
    )
    .unwrap();
    let writer_marker = tmp.path().join("legacy-stale-writer-invoked");
    let bin_dir = tmp.path().join("legacy-stale-writer-bin");
    write_mock_claude(
        &bin_dir,
        r##"#!/bin/bash
set -euo pipefail
for arg in "$@"; do
  if [ "$arg" = "-p" ]; then
    printf invoked > "$WRITER_MARKER"
    break
  fi
done
exit 42
"##,
    );

    let output = fluent_cmd()
        .current_dir(&project)
        .args([
            "queue",
            "resume",
            work_item_id.as_str(),
            "--attempt",
            "attempt-1",
        ])
        .env("PATH", mock_path(&bin_dir))
        .env("WRITER_MARKER", &writer_marker)
        .output()
        .unwrap();
    assert!(
        !output.status.success(),
        "stale legacy migration unexpectedly succeeded: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );

    assert_eq!(
        persisted_work_snapshot(&project, &work_item_id),
        before_model,
        "stale legacy migration changed model or artifacts"
    );
    assert_eq!(fs::read(&queue_path).ok(), before_queue);
    assert_eq!(
        git_head(&workspace_cleanup.workspace),
        before_candidate_head,
        "stale legacy migration changed the candidate"
    );
    assert_eq!(
        git::run_stdout(
            &workspace_cleanup.workspace,
            &["status", "--porcelain", "--untracked-files=all"],
            "inspect stale candidate after rejection",
        )
        .unwrap(),
        before_candidate_status
    );
    assert!(
        !writer_marker.exists(),
        "stale legacy migration invoked the Writer"
    );
    assert!(
        work_item_value(&project, &work_item_id)["attempts"][0]["evidence_recoveries"][0]["targets"]
            [0]["review_digest"]
            .is_null(),
        "stale legacy migration persisted a target digest"
    );
}

#[test]
fn host_evidence_classification_rejects_stale_inputs() {
    for case in [
        "wrong-attempt",
        "wrong-review",
        "changed-review",
        "changed-evidence",
        "dirty-candidate",
        "changed-candidate",
        "wrong-candidate-digest",
        "wrong-evidence-digest",
        "absolute-review-path",
        "changed-review-workspace",
        "missing-review-evidence-input",
    ] {
        let tmp = TempDir::new().unwrap();
        let (project, candidate, prior_review_path, targeted_path, digest, snapshot_path) =
            setup_paused_code_change_classification_fixture(&tmp, "evidence-classify-stale");
        let store = WorkModelStore::new(&project);
        let mut attempt_arg = "attempt-1".to_string();
        let mut candidate_arg = candidate.clone();
        let mut review_arg = targeted_path.clone();
        let mut evidence_arg = digest.clone();
        match case {
            "wrong-attempt" => attempt_arg = "attempt-9".to_string(),
            "wrong-review" => review_arg = prior_review_path.clone(),
            "changed-review" => fs::write(
                project.join(&targeted_path),
                "Verdict: fail\nDisposition: evidence-needed\nExternal-Condition: Changed after classification.\nAdditional-Proof: Re-run the check.\n",
            )
            .unwrap(),
            "changed-evidence" => fs::write(
                project.join(&snapshot_path),
                br#"{"schema_version":1,"producer":"host","check":"check","working_directory":"/repo","result":"pass","run_at":"2026-09-02T00:00:00Z","output":"changed"}"#,
            )
            .unwrap(),
            "dirty-candidate" => fs::write(project.join("dirty-candidate.txt"), "dirty\n").unwrap(),
            "changed-candidate" => git::run(
                &project,
                &["commit", "--allow-empty", "-m", "Advance candidate frontier"],
                "advance candidate frontier",
            )
            .unwrap(),
            "wrong-candidate-digest" => candidate_arg = "stale-candidate".to_string(),
            "wrong-evidence-digest" => evidence_arg = "sha256:stale".to_string(),
            "absolute-review-path" => {
                let outside = tmp.path().join("outside-review.md");
                fs::write(
                    &outside,
                    "Verdict: fail\nDisposition: evidence-needed\nExternal-Condition: Restore the host.\nAdditional-Proof: Attach proof.\n",
                )
                .unwrap();
                review_arg = outside.display().to_string();
            }
            "changed-review-workspace" => store
                .mutate_work_item("evidence-classify-stale", |item| {
                    let review = item.attempts[0]
                        .tasks
                        .iter_mut()
                        .find(|task| {
                            task.kind == fluent::work_model::TaskKind::Review
                                && task.role == "tests"
                                && task.artifact_area.as_ref().is_some_and(|area| {
                                    format!("{}/review.md", area.path) == targeted_path
                                })
                        })
                        .unwrap();
                    review
                        .review_context
                        .as_mut()
                        .unwrap()
                        .candidate_workspace_path = "../work-stale-candidate".to_string();
                    review
                        .workspace_access
                        .reads
                        .iter_mut()
                        .find(|workspace| workspace.id == "candidate")
                        .unwrap()
                        .path = "../work-stale-candidate".to_string();
                    Ok(())
                })
                .unwrap(),
            "missing-review-evidence-input" => store
                .mutate_work_item("evidence-classify-stale", |item| {
                    let review = item.attempts[0]
                        .tasks
                        .iter_mut()
                        .find(|task| {
                            task.kind == fluent::work_model::TaskKind::Review
                                && task.role == "tests"
                                && task.artifact_area.as_ref().is_some_and(|area| {
                                    format!("{}/review.md", area.path) == targeted_path
                                })
                        })
                        .unwrap();
                    review
                        .input_artifacts
                        .retain(|input| input.producer_id != "host-evidence");
                    Ok(())
                })
                .unwrap(),
            _ => unreachable!("case list is exhaustive"),
        }
        let before = persisted_work_snapshot(&project, "evidence-classify-stale");
        let head_before = git_head(&project);
        let status_before = git::run_stdout(
            &project,
            &["status", "--porcelain", "--untracked-files=all"],
            "snapshot candidate status",
        )
        .unwrap();
        let output = fluent_cmd()
            .current_dir(&project)
            .args([
                "attempt",
                "evidence",
                "classify",
                "evidence-classify-stale",
                &attempt_arg,
                "--candidate",
                &candidate_arg,
                "--review-artifact",
                &review_arg,
                "--evidence-digest",
                &evidence_arg,
                "--resolution",
                "Correct the source.",
            ])
            .output()
            .unwrap();
        assert!(
            !output.status.success(),
            "stale case {case} unexpectedly succeeded: stdout={} stderr={}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        assert_eq!(
            persisted_work_snapshot(&project, "evidence-classify-stale"),
            before,
            "stale case {case} changed persisted model or artifacts"
        );
        assert_eq!(
            git_head(&project),
            head_before,
            "stale case {case} changed HEAD"
        );
        assert_eq!(
            git::run_stdout(
                &project,
                &["status", "--porcelain", "--untracked-files=all"],
                "verify candidate status"
            )
            .unwrap(),
            status_before,
            "stale case {case} changed candidate worktree"
        );
    }
}

#[test]
fn host_evidence_classification_rejects_stale_attempt_state_without_mutation() {
    for case in [
        "attempt-status",
        "pause-kind",
        "review-state",
        "recovery-state",
        "unrelated-task",
    ] {
        let tmp = TempDir::new().unwrap();
        let (project, candidate, _prior_review_path, targeted_path, digest, _snapshot_path) =
            setup_paused_code_change_classification_fixture(&tmp, "evidence-classify-attempt");
        let store = WorkModelStore::new(&project);
        store
            .mutate_work_item("evidence-classify-attempt", |item| {
                let attempt = &mut item.attempts[0];
                match case {
                    "attempt-status" => {
                        attempt.status = fluent::work_model::AttemptStatus::Reviewing;
                    }
                    "pause-kind" => {
                        attempt.pause_kind = Some(fluent::work_model::PauseKind::Auth);
                    }
                    "review-state" => {
                        attempt.review_state = Some(fluent::work_model::AttemptReviewState::Passed);
                    }
                    "recovery-state" => {
                        attempt.evidence_recoveries[0].state =
                            fluent::work_model::EvidenceRecoveryState::Reviewing;
                    }
                    "unrelated-task" => {
                        let mut extra = attempt.tasks[0].clone();
                        extra.id = "attempt-1-write-unrelated".to_string();
                        extra.status = fluent::work_model::TaskStatus::Planned;
                        extra.output = None;
                        extra.artifact_area = Some(fluent::work_model::TaskArtifactArea {
                            path: ".fluent/work/artifacts/evidence-classify-attempt/attempt-1/attempt-1-write-unrelated".to_string(),
                        });
                        extra.created_at = Some(fluent::work_model::now_iso8601());
                        extra.started_at = None;
                        extra.completed_at = None;
                        attempt.tasks.push(extra);
                    }
                    _ => unreachable!("stale Attempt cases are exhaustive"),
                }
                Ok(())
            })
            .unwrap();
        let before = persisted_work_snapshot(&project, "evidence-classify-attempt");
        let output = fluent_cmd()
            .current_dir(&project)
            .args([
                "attempt",
                "evidence",
                "classify",
                "evidence-classify-attempt",
                "attempt-1",
                "--candidate",
                &candidate,
                "--review-artifact",
                &targeted_path,
                "--evidence-digest",
                &digest,
                "--resolution",
                "Correct the source.",
            ])
            .output()
            .unwrap();
        assert!(
            !output.status.success(),
            "stale Attempt case {case} unexpectedly succeeded: stdout={} stderr={}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        assert_eq!(
            persisted_work_snapshot(&project, "evidence-classify-attempt"),
            before,
            "stale Attempt case {case} changed persisted state"
        );
    }
}

