#[test]
fn writer_handoff_preflight_rejects_wrong_or_changed_candidate() {
    use std::os::unix::fs::PermissionsExt;
    let tmp = TempDir::new().unwrap();
    let (project, candidate, head) = setup_active_writer_handoff(&tmp);
    fluent_cmd()
        .current_dir(&project)
        .args([
            "task",
            "check-handoff",
            "handoff-1",
            "attempt-1",
            "attempt-1-write-1",
        ])
        .assert()
        .failure();
    fluent_cmd()
        .current_dir(&candidate)
        .args([
            "task",
            "check-handoff",
            "handoff-1",
            "attempt-1",
            "other-task",
        ])
        .assert()
        .failure();
    let hooks = project.join(".fluent/hooks");
    fs::create_dir_all(&hooks).unwrap();
    let hook = hooks.join("check-pre-merge");
    fs::write(&hook, "#!/bin/sh\nprintf dirty > changed-by-hook.txt\n").unwrap();
    fs::set_permissions(&hook, fs::Permissions::from_mode(0o755)).unwrap();
    let report = run_writer_handoff(&candidate, "attempt-1-write-1");
    assert_ne!(report["overall"], "passed");
    assert!(report["checks"].as_array().unwrap().iter().any(|check| {
        check["name"] == "candidate-gate/project-check" && check["status"] == "not-verifiable"
    }));
    assert_eq!(
        git::run_stdout(
            &candidate,
            &["rev-parse", "HEAD"],
            "check original candidate"
        )
        .unwrap(),
        head
    );
    assert_eq!(
        WorkModelStore::new(&project)
            .read_work_item("handoff-1")
            .unwrap()
            .attempts[0]
            .tasks[0]
            .status,
        TaskStatus::Executing
    );
    assert_writer_handoff_rejects_changed_candidate_during_check();
}

#[test]
fn writer_handoff_preflight_hook_cannot_commit_to_candidate() {
    use std::os::unix::fs::PermissionsExt;
    let tmp = TempDir::new().unwrap();
    let (project, candidate, head) = setup_active_writer_handoff(&tmp);
    let hooks = project.join(".fluent/hooks");
    fs::create_dir_all(&hooks).unwrap();
    let hook = hooks.join("check-pre-merge");
    fs::write(&hook, "#!/bin/sh\nprintf hook > hook-output.txt\ngit add hook-output.txt\ngit -c user.name=Hook -c user.email=hook@example.com commit -m 'Add hook output' >/dev/null\n").unwrap();
    fs::set_permissions(&hook, fs::Permissions::from_mode(0o755)).unwrap();
    let report = run_writer_handoff(&candidate, "attempt-1-write-1");
    assert_ne!(report["overall"], "passed");
    assert_eq!(
        git::run_stdout(
            &candidate,
            &["rev-parse", "HEAD"],
            "read original candidate"
        )
        .unwrap(),
        head
    );
    assert!(!candidate.join("hook-output.txt").exists());
    fs::write(candidate.join("unfinished.txt"), "unfinished\n").unwrap();
    let dirty_report = run_writer_handoff(&candidate, "attempt-1-write-1");
    assert!(
        dirty_report["checks"]
            .as_array()
            .unwrap()
            .iter()
            .any(|check| {
                check["name"] == "candidate-gate" && check["status"] == "not-verifiable"
            })
    );
    assert_eq!(
        git::run_stdout(&candidate, &["rev-parse", "HEAD"], "read dirty candidate").unwrap(),
        head
    );
    assert!(!candidate.join("hook-output.txt").exists());
}

fn assert_writer_handoff_rejects_changed_candidate_during_check() {
    use std::os::unix::fs::PermissionsExt;
    let tmp = TempDir::new().unwrap();
    let (project, candidate, _) = setup_active_writer_handoff(&tmp);
    let hooks = project.join(".fluent/hooks");
    fs::create_dir_all(&hooks).unwrap();
    let hook = hooks.join("check-pre-merge");
    fs::write(&hook, "#!/bin/sh\ntouch \"$FLUENT_TEST_HOOK_SENTINEL\"\nwhile [ ! -f \"$FLUENT_TEST_HOOK_RELEASE\" ]; do sleep 0.02; done\n").unwrap();
    fs::set_permissions(&hook, fs::Permissions::from_mode(0o755)).unwrap();
    let sentinel = tmp.path().join("hook-started");
    let release = tmp.path().join("release-hook");
    let worker_candidate = candidate.clone();
    let worker_sentinel = sentinel.clone();
    let worker_release = release.clone();
    let worker = std::thread::spawn(move || {
        let output = fluent_cmd()
            .current_dir(&worker_candidate)
            .env("FLUENT_TEST_HOOK_SENTINEL", &worker_sentinel)
            .env("FLUENT_TEST_HOOK_RELEASE", &worker_release)
            .args([
                "task",
                "check-handoff",
                "handoff-1",
                "attempt-1",
                "attempt-1-write-1",
            ])
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
        serde_json::from_slice::<serde_json::Value>(&output.stdout).unwrap()
    });
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
    while !sentinel.exists() && std::time::Instant::now() < deadline {
        std::thread::sleep(std::time::Duration::from_millis(10));
    }
    if !sentinel.exists() {
        fs::write(&release, "go").unwrap();
        let _ = worker.join();
        panic!("project hook did not start");
    }
    fs::write(candidate.join("race.txt"), "changed while checking\n").unwrap();
    fs::write(&release, "go").unwrap();
    let report = worker.join().unwrap();
    assert_eq!(report["overall"], "failed");
    assert!(
        report["checks"]
            .as_array()
            .unwrap()
            .iter()
            .any(|check| { check["name"] == "candidate-stability" && check["status"] == "failed" })
    );
    assert_eq!(
        WorkModelStore::new(&project)
            .read_work_item("handoff-1")
            .unwrap()
            .attempts[0]
            .tasks[0]
            .status,
        TaskStatus::Executing
    );
}

#[test]
fn writer_preflight_and_final_handoff_have_check_parity() {
    let tmp = TempDir::new().unwrap();
    let (project, candidate, head) = setup_active_writer_handoff(&tmp);
    let preflight = run_writer_handoff(&candidate, "attempt-1-write-1");
    let store = WorkModelStore::new(&project);
    let mut item = store.read_work_item("handoff-1").unwrap();
    let task = &mut item.attempts[0].tasks[0];
    task.status = TaskStatus::Complete;
    task.output = Some(TaskOutput {
        workspace_id: "candidate".into(),
        workspace_path: task.workspace_access.writes[0].path.clone(),
        source_branch: "main".into(),
        base_commit: Some(git::run_stdout(&project, &["rev-parse", "HEAD"], "read base").unwrap()),
        commit: head.clone(),
        no_change: None,
        learner_canonicalization: None,
    });
    item.attempts[0].status = fluent::work_model::AttemptStatus::Complete;
    store.write_work_item(&item).unwrap();
    let final_report = fluent::work_attempt_loop::check_completed_writer_handoff(
        &project,
        "handoff-1",
        "attempt-1",
        "attempt-1-write-1",
    )
    .unwrap();
    let final_report = serde_json::to_value(final_report).unwrap();
    let states = |report: &serde_json::Value| {
        report["checks"]
            .as_array()
            .unwrap()
            .iter()
            .map(|check| {
                (
                    check["name"].as_str().unwrap().to_string(),
                    check["status"].as_str().unwrap().to_string(),
                )
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(states(&preflight), states(&final_report));
    assert_eq!(
        preflight["candidate_commit"],
        final_report["candidate_commit"]
    );
}

#[test]
fn writer_required_progress_has_preflight_and_final_handoff_parity() {
    use fluent::work_model::{ProgressContract, RequiredProgressEntry, WriterCompletionContract};

    for case in ["pending", "unreadable", "complete"] {
        let tmp = TempDir::new().unwrap();
        let (project, candidate, head) = setup_active_writer_handoff(&tmp);
        let store = WorkModelStore::new(&project);
        let mut item = store.read_work_item("handoff-1").unwrap();
        let requirement = "Complete the Writer change";
        let contract = WriterCompletionContract {
            version: WRITER_COMPLETION_CONTRACT_VERSION,
            requirements: vec![WriterCompletionRequirement {
                responsibility: Some(CompletionResponsibility::Writer),
                id: "plan:step-1".into(),
                kind: WriterCompletionRequirementKind::Plan,
                source: "plan.md#step-1".into(),
                requirement: requirement.into(),
                verification_refs: vec!["cargo test writer_required_progress".into()],
                command: None,
            }],
        };
        let mut matrix =
            WriterCompletionMatrix::skeleton(&contract, "attempt-1-write-1", &[], None).unwrap();
        if case != "pending" {
            matrix.rows[0].state = WriterCompletionState::Complete;
            matrix.rows[0].implementation_evidence = vec!["change.txt committed".into()];
            matrix.rows[0].verification = vec![WriterVerificationClaim {
                command: "cargo test writer_required_progress".into(),
                result: WriterVerificationResult::Pass,
            }];
        }
        let area = project.join(
            &item.attempts[0].tasks[0]
                .artifact_area
                .as_ref()
                .unwrap()
                .path,
        );
        fs::write(
            area.join("writer-completion.json"),
            serde_json::to_vec_pretty(&matrix).unwrap(),
        )
        .unwrap();
        let progress = project.join(".fluent/work/progress/handoff-1/attempt-1/progress.md");
        fs::create_dir_all(progress.parent().unwrap()).unwrap();
        if case == "unreadable" {
            fs::write(&progress, [0xff]).unwrap();
        } else {
            fs::write(
                &progress,
                "## Required completion\n\n- [ ] step-1 — Complete the Writer change\n",
            )
            .unwrap();
        }
        item.attempts[0].writer_completion_contract = Some(contract);
        item.attempts[0].progress_contract = Some(ProgressContract {
            version: fluent::work_model::PROGRESS_CONTRACT_VERSION,
            required: vec![RequiredProgressEntry {
                id: "step-1".into(),
                requirement: requirement.into(),
            }],
        });
        store.write_work_item(&item).unwrap();

        let before_progress = fs::read(&progress).unwrap();
        let preflight = run_writer_handoff(&candidate, "attempt-1-write-1");
        let preflight_check = preflight["checks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|check| check["name"] == "required-progress")
            .unwrap();
        let expected = if case == "complete" {
            "passed"
        } else {
            "failed"
        };
        assert_eq!(preflight_check["status"], expected, "{case}");
        assert_eq!(preflight["overall"], expected, "{case}");
        if case == "pending" {
            assert!(
                preflight_check["diagnostics"][0]
                    .as_str()
                    .unwrap()
                    .contains("completion matrix must pass")
            );
        }
        if case == "unreadable" {
            assert!(
                preflight_check["diagnostics"][0]
                    .as_str()
                    .unwrap()
                    .contains("UTF-8")
            );
        }
        assert_eq!(fs::read(&progress).unwrap(), before_progress, "{case}");

        let task = &mut item.attempts[0].tasks[0];
        task.status = TaskStatus::Complete;
        task.output = Some(TaskOutput {
            workspace_id: "candidate".into(),
            workspace_path: task.workspace_access.writes[0].path.clone(),
            source_branch: "main".into(),
            base_commit: Some(
                git::run_stdout(&project, &["rev-parse", "HEAD"], "read base").unwrap(),
            ),
            commit: head,
            no_change: None,
            learner_canonicalization: None,
        });
        item.attempts[0].status = fluent::work_model::AttemptStatus::Complete;
        store.write_work_item(&item).unwrap();
        let final_report = serde_json::to_value(
            fluent::work_attempt_loop::check_completed_writer_handoff(
                &project,
                "handoff-1",
                "attempt-1",
                "attempt-1-write-1",
            )
            .unwrap(),
        )
        .unwrap();
        let outcomes = |report: &serde_json::Value| {
            report["checks"]
                .as_array()
                .unwrap()
                .iter()
                .map(|check| (check["name"].clone(), check["status"].clone()))
                .collect::<Vec<_>>()
        };
        assert_eq!(outcomes(&preflight), outcomes(&final_report), "{case}");
        assert_eq!(final_report["overall"], expected, "{case}");
        assert_eq!(fs::read(&progress).unwrap(), before_progress, "{case}");
    }
}

#[test]
fn writer_handoff_failure_cases_have_final_check_parity() {
    use std::os::unix::fs::PermissionsExt;
    for case in ["dirty", "gate", "matrix", "host", "hook-context"] {
        let tmp = TempDir::new().unwrap();
        let (project, candidate, head) = setup_active_writer_handoff(&tmp);
        let store = WorkModelStore::new(&project);
        let mut item = store.read_work_item("handoff-1").unwrap();
        let area = project.join(
            &item.attempts[0].tasks[0]
                .artifact_area
                .as_ref()
                .unwrap()
                .path,
        );
        match case {
            "dirty" => fs::write(candidate.join("unfinished.txt"), "unfinished\n").unwrap(),
            "gate" | "hook-context" => {
                let hooks = project.join(".fluent/hooks");
                fs::create_dir_all(&hooks).unwrap();
                let hook = hooks.join("check-pre-merge");
                let script = if case == "gate" {
                    "#!/bin/sh\nexit 9\n"
                } else {
                    "#!/bin/sh\n[ \"$(git branch --show-current)\" = \"\" ]\n"
                };
                fs::write(&hook, script).unwrap();
                fs::set_permissions(&hook, fs::Permissions::from_mode(0o755)).unwrap();
            }
            "matrix" | "host" => {
                item.attempts[0].writer_completion_contract =
                    Some(fluent::work_model::WriterCompletionContract {
                        version: WRITER_COMPLETION_CONTRACT_VERSION,
                        requirements: if case == "host" {
                            vec![WriterCompletionRequirement {
                                responsibility: Some(CompletionResponsibility::Host),
                                id: "plan:step-2".into(),
                                kind: WriterCompletionRequirementKind::Plan,
                                source: "plan.md#step-2".into(),
                                requirement: "Prove confinement".into(),
                                verification_refs: vec!["cargo test confinement".into()],
                                command: Some(fluent::work_model::PlanCommand {
                                    applicability: Default::default(),
                                    command: "cargo test confinement".into(),
                                    working_directory: ".".into(),
                                    environment: Default::default(),
                                    source_row: "plan:step-2".into(),
                                }),
                            }]
                        } else {
                            Vec::new()
                        },
                    });
                if case == "matrix" {
                    fs::write(area.join("writer-completion.json"), "{broken").unwrap();
                } else {
                    let matrix = WriterCompletionMatrix::skeleton(
                        item.attempts[0]
                            .writer_completion_contract
                            .as_ref()
                            .unwrap(),
                        "attempt-1-write-1",
                        &[],
                        None,
                    )
                    .unwrap();
                    fs::write(
                        area.join("writer-completion.json"),
                        serde_json::to_vec_pretty(&matrix).unwrap(),
                    )
                    .unwrap();
                }
                store.write_work_item(&item).unwrap();
            }
            _ => unreachable!(),
        }
        let preflight = run_writer_handoff(&candidate, "attempt-1-write-1");
        let task = &mut item.attempts[0].tasks[0];
        task.status = TaskStatus::Complete;
        task.output = Some(TaskOutput {
            workspace_id: "candidate".into(),
            workspace_path: task.workspace_access.writes[0].path.clone(),
            source_branch: "main".into(),
            base_commit: Some(
                git::run_stdout(&project, &["rev-parse", "HEAD"], "read base").unwrap(),
            ),
            commit: head,
            no_change: None,
            learner_canonicalization: None,
        });
        item.attempts[0].status = fluent::work_model::AttemptStatus::Complete;
        store.write_work_item(&item).unwrap();
        let final_report = serde_json::to_value(
            fluent::work_attempt_loop::check_completed_writer_handoff(
                &project,
                "handoff-1",
                "attempt-1",
                "attempt-1-write-1",
            )
            .unwrap(),
        )
        .unwrap();
        let states = |report: &serde_json::Value| {
            report["checks"]
                .as_array()
                .unwrap()
                .iter()
                .map(|check| (check["name"].clone(), check["status"].clone()))
                .collect::<Vec<_>>()
        };
        assert_eq!(
            preflight["candidate_commit"], final_report["candidate_commit"],
            "{case}"
        );
        assert_eq!(states(&preflight), states(&final_report), "{case}");
        if case == "hook-context" {
            assert_eq!(preflight["overall"], "passed");
        }
    }
}

// -------------------------------------------------------------------------
// Update: helpers
// -------------------------------------------------------------------------

fn target_triple() -> String {
    let arch = std::env::consts::ARCH;
    match std::env::consts::OS {
        "macos" => format!("{arch}-apple-darwin"),
        "linux" => format!("{arch}-unknown-linux-gnu"),
        other => format!("{arch}-{other}"),
    }
}

/// Build a fixture release directory that `fluent update` can fetch via
/// `file://` URLs through curl. Returns (api_base, release_repo) env values.
///
/// The fixture contains:
/// - `repos/{owner}/{repo}/releases/latest` — GitHub API JSON
/// - `download/v{version}/fluent-{triple}` — the binary asset
/// - `download/v{version}/fluent-{triple}.sha256` — its checksum
fn setup_fixture_release(dir: &Path, version: &str, binary_content: &[u8]) -> (String, String) {
    let owner = "test-owner";
    let repo = "fluent";
    let triple = target_triple();
    let asset_name = format!("fluent-{triple}");
    let tag = format!("v{version}");

    let download_dir = dir.join("download").join(&tag);
    fs::create_dir_all(&download_dir).unwrap();

    let binary_path = download_dir.join(&asset_name);
    fs::write(&binary_path, binary_content).unwrap();

    let digest = format!("{:x}", Sha256::digest(binary_content));
    let checksum_name = format!("{asset_name}.sha256");
    let checksum_path = download_dir.join(&checksum_name);
    fs::write(&checksum_path, format!("{digest}  {asset_name}\n")).unwrap();

    let binary_url = format!("file://{}", binary_path.to_string_lossy());
    let checksum_url = format!("file://{}", checksum_path.to_string_lossy());

    let assets = vec![
        serde_json::json!({
            "name": asset_name,
            "browser_download_url": binary_url,
        }),
        serde_json::json!({
            "name": checksum_name,
            "browser_download_url": checksum_url,
        }),
    ];

    let release_json = serde_json::json!({
        "tag_name": tag,
        "assets": assets,
    });

    let api_dir = dir.join("repos").join(owner).join(repo).join("releases");
    fs::create_dir_all(&api_dir).unwrap();
    fs::write(
        api_dir.join("latest"),
        serde_json::to_string_pretty(&release_json).unwrap(),
    )
    .unwrap();

    let api_base = format!("file://{}", dir.to_string_lossy());
    let release_repo = format!("{owner}/{repo}");
    (api_base, release_repo)
}

