#[test]
fn usage_limit_writer_preflight_pause_revalidates_reopen_journal() {
    for route in ["maintenance-read", "upgrade"] {
        let fixture = usage_limit_fixture();
        let paused = usage_limit_preflight_pause(&fixture);
        let source_path = fixture.workspace.join("correction.txt");
        let approved_source = fs::read(&source_path).unwrap();
        usage_limit_retry_command(&fixture)
            .env("FLUENT_TEST_USAGE_LIMIT_INTERRUPT", "prepare-journal")
            .assert()
            .code(86);
        let journal = fixture
            .project
            .join(format!(".fluent/work/transactions/{}.json", fixture.work));
        assert!(journal.exists());

        // Change source while the reopening exists only in the journal. Both
        // maintenance recovery routes must refuse before publishing any Work.
        fs::write(&source_path, "changed before reopen publication").unwrap();
        let before = snapshot_tree(&fixture.project.join(".fluent/work"));
        let source = snapshot_tree(&fixture.workspace);
        let store = WorkModelStore::new(&fixture.project);
        if route == "maintenance-read" {
            let error = store
                .read_work_item(&fixture.work)
                .err()
                .expect("changed source must prevent reopen publication");
            assert!(format!("{error:#}").contains("partial candidate changed"));
        } else {
            fluent_cmd()
                .current_dir(&fixture.project)
                .args(["work-item", "upgrade", &fixture.work])
                .assert()
                .failure()
                .stderr(predicate::str::contains("partial candidate changed"));
        }
        assert_eq!(snapshot_tree(&fixture.project.join(".fluent/work")), before);
        assert_eq!(snapshot_tree(&fixture.workspace), source);
        assert!(!fixture.workspace.join("resumed-source.txt").exists());

        // Restoring the approved bytes lets the same journal publish without
        // another approval, Task, or Writer round.
        fs::write(&source_path, approved_source).unwrap();
        if route == "upgrade" {
            fluent_cmd()
                .current_dir(&fixture.project)
                .args(["work-item", "upgrade", &fixture.work])
                .assert()
                .success();
        }
        let reopened = store.read_work_item(&fixture.work).unwrap();
        assert!(!journal.exists());
        let attempt = &reopened.attempts[0];
        assert_eq!(attempt.status, fluent::work_model::AttemptStatus::Planned);
        assert_eq!(attempt.tasks.last().unwrap().status, TaskStatus::Planned);
        assert_eq!(attempt.tasks.last().unwrap().id, fixture.task);
        assert_eq!(attempt.tasks.len(), paused.attempts[0].tasks.len());
        assert_eq!(
            attempt.recovery_operations,
            paused.attempts[0].recovery_operations
        );
        assert_eq!(
            attempt.materialized_write_rounds(),
            paused.attempts[0].materialized_write_rounds()
        );
        run_usage_limit_retry(&fixture);
    }
}

#[test]
fn usage_limit_writer_preflight_pause_direct_task_revalidates() {
    for changed in [false, true] {
        let fixture = usage_limit_fixture();
        usage_limit_preflight_pause(&fixture);
        let paused = snapshot_tree(&fixture.project.join(".fluent/work"));
        usage_limit_provider_command(&fixture)
            .args([
                "task",
                "run",
                &fixture.work,
                "attempt-1",
                &fixture.task,
                "--no-sandbox",
            ])
            .assert()
            .failure()
            .stderr(predicate::str::contains("expected planned"));
        assert!(
            snapshot_tree(&fixture.project.join(".fluent/work")) == paused,
            "direct Task refusal must not mutate paused Work"
        );
        // Interrupt after the explicit resume publishes preparation, then use
        // the direct public Task route to cross reservation independently.
        usage_limit_retry_command(&fixture)
            .env("FLUENT_TEST_USAGE_LIMIT_INTERRUPT", "prepare-journal")
            .assert()
            .code(86);
        fluent_cmd()
            .current_dir(&fixture.project)
            .args(["work-item", "upgrade", &fixture.work])
            .assert()
            .success();
        if changed {
            fs::write(
                fixture.workspace.join("correction.txt"),
                "changed before reservation",
            )
            .unwrap();
        }
        let before = snapshot_tree(&fixture.project.join(".fluent/work"));
        let mut command = usage_limit_provider_command(&fixture);
        command.args([
            "task",
            "run",
            &fixture.work,
            "attempt-1",
            &fixture.task,
            "--no-sandbox",
        ]);
        if changed {
            command
                .assert()
                .failure()
                .stderr(predicate::str::contains("changed"));
            assert_eq!(snapshot_tree(&fixture.project.join(".fluent/work")), before);
            assert!(!fixture.workspace.join("resumed-source.txt").exists());
        } else {
            command.assert().success();
            fixture.assert_settled();
            assert!(fixture.workspace.join("resumed-source.txt").exists());
        }
    }
}

