#[test]
fn usage_limit_writer_recovery_rejects_unproven_state() {
    for damage in [
        "missing-transcript",
        "model-text",
        "malformed",
        "mismatch",
        "running-record",
        "missing-owner",
        "review-bytes",
        "symlink-transcript",
        "source-symlink-ancestor",
        "directory-lock",
    ] {
        let fixture = usage_limit_fixture();
        match damage {
            "missing-transcript" => fs::remove_file(fixture.failed_area.join("transcript.jsonl")).unwrap(),
            "model-text" => fs::write(fixture.failed_area.join("transcript.jsonl"), "{\"type\":\"item.completed\",\"item\":{\"type\":\"agent_message\",\"text\":\"You've hit your usage limit. Try again later.\"}}\n").unwrap(),
            "malformed" => fs::write(fixture.failed_area.join("transcript.jsonl"), "{unfinished\n").unwrap(),
            "mismatch" => {
                let path = fixture.failed_area.join("transcript.jsonl");
                let bytes = fs::read_to_string(&path).unwrap().replacen("Try again later.", "Other failure.", 1);
                fs::write(path, bytes).unwrap();
            },
            "running-record" => {
                let path = fixture.failed_area.join("execution.json");
                let mut record = read_json_path(&path);
                record["state"] = "running".into();
                fs::write(path, serde_json::to_vec(&record).unwrap()).unwrap();
            },
            "missing-owner" => fs::remove_file(fixture.failed_area.join("execution-owner.lock")).unwrap(),
            "symlink-transcript" => {
                let path = fixture.failed_area.join("transcript.jsonl");
                let moved = fixture._tmp.path().join("unmanaged-transcript");
                fs::rename(&path, &moved).unwrap();
                std::os::unix::fs::symlink(moved, path).unwrap();
            },
            "source-symlink-ancestor" => {
                let path = fixture.workspace.join("expertise");
                let moved = fixture._tmp.path().join("outside-expertise");
                fs::rename(&path, &moved).unwrap();
                std::os::unix::fs::symlink(moved, path).unwrap();
            },
            "directory-lock" => {
                let path = fixture.failed_area.join("execution-owner.lock");
                fs::remove_file(&path).unwrap(); fs::create_dir(path).unwrap();
            },
            "review-bytes" => {
                let item = WorkModelStore::new(&fixture.project).read_work_item(&fixture.work).unwrap();
                let path = &item.attempts[0].tasks.last().unwrap().writer_correction_assignment.as_ref().unwrap().evidence[0].artifact.path;
                fs::write(fixture.project.join(path), "Verdict: pass\n").unwrap();
            },
            _ => unreachable!(),
        }
        let before = snapshot_tree(&fixture.project.join(".fluent/work"));
        let source = snapshot_tree(&fixture.workspace);
        fluent_cmd()
            .current_dir(&fixture.project)
            .args([
                "attempt",
                "recover-usage-limit",
                &fixture.work,
                "attempt-1",
                "--resolution",
                "Continue the saved correction",
            ])
            .assert()
            .failure();
        assert_eq!(
            snapshot_tree(&fixture.project.join(".fluent/work")),
            before,
            "{damage}"
        );
        assert_eq!(snapshot_tree(&fixture.workspace), source, "{damage}");
    }
}

#[test]
fn usage_limit_writer_resume_rejects_stale_or_live_state() {
    for damage in [
        "unstaged",
        "staged",
        "untracked",
        "deleted",
        "mode",
        "symlink-target",
        "symlink-to-file",
        "partial-head",
        "live-task",
        "live-execution",
    ] {
        let fixture = usage_limit_fixture();
        fixture.approve();
        let mut held = None;
        match damage {
            "unstaged" => {
                fs::write(fixture.workspace.join("correction.txt"), "changed again\n").unwrap()
            }
            "deleted" => fs::remove_file(fixture.workspace.join("correction.txt")).unwrap(),
            "mode" => {
                use std::os::unix::fs::PermissionsExt;
                fs::set_permissions(
                    fixture.workspace.join("correction.txt"),
                    fs::Permissions::from_mode(0o755),
                )
                .unwrap();
            }
            "symlink-target" => {
                let path = fixture.workspace.join("CLAUDE.md");
                fs::remove_file(&path).unwrap();
                // The resolved file stays the same; the literal target changes.
                std::os::unix::fs::symlink("./AGENTS.md", path).unwrap();
            }
            "symlink-to-file" => {
                use std::os::unix::fs::PermissionsExt;
                let path = fixture.workspace.join("CLAUDE.md");
                let permissions = fs::symlink_metadata(&path).unwrap().permissions();
                fs::remove_file(&path).unwrap();
                // Keep the bytes and permissions equal to the link's encoding.
                fs::write(&path, "AGENTS.md").unwrap();
                fs::set_permissions(&path, fs::Permissions::from_mode(permissions.mode())).unwrap();
            }
            "staged" => git::run(
                &fixture.workspace,
                &["add", "correction.txt"],
                "change index",
            )
            .unwrap(),
            "untracked" => {
                fs::write(fixture.workspace.join("new-source.txt"), "new bytes\n").unwrap()
            }
            "partial-head" => commit_file(
                &fixture.workspace,
                "other.txt",
                "other\n",
                "Add other source",
            ),
            "live-task" => {
                held = Some(
                    fluent::lease::acquire(&fluent::lease::task_lock_path(
                        &fixture.project,
                        &fixture.work,
                        &fixture.task,
                    ))
                    .unwrap(),
                )
            }
            "live-execution" => {
                held = Some(
                    fluent::lease::acquire(&fixture.failed_area.join("execution-owner.lock"))
                        .unwrap(),
                )
            }
            _ => unreachable!(),
        }
        let before = snapshot_tree(&fixture.project.join(".fluent/work"));
        let source = snapshot_tree(&fixture.workspace);
        fluent_cmd()
            .current_dir(&fixture.project)
            .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
            .assert()
            .failure()
            .stderr(predicate::str::contains("changed").or(predicate::str::contains("ownership")));
        assert_eq!(
            snapshot_tree(&fixture.project.join(".fluent/work")),
            before,
            "{damage}"
        );
        assert_eq!(snapshot_tree(&fixture.workspace), source, "{damage}");
        drop(held);
    }
}

