#[test]
fn usage_limit_writer_recovery_reconciles_interrupted_publication() {
    for boundary in ["audit", "approval-journal", "prepare-journal"] {
        let fixture = usage_limit_fixture();
        if boundary == "prepare-journal" {
            fixture.approve();
        }
        let mut command = fluent_cmd();
        command
            .current_dir(&fixture.project)
            .env("FLUENT_TEST_USAGE_LIMIT_INTERRUPT", boundary);
        if boundary == "prepare-journal" {
            command.args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"]);
        } else {
            command.args([
                "attempt",
                "recover-usage-limit",
                &fixture.work,
                "attempt-1",
                "--resolution",
                "Continue the saved correction",
            ]);
        }
        command.assert().code(86);
        if boundary != "audit" {
            assert!(
                fixture
                    .project
                    .join(format!(".fluent/work/transactions/{}.json", fixture.work))
                    .exists()
            );
        }
        if boundary == "prepare-journal" {
            run_usage_limit_retry(&fixture);
        } else {
            fixture.approve();
        }
        let item = WorkModelStore::new(&fixture.project)
            .read_work_item(&fixture.work)
            .unwrap();
        assert_eq!(
            item.attempts[0]
                .recovery_operations
                .iter()
                .filter(|r| r.operation_kind == "usage-limit-writer-approval")
                .count(),
            1
        );
        assert!(
            !fixture
                .project
                .join(format!(".fluent/work/transactions/{}.json", fixture.work))
                .exists()
        );
    }
}

