    let mut command = usage_limit_retry_command(&fixture);
    let quota = fs::read_to_string(fixture.failed_area.join("transcript.jsonl")).unwrap();
    let script = format!(
        "#!/bin/bash\nif [[ \"${{1:-}} ${{2:-}}\" == \"login status\" ]]; then exit 0; fi\ncat <<'QUOTA'\n{quota}QUOTA\nexit 1\n"
    );
    write_mock_codex(&fixture._tmp.path().join("quota-provider"), &script);
    command.assert().failure();
    let before = snapshot_tree(&fixture.project.join(".fluent/work"));
    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
