fn usage_limit_prepare_confinement_probe(
    fixture: &UsageLimitFixture,
) -> (
    fluent::work_model::WorkItem,
    fluent::codex_worker::CodexWorkerEnvironment,
) {
    fixture.approve();
    fluent_cmd()
        .current_dir(&fixture.project)
        .env("FLUENT_TEST_USAGE_LIMIT_INTERRUPT", "prepare-journal")
        .args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"])
        .assert()
        .code(86);
    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["work-item", "upgrade", &fixture.work])
        .assert()
        .success();
    let item = WorkModelStore::new(&fixture.project)
        .read_work_item(&fixture.work)
        .unwrap();
    let _command = usage_limit_retry_command(fixture);
    let source_home = fixture._tmp.path().join("quota-codex-home");
    // nextest isolates this environment per test process.
    unsafe {
        std::env::set_var("CODEX_HOME", &source_home);
        std::env::set_var(
            "PATH",
            mock_path(&fixture._tmp.path().join("quota-provider")),
        );
        std::env::set_var("FLUENT_TEST_HERMETIC_PROVIDERS", "1");
        std::env::set_var("FLUENT_TEST_HOST_SANDBOX_PREFLIGHT", "pass");
    }
    let worker =
        fluent::codex_worker::CodexWorkerEnvironment::prepare_for_project(&fixture.project)
            .unwrap();
    (item, worker)
}

#[test]
fn usage_limit_writer_recovery_profile_resolves_fixture_paths() {
    let fixture = usage_limit_fixture();
    let (item, worker) = usage_limit_prepare_confinement_probe(&fixture);
    let (git_configs, inactive_config) = usage_limit_git_config_fixture(&fixture);
    let task = item.attempts[0].tasks.last().unwrap();
    // Exercise an alias even when TMPDIR already uses its physical path.
    let alias = fixture._tmp.path().join("probe-alias");
    std::os::unix::fs::symlink(fixture._tmp.path().canonicalize().unwrap(), &alias).unwrap();
    let profile = fluent::work_task_executor::usage_limit_profile_for_test(
        &alias.join("main"),
        task,
        &worker,
    )
    .unwrap();
    let rendered = fs::read_to_string(&profile.path).unwrap();
    let project = fixture.project.canonicalize().unwrap();
    for root in [
        fixture.workspace.clone(),
        project.join(".git"),
        project.join(format!(".fluent/work/progress/{}/attempt-1", fixture.work)),
        project.join(&task.artifact_area.as_ref().unwrap().path),
    ] {
        assert!(
            rendered.contains(&format!(
                "(allow file-write* (subpath \"{}\"))",
                root.display()
            )),
            "retry profile must grant the resolved writable root {}",
            root.display()
        );
    }
    assert!(
        !rendered.contains(&alias.to_string_lossy().to_string()),
        "the probe must resolve aliases before rendering the production profile"
    );
    assert!(!rendered.contains("(allow file-write* (subpath \"/private/var/folders\"))"));
    assert!(!rendered.contains("(allow file-write* (subpath \"/private/tmp\"))"));
    for config in &git_configs {
        assert!(
            rendered.contains(&format!(
                "(allow file-read*  (subpath \"{}\"))",
                config.display()
            )),
            "the retry must read the exact Git configuration file {}",
            config.display()
        );
        for ancestor in config.ancestors() {
            assert!(!rendered.contains(&format!(
                "(allow file-write* (subpath \"{}\"))",
                ancestor.display()
            )));
        }
        for ancestor in config.parent().unwrap().ancestors() {
            for spacing in [" ", "  "] {
                assert!(!rendered.contains(&format!(
                    "(allow file-read*{spacing}(subpath \"{}\"))",
                    ancestor.display()
                )));
            }
        }
    }
    assert!(
        !rendered.contains(inactive_config.to_str().unwrap()),
        "inactive conditional includes must not grant read access"
    );
    let toolchain = PathBuf::from(std::env::var_os("RUSTUP_HOME").unwrap_or_else(|| {
        PathBuf::from(std::env::var_os("HOME").unwrap())
            .join(".rustup")
            .into_os_string()
    }))
    .canonicalize()
    .unwrap();
    assert!(
        rendered.contains(&format!(
            "(allow file-map-executable (subpath \"{}\"))",
            toolchain.display()
        )),
        "the retry must map the installed Rust toolchain"
    );
    // xcrun reads the selection link before it can locate the SDK and linker.
    // Reading only its resolved Xcode directory does not permit that lookup.
    for selection in [
        "/var/select/developer_dir",
        "/private/var/select/developer_dir",
        "/private/var/db/xcode_select_link",
    ] {
        let selection = Path::new(selection);
        if !selection.exists() {
            continue;
        }
        for root in [selection.to_path_buf(), selection.canonicalize().unwrap()] {
            assert!(
                rendered.contains(&format!(
                    "(allow file-read*  (subpath \"{}\"))",
                    root.display()
                )),
                "the retry must read the selected developer link and target: {}",
                root.display()
            );
            for ancestor in root.ancestors() {
                assert!(
                    !rendered.contains(&format!(
                        "(allow file-write* (subpath \"{}\"))",
                        ancestor.display()
                    )),
                    "installed developer tools must remain read-only"
                );
            }
        }
    }
    for parent in ["/var", "/private/var", "/var/select", "/private/var/select"] {
        for spacing in [" ", "  "] {
            assert!(!rendered.contains(&format!(
                "(allow file-read*{spacing}(subpath \"{parent}\"))"
            )));
        }
    }
}

fn usage_limit_git_config_fixture(fixture: &UsageLimitFixture) -> (Vec<PathBuf>, PathBuf) {
    let root = fixture
        ._tmp
        .path()
        .canonicalize()
        .unwrap()
        .join("git-settings");
    fs::create_dir(&root).unwrap();
    let config = root.join("included config");
    let link = root.join("config-link");
    let nested = root.join("nested config");
    let empty = root.join("empty config");
    fs::write(
        &config,
        "[include]\n path = nested config\n path = empty config\n",
    )
    .unwrap();
    fs::write(&nested, "[quota]\n included = readable\n").unwrap();
    fs::write(&empty, "").unwrap();
    std::os::unix::fs::symlink(&config, &link).unwrap();
    let git_dir = fluent::git::run_stdout(
        &fixture.workspace,
        &["rev-parse", "--absolute-git-dir"],
        "locate the retry worktree's Git directory",
    )
    .unwrap();
    fluent::git::run(
        &fixture.workspace,
        &[
            "config",
            "--local",
            &format!("includeIf.gitdir:{git_dir}.path"),
            link.to_str().unwrap(),
        ],
        "include the fixture Git settings",
    )
    .unwrap();
    let inactive = root.join("inactive config");
    fs::write(&inactive, "[quota]\n inactive = unreadable\n").unwrap();
    fluent::git::run(
        &fixture.workspace,
        &[
            "config",
            "--local",
            "includeIf.onbranch:__fluent_inactive_branch__.path",
            inactive.to_str().unwrap(),
        ],
        "declare an inactive conditional include",
    )
    .unwrap();
    (vec![link, config, nested, empty], inactive)
}

#[test]
fn usage_limit_writer_recovery_real_confinement() {
    let mandatory = std::env::var_os("FLUENT_USAGE_LIMIT_REQUIRE_REAL_CONFINEMENT").is_some();
    // Keep the repository outside the worker temp tree: otherwise its ancestor
    // grants can hide a missing private-home capability.
    let fixture_root = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/output");
    fs::create_dir_all(&fixture_root).unwrap();
    let fixture = usage_limit_fixture_in(TempDir::new_in(&fixture_root).unwrap());
    let source_home = std::env::var_os("CODEX_HOME");
    let source_path = std::env::var_os("PATH");
    let (item, hermetic_worker) = usage_limit_prepare_confinement_probe(&fixture);
    let worker = if mandatory {
        // The mandatory host command uses the installed launcher and existing
        // authentication, never the fixture provider or synthetic readiness.
        unsafe {
            match source_home {
                Some(value) => std::env::set_var("CODEX_HOME", value),
                None => std::env::remove_var("CODEX_HOME"),
            }
            std::env::set_var("PATH", source_path.unwrap());
            std::env::remove_var("FLUENT_TEST_HERMETIC_PROVIDERS");
            std::env::remove_var("FLUENT_TEST_HOST_SANDBOX_PREFLIGHT");
        }
        fluent::codex_worker::CodexWorkerEnvironment::prepare_for_project(&fixture.project)
            .expect("prepare production Codex readiness without exposing credentials")
    } else {
        hermetic_worker
    };
    if mandatory {
        assert!(
            !fixture
                .workspace
                .starts_with(std::env::temp_dir().canonicalize().unwrap())
        );
        assert!(
            worker
                .home()
                .starts_with(std::env::temp_dir().canonicalize().unwrap())
        );
    }
    let (git_configs, inactive_config) = usage_limit_git_config_fixture(&fixture);
    let task = item.attempts[0].tasks.last().unwrap();
    let profile =
        fluent::work_task_executor::usage_limit_profile_for_test(&fixture.project, task, &worker)
            .unwrap();
    let rendered = fs::read_to_string(&profile.path).unwrap();
    assert!(!rendered.contains("(allow file-write* (subpath \"/private/var/folders\"))"));
    assert!(!rendered.contains("(allow file-write* (subpath \"/private/tmp\"))"));
    assert!(!rendered.contains(inactive_config.to_str().unwrap()));
    let probe = fluent::os::preflight_profile_with(&profile, |path| {
        Command::new("/usr/bin/sandbox-exec")
            .current_dir(&fixture.workspace)
            .args(["-f"])
            .arg(path)
            .arg("/usr/bin/true")
            .output()
    });
    if let Err(error) = probe {
        assert!(
            !mandatory,
            "required real confinement probe failed: {error:#}"
        );
        assert!(
            format!("{error:#}").contains("Operation not permitted"),
            "unexpected real sandbox probe failure: {error:#}"
        );
        eprintln!("Real confinement remains unproven on this host: {error:#}");
        return;
    }
    let tool_env =
        fluent::work_task_executor::usage_limit_tool_env_for_test(&fixture.project, task).unwrap();
    let cargo = std::env::split_paths(&std::env::var_os("PATH").unwrap())
        .map(|path| path.join("cargo"))
        .find(|path| path.is_file())
        .expect("installed Cargo");
    let installed_cargo = cargo.canonicalize().unwrap();
    let installed_bytes = fs::read(&installed_cargo).unwrap();
    let original_head = git_head(&fixture.workspace);
    let rust_fixture = fixture.workspace.join("confined-rust");
    fs::create_dir_all(rust_fixture.join("src")).unwrap();
    fs::write(rust_fixture.join("Cargo.toml"), "[package]\nname = \"confined-rust\"\nversion = \"0.1.0\"\nedition = \"2024\"\n[workspace]\n").unwrap();
    fs::write(
        rust_fixture.join("src/lib.rs"),
        r#"
#[test]
fn installed_toolchain_compiles_and_runs() {
    assert_eq!(2 + 2, 4);
    std::fs::write("executed.txt", std::env::var("CARGO_HOME").unwrap()).unwrap();
}
"#,
    )
    .unwrap();
    let operator_cache = PathBuf::from(std::env::var_os("HOME").unwrap()).join(".cargo");
    let denied_cache_probe = operator_cache.join(format!("quota-denied-{}", fixture.work));
    assert!(!denied_cache_probe.exists());
    let rustup = PathBuf::from(std::env::var_os("RUSTUP_HOME").unwrap_or_else(|| {
        PathBuf::from(std::env::var_os("HOME").unwrap())
            .join(".rustup")
            .into_os_string()
    }));
    let denied_toolchain_probe = rustup.join(format!("quota-denied-{}", fixture.work));
    assert!(!denied_toolchain_probe.exists());
    let project = fixture.project.canonicalize().unwrap();
    let audit = project.join(
        &item.attempts[0]
            .artifacts
            .iter()
            .find(|a| a.producer_id == "usage-limit-writer-approval")
            .unwrap()
            .path,
    );
    let review = project.join(
        &task.writer_correction_assignment.as_ref().unwrap().evidence[0]
            .artifact
            .path,
    );
    let outside = fixture._tmp.path().join("unrelated-host-file");
    fs::write(&outside, "host-owned\n").unwrap();
    let unrelated_temp = TempDir::new().unwrap();
    let temp_secret = unrelated_temp.path().join("unrelated-content");
    fs::write(&temp_secret, "unrelated temporary content").unwrap();
    let operator_secret = fixture_root.join(format!("operator-content-{}", fixture.work));
    let operator_secret =
        tempfile::NamedTempFile::new_in(operator_secret.parent().unwrap()).unwrap();
    fs::write(operator_secret.path(), "unrelated operator content").unwrap();
    let mut targets = vec![
        fixture
            .failed_area
            .join("transcript.jsonl")
            .canonicalize()
            .unwrap(),
        review,
        audit,
        outside.canonicalize().unwrap(),
        temp_secret.canonicalize().unwrap(),
        operator_secret.path().canonicalize().unwrap(),
    ];
    targets.extend(git_configs);
    let before = targets
        .iter()
        .map(|p| fs::read(p).unwrap())
        .collect::<Vec<_>>();
    let fresh = project
        .join(&task.artifact_area.as_ref().unwrap().path)
        .join("probe.txt");
    let source = fixture.workspace.join("correction.txt");
    let mut continued = fs::read(&source).unwrap();
    continued.extend_from_slice(b"continued");
    let mut command = Command::new("/usr/bin/sandbox-exec");
    command
        .current_dir(&fixture.workspace)
        .arg("-f")
        .arg(&profile.path)
        .envs(tool_env.clone())
        .args([
            // Select the shell directly so this probe does not need access to
            // macOS's /private/var/select/sh or the caller's startup files.
            "/bin/bash",
            "--noprofile",
            "--norc",
            "-c",
            r#"
set -eu
"$4" test --offline --manifest-path "$3" -- --exact installed_toolchain_compiles_and_runs
# Opening for append performs a real write-permission check without changing
# an installed binary even if the boundary is broken.
if (: >> "$5") 2>/dev/null; then exit 20; fi
if (: > "$6") 2>/dev/null; then /bin/rm -f "$6"; exit 21; fi
if (: > "$7") 2>/dev/null; then /bin/rm -f "$7"; exit 22; fi
printf continued >> "$1"
/bin/cat "$1" > "$2"
printf fresh >> "$2"
test "$(/usr/bin/git config quota.included)" = readable
/usr/bin/git add correction.txt
/usr/bin/git -c commit.gpgsign=false commit -m "Continue confined Writer" >/dev/null
for denied_read in "$8" "$9" "${10}"; do
  if /bin/cat "$denied_read" >/dev/null 2>&1; then exit 23; fi
done
shift 10
for target in "$@"; do
  if (printf forbidden > "$target") 2>/dev/null; then exit 19; fi
done
"#,
            "probe",
        ])
        .arg(&source)
        .arg(&fresh)
        .arg(rust_fixture.join("Cargo.toml"))
        .arg(&cargo)
        .arg(&installed_cargo)
        .arg(&denied_cache_probe)
        .arg(&denied_toolchain_probe)
        .arg(&inactive_config)
        .arg(&temp_secret)
        .arg(operator_secret.path())
        .args(&targets);
    let output = command.output().unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    let expected_cache = tool_env
        .iter()
        .find(|(name, _)| name == "CARGO_HOME")
        .unwrap()
        .1
        .clone();
    assert_eq!(
        fs::read_to_string(rust_fixture.join("executed.txt")).unwrap(),
        expected_cache
    );
    assert_eq!(fs::read(&installed_cargo).unwrap(), installed_bytes);
    assert!(!denied_cache_probe.exists());
    assert!(!denied_toolchain_probe.exists());
    assert_ne!(git_head(&fixture.workspace), original_head);
    assert_eq!(fs::read(&source).unwrap(), continued);
    continued.extend_from_slice(b"fresh");
    assert_eq!(fs::read(&fresh).unwrap(), continued);
    for (path, bytes) in targets.iter().zip(before) {
        assert_eq!(fs::read(path).unwrap(), bytes);
    }
}

struct UsageLimitCliRunner<'a>(&'a UsageLimitFixture);
impl fluent::scheduler::AttemptRunner for UsageLimitCliRunner<'_> {
    fn run(
        &self,
        project: &Path,
        work: &str,
        attempt: &str,
        _: bool,
    ) -> anyhow::Result<fluent::scheduler::AttemptOutcome> {
        let ledger = fluent::queue::read_ledger(project, work)?.unwrap();
        let output = usage_limit_retry_command(self.0)
            .args(["--dispatch-id", &ledger.active().unwrap().dispatch_id])
            .output()?;
        anyhow::ensure!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
        fluent::scheduler::classify_attempt_outcome(project, work, attempt)
    }
}

#[test]
fn usage_limit_writer_recovery_scheduler_claim_drives_same_task() {
    let fixture = usage_limit_fixture();
    fixture.approve();
    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
        .assert()
        .success();
    let dispatch = fluent::scheduler::pick_next_queued(&fixture.project)
        .unwrap()
        .unwrap();
    fluent::scheduler::dispatch_one(&fixture.project, &dispatch, &UsageLimitCliRunner(&fixture))
        .unwrap();
    fixture.assert_settled();
    let item = WorkModelStore::new(&fixture.project)
        .read_work_item(&fixture.work)
        .unwrap();
    assert_eq!(
        item.attempts[0]
            .tasks
            .iter()
            .find(|t| t.id == fixture.task)
            .unwrap()
            .status,
        TaskStatus::Complete
    );
    assert_eq!(
        item.attempts[0]
            .tasks
            .iter()
            .filter(|t| t.kind == fluent::work_model::TaskKind::Write)
            .count(),
        2
    );
    assert!(!fluent::lease::is_leased(
        &fluent::queue::dispatch_lease_path(&fixture.project, &fixture.work)
    ));
}

#[test]
fn usage_limit_writer_recovery_scheduler_rejects_changed_candidate_at_claim() {
    let fixture = usage_limit_fixture();
    fixture.approve();
    fluent_cmd()
        .current_dir(&fixture.project)
        .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
        .assert()
        .success();
    let dispatch = fluent::scheduler::pick_next_queued(&fixture.project)
        .unwrap()
        .unwrap();
    fs::write(
        fixture.workspace.join("new-source.txt"),
        "changed before claim\n",
    )
    .unwrap();
    let before = snapshot_tree(&fixture.project.join(".fluent/work"));
    assert!(
        fluent::scheduler::dispatch_one(
            &fixture.project,
            &dispatch,
            &UsageLimitCliRunner(&fixture)
        )
        .is_err()
    );
    assert_eq!(snapshot_tree(&fixture.project.join(".fluent/work")), before);
    assert!(!fixture.workspace.join("resumed-source.txt").exists());
}

const USAGE_LIMIT_OLD_SOURCE: &str = "5c670fdd9eec7eda22e93aee4ea619f1c60f7a70";

fn usage_limit_old_reader() -> PathBuf {
    let binary = writer_assignment_old_reader("FLUENT_USAGE_LIMIT_OLD_BIN", USAGE_LIMIT_OLD_SOURCE);
    let root = binary.parent().unwrap().parent().unwrap().parent().unwrap();
    let archive = git::run_raw(
        Path::new(env!("CARGO_MANIFEST_DIR")),
        &["archive", USAGE_LIMIT_OLD_SOURCE],
    )
    .unwrap();
    assert!(archive.status.success());
    assert_eq!(
        read_json_path(&root.join("identity.json"))["source_archive_sha256"],
        format!("{:x}", Sha256::digest(archive.stdout))
    );
    binary
}

fn usage_limit_old_mutation_refuses(binary: &Path, fixture: &UsageLimitFixture) {
    let before = snapshot_tree(&fixture.project.join(".fluent/work"));
    let candidate = snapshot_tree(&fixture.workspace);
    let result = Command::new(binary)
        .current_dir(&fixture.project)
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .args(["work-item", "upgrade", &fixture.work])
        .output()
        .unwrap();
    assert!(
        !result.status.success(),
        "older reader accepted usage-limit authority"
    );
    let error = String::from_utf8_lossy(&result.stderr);
    assert!(
        error.contains("schema") || error.contains("transaction"),
        "{error}"
    );
    assert_eq!(snapshot_tree(&fixture.project.join(".fluent/work")), before);
    assert_eq!(snapshot_tree(&fixture.workspace), candidate);
}

#[test]
fn usage_limit_writer_compatibility_refuses_published_authority() {
    let binary = usage_limit_old_reader();
    for fence in ["envelope", "root", "attempt"] {
        let fixture = usage_limit_fixture();
        fixture.approve();
        let path = fixture
            .project
            .join(format!(".fluent/work/items/{}.json", fixture.work));
        let mut record = read_json_path(&path);
        if fence != "envelope" {
            record["model_writer_version"]["schema_version"] = 4.into();
        }
        if fence == "attempt" {
            record["schema_version"] = 6.into();
        }
        write_json_path(&path, &record);
        usage_limit_old_mutation_refuses(&binary, &fixture);
        fixture.approve();
        let item = WorkModelStore::new(&fixture.project)
            .read_work_item(&fixture.work)
            .unwrap();
        assert_eq!(item.attempts[0].recovery_operations.len(), 1);
    }
}

#[test]
fn usage_limit_writer_compatibility_refuses_public_pending_transaction() {
    let binary = usage_limit_old_reader();
    let fixture = usage_limit_fixture();
    // Construct legacy envelopes before invoking the new public operation, so
    // the old executable reaches the genuine interrupted journal's inner fence.
    for path in [
        fixture
            .project
            .join(format!(".fluent/work/items/{}.json", fixture.work)),
        fixture.project.join(format!(
            ".fluent/work/attempts/{}/attempt-1.json",
            fixture.work
        )),
    ] {
        let mut record = read_json_path(&path);
        record["schema_version"] = 6.into();
        if record.get("model_writer_version").is_some() {
            record["model_writer_version"]["schema_version"] = 4.into();
        }
        write_json_path(&path, &record);
    }
    fluent_cmd()
        .current_dir(&fixture.project)
        .env("FLUENT_TEST_USAGE_LIMIT_INTERRUPT", "approval-journal")
        .args([
            "attempt",
            "recover-usage-limit",
            &fixture.work,
            "attempt-1",
            "--resolution",
            "Continue the saved correction",
        ])
        .assert()
        .code(86);
    let journal = fixture
        .project
        .join(format!(".fluent/work/transactions/{}.json", fixture.work));
    assert_eq!(read_json_path(&journal)["schema_version"], 14);
    usage_limit_old_mutation_refuses(&binary, &fixture);
    fixture.approve();
    fixture.approve();
    assert!(!journal.exists());
    let item = WorkModelStore::new(&fixture.project)
        .read_work_item(&fixture.work)
        .unwrap();
    assert_eq!(item.attempts[0].recovery_operations.len(), 1);
    assert_eq!(
        item.attempts[0].tasks.last().unwrap().status,
        TaskStatus::Failed
    );
}

