#[test]
fn usage_limit_committed_matrix_recovery_rejects_changed_partial_work() {
    for queued in [false, true] {
        let fixture = usage_limit_committed_matrix_fixture();
        fixture.approve();
        fs::write(
            fixture.workspace.join("correction.txt"),
            "changed after approval\n",
        )
        .unwrap();
        let before = snapshot_tree(&fixture.project.join(".fluent/work"));
        let source = snapshot_tree(&fixture.workspace);
        let mut command = fluent_cmd();
        command.current_dir(&fixture.project);
        if queued {
            command.args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"]);
        } else {
            command.args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"]);
        }
        command
            .assert()
            .failure()
            .stderr(predicate::str::contains("partial candidate changed"));
        assert_eq!(snapshot_tree(&fixture.project.join(".fluent/work")), before);
        assert_eq!(snapshot_tree(&fixture.workspace), source);
        assert!(!fixture.workspace.join("resumed-source.txt").exists());
    }
}

fn assert_usage_limit_completion_recovery_resume(queued: bool, repeated_quota: bool) {
    let fixture = usage_limit_fixture_with_history(TempDir::new().unwrap(), true);
    assert_usage_limit_completion_recovery_resume_with(fixture, queued, repeated_quota);
}

fn assert_usage_limit_completion_recovery_resume_with(
    fixture: UsageLimitFixture,
    queued: bool,
    repeated_quota: bool,
) {
    let store = WorkModelStore::new(&fixture.project);
    let before = store.read_work_item_snapshot(&fixture.work).unwrap();
    let failed = before.attempts[0].tasks.last().unwrap();
    let completion = failed
        .input_artifacts
        .iter()
        .find(|a| a.producer_id == "writer-completion-recovery")
        .unwrap();
    let completion_bytes = fs::read(fixture.project.join(&completion.path)).unwrap();
    let failure_bytes = snapshot_tree(&fixture.failed_area);
    fixture.approve();
    let approved = store.read_work_item_snapshot(&fixture.work).unwrap();
    assert_eq!(approved.attempts[0].tasks, before.attempts[0].tasks);
    let saved = snapshot_tree(&fixture.project.join(".fluent/work"));
    fluent_cmd()
        .current_dir(&fixture.project)
        .arg("status")
        .assert()
        .success()
        .stdout(predicate::str::contains(format!(
            "fluent attempt run {} attempt-1",
            fixture.work
        )))
        .stderr(predicate::str::contains("recover assignment context").not());
    assert_eq!(snapshot_tree(&fixture.project.join(".fluent/work")), saved);
    if repeated_quota {
        let mut command = usage_limit_retry_command(&fixture);
        let quota = fs::read_to_string(fixture.failed_area.join("transcript.jsonl")).unwrap();
        write_mock_codex(
            &fixture._tmp.path().join("quota-provider"),
            &format!(
                "#!/bin/bash\nif [[ \"${{1:-}} ${{2:-}}\" == \"login status\" ]]; then exit 0; fi\ncat <<'QUOTA'\n{quota}QUOTA\nexit 1\n"
            ),
        );
        command.assert().failure();
        fixture.assert_settled();
        let stopped = snapshot_tree(&fixture.project.join(".fluent/work"));
        for args in [
            vec!["queue", "resume", &fixture.work, "--attempt", "attempt-1"],
            vec!["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"],
        ] {
            fluent_cmd()
                .current_dir(&fixture.project)
                .args(args)
                .assert()
                .failure()
                .stderr(predicate::str::contains("cannot restart"));
            assert_eq!(
                snapshot_tree(&fixture.project.join(".fluent/work")),
                stopped
            );
        }
        fixture.approve();
    }
    if queued {
        fluent_cmd()
            .current_dir(&fixture.project)
            .args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"])
            .assert()
            .success();
        let dispatch = fluent::scheduler::pick_next_queued(&fixture.project)
            .unwrap()
            .unwrap();
        fluent::scheduler::dispatch_one(
            &fixture.project,
            &dispatch,
            &UsageLimitCliRunner(&fixture),
        )
        .unwrap();
        fixture.assert_settled();
    } else {
        run_usage_limit_retry(&fixture);
    }
    let after = store.read_work_item_snapshot(&fixture.work).unwrap();
    let attempt = &after.attempts[0];
    let writer = attempt.tasks.iter().find(|t| t.id == fixture.task).unwrap();
    assert_eq!(writer.status, TaskStatus::Complete);
    assert_eq!(
        writer.writer_correction_assignment,
        failed.writer_correction_assignment
    );
    assert!(writer.input_artifacts.contains(completion));
    assert_eq!(
        attempt.materialized_write_rounds(),
        before.attempts[0].materialized_write_rounds()
    );
    assert_eq!(
        attempt.round_cap_extensions,
        before.attempts[0].round_cap_extensions
    );
    assert_eq!(attempt.coder_mapping, before.attempts[0].coder_mapping);
    assert!(
        !attempt
            .recovery_operations
            .iter()
            .any(|r| r.operation_kind.starts_with("writer-completion-context-"))
    );
    assert_eq!(
        fs::read(fixture.project.join(&completion.path)).unwrap(),
        completion_bytes
    );
    assert_eq!(snapshot_tree(&fixture.failed_area), failure_bytes);
    assert_eq!(
        fs::read_to_string(fixture.workspace.join("resumed-source.txt")).unwrap(),
        "unfinished tracked correction\nunfinished untracked correction\n"
    );
}

#[test]
fn usage_limit_writer_completion_recovery_rejects_invalid_approval() {
    for queued in [false, true] {
        for damage in [
            "missing-approval",
            "changed-candidate",
            "changed-approval",
            "changed-transcript",
            "changed-instructions",
        ] {
            let fixture = usage_limit_fixture_with_history(TempDir::new().unwrap(), true);
            if damage != "missing-approval" {
                fixture.approve();
            }
            match damage {
                "missing-approval" => {}
                "changed-candidate" => fs::write(
                    fixture.workspace.join("new-source.txt"),
                    "changed after approval\n",
                )
                .unwrap(),
                "changed-transcript" => {
                    fs::write(fixture.failed_area.join("transcript.jsonl"), "{}\n").unwrap()
                }
                "changed-instructions" => {
                    let store = WorkModelStore::new(&fixture.project);
                    let mut item = store.read_work_item_snapshot(&fixture.work).unwrap();
                    item.attempts[0]
                        .tasks
                        .last_mut()
                        .unwrap()
                        .instructions
                        .as_mut()
                        .unwrap()
                        .push_str("\nUnaudited retry instruction");
                    store.write_work_item(&item).unwrap();
                }
                "changed-approval" => {
                    let item = WorkModelStore::new(&fixture.project)
                        .read_work_item_snapshot(&fixture.work)
                        .unwrap();
                    let approval = item.attempts[0]
                        .artifacts
                        .iter()
                        .find(|a| a.path.ends_with("/approval.json"))
                        .unwrap();
                    fs::write(fixture.project.join(&approval.path), "{}\n").unwrap();
                }
                _ => unreachable!(),
            }
            let before = snapshot_tree(&fixture.project.join(".fluent/work"));
            let source = snapshot_tree(&fixture.workspace);
            let mut command = fluent_cmd();
            command.current_dir(&fixture.project);
            if queued {
                command.args(["queue", "resume", &fixture.work, "--attempt", "attempt-1"]);
            } else {
                command.args(["attempt", "run", &fixture.work, "attempt-1", "--no-sandbox"]);
            }
            command.assert().failure();
            assert_eq!(
                snapshot_tree(&fixture.project.join(".fluent/work")),
                before,
                "queued={queued}, {damage}"
            );
            assert_eq!(
                snapshot_tree(&fixture.workspace),
                source,
                "queued={queued}, {damage}"
            );
            assert!(!fixture.workspace.join("resumed-source.txt").exists());
        }
    }
}

fn write_sandboxed_mock_claude(bin_dir: &Path, script: &str) {
    write_mock_claude(bin_dir, script);
    write_mock_sandbox_exec(bin_dir);
}

fn restore_snapshot_preserving(root: &Path, before: &[SnapshotEntry], preserve: &Path) {
    let preserve_relative = preserve.strip_prefix(root).unwrap();
    let current = snapshot_tree(root);
    for entry in current.iter().rev() {
        let is_preserved =
            entry.path == preserve_relative || preserve_relative.starts_with(&entry.path);
        if is_preserved || before.iter().any(|saved| saved.path == entry.path) {
            continue;
        }
        let path = root.join(&entry.path);
        match entry.kind {
            "directory" => fs::remove_dir(&path).unwrap(),
            "file" | "symlink" => fs::remove_file(&path).unwrap(),
            kind => panic!("unknown snapshot entry kind {kind:?}"),
        }
    }
    for entry in before {
        let path = root.join(&entry.path);
        match entry.kind {
            "directory" => fs::create_dir_all(&path).unwrap(),
            "file" => {
                fs::create_dir_all(path.parent().unwrap()).unwrap();
                fs::write(&path, &entry.bytes).unwrap();
            }
            "symlink" => panic!("snapshot restoration does not support symlinks"),
            kind => panic!("unknown snapshot entry kind {kind:?}"),
        }
    }
}

