#[test]
#[serial]
fn round_cap_approach_revision_replays_historical_plan_applicability_in_source_workspace() {
    let fixture = setup_round_cap_approach_revision_fixture_with_accepted_host_evidence();
    approve_round_cap_extension(&fixture);
    revise_round_cap_approach(&fixture).success();

    let prompt_log = fixture
        ._tmp
        .path()
        .join("historical-applicability-prompts.log");
    let bin = fixture
        ._tmp
        .path()
        .join("historical-applicability-provider");
    write_sandboxed_mock_claude(&bin, &round_cap_downstream_provider_script(&prompt_log));
    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .env("PATH", mock_path(&bin))
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success();

    let stored = fixture.store.read_work_item("work-1").unwrap();
    let attempt = &stored.attempts[0];
    let latest_writer = attempt
        .tasks
        .iter()
        .rev()
        .find(|task| task.kind == fluent::work_model::TaskKind::Write)
        .unwrap();
    assert_eq!(
        latest_writer.status,
        fluent::work_model::TaskStatus::Complete,
        "the corrective Writer must finish after historical receipt replay"
    );
    assert_ne!(
        latest_writer.output.as_ref().unwrap().commit,
        fixture.candidate,
        "the test must exercise a newer candidate workspace"
    );
    assert_eq!(
        attempt.status,
        fluent::work_model::AttemptStatus::NeedsUser,
        "the newer candidate still waits for its current host-owned row"
    );
    assert_eq!(
        attempt.pause_kind,
        Some(fluent::work_model::PauseKind::WriterCompletion)
    );
    assert_eq!(
        attempt
            .evidence_recoveries
            .iter()
            .find(|recovery| recovery.candidate_commit == fixture.candidate)
            .map(|recovery| recovery.state.clone()),
        Some(fluent::work_model::EvidenceRecoveryState::Complete)
    );
}

#[test]
#[serial]
fn round_cap_approach_revision_replays_bound_frontier_after_writer_completion() {
    let fixture = setup_round_cap_approach_revision_fixture_with_accepted_host_evidence();
    approve_round_cap_extension(&fixture);
    revise_round_cap_approach(&fixture).success();

    let prompt_log = fixture._tmp.path().join("historical-frontier-prompts.log");
    let bin = fixture._tmp.path().join("historical-frontier-provider");
    write_sandboxed_mock_claude(&bin, &round_cap_downstream_provider_script(&prompt_log));
    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .env("PATH", mock_path(&bin))
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success();

    let completed = fixture.store.read_work_item("work-1").unwrap();
    assert!(completed.attempts[0].tasks.iter().any(|task| {
        task.role == "approach-revision-correction"
            && task.status == fluent::work_model::TaskStatus::Complete
    }));
    let audit_ref = completed.attempts[0]
        .artifacts
        .iter()
        .find(|artifact| artifact.producer_id == "planning-approach-recovery")
        .unwrap();
    let audit_path = fixture.main_dir.join(&audit_ref.path);
    let mut audit = read_json_path(&audit_path);
    audit["round-cap-extension"]["pre-extension-write-rounds"] = serde_json::json!(0);
    write_json_path(&audit_path, &audit);
    let audit_bytes = fs::read(&audit_path).unwrap();
    let audit_digest = format!("{:x}", Sha256::digest(&audit_bytes));
    let request = fluent::work_model::RecoveryOperationRequest::new(
        "planning-approach-revision",
        "work-1",
        "attempt-1",
        Some(audit["candidate-commit"].as_str().unwrap().to_string()),
        Some(audit["source-review-task-id"].as_str().unwrap().to_string()),
        None,
        None,
        Some(audit["resolution"].as_str().unwrap().to_string()),
        Some(audit_digest.clone()),
    );

    let attempt_path = fixture
        .main_dir
        .join(".fluent/work/attempts/work-1/attempt-1.json");
    let mut attempt = read_json_path(&attempt_path);
    attempt["round_cap_extensions"][0]["pre_extension_write_rounds"] = serde_json::json!(0);
    for operation in attempt["recovery_operations"].as_array_mut().unwrap() {
        if operation["operation-kind"] == "planning-approach-revision" {
            operation["operation-id"] = serde_json::json!(request.operation_id());
            operation["input-digest"] = serde_json::json!(audit_digest);
        }
    }
    write_json_path(&attempt_path, &attempt);
    assert_eq!(
        fixture.store.read_work_item("work-1").unwrap().attempts[0].round_cap_extensions[0]
            .pre_extension_write_rounds,
        Some(0)
    );

    let prompt_count = fs::read_to_string(&prompt_log)
        .unwrap()
        .matches("--- invocation ---")
        .count();
    revise_round_cap_approach(&fixture)
        .failure()
        .stderr(predicate::str::contains("pre-extension Writer rounds"));
    assert_eq!(
        fs::read_to_string(&prompt_log)
            .unwrap()
            .matches("--- invocation ---")
            .count(),
        prompt_count,
        "historical frontier rejection must not launch another provider"
    );
}

#[test]
#[serial]
fn round_cap_approach_revision_resumes_after_a_second_revision() {
    let fixture = setup_round_cap_approach_revision_fixture();
    make_round_cap_behavior_testable(&fixture);
    approve_round_cap_extension(&fixture);

    let prompt_log = fixture._tmp.path().join("two-revision-prompts.log");
    let bin = fixture._tmp.path().join("two-revision-provider");
    write_sandboxed_mock_claude(&bin, &round_cap_two_revision_provider_script(&prompt_log));
    revise_round_cap_approach(&fixture).success();
    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .env("PATH", mock_path(&bin))
        .env("FLUENT_MAX_TOTAL_WRITE_ROUNDS", "1")
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success();

    let first_round = fixture.store.read_work_item("work-1").unwrap();
    let first_attempt = &first_round.attempts[0];
    assert_eq!(first_attempt.round_cap_extensions.len(), 1);
    assert_eq!(
        first_attempt.pause_kind,
        Some(fluent::work_model::PauseKind::RoundCap),
        "the first failed corrective review must pause at the round cap"
    );
    assert_eq!(
        first_attempt
            .tasks
            .iter()
            .filter(|task| task.kind == fluent::work_model::TaskKind::Write)
            .count(),
        2
    );

    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .args([
            "attempt",
            "extend",
            "work-1",
            "attempt-1",
            "--additional-write-rounds",
            "1",
            "--resolution",
            "Approve the second bounded corrective Approach revision.",
        ])
        .env("FLUENT_MAX_TOTAL_WRITE_ROUNDS", "2")
        .assert()
        .success();
    let second_approach =
        "# Second Revised Approach\n\nUse the second approved corrective boundary.\n";
    revise_round_cap_approach_with_values(
        &fixture,
        second_approach,
        "Approve the second bounded corrective Approach revision.",
    )
    .success();

    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .env("PATH", mock_path(&bin))
        .env("FLUENT_MAX_TOTAL_WRITE_ROUNDS", "2")
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success();

    let stored = fixture.store.read_work_item("work-1").unwrap();
    let attempt = &stored.attempts[0];
    assert_eq!(
        attempt
            .artifacts
            .iter()
            .filter(|artifact| artifact.producer_id == "planning-approach-recovery")
            .count(),
        2,
        "both Approach revisions must remain in chronological history"
    );
    assert_eq!(
        attempt
            .tasks
            .iter()
            .filter(|task| task.role == "approach-revision-correction")
            .count(),
        2,
        "the second revision must prepare one additional corrective Writer"
    );
    let latest_writer = attempt
        .tasks
        .iter()
        .rev()
        .find(|task| task.kind == fluent::work_model::TaskKind::Write)
        .unwrap();
    assert_eq!(
        latest_writer.status,
        fluent::work_model::TaskStatus::Complete,
        "resume must reach the second corrective Writer"
    );
    assert_eq!(
        attempt.pause_kind,
        Some(fluent::work_model::PauseKind::RoundCap),
        "the second failed corrective review must remain at the round cap"
    );
}

#[test]
#[serial]
fn round_cap_approach_revision_does_not_deduplicate_a_new_frontier() {
    let fixture = setup_round_cap_approach_revision_fixture();
    make_round_cap_behavior_testable(&fixture);
    approve_round_cap_extension(&fixture);

    let prompt_log = fixture._tmp.path().join("same-input-frontier-prompts.log");
    let bin = fixture._tmp.path().join("same-input-frontier-provider");
    write_sandboxed_mock_claude(&bin, &round_cap_two_revision_provider_script(&prompt_log));
    revise_round_cap_approach(&fixture).success();
    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .env("PATH", mock_path(&bin))
        .env("FLUENT_MAX_TOTAL_WRITE_ROUNDS", "1")
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success();

    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .args([
            "attempt",
            "extend",
            "work-1",
            "attempt-1",
            "--additional-write-rounds",
            "1",
            "--resolution",
            &fixture.resolution,
        ])
        .env("FLUENT_MAX_TOTAL_WRITE_ROUNDS", "2")
        .assert()
        .success();
    revise_round_cap_approach_with_values(&fixture, &fixture.replacement, &fixture.resolution)
        .success();

    let stored = fixture.store.read_work_item("work-1").unwrap();
    let attempt = &stored.attempts[0];
    let audits: Vec<_> = attempt
        .artifacts
        .iter()
        .filter(|artifact| artifact.producer_id == "planning-approach-recovery")
        .collect();
    assert_eq!(audits.len(), 2, "a new bound frontier needs a new audit");
    assert_ne!(
        read_json_path(&fixture.main_dir.join(&audits[0].path))["revision-id"],
        read_json_path(&fixture.main_dir.join(&audits[1].path))["revision-id"],
        "same text on a new candidate frontier must not reuse the old identity"
    );
    assert_eq!(
        attempt
            .tasks
            .iter()
            .filter(|task| task.role == "approach-revision-correction")
            .count(),
        2
    );
}

#[test]
#[serial]
fn round_cap_approach_revision_resume_preserves_downstream_gates() {
    let direct = setup_round_cap_approach_revision_fixture_with_downstream_gates();
    approve_round_cap_extension(&direct);
    revise_round_cap_approach(&direct).success();
    let direct_prompt_log = direct._tmp.path().join("direct-gates-provider-prompts.log");
    let direct_bin = direct._tmp.path().join("direct-gates-provider");
    write_sandboxed_mock_claude(
        &direct_bin,
        &round_cap_downstream_provider_script(&direct_prompt_log),
    );

    fluent_cmd()
        .current_dir(&direct.main_dir)
        .env("PATH", mock_path(&direct_bin))
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success();
    let direct_after = direct.store.read_work_item("work-1").unwrap();
    let direct_attempt = &direct_after.attempts[0];
    let responsibilities: Vec<_> = direct_attempt
        .writer_completion_contract
        .as_ref()
        .unwrap()
        .requirements
        .iter()
        .filter_map(|row| row.responsibility)
        .collect();
    assert!(responsibilities.contains(&fluent::work_model::CompletionResponsibility::Host));
    assert!(responsibilities.contains(&fluent::work_model::CompletionResponsibility::Review));
    assert!(responsibilities.contains(&fluent::work_model::CompletionResponsibility::Tester));
    assert!(responsibilities.contains(&fluent::work_model::CompletionResponsibility::Learner));
    assert_eq!(
        direct_attempt.status,
        fluent::work_model::AttemptStatus::NeedsUser
    );
    assert_eq!(
        direct_attempt.pause_kind,
        Some(fluent::work_model::PauseKind::WriterCompletion)
    );
    assert_eq!(
        direct_attempt
            .tasks
            .iter()
            .filter(|task| task.kind == fluent::work_model::TaskKind::Write)
            .count(),
        2
    );
    assert!(direct_attempt.learning.is_none());
    let direct_prompt = fs::read_to_string(&direct_prompt_log).unwrap();
    let direct_writer_invocations = direct_prompt.matches("--- invocation ---").count();
    assert_eq!(direct_writer_invocations, 1);

    let direct_writer_count = direct_attempt
        .tasks
        .iter()
        .filter(|task| task.kind == fluent::work_model::TaskKind::Write)
        .count();
    fluent_cmd()
        .current_dir(&direct.main_dir)
        .env("PATH", mock_path(&direct_bin))
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .failure()
        .stderr(predicate::str::contains("plan:step-2"));
    assert_eq!(
        fs::read_to_string(&direct_prompt_log)
            .unwrap()
            .matches("--- invocation ---")
            .count(),
        direct_writer_invocations,
        "missing host proof must block another foreground provider launch"
    );
    assert_eq!(
        direct.store.read_work_item("work-1").unwrap().attempts[0]
            .tasks
            .iter()
            .filter(|task| task.kind == fluent::work_model::TaskKind::Write)
            .count(),
        direct_writer_count
    );
    let direct_snapshot = attach_round_cap_host_evidence(&direct, "direct");
    let direct_original_evidence = fs::read(&direct_snapshot).unwrap();
    fs::write(&direct_snapshot, b"changed host proof\n").unwrap();
    fluent_cmd()
        .current_dir(&direct.main_dir)
        .env("PATH", mock_path(&direct_bin))
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .failure()
        .stderr(predicate::str::contains("digest changed"));
    assert_eq!(
        direct.store.read_work_item("work-1").unwrap().attempts[0]
            .tasks
            .iter()
            .filter(|task| task.kind == fluent::work_model::TaskKind::Write)
            .count(),
        direct_writer_count,
        "changed host proof must not dispatch another Writer"
    );
    fs::write(&direct_snapshot, &direct_original_evidence).unwrap();
    fluent_cmd()
        .current_dir(&direct.main_dir)
        .env("PATH", mock_path(&direct_bin))
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success();
    assert_round_cap_downstream_completion(&direct);
    let direct_before_late_tamper = direct.store.read_work_item("work-1").unwrap();
    fs::remove_file(&direct_snapshot).unwrap();
    fluent_cmd()
        .current_dir(&direct.main_dir)
        .env("PATH", mock_path(&direct_bin))
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .failure();
    assert_eq!(
        direct.store.read_work_item("work-1").unwrap(),
        direct_before_late_tamper,
        "missing accepted proof must block the completed downstream frontier"
    );
    fs::write(&direct_snapshot, &direct_original_evidence).unwrap();

    let queued = setup_round_cap_approach_revision_fixture_with_downstream_gates();
    approve_round_cap_extension(&queued);
    revise_round_cap_approach(&queued).success();
    let queued_prompt_log = queued._tmp.path().join("queued-gates-provider-prompts.log");
    let queued_bin = queued._tmp.path().join("queued-gates-provider");
    write_scheduler_claude(
        &queued_bin,
        &round_cap_downstream_provider_script(&queued_prompt_log),
    );
    fluent_cmd()
        .current_dir(&queued.main_dir)
        .args(["queue", "resume", "work-1", "--attempt", "attempt-1"])
        .assert()
        .success()
        .stdout(predicate::str::contains("Queued resume"));
    run_scheduler_until_dispatch_status(&queued.main_dir, "work-1", &queued_bin, "needs-user");
    assert_eq!(dispatch_count(&queued.main_dir, "work-1"), 1);
    let queued_attempt = queued.store.read_work_item("work-1").unwrap().attempts[0].clone();
    assert_eq!(
        queued_attempt
            .tasks
            .iter()
            .filter(|task| task.kind == fluent::work_model::TaskKind::Write)
            .count(),
        2,
        "queued downstream-gate admission must not dispatch another Writer"
    );
    assert_eq!(
        queued_attempt.pause_kind,
        Some(fluent::work_model::PauseKind::WriterCompletion)
    );
    assert!(queued_attempt.learning.is_none());
    let queued_writer_count = queued_attempt
        .tasks
        .iter()
        .filter(|task| task.kind == fluent::work_model::TaskKind::Write)
        .count();
    fluent_cmd()
        .current_dir(&queued.main_dir)
        .args(["queue", "resume", "work-1", "--attempt", "attempt-1"])
        .assert()
        .failure()
        .stderr(predicate::str::contains("plan:step-2"));
    assert_eq!(dispatch_count(&queued.main_dir, "work-1"), 1);
    assert_eq!(
        queued.store.read_work_item("work-1").unwrap().attempts[0]
            .tasks
            .iter()
            .filter(|task| task.kind == fluent::work_model::TaskKind::Write)
            .count(),
        queued_writer_count
    );
    let queued_snapshot = attach_round_cap_host_evidence(&queued, "queued");
    let queued_original_evidence = fs::read(&queued_snapshot).unwrap();
    fs::write(&queued_snapshot, b"changed queued host proof\n").unwrap();
    fluent_cmd()
        .current_dir(&queued.main_dir)
        .args(["queue", "resume", "work-1", "--attempt", "attempt-1"])
        .assert()
        .failure()
        .stderr(predicate::str::contains("digest changed"));
    assert_eq!(dispatch_count(&queued.main_dir, "work-1"), 1);
    fs::write(&queued_snapshot, &queued_original_evidence).unwrap();
    fluent_cmd()
        .current_dir(&queued.main_dir)
        .args(["queue", "resume", "work-1", "--attempt", "attempt-1"])
        .assert()
        .success()
        .stdout(predicate::str::contains("Queued resume"));
    run_scheduler_until_dispatch_status(&queued.main_dir, "work-1", &queued_bin, "candidate-ready");
    assert_eq!(dispatch_count(&queued.main_dir, "work-1"), 2);
    assert_round_cap_downstream_completion(&queued);
    let queued_before_late_tamper = queued.store.read_work_item("work-1").unwrap();
    fs::write(&queued_snapshot, b"late changed queued host proof\n").unwrap();
    fluent_cmd()
        .current_dir(&queued.main_dir)
        .args(["queue", "resume", "work-1", "--attempt", "attempt-1"])
        .assert()
        .failure();
    assert_eq!(dispatch_count(&queued.main_dir, "work-1"), 2);
    assert_eq!(
        queued.store.read_work_item("work-1").unwrap(),
        queued_before_late_tamper
    );
    fs::write(&queued_snapshot, &queued_original_evidence).unwrap();
    assert_eq!(
        fs::read_to_string(&queued_prompt_log)
            .unwrap()
            .matches("Correct Writer Task attempt-1-write-2")
            .count(),
        1,
        "queued resume must not launch another Writer past the downstream gates"
    );
}

#[test]
#[serial]
fn round_cap_approach_revision_completed_resume_uses_effective_reviews() {
    use fluent::work_model::{
        AttemptStatus, EvidenceRecoveryState, LearningStatus, TaskKind, now_iso8601,
    };

    let fixture = setup_round_cap_approach_revision_fixture_with_downstream_gates();
    approve_round_cap_extension(&fixture);
    revise_round_cap_approach(&fixture).success();
    let prompt_log = fixture._tmp.path().join("effective-reviews-prompts.log");
    let provider = fixture._tmp.path().join("effective-reviews-provider");
    let passing = round_cap_downstream_provider_script(&prompt_log);
    let requesting = passing.replace(
        "    printf 'Verdict: pass\\n\\nDownstream route review.\\n' > review.md",
        r#"    if [[ "$PWD" == *-tests && "$PROMPT" != *'## Evidence-targeted review'* ]]; then
      printf 'Verdict: fail\nDisposition: evidence-needed\nEvidence-Command: cargo test exact_host_check\nEvidence-Working-Directory: .\n\n## Findings\n\n- [ ] Observe the host check\n' > review.md
    else
      printf 'Verdict: pass\n\nAccepted the attached check.\n' > review.md
    fi"#,
    );
    assert_ne!(requesting, passing);
    write_sandboxed_mock_claude(&provider, &requesting);
    let run = || {
        let mut command = fluent_cmd();
        command
            .current_dir(&fixture.main_dir)
            .env("PATH", mock_path(&provider))
            .args(["attempt", "run", "work-1", "attempt-1"]);
        command
    };
    run().assert().success();
    attach_round_cap_host_evidence(&fixture, "effective-reviews");
    run().assert().success();
    let requested = fixture.store.read_work_item("work-1").unwrap();
    assert_eq!(requested.attempts[0].status, AttemptStatus::NeedsUser);
    let request = requested.attempts[0]
        .tasks
        .iter()
        .rev()
        .find(|task| {
            task.kind == TaskKind::Review
                && task.role == "tests"
                && task.evidence_review_context.is_none()
        })
        .unwrap();
    let review_ref = format!("{}/review.md", request.artifact_area.as_ref().unwrap().path);
    let request_bytes = fs::read(fixture.main_dir.join(&review_ref)).unwrap();
    assert_eq!(
        review::extract_verdict(std::str::from_utf8(&request_bytes).unwrap()),
        review::Verdict::Fail
    );
    let candidate = &request.review_context.as_ref().unwrap().candidate_commit;
    let proof = fixture._tmp.path().join("requested-host-check.json");
    write_json_path(
        &proof,
        &serde_json::json!({
            "schema_version": 1, "producer": "fixture host",
            "check": "cargo test exact_host_check", "working_directory": ".",
            "result": "pass", "run_at": now_iso8601(), "output": "passed"
        }),
    );
    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .args([
            "attempt",
            "evidence",
            "attach",
            "work-1",
            "attempt-1",
            "--candidate",
            candidate,
            "--review-artifact",
            &review_ref,
            "--evidence-file",
            proof.to_str().unwrap(),
        ])
        .assert()
        .success();
    write_sandboxed_mock_claude(&provider, &passing);
    run().assert().success().stdout(predicate::str::contains(
        "Merge Candidate attempt-1-merge-candidate is ready",
    ));

    let before = fixture.store.read_work_item("work-1").unwrap();
    let attempt = &before.attempts[0];
    assert_eq!(attempt.status, AttemptStatus::Complete);
    assert_eq!(
        attempt.learning.as_ref().unwrap().status,
        LearningStatus::Succeeded
    );
    let writer_index = attempt
        .tasks
        .iter()
        .rposition(|task| task.kind == TaskKind::Write)
        .unwrap();
    let writer = &attempt.tasks[writer_index];
    assert_eq!(writer.role, "approach-revision-correction");
    assert_eq!(
        attempt
            .tasks
            .iter()
            .filter(|task| task.kind == TaskKind::Write)
            .count(),
        2
    );
    let ordinary: Vec<_> = attempt.tasks[writer_index + 1..]
        .iter()
        .filter(|task| {
            task.kind == TaskKind::Review
                && task.role == "tests"
                && task.evidence_review_context.is_none()
        })
        .collect();
    assert_eq!(ordinary.len(), 2);
    assert_eq!(ordinary[0].id, request.id);
    let effective_path = fixture
        .main_dir
        .join(&ordinary[1].artifact_area.as_ref().unwrap().path)
        .join("review.md");
    assert_eq!(
        review::extract_verdict(&fs::read_to_string(&effective_path).unwrap()),
        review::Verdict::Pass
    );
    let recovery = attempt
        .evidence_recoveries
        .iter()
        .find(|recovery| {
            recovery
                .required_check
                .as_ref()
                .is_some_and(|check| check.command == "cargo test exact_host_check")
        })
        .unwrap();
    assert_eq!(recovery.state, EvidenceRecoveryState::Complete);
    let targeted = attempt
        .tasks
        .iter()
        .find(|task| Some(task.id.as_str()) == recovery.targets[0].review_task_id.as_deref())
        .unwrap();
    assert!(targeted.evidence_review_context.is_some());
    assert_ne!(targeted.id, ordinary[1].id);
    let targeted_path = fixture
        .main_dir
        .join(&targeted.artifact_area.as_ref().unwrap().path)
        .join("review.md");
    let tester = attempt
        .tasks
        .iter()
        .rev()
        .find(|task| task.kind == TaskKind::Tester && !task.is_failed_command_recheck())
        .unwrap();
    let tester_path = fixture
        .main_dir
        .join(&tester.artifact_area.as_ref().unwrap().path)
        .join("tester-results.json");
    let mut failed_results = read_json_path(&tester_path);
    failed_results["commands"][0]["exit_code"] = serde_json::json!(1);
    let workspace = fixture
        .main_dir
        .join(&writer.output.as_ref().unwrap().workspace_path);
    let candidate_head = git_head(&workspace);
    let prompts = fs::read(&prompt_log).unwrap();

    // Readiness and completed resume must agree about the preserved failed Review.
    run().assert().success().stdout(predicate::str::contains(
        "Merge Candidate attempt-1-merge-candidate is ready",
    ));
    assert_eq!(fixture.store.read_work_item("work-1").unwrap(), before);
    assert_eq!(fs::read(&prompt_log).unwrap(), prompts);
    assert_eq!(
        fs::read(fixture.main_dir.join(&review_ref)).unwrap(),
        request_bytes
    );

    for (path, replacement, diagnostic) in [
        (
            effective_path,
            b"Verdict: fail\n\nCurrent domain evidence changed.\n".to_vec(),
            "no longer passes",
        ),
        (
            targeted_path,
            b"Verdict: fail\n\nTargeted acceptance changed.\n".to_vec(),
            "unresolved",
        ),
        (
            tester_path,
            serde_json::to_vec_pretty(&failed_results).unwrap(),
            "needs diagnosis",
        ),
    ] {
        let original = fs::read(&path).unwrap();
        fs::write(&path, &replacement).unwrap();
        run()
            .assert()
            .failure()
            .stderr(predicate::str::contains(diagnostic));
        fluent_cmd()
            .current_dir(&fixture.main_dir)
            .args(["queue", "resume", "work-1", "--attempt", "attempt-1"])
            .assert()
            .failure()
            .stderr(predicate::str::contains(diagnostic));
        assert_eq!(fixture.store.read_work_item("work-1").unwrap(), before);
        assert!(
            fluent::queue::read_ledger(&fixture.main_dir, "work-1")
                .unwrap()
                .is_none()
        );
        assert_eq!(git_head(&workspace), candidate_head);
        assert_eq!(fs::read(&prompt_log).unwrap(), prompts);
        assert_eq!(fs::read(&path).unwrap(), replacement);
        fs::write(path, original).unwrap();
    }
    run().assert().success();
    assert_eq!(fixture.store.read_work_item("work-1").unwrap(), before);
}

#[test]
#[serial]
fn round_cap_approach_revision_completed_resume_rejects_unresolved_command() {
    let fixture = setup_round_cap_approach_revision_fixture_with_downstream_gates();
    let (tester_results, candidate_workspace, prompt_log) =
        complete_round_cap_approach_revision(&fixture, "unresolved-command");
    let before = fixture.store.read_work_item("work-1").unwrap();
    let candidate = before.attempts[0]
        .tasks
        .iter()
        .rev()
        .find(|task| task.kind == fluent::work_model::TaskKind::Write)
        .and_then(|task| task.output.as_ref())
        .map(|output| output.commit.clone())
        .unwrap();
    let candidate_head = git_head(&candidate_workspace);
    let gate_path = before.attempts[0]
        .artifacts
        .iter()
        .rev()
        .find(|artifact| artifact.path.ends_with("candidate-gate.json"))
        .map(|artifact| fixture.main_dir.join(&artifact.path))
        .unwrap();
    let gate_bytes = fs::read(&gate_path).unwrap();
    let mut results = read_json_path(&tester_results);
    assert_eq!(results["candidate_commit"], candidate);
    assert_eq!(results["error"], serde_json::Value::Null);
    assert!(results["tests"].as_array().unwrap().is_empty());
    assert_eq!(results["summary"]["total"], 0);
    results["commands"][0]["exit_code"] = serde_json::json!(1);
    write_json_path(&tester_results, &results);
    let failed_results = fs::read(&tester_results).unwrap();
    let prompt_count = fs::read_to_string(&prompt_log)
        .unwrap()
        .matches("--- invocation ---")
        .count();

    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .failure()
        .stderr(predicate::str::contains("needs diagnosis"));

    assert_eq!(fixture.store.read_work_item("work-1").unwrap(), before);
    assert_eq!(git_head(&candidate_workspace), candidate_head);
    assert_eq!(fs::read(&gate_path).unwrap(), gate_bytes);
    assert_eq!(fs::read(&tester_results).unwrap(), failed_results);
    assert_eq!(
        fs::read_to_string(&prompt_log)
            .unwrap()
            .matches("--- invocation ---")
            .count(),
        prompt_count,
        "an unresolved command must not launch another worker"
    );
}

#[test]
#[serial]
fn round_cap_approach_revision_completed_resume_accepts_satisfied_verification() {
    for (label, fixture) in [
        (
            "passing",
            setup_round_cap_approach_revision_fixture_with_downstream_gates(),
        ),
        (
            "accepted-host-proof",
            setup_round_cap_approach_revision_fixture_with_accepted_host_evidence(),
        ),
    ] {
        let (_tester_results, candidate_workspace, prompt_log) =
            complete_round_cap_approach_revision(&fixture, label);
        let before = fixture.store.read_work_item("work-1").unwrap();
        let prompt_count = fs::read_to_string(&prompt_log)
            .unwrap()
            .matches("--- invocation ---")
            .count();

        fluent_cmd()
            .current_dir(&fixture.main_dir)
            .args(["attempt", "run", "work-1", "attempt-1"])
            .assert()
            .success()
            .stdout(predicate::str::contains(
                "Merge Candidate attempt-1-merge-candidate is ready",
            ));

        assert_eq!(fixture.store.read_work_item("work-1").unwrap(), before);
        assert_eq!(
            git_head(&candidate_workspace),
            before.attempts[0]
                .tasks
                .iter()
                .rev()
                .find(|task| task.kind == fluent::work_model::TaskKind::Write)
                .and_then(|task| task.output.as_ref())
                .map(|output| output.commit.as_str())
                .unwrap()
        );
        assert_eq!(
            fs::read_to_string(&prompt_log)
                .unwrap()
                .matches("--- invocation ---")
                .count(),
            prompt_count,
            "a satisfied completed resume must not restart a Task"
        );
    }

    let fixture = setup_round_cap_approach_revision_fixture_with_downstream_gates();
    let (tester_results, candidate_workspace, prompt_log) =
        complete_round_cap_approach_revision(&fixture, "preexisting-baseline");
    let mut current = read_json_path(&tester_results);
    let candidate = current["candidate_commit"].as_str().unwrap().to_string();
    let baseline_path = fixture.main_dir.join(
        ".fluent/work/artifacts/work-1/attempt-1/attempt-1-baseline-tester/tester-results.json",
    );
    current["commands"][0]["exit_code"] = serde_json::json!(1);
    current["tests"] = serde_json::json!([{
        "id": "known-baseline-failure",
        "test_harness": "shell-harness",
        "status": "fail",
        "duration_ms": 1,
        "failure_excerpt": "known baseline failure"
    }]);
    current["summary"] = serde_json::json!({
        "total": 1,
        "pass": 0,
        "fail": 1,
        "skipped": 0
    });
    let baseline = current.clone();
    fs::create_dir_all(baseline_path.parent().unwrap()).unwrap();
    write_json_path(&baseline_path, &baseline);
    write_json_path(&tester_results, &current);
    let before = fixture.store.read_work_item("work-1").unwrap();
    let prompt_count = fs::read_to_string(&prompt_log)
        .unwrap()
        .matches("--- invocation ---")
        .count();

    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success()
        .stdout(predicate::str::contains(
            "Merge Candidate attempt-1-merge-candidate is ready",
        ));

    assert_eq!(fixture.store.read_work_item("work-1").unwrap(), before);
    assert_eq!(git_head(&candidate_workspace), candidate);
    assert_eq!(
        fs::read_to_string(&prompt_log)
            .unwrap()
            .matches("--- invocation ---")
            .count(),
        prompt_count,
        "baseline-covered verification must not restart a Task"
    );
}

#[test]
#[serial]
fn round_cap_approach_revision_completed_resume_accepts_failed_command_with_host_proof() {
    let fixture =
        setup_round_cap_approach_revision_fixture_with_accepted_host_evidence_for_failed_tester();
    let (tester_results, candidate_workspace, prompt_log) =
        complete_round_cap_approach_revision_with_accepted_canonical_host_proof(
            &fixture,
            "accepted-failed-command",
        );
    let before = fixture.store.read_work_item("work-1").unwrap();
    let before_task_ids: Vec<_> = before.attempts[0]
        .tasks
        .iter()
        .map(|task| task.id.clone())
        .collect();
    let results = read_json_path(&tester_results);
    assert_eq!(results["commands"][0]["command"], "false");
    assert_eq!(results["commands"][0]["exit_code"], 1);
    assert_eq!(results["error"], serde_json::Value::Null);
    let recovery = before.attempts[0]
        .evidence_recoveries
        .iter()
        .find(|recovery| recovery.required_check.is_some())
        .expect("failed canonical command must retain accepted required-check proof");
    assert_eq!(recovery.required_check.as_ref().unwrap().command, "false");
    assert_eq!(
        recovery.state,
        fluent::work_model::EvidenceRecoveryState::Complete
    );
    let target = recovery.targets.first().unwrap();
    let review_task = before.attempts[0]
        .tasks
        .iter()
        .find(|task| Some(task.id.as_str()) == target.review_task_id.as_deref())
        .expect("required-check recovery must retain its targeted Tests Review");
    assert_eq!(review_task.role, "tests");
    assert_eq!(
        review::extract_verdict(
            &fs::read_to_string(
                fixture
                    .main_dir
                    .join(&review_task.artifact_area.as_ref().unwrap().path)
                    .join("review.md")
            )
            .unwrap()
        ),
        review::Verdict::Pass
    );
    let candidate = before.attempts[0]
        .tasks
        .iter()
        .rev()
        .find(|task| task.kind == fluent::work_model::TaskKind::Write)
        .and_then(|task| task.output.as_ref())
        .map(|output| output.commit.clone())
        .unwrap();
    let candidate_head = git_head(&candidate_workspace);
    let prompt_count = fs::read_to_string(&prompt_log)
        .unwrap()
        .matches("--- invocation ---")
        .count();

    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success()
        .stdout(predicate::str::contains(
            "Merge Candidate attempt-1-merge-candidate is ready",
        ));

    let after = fixture.store.read_work_item("work-1").unwrap();
    assert_eq!(after, before);
    assert_eq!(
        after.attempts[0]
            .tasks
            .iter()
            .map(|task| task.id.clone())
            .collect::<Vec<_>>(),
        before_task_ids,
        "a satisfied completed resume must not create another Task"
    );
    assert_eq!(git_head(&candidate_workspace), candidate_head);
    assert_eq!(
        fs::read_to_string(&prompt_log)
            .unwrap()
            .matches("--- invocation ---")
            .count(),
        prompt_count,
        "accepted host proof must not restart a completed Task"
    );
    assert_eq!(
        after.merge_candidates[0].candidate_commit, candidate,
        "resume must return the existing Merge Candidate"
    );
}

#[test]
#[serial]
fn round_cap_approach_revision_rechecks_downstream_evidence_on_both_routes() {
    for queued in [false, true] {
        let fixture = setup_round_cap_approach_revision_fixture_with_downstream_gates();
        approve_round_cap_extension(&fixture);
        revise_round_cap_approach(&fixture).success();
        let prompt_log = fixture._tmp.path().join(if queued {
            "queued-downstream-tamper-prompts.log"
        } else {
            "foreground-downstream-tamper-prompts.log"
        });
        let bin = fixture._tmp.path().join(if queued {
            "queued-downstream-tamper-provider"
        } else {
            "foreground-downstream-tamper-provider"
        });
        if queued {
            write_scheduler_claude(&bin, &round_cap_downstream_provider_script(&prompt_log));
            fluent_cmd()
                .current_dir(&fixture.main_dir)
                .args(["queue", "resume", "work-1", "--attempt", "attempt-1"])
                .assert()
                .success();
            run_scheduler_until_dispatch_status(&fixture.main_dir, "work-1", &bin, "needs-user");
            attach_round_cap_host_evidence(&fixture, "queued-tamper");
            fluent_cmd()
                .current_dir(&fixture.main_dir)
                .args(["queue", "resume", "work-1", "--attempt", "attempt-1"])
                .assert()
                .success();
            run_scheduler_until_dispatch_status(
                &fixture.main_dir,
                "work-1",
                &bin,
                "candidate-ready",
            );
        } else {
            write_sandboxed_mock_claude(&bin, &round_cap_downstream_provider_script(&prompt_log));
            fluent_cmd()
                .current_dir(&fixture.main_dir)
                .env("PATH", mock_path(&bin))
                .args(["attempt", "run", "work-1", "attempt-1"])
                .assert()
                .success();
            attach_round_cap_host_evidence(&fixture, "foreground-tamper");
            fluent_cmd()
                .current_dir(&fixture.main_dir)
                .env("PATH", mock_path(&bin))
                .args(["attempt", "run", "work-1", "attempt-1"])
                .assert()
                .success();
        }
        assert_round_cap_downstream_completion(&fixture);
        let baseline_prompt_count = fs::read_to_string(&prompt_log)
            .unwrap()
            .matches("--- invocation ---")
            .count();
        let baseline_dispatch_count = queued.then(|| dispatch_count(&fixture.main_dir, "work-1"));

        for tamper in [
            RoundCapDownstreamTamper::Review,
            RoundCapDownstreamTamper::Tester,
            RoundCapDownstreamTamper::CandidateGate,
            RoundCapDownstreamTamper::Learning,
        ] {
            let (path, original, replacement, diagnostic) =
                tamper_completed_downstream_evidence(&fixture, tamper);
            let before = fixture.store.read_work_item("work-1").unwrap();
            fs::write(&path, replacement).unwrap();
            if queued {
                fluent_cmd()
                    .current_dir(&fixture.main_dir)
                    .args(["queue", "resume", "work-1", "--attempt", "attempt-1"])
                    .assert()
                    .failure()
                    .stderr(predicate::str::contains(diagnostic));
                assert_eq!(
                    dispatch_count(&fixture.main_dir, "work-1"),
                    baseline_dispatch_count.unwrap(),
                    "queued resume must not create a dispatch for tampered {tamper:?} evidence"
                );
            } else {
                fluent_cmd()
                    .current_dir(&fixture.main_dir)
                    .env("PATH", mock_path(&bin))
                    .args(["attempt", "run", "work-1", "attempt-1"])
                    .assert()
                    .failure()
                    .stderr(predicate::str::contains(diagnostic));
            }
            assert_eq!(
                fixture.store.read_work_item("work-1").unwrap(),
                before,
                "tampered {tamper:?} evidence must not mutate Work-model state"
            );
            assert_eq!(
                fs::read_to_string(&prompt_log)
                    .unwrap()
                    .matches("--- invocation ---")
                    .count(),
                baseline_prompt_count,
                "tampered {tamper:?} evidence must not launch another provider"
            );
            fs::write(path, original).unwrap();
        }
    }
}

