#[test]
#[serial]
fn round_cap_approach_revision_rejects_unsupported_assignment_format() {
    for pending in [false, true] {
        let tmp = TempDir::new().unwrap();
        let project = setup_git_project(&tmp);
        fluent_cmd()
            .current_dir(&project)
            .args([
                "work-item",
                "create",
                "assignment-format",
                "--title",
                "Reject unsupported assignment format",
            ])
            .assert()
            .success();
        fluent_cmd()
            .current_dir(&project)
            .args(["attempt", "create", "assignment-format", "attempt-1"])
            .assert()
            .success();

        let work_root = project.join(".fluent/work");
        if pending {
            let store = WorkModelStore::new(&project);
            let item = store.read_work_item("assignment-format").unwrap();
            let mut work_item = serde_json::to_value(item).unwrap();
            work_item["title"] = serde_json::json!("Unsupported pending assignment");
            work_item["attempts"][0]["tasks"][0]["writer_correction_assignment"] =
                assignment_wire_value();
            write_json_path(
                &work_root.join("transactions/assignment-format.json"),
                &serde_json::json!({
                    "schema_version": 999,
                    "id": "assignment-format",
                    "base_revision": 0,
                    "target_revision": 1,
                    "work_item": work_item,
                }),
            );
        } else {
            let record_path = work_root.join("items/assignment-format.json");
            let mut record = read_json_path(&record_path);
            record["schema_version"] = serde_json::json!(6);
            record["model_writer_version"]["schema_version"] = serde_json::json!(999);
            write_json_path(&record_path, &record);

            let attempt_path = work_root.join("attempts/assignment-format/attempt-1.json");
            let mut attempt = read_json_path(&attempt_path);
            attempt["schema_version"] = serde_json::json!(6);
            write_json_path(&attempt_path, &attempt);

            let task_path =
                work_root.join("tasks/assignment-format/attempt-1/attempt-1-write-1.json");
            let mut task = read_json_path(&task_path);
            task["writer_correction_assignment"] = assignment_wire_value();
            write_json_path(&task_path, &task);
        }

        let before = snapshot_tree(&work_root);
        fluent_cmd()
            .current_dir(&project)
            .args([
                "work-item",
                "abandon",
                "assignment-format",
                "--reason",
                "must reject unsupported assignment format",
            ])
            .assert()
            .failure();
        assert_eq!(snapshot_tree(&work_root), before, "pending={pending}");
    }
}

fn round_cap_resume_provider_script(prompt_log: &Path) -> String {
    format!(
        r##"#!/bin/bash
set -eu
PROMPT=""
while [ "$#" -gt 0 ]; do
  if [ "$1" = "-p" ]; then
    shift
    PROMPT="${{1:-}}"
    break
  fi
  shift
done
if [ -z "$PROMPT" ]; then exit 0; fi
printf '\n--- invocation ---\n%s\n' "$PROMPT" >> '{prompt_log}'
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  mkdir -p "$(dirname "$DRAFT")"
  printf '%s\n' '{{"learning_summary":"public route","follow_ups":[]}}' > "$DRAFT"
  exit 0
fi
case "$PWD" in
  */work-6-work-1-attempt-1)
    printf 'public route correction\n' > route-correction.txt
    git add route-correction.txt
    git commit -m "Apply public route correction" >/dev/null
    ;;
  *)
    printf 'Verdict: pass\n\nPublic route review.\n' > review.md
    ;;
esac
exit 0
"##,
        prompt_log = prompt_log.display(),
    )
}

fn round_cap_downstream_provider_script(prompt_log: &Path) -> String {
    format!(
        r##"#!/bin/bash
set -eu
PROMPT=""
while [ "$#" -gt 0 ]; do
  if [ "$1" = "-p" ]; then
    shift
    PROMPT="${{1:-}}"
    break
  fi
  shift
done
if [ -z "$PROMPT" ]; then exit 0; fi
printf '\n--- invocation ---\n%s\n' "$PROMPT" >> '{prompt_log}'
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  mkdir -p "$(dirname "$DRAFT")"
  printf '%s\n' '{{"learning_summary":"downstream route","follow_ups":[]}}' > "$DRAFT"
  exit 0
fi
case "$PWD" in
  */work-6-work-1-attempt-1)
    MATRIX=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*writer-completion.json' | tail -1 || true)
    if [ -n "$MATRIX" ] && [ -f "$MATRIX" ]; then
      python3 - "$MATRIX" <<'PYCODE'
import json
import pathlib
import sys

path = pathlib.Path(sys.argv[1])
data = json.loads(path.read_text())
for row in data["rows"]:
    if row.get("responsibility", "writer") == "writer":
        row["state"] = "complete"
        row["implementation-evidence"] = ["README.md: apply the revised Approach"]
        row["verification"] = [{{"command": "true", "result": "pass"}}]
path.write_text(json.dumps(data, indent=2) + "\n")
PYCODE
    fi
    WRITER_TAG=$(printf '%s' "$PROMPT" | grep -o 'Task attempt-1-write-[0-9]*' | tail -1 | sed 's/ /-/g')
    printf 'downstream route correction %s\n' "$WRITER_TAG" > "${{WRITER_TAG}}.txt"
    git add "${{WRITER_TAG}}.txt"
    git commit -m "Apply downstream correction" >/dev/null
    ;;
  *)
    printf 'Verdict: pass\n\nDownstream route review.\n' > review.md
    ;;
esac
exit 0
"##,
        prompt_log = prompt_log.display(),
    )
}

fn round_cap_two_revision_provider_script(prompt_log: &Path) -> String {
    format!(
        r##"#!/bin/bash
set -eu
PROMPT=""
while [ "$#" -gt 0 ]; do
  if [ "$1" = "-p" ]; then
    shift
    PROMPT="${{1:-}}"
    break
  fi
  shift
done
if [ -z "$PROMPT" ]; then exit 0; fi
printf '\n--- invocation ---\n%s\n' "$PROMPT" >> '{prompt_log}'
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  exit 0
fi
case "$PWD" in
  */work-6-work-1-attempt-1)
    MATRIX=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*writer-completion.json' | tail -1 || true)
    if [ -n "$MATRIX" ] && [ -f "$MATRIX" ]; then
      python3 - "$MATRIX" <<'PYCODE'
import json
import pathlib
import sys

path = pathlib.Path(sys.argv[1])
data = json.loads(path.read_text())
for row in data["rows"]:
    if row.get("responsibility", "writer") == "writer":
        row["state"] = "complete"
        row["implementation-evidence"] = ["README.md: apply the revised Approach"]
        row["verification"] = [{{"command": "true", "result": "pass"}}]
        if row["kind"] == "finding":
            row["applicable-constraints"] = ["plan:step-1"]
path.write_text(json.dumps(data, indent=2) + "\n")
PYCODE
    fi
    WRITER_TAG=$(printf '%s' "$PROMPT" | grep -o 'Task attempt-1-write-[0-9]*' | tail -1 | sed 's/ /-/g')
    printf 'two-revision correction %s\n' "$WRITER_TAG" > "${{WRITER_TAG}}.txt"
    git add "${{WRITER_TAG}}.txt"
    git commit -m "Apply two-revision correction" >/dev/null
    ;;
  */attempt-1-review-tests|*/attempt-1-review-2-tests|*/attempt-1-review-3-tests|*/review-6-work-1-attempt-1-tests)
    printf 'Verdict: fail\n\n- [ ] Resolve the second review frontier.\n' > review.md
    ;;
  *)
    printf 'Verdict: pass\n\nSecond revision review.\n' > review.md
    ;;
esac
exit 0
"##,
        prompt_log = prompt_log.display(),
    )
}

fn attach_round_cap_host_evidence(
    fixture: &RoundCapApproachRevisionFixture,
    label: &str,
) -> PathBuf {
    let item = fixture.store.read_work_item("work-1").unwrap();
    let candidate = item.attempts[0]
        .tasks
        .iter()
        .rev()
        .find(|task| task.kind == fluent::work_model::TaskKind::Write)
        .and_then(|task| task.output.as_ref())
        .map(|output| output.commit.clone())
        .expect("downstream fixture must have a latest Writer candidate");
    let evidence_path = fixture
        ._tmp
        .path()
        .join(format!("{label}-downstream-host-evidence.json"));
    fs::write(
        &evidence_path,
        serde_json::json!({
            "schema_version": 1,
            "producer": "authorized downstream host",
            "check": "bash tests/host.sh",
            "working_directory": ".",
            "comparison_commits": {"HEAD": candidate},
            "result": "pass",
            "run_at": "2026-09-12T00:00:00Z",
            "output": "downstream host check passed"
        })
        .to_string(),
    )
    .unwrap();
    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .args([
            "attempt",
            "evidence",
            "attach",
            "work-1",
            "attempt-1",
            "--candidate",
            &candidate,
            "--plan-row",
            "plan:step-2",
            "--evidence-file",
            evidence_path.to_str().unwrap(),
        ])
        .assert()
        .success();
    let after = fixture.store.read_work_item("work-1").unwrap();
    let recovery = after.attempts[0]
        .evidence_recoveries
        .iter()
        .rev()
        .find(|recovery| recovery.candidate_commit == candidate)
        .expect("host attachment must create a candidate-bound recovery");
    assert_eq!(
        recovery.state,
        fluent::work_model::EvidenceRecoveryState::Reviewing
    );
    fixture.main_dir.join(&recovery.attachment.snapshot_path)
}

fn assert_round_cap_downstream_completion(fixture: &RoundCapApproachRevisionFixture) {
    let item = fixture.store.read_work_item("work-1").unwrap();
    let attempt = &item.attempts[0];
    assert_eq!(
        attempt
            .tasks
            .iter()
            .filter(|task| task.kind == fluent::work_model::TaskKind::Write)
            .count(),
        2,
        "downstream recovery must use exactly one corrective Writer"
    );
    assert_eq!(attempt.status, fluent::work_model::AttemptStatus::Complete);
    assert_eq!(
        attempt.review_state,
        Some(fluent::work_model::AttemptReviewState::Passed)
    );
    assert_eq!(
        attempt.learning.as_ref().map(|learning| learning.status),
        Some(fluent::work_model::LearningStatus::Succeeded)
    );
    let latest_writer_index = attempt
        .tasks
        .iter()
        .rposition(|task| task.kind == fluent::work_model::TaskKind::Write)
        .unwrap();
    let latest_writer = &attempt.tasks[latest_writer_index];
    assert_task_settled(&fixture.main_dir, "work-1", latest_writer);
    assert!(attempt.tasks[latest_writer_index + 1..].iter().all(|task| {
        task.kind != fluent::work_model::TaskKind::Review
            || task.status == fluent::work_model::TaskStatus::Complete
    }));
    assert!(
        attempt.tasks[latest_writer_index + 1..]
            .iter()
            .filter(|task| task.kind == fluent::work_model::TaskKind::Review)
            .all(|task| {
                let path = fixture
                    .main_dir
                    .join(&task.artifact_area.as_ref().unwrap().path)
                    .join("review.md");
                review::extract_verdict(&fs::read_to_string(path).unwrap()) == review::Verdict::Pass
            })
    );
    assert!(attempt.tasks.iter().any(|task| {
        task.kind == fluent::work_model::TaskKind::Tester
            && task.status == fluent::work_model::TaskStatus::Complete
    }));
    let candidate_gates: Vec<_> = attempt
        .artifacts
        .iter()
        .filter(|artifact| artifact.path.ends_with("candidate-gate.json"))
        .collect();
    assert!(
        candidate_gates.len() >= 2,
        "the Writer and final Tester candidate gates must both be recorded"
    );
    for artifact in candidate_gates {
        assert_eq!(
            read_json_path(&fixture.main_dir.join(&artifact.path))["disposition"],
            "passed"
        );
    }
}

fn complete_round_cap_approach_revision(
    fixture: &RoundCapApproachRevisionFixture,
    label: &str,
) -> (PathBuf, PathBuf, PathBuf) {
    approve_round_cap_extension(fixture);
    revise_round_cap_approach(fixture).success();

    let prompt_log = fixture
        ._tmp
        .path()
        .join(format!("{label}-provider-prompts.log"));
    let provider = fixture._tmp.path().join(format!("{label}-provider"));
    write_sandboxed_mock_claude(
        &provider,
        &round_cap_downstream_provider_script(&prompt_log),
    );
    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .env("PATH", mock_path(&provider))
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success();
    attach_round_cap_host_evidence(fixture, label);
    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .env("PATH", mock_path(&provider))
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success();
    assert_round_cap_downstream_completion(fixture);

    let item = fixture.store.read_work_item("work-1").unwrap();
    let writer = item.attempts[0]
        .tasks
        .iter()
        .rev()
        .find(|task| task.kind == fluent::work_model::TaskKind::Write)
        .unwrap();
    let workspace = Path::new(&writer.output.as_ref().unwrap().workspace_path);
    let workspace = if workspace.is_absolute() {
        workspace.to_path_buf()
    } else {
        fixture.main_dir.join(workspace)
    };
    let tester = item.attempts[0]
        .tasks
        .iter()
        .rev()
        .find(|task| {
            task.kind == fluent::work_model::TaskKind::Tester
                && task.status == fluent::work_model::TaskStatus::Complete
                && !task.is_failed_command_recheck()
        })
        .unwrap();
    let results = fixture
        .main_dir
        .join(&tester.artifact_area.as_ref().unwrap().path)
        .join("tester-results.json");
    (results, workspace, prompt_log)
}

fn complete_round_cap_approach_revision_with_accepted_canonical_host_proof(
    fixture: &RoundCapApproachRevisionFixture,
    label: &str,
) -> (PathBuf, PathBuf, PathBuf) {
    approve_round_cap_extension(fixture);
    revise_round_cap_approach(fixture).success();

    let prompt_log = fixture
        ._tmp
        .path()
        .join(format!("{label}-provider-prompts.log"));
    let provider = fixture._tmp.path().join(format!("{label}-provider"));
    write_sandboxed_mock_claude(
        &provider,
        &round_cap_downstream_provider_script(&prompt_log),
    );
    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .env("PATH", mock_path(&provider))
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success();
    attach_round_cap_host_evidence(fixture, label);
    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .env("PATH", mock_path(&provider))
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success();

    let item = fixture.store.read_work_item("work-1").unwrap();
    let candidate = item.attempts[0]
        .tasks
        .iter()
        .rev()
        .find(|task| task.kind == fluent::work_model::TaskKind::Write)
        .and_then(|task| task.output.as_ref())
        .map(|output| output.commit.clone())
        .unwrap();
    let tester = item.attempts[0]
        .tasks
        .iter()
        .rev()
        .find(|task| {
            task.kind == fluent::work_model::TaskKind::Tester
                && task.status == fluent::work_model::TaskStatus::Complete
                && !task.is_failed_command_recheck()
        })
        .expect("failed canonical Tester must remain recorded");
    let tester_results = fixture
        .main_dir
        .join(&tester.artifact_area.as_ref().unwrap().path)
        .join("tester-results.json");
    let results = read_json_path(&tester_results);
    assert_eq!(results["commands"][0]["exit_code"], 1);
    assert!(item.merge_candidates.is_empty());

    let config = fs::read(fixture.main_dir.join(".fluent/tester.yaml")).unwrap();
    let selector = format!("tester:{:x}:0", Sha256::digest(&config));
    let evidence = fixture
        ._tmp
        .path()
        .join(format!("{label}-canonical-host.json"));
    fs::write(
        &evidence,
        serde_json::to_vec(&serde_json::json!({
            "schema_version": 1,
            "producer": "authorized fixture host",
            "check": "false",
            "working_directory": ".",
            "result": "pass",
            "run_at": "2026-09-12T00:00:00Z",
            "output": "host proof accepted the failed canonical command"
        }))
        .unwrap(),
    )
    .unwrap();
    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .args([
            "attempt",
            "evidence",
            "attach",
            "work-1",
            "attempt-1",
            "--candidate",
            &candidate,
            "--required-check",
            &selector,
            "--evidence-file",
            evidence.to_str().unwrap(),
        ])
        .assert()
        .success();

    let attached = fixture.store.read_work_item("work-1").unwrap();
    let recovery = attached.attempts[0]
        .evidence_recoveries
        .iter()
        .find(|recovery| recovery.required_check.is_some())
        .expect("public required-check attachment must be recorded");
    assert_eq!(
        recovery.state,
        fluent::work_model::EvidenceRecoveryState::Reviewing
    );
    assert_eq!(recovery.required_check.as_ref().unwrap().id, selector);

    fluent_cmd()
        .current_dir(&fixture.main_dir)
        .env("PATH", mock_path(&provider))
        .args(["attempt", "run", "work-1", "attempt-1"])
        .assert()
        .success()
        .stdout(predicate::str::contains(
            "Merge Candidate attempt-1-merge-candidate is ready",
        ));
    assert_round_cap_downstream_completion(fixture);

    let item = fixture.store.read_work_item("work-1").unwrap();
    let writer = item.attempts[0]
        .tasks
        .iter()
        .rev()
        .find(|task| task.kind == fluent::work_model::TaskKind::Write)
        .unwrap();
    let workspace = Path::new(&writer.output.as_ref().unwrap().workspace_path);
    let workspace = if workspace.is_absolute() {
        workspace.to_path_buf()
    } else {
        fixture.main_dir.join(workspace)
    };
    (tester_results, workspace, prompt_log)
}

#[derive(Debug, Clone, Copy)]
enum RoundCapDownstreamTamper {
    Review,
    Tester,
    CandidateGate,
    Learning,
}

fn tamper_completed_downstream_evidence(
    fixture: &RoundCapApproachRevisionFixture,
    tamper: RoundCapDownstreamTamper,
) -> (PathBuf, Vec<u8>, Vec<u8>, &'static str) {
    let item = fixture.store.read_work_item("work-1").unwrap();
    let attempt = &item.attempts[0];
    let latest_write_index = attempt
        .tasks
        .iter()
        .rposition(|task| task.kind == fluent::work_model::TaskKind::Write)
        .unwrap();
    match tamper {
        RoundCapDownstreamTamper::Review => {
            let task = attempt.tasks[latest_write_index + 1..]
                .iter()
                .rev()
                .find(|task| {
                    task.kind == fluent::work_model::TaskKind::Review
                        && task.status == fluent::work_model::TaskStatus::Complete
                })
                .unwrap();
            let path = fixture
                .main_dir
                .join(&task.artifact_area.as_ref().unwrap().path)
                .join("review.md");
            (
                path.clone(),
                fs::read(&path).unwrap(),
                b"Verdict: fail\n\nThe completed review was changed.\n".to_vec(),
                "completed review",
            )
        }
        RoundCapDownstreamTamper::Tester => {
            let task = attempt.tasks[latest_write_index + 1..]
                .iter()
                .rev()
                .find(|task| {
                    task.kind == fluent::work_model::TaskKind::Tester
                        && task.status == fluent::work_model::TaskStatus::Complete
                        && !task.is_failed_command_recheck()
                })
                .unwrap();
            let path = fixture
                .main_dir
                .join(&task.artifact_area.as_ref().unwrap().path)
                .join("tester-results.json");
            let original = fs::read(&path).unwrap();
            let mut results = read_json_path(&path);
            results["candidate_commit"] = serde_json::json!("tampered-candidate");
            (
                path,
                original,
                serde_json::to_vec_pretty(&results).unwrap(),
                "candidate binding",
            )
        }
        RoundCapDownstreamTamper::CandidateGate => {
            let artifact = attempt
                .artifacts
                .iter()
                .rev()
                .find(|artifact| artifact.path.ends_with("candidate-gate.json"))
                .unwrap();
            let path = fixture.main_dir.join(&artifact.path);
            let original = fs::read(&path).unwrap();
            let mut gate = read_json_path(&path);
            assert_eq!(gate["phase"], "final-tester");
            gate["disposition"] = serde_json::json!("blocked");
            (
                path,
                original,
                serde_json::to_vec_pretty(&gate).unwrap(),
                "final Tester candidate gate",
            )
        }
        RoundCapDownstreamTamper::Learning => {
            let handoff = attempt
                .learning
                .as_ref()
                .and_then(|learning| learning.handoff.as_ref())
                .unwrap();
            let path = fixture.main_dir.join(&handoff.path);
            (
                path.clone(),
                fs::read(&path).unwrap(),
                b"tampered Learner handoff\n".to_vec(),
                "Learner handoff",
            )
        }
    }
}

fn assert_round_cap_writer_prompt(
    fixture: &RoundCapApproachRevisionFixture,
    prompt_log: &Path,
    attempt: &fluent::work_model::Attempt,
) {
    let prompt = fs::read_to_string(prompt_log).unwrap();
    assert!(prompt.contains(&fixture.resolution));
    assert!(prompt.contains("Apply every current finding test-first"));
    let corrective = attempt
        .tasks
        .iter()
        .find(|task| task.role == "approach-revision-correction")
        .unwrap();
    assert_task_settled(&fixture.main_dir, "work-1", corrective);
    for artifact in &corrective.input_artifacts {
        if artifact.producer_id == "planning-approach-recovery" {
            continue;
        }
        let absolute = fixture.main_dir.join(&artifact.path).display().to_string();
        assert!(
            prompt.contains(&absolute),
            "Writer prompt omitted retained input artifact {}",
            artifact.path
        );
    }
    let approach_path = fixture
        .main_dir
        .join(".fluent/work/items/work-1/approach.md");
    assert_eq!(
        fs::read_to_string(approach_path).unwrap(),
        fixture.replacement
    );
}

fn assert_task_settled(project_root: &Path, work_item_id: &str, task: &fluent::work_model::Task) {
    assert_eq!(task.status, fluent::work_model::TaskStatus::Complete);
    assert!(!fluent::lease::is_leased(&fluent::lease::task_lock_path(
        project_root,
        work_item_id,
        &task.id,
    )));
    let area = task
        .artifact_area
        .as_ref()
        .expect("settled Task must retain an artifact area");
    let execution_path = fluent::execution::record_path_for_artifact(project_root, &area.path);
    let record: fluent::execution::ExecutionRecord =
        serde_json::from_slice(&fs::read(&execution_path).unwrap_or_else(|error| {
            panic!(
                "settled Task must retain execution record {}: {error}",
                execution_path.display()
            )
        }))
        .unwrap_or_else(|error| {
            panic!(
                "settled Task execution record must be readable {}: {error}",
                execution_path.display()
            )
        });
    assert_eq!(record.state, fluent::execution::ExecutionState::Settled);
    assert!(record.settled_at.is_some());
    assert!(!fluent::execution::execution_is_live(&execution_path).unwrap());
}

fn round_cap_approach_revision_old_reader(variable: &str, source_commit: &str) -> PathBuf {
    let binary = PathBuf::from(
        std::env::var_os(variable)
            .unwrap_or_else(|| panic!("build the pinned reader for {variable} first")),
    );
    let reader_root = binary
        .parent()
        .and_then(Path::parent)
        .and_then(Path::parent)
        .expect("pinned reader target directory")
        .to_path_buf();
    let identity = read_json_path(&reader_root.join("identity.json"));
    assert_eq!(identity["source_commit"], source_commit);
    let source = Command::new("git")
        .args(["show", &format!("{source_commit}:src/work_model.rs")])
        .output()
        .expect("read pinned Work-model source");
    assert!(source.status.success());
    assert_eq!(
        identity["work_model_sha256"],
        format!("{:x}", Sha256::digest(&source.stdout))
    );
    assert_eq!(
        identity["binary_sha256"],
        format!("{:x}", Sha256::digest(fs::read(&binary).unwrap()))
    );
    binary
}

fn assert_old_reader_refuses_round_cap_authority(binary: &Path) {
    for pending in [false, true] {
        let fixture = setup_round_cap_approach_revision_fixture();
        approve_round_cap_extension(&fixture);
        revise_round_cap_approach(&fixture).success();
        if pending {
            leave_round_cap_publication_pending(&fixture);
        }

        let work_root = fixture.main_dir.join(".fluent/work");
        let before = snapshot_tree(&work_root);
        let output = Command::new(binary)
            .current_dir(&fixture.main_dir)
            .env("FLUENT_NO_UPDATE_CHECK", "1")
            .args([
                "work-item",
                "abandon",
                "work-1",
                "--reason",
                "must refuse new round-cap authority",
            ])
            .output()
            .unwrap();
        assert!(
            !output.status.success(),
            "older reader accepted new authority (pending={pending}): {}",
            String::from_utf8_lossy(&output.stdout)
        );
        assert_eq!(snapshot_tree(&work_root), before, "pending={pending}");
    }
}

#[test]
#[serial]
fn combined_installation_old_readers_preserve_authority() {
    use fluent::work_model::*;
    for (variable, source_commit, envelope, record_schema) in [
        (
            "FLUENT_INSTALLATION_MAIN_OLD_BIN",
            "d27e42d2a615a89835aa03da2a809ef93056d4cb",
            5,
            4,
        ),
        (
            "FLUENT_INSTALLATION_OUTPUT_FREE_OLD_BIN",
            "8ab476f75544016bd45b078c8d17627a439914a9",
            8,
            9,
        ),
        (
            "FLUENT_INSTALLATION_ACCEPTED_PROOF_OLD_BIN",
            "d7d1b2da8c8b249aa11c2f6f40cd4a0aafceb0e0",
            8,
            9,
        ),
    ] {
        let binary = writer_assignment_old_reader(variable, source_commit);
        let control = TempDir::new().unwrap();
        for args in [
            vec![
                "work-item",
                "create",
                "control",
                "--title",
                "Predecessor control",
            ],
            vec!["attempt", "create", "control", "attempt-1"],
            vec![
                "work-item",
                "abandon",
                "control",
                "--reason",
                "Positive mutation control",
            ],
        ] {
            let output = Command::new(&binary)
                .current_dir(control.path())
                .env("FLUENT_NO_UPDATE_CHECK", "1")
                .args(args)
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "{variable}: {}",
                String::from_utf8_lossy(&output.stderr)
            );
        }
        let control_store = WorkModelStore::new(control.path());
        let original = control_store.read_work_item_snapshot("control").unwrap();
        let bytes = snapshot_tree(&control.path().join(".fluent/work"));
        fluent_cmd()
            .current_dir(control.path())
            .args(["work-item", "show", "control"])
            .assert()
            .success();
        assert_eq!(snapshot_tree(&control.path().join(".fluent/work")), bytes);
        fluent_cmd()
            .current_dir(control.path())
            .args(["work-item", "upgrade", "control"])
            .assert()
            .success();
        assert_eq!(
            control_store.read_work_item_snapshot("control").unwrap(),
            original
        );
        let fixture = setup_round_cap_approach_revision_fixture_with_review(
            "| # | State reached | Behaviors | Verification | Responsibility | Req? |\n|---|---|---|---|---|---|\n| 1 | Preserve the contract. | B1 | `cargo test` | writer | Yes |\n".into(),
            "true", "Verdict: fail\n\n## Findings\n\n- [ ] Retain the assigned correction.\n",
        );
        make_round_cap_behavior_testable(&fixture);
        approve_round_cap_extension(&fixture);
        revise_round_cap_approach(&fixture).success();
        let bin = fixture._tmp.path().join("installation-provider");
        write_sandboxed_mock_claude(
            &bin,
            &round_cap_two_revision_provider_script(&fixture._tmp.path().join("prompts.log")),
        );
        fluent_cmd()
            .current_dir(&fixture.main_dir)
            .env("PATH", mock_path(&bin))
            .env("FLUENT_MAX_TOTAL_WRITE_ROUNDS", "1")
            .args(["attempt", "run", "work-1", "attempt-1"])
            .assert()
            .success();
        let prior = fixture.store.read_work_item_snapshot("work-1").unwrap();
        let source = prior.attempts[0]
            .tasks
            .iter()
            .rev()
            .find(|task| task.kind == TaskKind::Write)
            .unwrap();
        assert!(
            !source
                .writer_correction_assignment
                .as_ref()
                .unwrap()
                .findings
                .is_empty()
        );
        let root = fixture.main_dir.join(".fluent/work");
        let record_path = root.join("items/work-1.json");
        let original_record = read_json_path(&record_path);
        let refuse = |pending: bool| {
            let before = snapshot_tree(&root);
            let output = Command::new(&binary)
                .current_dir(&fixture.main_dir)
                .env("FLUENT_NO_UPDATE_CHECK", "1")
                .args([
                    "work-item",
                    "abandon",
                    "work-1",
                    "--reason",
                    "must preserve combined authority",
                ])
                .output()
                .unwrap();
            assert!(
                !output.status.success(),
                "{variable} rewrote combined authority (pending={pending})"
            );
            let error = String::from_utf8_lossy(&output.stderr);
            assert!(
                error.contains("schema") || error.contains("transaction"),
                "{variable}: {error}"
            );
            assert_eq!(
                snapshot_tree(&root),
                before,
                "{variable}, pending={pending}"
            );
        };
        for fence in ["envelope", "root", "attempt"] {
            let mut record = original_record.clone();
            if fence != "envelope" {
                record["model_writer_version"]["schema_version"] = envelope.into();
            }
            if fence == "attempt" {
                record["schema_version"] = record_schema.into();
            }
            write_json_path(&record_path, &record);
            refuse(false);
        }
        write_json_path(&record_path, &original_record);
        fluent_cmd()
            .current_dir(&fixture.main_dir)
            .args([
                "attempt",
                "extend",
                "work-1",
                "attempt-1",
                "--additional-write-rounds",
                "1",
                "--resolution",
                "Publish the next combined recovery revision",
            ])
            .env("FLUENT_MAX_TOTAL_WRITE_ROUNDS", "2")
            .assert()
            .success();
        // Lower only the surrounding envelopes so the predecessor must inspect
        // a genuine current journal before it can publish any split records.
        for path in [&record_path, &root.join("attempts/work-1/attempt-1.json")] {
            let mut record = read_json_path(path);
            record["schema_version"] = record_schema.into();
            if record.get("model_writer_version").is_some() {
                record["model_writer_version"]["schema_version"] = envelope.into();
            }
            write_json_path(path, &record);
        }
        let replacement =
            "# Next combined Approach\n\nKeep assignments and revision audits together.\n";
        let resolution = "Publish the next combined recovery revision";
        let approach_path = fixture.main_dir.join("next-combined-approach.md");
        fs::write(&approach_path, replacement).unwrap();
        fluent_cmd()
            .current_dir(&fixture.main_dir)
            .args([
                "attempt",
                "revise-approach",
                "work-1",
                "attempt-1",
                "--approach-file",
                approach_path.to_str().unwrap(),
                "--resolution",
                resolution,
            ])
            .env("FLUENT_MAX_TOTAL_WRITE_ROUNDS", "2")
            .env(
                "FLUENT_TEST_WORK_MODEL_INTERRUPT",
                "before-child-publication",
            )
            .assert()
            .failure();
        let journal = root.join("transactions/work-1.json");
        let pending = read_json_path(&journal);
        assert!(!pending["managed_files"].as_array().unwrap().is_empty());
        refuse(true);
        revise_round_cap_approach_with_values(&fixture, replacement, resolution).success();
        assert!(!journal.exists());
        let recovered = fixture.store.read_work_item_snapshot("work-1").unwrap();
        assert_eq!(
            &recovered.attempts[0].tasks[..prior.attempts[0].tasks.len()],
            prior.attempts[0].tasks.as_slice()
        );
        assert_eq!(recovered.attempts[0].round_cap_extensions.len(), 2);
        assert_eq!(
            recovered.attempts[0]
                .artifacts
                .iter()
                .filter(|a| a.producer_id == "planning-approach-recovery")
                .count(),
            2
        );
    }
}

fn leave_round_cap_publication_pending(fixture: &RoundCapApproachRevisionFixture) {
    let mut target = fixture.store.read_work_item("work-1").unwrap();
    target.title = "Interrupted round-cap publication".to_string();
    unsafe {
        std::env::set_var(
            "FLUENT_TEST_WORK_MODEL_INTERRUPT",
            "before-child-publication",
        );
    }
    let result = fixture.store.write_work_item(&target);
    unsafe {
        std::env::remove_var("FLUENT_TEST_WORK_MODEL_INTERRUPT");
    }
    assert!(result.is_err(), "fixture must leave a pending transaction");
    assert!(
        fixture
            .main_dir
            .join(".fluent/work/transactions/work-1.json")
            .is_file()
    );
}

