#[test]
fn landed_status_uses_final_landing_tester_evidence() {
    let tmp = TempDir::new().unwrap();
    let (project, bin, _) = setup_rebased_tester_candidate(&tmp, ":");
    let ready = work_item_value(&project, "work-1");
    let target = advance_tester_target(&project);
    land_work_1(&project, &bin, true);
    let trace_output =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("target/formal/workflow/evidence-status");
    record_evidence_status_trace(&project, "work-1", &ready, &target, &trace_output);
    let item = read_work_show_json(&project, "work-1");
    let attempt_tester = item["attempts"][0]["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .find(|task| task["kind"] == "tester" && task["status"] == "complete")
        .unwrap();
    assert_ne!(
        attempt_tester["review_context"]["candidate_commit"],
        git_head(&project)
    );
    let landing_path = item["merge_candidates"][0]["merge_state"]["check_artifacts"]
        .as_array()
        .unwrap()
        .iter()
        .find(|artifact| artifact["producer_id"] == "merge-tester")
        .unwrap()["path"]
        .as_str()
        .unwrap();
    let manifest = item["merge_candidates"][0]["merge_state"]["check_artifacts"]
        .as_array()
        .unwrap()
        .iter()
        .find(|artifact| artifact["producer_id"] == "merge-tester-manifest")
        .expect("landing retains the resolved comparison inputs in its evidence digest");
    assert_eq!(
        Path::new(manifest["path"].as_str().unwrap()),
        Path::new(landing_path).with_file_name("canonical-run.json")
    );
    assert_eq!(item["evidence-history"]["tester-results"], landing_path);
    assert_eq!(
        item["evidence-history"]["merged-commit"],
        git_head(&project)
    );
    assert!(item["evidence-history"]["diagnostic"].is_null());
    let status = fluent::work_status::load_work_status(&project).unwrap();
    assert_eq!(status.rows[0].action, "merged");
    assert_eq!(
        status.rows[0]
            .evidence_history
            .as_ref()
            .unwrap()
            .tester_results
            .as_deref(),
        Some(landing_path)
    );
    assert!(
        fluent::work_status::format_work_dashboard_lines(&status)
            .iter()
            .any(|line| line.contains(landing_path))
    );

    // A failure already present on the target is accepted by the landing
    // Tester and remains valid historical proof.
    let known_tmp = TempDir::new().unwrap();
    let (known_project, known_bin, _) = setup_rebased_tester_candidate(
        &known_tmp,
        "printf 'not ok known-target-failure\\n'; exit 1",
    );
    advance_tester_target(&known_project);
    land_work_1(&known_project, &known_bin, true);
    let known = read_work_show_json(&known_project, "work-1");
    assert_eq!(
        known["evidence-history"]["tester-results"],
        known["merge_candidates"][0]["merge_state"]["check_artifacts"]
            .as_array()
            .unwrap()
            .iter()
            .find(|artifact| artifact["producer_id"] == "merge-tester")
            .unwrap()["path"]
    );
    assert!(known["evidence-history"]["diagnostic"].is_null());
}

fn record_evidence_status_trace(
    project: &Path,
    work: &str,
    ready: &serde_json::Value,
    target: &str,
    output: &Path,
) {
    fs::create_dir_all(output).unwrap();
    let landed = work_item_value(project, work);
    let status = fluent_cmd()
        .current_dir(project)
        .arg("status")
        .output()
        .unwrap();
    assert!(status.status.success());
    let show = fluent_cmd()
        .current_dir(project)
        .args(["work-item", "show", work])
        .output()
        .unwrap();
    assert!(show.status.success());
    let candidate = &landed["merge_candidates"][0];
    let artifact = |producer: &str| {
        candidate["merge_state"]["check_artifacts"]
            .as_array()
            .unwrap()
            .iter()
            .find(|artifact| artifact["producer_id"] == producer)
            .unwrap()["path"]
            .as_str()
            .unwrap()
            .to_string()
    };
    let final_path = artifact("merge-tester");
    let baseline_path = artifact("merge-target-baseline");
    let attempt_path = landed["attempts"][0]["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .find(|task| task["kind"] == "tester" && task["status"] == "complete")
        .unwrap()["artifact_area"]["path"]
        .as_str()
        .unwrap()
        .to_string();
    let mut files: Vec<(String, Vec<u8>)> = vec![
        (
            "ready-work.json".into(),
            serde_json::to_vec_pretty(ready).unwrap(),
        ),
        (
            "landed-work.json".into(),
            serde_json::to_vec_pretty(&landed).unwrap(),
        ),
        (
            "landing-results.json".into(),
            fs::read(project.join(&final_path)).unwrap(),
        ),
        (
            "landing-manifest.json".into(),
            fs::read(
                project
                    .join(&final_path)
                    .with_file_name("canonical-run.json"),
            )
            .unwrap(),
        ),
        (
            "target-baseline.json".into(),
            fs::read(project.join(&baseline_path)).unwrap(),
        ),
        (
            "attempt-results.json".into(),
            fs::read(project.join(attempt_path).join("tester-results.json")).unwrap(),
        ),
        ("status.txt".into(), status.stdout.clone()),
        ("shown-work.json".into(), show.stdout.clone()),
        (
            "tester-config.yaml".into(),
            fs::read(project.join(".fluent/tester.yaml")).unwrap(),
        ),
        (
            "extractor".into(),
            fs::read(project.join(".fluent/extract-tester-results")).unwrap(),
        ),
    ];
    let writes: Vec<_> = ready["attempts"][0]["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|task| task["kind"] == "write" && task["status"] == "complete")
        .collect();
    let mut deltas = Vec::new();
    for (index, pair) in writes.windows(2).enumerate() {
        let from = pair[0]["output"]["commit"].as_str().unwrap();
        let to = pair[1]["output"]["commit"].as_str().unwrap();
        let diff = std::process::Command::new("git")
            .current_dir(project)
            .args(["diff", "--name-only", from, to])
            .output()
            .unwrap();
        assert!(diff.status.success());
        let paths: Vec<_> = String::from_utf8(diff.stdout.clone())
            .unwrap()
            .lines()
            .map(str::to_string)
            .collect();
        files.push((format!("writer-diff-{}.txt", index + 1), diff.stdout));
        deltas.push(serde_json::json!({"from":from,"to":to,"paths":paths}));
    }
    files.push((
        "writer-deltas.json".into(),
        serde_json::to_vec(&deltas).unwrap(),
    ));
    for review in ready["attempts"][0]["tasks"].as_array().unwrap() {
        if review["kind"] == "review"
            && review["status"] == "complete"
            && review["evidence_review_context"].is_null()
        {
            let area = review["artifact_area"]["path"].as_str().unwrap();
            let id = review["id"].as_str().unwrap();
            files.push((
                format!("review-{id}.md"),
                fs::read(project.join(area).join("review.md")).unwrap(),
            ));
        }
    }
    let results = read_json_path(&project.join(&final_path));
    for (index, command) in results["commands"].as_array().unwrap().iter().enumerate() {
        for (stream, key) in [("stdout", "stdout_log"), ("stderr", "stderr_log")] {
            let name = format!("landing-{index}-{stream}.log");
            files.push((
                name,
                fs::read(
                    project
                        .join(&final_path)
                        .parent()
                        .unwrap()
                        .join(command[key].as_str().unwrap()),
                )
                .unwrap(),
            ));
        }
    }
    let artifacts = files
        .iter()
        .map(|(name, bytes)| {
            fs::write(output.join(name), bytes).unwrap();
            serde_json::json!({"path":name,"sha256":format!("{:x}", Sha256::digest(bytes))})
        })
        .collect::<Vec<_>>();
    let source = Path::new(env!("CARGO_MANIFEST_DIR"));
    let trace = serde_json::json!({
        "schema-version":1,
        "scenario":"evidence-status-rebased-landing",
        "fluent-commit":git_head(source),
        "fluent-binary-sha256":format!("{:x}", Sha256::digest(fs::read(env!("CARGO_BIN_EXE_fluent")).unwrap())),
        "model-profile":"evidence-status",
        "collection-complete":true,
        "artifacts":artifacts,
        "events":[
            {"sequence":1,"actor":"operator","operation-id":"attempt-run",
             "generation":null,"boundary":"ready","causal-predecessors":[],
             "raw-facts":{"work":ready}},
            {"sequence":2,"actor":"operator","operation-id":"advance-target",
             "generation":null,"boundary":"target-advanced","causal-predecessors":[1],
             "raw-facts":{"target-commit":target}},
            {"sequence":3,"actor":"operator","operation-id":"land-candidate",
             "generation":null,"boundary":"landed","causal-predecessors":[2],
             "raw-facts":{"work":landed,"merged-commit":git_head(project)}},
            {"sequence":4,"actor":"operator","operation-id":"inspect-landed",
             "generation":null,"boundary":"observed","causal-predecessors":[3],
             "raw-facts":{"status":String::from_utf8(status.stdout).unwrap(),
                          "show":serde_json::from_slice::<serde_json::Value>(&show.stdout).unwrap()}}
        ]
    });
    fs::write(
        output.join("production-trace.json"),
        serde_json::to_vec_pretty(&trace).unwrap(),
    )
    .unwrap();
}

#[test]
fn landed_status_validates_retained_landing_evidence() {
    let tmp = TempDir::new().unwrap();
    let (project, bin, _) = setup_rebased_tester_candidate(&tmp, ":");
    advance_tester_target(&project);
    land_work_1(&project, &bin, true);
    let item = read_work_show_json(&project, "work-1");
    let path = item["evidence-history"]["tester-results"].as_str().unwrap();
    let original = fs::read(project.join(path)).unwrap();
    let mut wrong: serde_json::Value = serde_json::from_slice(&original).unwrap();
    wrong["candidate_commit"] = serde_json::json!("wrong-commit");
    fs::write(project.join(path), serde_json::to_vec(&wrong).unwrap()).unwrap();
    let shown = read_work_show_json(&project, "work-1");
    assert!(shown["evidence-history"]["tester-results"].is_null());
    assert!(
        shown["evidence-history"]["diagnostic"]
            .as_str()
            .unwrap()
            .contains("candidate")
    );
    assert!(shown.get("next-action").is_none());
    assert_eq!(
        fluent::work_status::load_work_status(&project)
            .unwrap()
            .rows[0]
            .action,
        "merged"
    );
    fs::write(project.join(path), &original).unwrap();
    let mut wrong: serde_json::Value = read_json_path(&project.join(path));
    wrong["commands"][0]["command"] = serde_json::json!("printf forged");
    fs::write(project.join(path), serde_json::to_vec(&wrong).unwrap()).unwrap();
    assert!(
        read_work_show_json(&project, "work-1")["evidence-history"]["diagnostic"]
            .as_str()
            .unwrap()
            .contains("command differs")
    );
    fs::write(project.join(path), &original).unwrap();
    let manifest_path = project.join(path).with_file_name("canonical-run.json");
    let mut manifest = read_json_path(&manifest_path);
    let original_manifest = fs::read(&manifest_path).unwrap();
    manifest["run_at"] = serde_json::json!("2000-01-01T00:00:00Z");
    fs::write(&manifest_path, serde_json::to_vec(&manifest).unwrap()).unwrap();
    assert!(
        read_work_show_json(&project, "work-1")["evidence-history"]["diagnostic"]
            .as_str()
            .unwrap()
            .contains("landing evidence changed"),
        "landing binds the complete canonical manifest, including resolved inputs"
    );
    fs::write(&manifest_path, &original_manifest).unwrap();
    let mut manifest = read_json_path(&manifest_path);
    manifest["config_digest"] = serde_json::json!("sha256:forged");
    fs::write(&manifest_path, serde_json::to_vec(&manifest).unwrap()).unwrap();
    assert!(
        read_work_show_json(&project, "work-1")["evidence-history"]["diagnostic"]
            .as_str()
            .unwrap()
            .contains("configuration")
    );

    let known_tmp = TempDir::new().unwrap();
    let (known_project, known_bin, _) = setup_rebased_tester_candidate(
        &known_tmp,
        "printf 'not ok known-target-failure\\n'; exit 1",
    );
    advance_tester_target(&known_project);
    land_work_1(&known_project, &known_bin, true);
    let known = read_work_show_json(&known_project, "work-1");
    let baseline = known["merge_candidates"][0]["merge_state"]["check_artifacts"]
        .as_array()
        .unwrap()
        .iter()
        .find(|artifact| artifact["producer_id"] == "merge-target-baseline")
        .unwrap()["path"]
        .as_str()
        .unwrap();
    let mut wrong_baseline = read_json_path(&known_project.join(baseline));
    wrong_baseline["candidate_commit"] = serde_json::json!("wrong-target");
    fs::write(
        known_project.join(baseline),
        serde_json::to_vec(&wrong_baseline).unwrap(),
    )
    .unwrap();
    assert!(
        read_work_show_json(&known_project, "work-1")["evidence-history"]["diagnostic"]
            .as_str()
            .unwrap()
            .contains("target baseline")
    );
}

#[test]
fn workflow_evidence_satisfies_only_validly_bound_requirements() {
    let tmp = TempDir::new().unwrap();
    let (project, bin, _) = setup_rebased_tester_candidate(&tmp, ":");
    let before = git_head(&project);
    let candidate_workspace = project.join("../work-6-work-1-attempt-1");
    git::run(
        &candidate_workspace,
        &["commit", "--allow-empty", "-m", "Change candidate"],
        "change candidate after its Tester",
    )
    .unwrap();
    fluent_cmd()
        .current_dir(&project)
        .args(["merge-candidate", "land", "work-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin))
        .assert()
        .failure();
    assert_eq!(git_head(&project), before);
    let shown = read_work_show_json(&project, "work-1");
    assert_ne!(
        shown["attempts"][0]["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|task| task["kind"] == "tester")
            .unwrap()["review_context"]["candidate_commit"],
        git_head(&candidate_workspace)
    );
    assert_ne!(
        shown["merge_candidates"][0]["merge_state"]["status"],
        "merged"
    );
}

#[test]
fn workflow_changed_bindings_reassess_evidence_before_advancement() {
    for binding in [
        "review-candidate",
        "review-unrelated-commit",
        "review-source",
        "review-workspace",
    ] {
        let tmp = TempDir::new().unwrap();
        let (project, bin, _) = setup_rebased_tester_candidate(&tmp, ":");
        let before = git_head(&project);
        WorkModelStore::new(&project)
            .mutate_work_item("work-1", |item| {
                let review = item.attempts[0]
                    .tasks
                    .iter_mut()
                    .find(|task| {
                        task.kind == fluent::work_model::TaskKind::Review && task.role == "tests"
                    })
                    .unwrap();
                let context = review.review_context.as_mut().unwrap();
                match binding {
                    "review-candidate" => context.candidate_commit = "0".repeat(40),
                    "review-unrelated-commit" => context.candidate_commit = git_head(&project),
                    "review-source" => context.source_branch = "other".into(),
                    "review-workspace" => {
                        context.candidate_workspace_path = "../other-candidate".into();
                        review.workspace_access.reads[0].path = "../other-candidate".into();
                    }
                    _ => unreachable!(),
                }
                Ok(())
            })
            .unwrap();
        fluent_cmd()
            .current_dir(&project)
            .args(["merge-candidate", "land", "work-1", "--no-sandbox"])
            .env("PATH", mock_path(&bin))
            .assert()
            .failure()
            .stderr(predicate::str::contains(
                "ordinary tests review binding changed before landing",
            ));
        assert_eq!(git_head(&project), before, "{binding} advanced main");
    }

    let tmp = TempDir::new().unwrap();
    let (project, bin, _) = setup_rebased_tester_candidate(&tmp, ":");
    let target = advance_tester_target(&project);
    land_work_1(&project, &bin, true);
    let shown = read_work_show_json(&project, "work-1");
    let path = shown["evidence-history"]["tester-results"]
        .as_str()
        .unwrap();
    let mut results = read_json_path(&project.join(path));
    results["candidate_commit"] = serde_json::json!(target);
    fs::write(project.join(path), serde_json::to_vec(&results).unwrap()).unwrap();
    let status = fluent::work_status::load_work_status(&project).unwrap();
    assert_eq!(status.rows[0].action, "merged");
    assert!(
        status.rows[0]
            .evidence_history
            .as_ref()
            .unwrap()
            .tester_results
            .is_none()
    );
    assert!(
        status.rows[0]
            .recovery_blocker
            .as_deref()
            .unwrap()
            .contains("merged candidate")
    );
    assert!(status.rows[0].next_action.is_none());
}

